/* =========================================================================
   Arbitrage Control Room — design system ported from CG Signal Lab.
   Surfaces, not boxes: structure = whitespace + hairlines. Tinted tiles only
   where Coinbase uses them. Color is reserved for data (up/down/accent).
   ========================================================================= */

:root, [data-theme="light"] {
  color-scheme: light;
  --bg:            #ffffff;
  --panel:         #ffffff;
  --tile:          #f5f6f8;
  --tile-hover:    #eff1f4;
  --hover:         #f7f8fa;
  --line:          #eef0f3;
  --line-2:        #e4e7ec;
  --line-strong:   #d3d7df;

  --text:          #0b0e14;
  --text-2:        #2c313a;
  --muted:         #697180;
  --muted-2:       #858e9b;
  --faint:         #9aa3b2;

  --accent:        #2f6bff;
  --accent-ink:    #1d4ed8;
  --accent-soft:   rgba(47, 107, 255, .13);
  --accent-line:   rgba(47, 107, 255, .42);

  --up:            #0a9b64;
  --up-soft:       rgba(10, 155, 100, .10);
  --down:          #e0414b;
  --down-soft:     rgba(224, 65, 75, .10);

  --cta-bg:        #2f6bff;
  --cta-fg:        #ffffff;

  --shadow-sm:     0 1px 2px rgba(16, 20, 28, .05);
  --shadow-md:     0 6px 24px -8px rgba(16, 20, 28, .16);
  --shadow-pop:    0 12px 40px -12px rgba(16, 20, 28, .26);

  --r-sm: 8px; --r-md: 12px; --r-lg: 16px; --r-pill: 999px;
  --maxw: 1460px;
  --header-h: 58px;

  --font: "InterVariable", "Inter", "SF Pro Text", -apple-system, BlinkMacSystemFont,
          "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: "SF Mono", "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;

  /* translucent chrome for overlays and navigation; data surfaces stay calm. */
  --glass:           rgba(255, 255, 255, .62);
  --glass-strong:    rgba(255, 255, 255, .78);
  --glass-border:    rgba(255, 255, 255, .55);
  --glass-edge:      rgba(16, 20, 28, .08);
  --glass-highlight: inset 0 1px 0 rgba(255, 255, 255, .75);
  --glass-blur:      saturate(180%) blur(18px);
  --ambient-a:       rgba(47, 107, 255, .07);
  --ambient-b:       rgba(141, 125, 255, .06);
  --ambient-c:       rgba(10, 155, 100, .05);
  /* subtle rim + depth (light) */
  --rim-hi:          rgba(255, 255, 255, .9);
  --rim-lo:          rgba(255, 255, 255, .12);
  --depth:           0 1px 2px rgba(16,20,28,.05), 0 10px 30px -16px rgba(16,20,28,.18);
  --depth-lift:      0 2px 4px rgba(16,20,28,.06), 0 18px 40px -18px rgba(16,20,28,.26);
}

/* Dark = flat pro-terminal surfaces (Binance/Coinbase/Uniswap dark): panels
   sit a step lighter than the bg with NO bright borders, structure comes from
   spacing and faint hairlines. Zero specular/glass glare. */
[data-theme="dark"] {
  color-scheme: dark;
  --bg:            #0b0e11;
  --panel:         #15181d;
  --tile:          #1b1f26;
  --tile-hover:    #20252d;
  --hover:         #171b21;
  --line:          #181c22;
  --line-2:        #262d38; /* razor-thin visible edge in dark (owner 2026-07-09) */
  --line-strong:   #2b3139;

  --text:          #e8edf4;
  --text-2:        #aeb7c4;
  --muted:         #717b8a;
  --muted-2:       #626c79;
  --faint:         #4d5664;

  --accent:        #2f6bff;
  --accent-ink:    #2f6bff;
  --accent-soft:   rgba(47, 107, 255, .16);
  --accent-line:   rgba(47, 107, 255, .42);

  --up:            #2ebd85;
  --up-soft:       rgba(46, 189, 133, .13);
  --down:          #f6465d;
  --down-soft:     rgba(246, 70, 93, .13);

  /* primary action = accent (blue by default), never a glaring white pill */
  --cta-bg:        #2f6bff;
  --cta-fg:        #ffffff;

  --shadow-sm:     0 1px 2px rgba(0,0,0,.4);
  --shadow-md:     0 8px 28px -10px rgba(0,0,0,.6);
  --shadow-pop:    0 16px 48px -14px rgba(0,0,0,.7);

  --glass:           rgba(13, 16, 20, .86);
  --glass-strong:    rgba(16, 19, 24, .94);
  --glass-border:    rgba(255, 255, 255, .04);
  --glass-edge:      rgba(0, 0, 0, 0);
  --glass-highlight: inset 0 1px 0 rgba(255, 255, 255, 0);
  --glass-blur:      saturate(110%) blur(12px);
  --ambient-a:       rgba(240, 185, 11, 0);
  --ambient-b:       rgba(118, 144, 255, 0);
  --ambient-c:       rgba(46, 189, 133, 0);
  --rim-hi:          rgba(255, 255, 255, 0);
  --rim-lo:          rgba(255, 255, 255, 0);
  --depth:           0 0 0 0 rgba(0,0,0,0);
  --depth-lift:      0 0 0 0 rgba(0,0,0,0);
}

* { box-sizing: border-box; }
html, body { height: 100%; overflow-x: clip; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 13.5px;
  line-height: 1.5;
  font-optical-sizing: auto;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}
/* faint ambient field; deliberately restrained in dark mode */
body::before {
  content: ""; position: fixed; inset: 0; z-index: -1; pointer-events: none;
  background:
    radial-gradient(720px 420px at 8% -6%, var(--ambient-a), transparent 62%),
    radial-gradient(900px 520px at 96% 4%, var(--ambient-b), transparent 60%),
    radial-gradient(760px 560px at 55% 108%, var(--ambient-c), transparent 62%);
}
[data-theme="dark"] body::before { opacity: .42; }

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; color: inherit; }
input, select { font-family: inherit; }
:focus-visible { outline: 2px solid var(--accent-line); outline-offset: 2px; border-radius: 4px; }

.num { font-variant-numeric: lining-nums tabular-nums; font-feature-settings: "tnum" 1, "lnum" 1; font-weight: 620; }
.mono { font-family: var(--mono); }
.up   { color: var(--up); }
.down { color: var(--down); }
.strong { color: var(--text); }
.muted  { color: var(--muted); }
.faint  { color: var(--faint); }
.small { font-size: 12px; }

/* ---- scaffold: sidebar cockpit ---- */
.app-root { height: calc(100vh / var(--uiz, 1)); display: flex; overflow: hidden; }
.app-main { flex: 1; min-width: 0; height: 100%; display: flex; flex-direction: column; overflow: hidden; }
.app-main main { flex: 1 1 auto; min-height: 0; overflow-y: auto; overflow-x: clip; display: flex; flex-direction: column; }
.app-main main > * { flex: 0 0 auto; }
.app-main main .container.page { flex: 1 0 auto; }

.global-mutation-alert:empty { display: none; }
.global-mutation-alert {
  flex: none;
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 7px 18px;
  border-bottom: 1px solid color-mix(in srgb, var(--down) 32%, var(--line));
  background: color-mix(in srgb, var(--down) 9%, var(--panel));
  color: var(--down);
  font-size: 11.5px;
  line-height: 16px;
  text-align: center;
}
.global-mutation-alert strong {
  flex: none;
  font-size: 10px;
  font-weight: 720;
  letter-spacing: .07em;
}
.global-mutation-alert span { color: var(--text-2); }

.snav {
  width: 212px; flex-shrink: 0; display: flex; flex-direction: column;
  background: color-mix(in srgb, var(--panel) 90%, transparent);
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  position: relative; height: 100%; overflow: hidden;
  padding: 0 9px 10px;
}
.snav-nav { flex: 1 1 auto; min-height: 0; overflow-y: auto; scrollbar-width: thin; }
.snav-utils, .snav-foot { flex: none; }
/* Brand band sits exactly in line with the 52px top bar — one continuous row,
   no divider (Google Cloud console pattern). */
.snav-brand {
  display: flex; align-items: center; gap: 10px; flex: none;
  height: 52px; padding: 0 5px; cursor: pointer;
}
.brand-mark {
  flex: none; display: block; width: 33px; height: 33px;
  filter: drop-shadow(0 6px 14px color-mix(in srgb, var(--accent) 32%, transparent));
  transition: transform .2s cubic-bezier(.34,1.4,.5,1), filter .2s;
}
.snav-brand:hover .brand-mark { transform: rotate(6deg) scale(1.07); }
.brand-lockup { min-width: 0; display: flex; flex-direction: column; justify-content: center; gap: 2px; }
.brand-name {
  color: var(--text); font-size: 18.5px; font-weight: 650; line-height: 1;
  letter-spacing: -0.4px; white-space: nowrap;
  font-optical-sizing: auto;
}
.brand-sub {
  display: flex; align-items: center; gap: 5px;
  color: var(--text-2); font-size: 10.5px; font-weight: 680; line-height: 1.12;
  letter-spacing: 0; text-transform: none; white-space: nowrap;
}
.brand-sub-dot {
  width: 5px; height: 5px; border-radius: 50%; flex: none;
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
[data-theme="dark"] .brand-mark { filter: drop-shadow(0 10px 20px color-mix(in srgb, var(--accent) 40%, transparent)); }
.snav-group { margin-bottom: 3px; }
.snav-group-title {
  font-size: 9.5px; font-weight: 650; text-transform: uppercase; letter-spacing: 0;
  color: var(--faint); padding: 7px 10px 3px;
}
.snav-item {
  position: relative; display: flex; align-items: center; gap: 8px; width: 100%;
  height: 31px; padding: 0 8px; border: 0; background: none; border-radius: 8px;
  color: var(--muted); font-size: 12.5px; font-weight: 600; text-align: left;
  text-decoration: none; cursor: pointer;
  transition: color .12s, background .12s;
}
.snav-item svg { flex: none; }
.snav-item:hover { color: var(--text); background: var(--hover); }
.snav-item.active { color: var(--text); background: color-mix(in srgb, var(--accent-soft) 46%, transparent); font-weight: 620; }
.snav-item.active::before {
  content: ""; position: absolute; left: -10px; top: 6px; bottom: 6px; width: 2.5px;
  border-radius: 2px; background: var(--accent);
}
.snav-item .nav-badge { margin-left: auto; }
.snav-foot { flex: none; margin-top: 10px; padding: 10px 4px 2px; }
.tb-title { font-size: 15.5px; font-weight: 640; letter-spacing: 0; color: var(--text); margin: 0; white-space: nowrap; }

[data-motion="reduced"] * { animation-duration: .01ms !important; transition-duration: .01ms !important; }
[data-motion="reduced"] .tape-track { animation: none !important; }
.dense-tables .mkt tbody td { height: 44px; }
/* Page gutter matches the sidebar's internal text gutter (~22px), so content
   starts close to the nav instead of floating behind a wide dead zone. */
.container { width: 100%; max-width: none; margin: 0; padding: 0 22px; } /* Account law (owner 2026-07-09): content STRETCHES with the window; gutters stay constant-pixel — no dead side space ever */
/* form/list pages (Settings, System Health) read as a constrained column so
   labels and their controls never drift apart across a wide/zoomed viewport */
.container.page-narrow { max-width: 940px; }
/* Vertical padding only — leave the horizontal gutter to .container so page
   content always keeps a gap from the sidebar divider (never flush against it). */
.page { flex: 1 0 auto; padding-top: 24px; padding-bottom: 90px; } /* NO entry animation — keyframes freeze at :root zoom and hold opacity 0 (the washed-out-page bug) */

/* ---- data panels: calm, bounded surfaces without dark-mode glare ---- */
.card {
  position: relative;
  background: color-mix(in srgb, var(--panel) 96%, transparent);
  backdrop-filter: saturate(112%) blur(6px);
  -webkit-backdrop-filter: saturate(112%) blur(6px);
  border: 1px solid var(--line-2);
  border-radius: 14px;
  box-shadow: var(--glass-highlight), 0 1px 1px rgba(16,20,28,.035);
  padding: 18px 20px;
  margin-bottom: 16px;
}

/* Subtle rim only. In dark mode it is deliberately quiet so panels do not glow. */
.card::after,
.stat-tile::after,
.mcard::after,
.hero-donut::after,
.cta-pill::after,
.mode-pill::after,
.conn-panel::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--rim-hi) 68%, transparent) 0%, transparent 35%, transparent 72%, var(--rim-lo) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor; mask-composite: exclude;
  pointer-events: none; z-index: 1; opacity: .46;
}
.hero-donut { position: relative; }
.stat-tile, .mcard, .cta-pill, .mode-pill, .conn-panel, .tb-action { position: relative; }
/* rim brightens slightly on hover for interactive surfaces */
.stat-tile:hover::after, .mcard:hover::after, .cta-pill:hover::after {
  background: linear-gradient(135deg, var(--rim-hi) 0%, transparent 30%, transparent 64%, var(--rim-hi) 100%);
}
.card { transition: box-shadow .18s ease, border-color .18s ease, background .18s ease; }
[data-theme="dark"] .card {
  background: var(--panel);
  border-color: var(--line-2); /* every card keeps its edge in dark — no borderless tabs */
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: none;
}
/* dark mode: rims OFF — no light-catching edges anywhere (owner: glare) */
[data-theme="dark"] .card::after,
[data-theme="dark"] .stat-tile::after,
[data-theme="dark"] .mcard::after,
[data-theme="dark"] .hero-donut::after,
[data-theme="dark"] .cta-pill::after,
[data-theme="dark"] .mode-pill::after,
[data-theme="dark"] .conn-panel::after,
[data-theme="dark"] .hdr-health::after {
  opacity: 0;
}
[data-theme="dark"] .stat-tile {
  background: var(--panel);
  border-color: transparent;
  box-shadow: none;
}
[data-theme="dark"] .stat-tile:hover { background: var(--tile); box-shadow: none; }
[data-theme="dark"] .wallet-ring-placeholder::after { box-shadow: none; }
[data-theme="dark"] .dash-symbol-field input:focus { box-shadow: 0 0 0 3px var(--accent-soft); }
.card.pad-0 { padding: 0; }
.card.flush { margin-bottom: 0; }
/* header row inside a card: title + optional action link */
.card-head {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  margin: -2px 0 12px;
}
.card-head .ch-title { font-size: 14.5px; font-weight: 650; color: var(--text); letter-spacing: 0; }
.card-head .ch-title .muted { font-weight: 600; font-size: 12px; }
.card-body-empty { padding: 26px 8px; text-align: center; }

/* a subtly tinted card for the account-summary hero */
.card.hero-card {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--accent-soft) 55%, transparent), transparent 60%),
    color-mix(in srgb, var(--panel) 82%, transparent);
}
@keyframes pageIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  .page { animation: none; }
  .tape-track { animation: none !important; }
  .flash-up, .flash-down, .cell-up, .cell-down { animation: none !important; }
}

/* ==== LIVE INTELLIGENCE V5 — News + Calendar ============================= */
.nwx-page.nwx-calendar,
.clx-page.clx-v5 {
  --intel-grid: 92px 204px minmax(0, 1fr) 32px;
  max-width: 1500px;
}
.nwx-calendar .nwx-hero,
.clx-v5 .clx-hero {
  margin-bottom: 0;
  padding: 22px 0 18px;
  border-bottom: 1px solid var(--line);
}
.nwx-calendar .nwx-hero .bwx-title-row h1,
.clx-v5 .clx-hero .bwx-title-row h1 {
  font-size: 26px;
  font-weight: 560;
  letter-spacing: -.035em;
  line-height: 32px;
}
.nwx-calendar .nwx-hero p,
.clx-v5 .clx-hero p {
  max-width: 720px;
  margin-top: 4px;
  color: var(--text-2);
  font-size: 13px;
  font-weight: 400;
  line-height: 19px;
}
.nwx-command {
  gap: 0;
  padding: 0;
  border-bottom: 1px solid var(--line);
}
.nwx-bucket-strip {
  min-height: 47px;
  padding: 0;
  border-bottom: 1px solid var(--line);
}
.nwx-bucket {
  min-height: 47px;
  padding: 0 14px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: transparent;
}
.nwx-bucket:hover { background: var(--hover); }
.nwx-bucket.on {
  color: var(--text);
  border-bottom-color: var(--accent);
  background: transparent;
  box-shadow: none;
}
.nwx-bucket span { font-size: 12px; font-weight: 500; letter-spacing: 0; }
.nwx-bucket b { color: var(--text-2); font-size: 10px; font-weight: 500; }
.nwx-tool-row {
  display: grid;
  grid-template-columns: 250px minmax(260px, 1fr);
  gap: 10px;
  min-height: 56px;
  padding: 10px 0;
}
.nwx-source-control .nwx-select-pill,
.nwx-calendar-search {
  min-height: 36px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--panel);
  box-shadow: none;
}
.nwx-calendar-search:focus-within { border-color: color-mix(in srgb, var(--accent) 52%, var(--line)); }
.nwx-calendar-search input { font-size: 12px; font-weight: 400; }

.nwx-source-rail {
  border-bottom: 1px solid var(--line);
  background: var(--panel);
}
.nwx-source-rail-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 38px;
  padding: 0 2px;
}
.nwx-source-rail-head > span { display: flex; align-items: baseline; gap: 9px; }
.nwx-source-rail-head b { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.nwx-source-rail-head em { color: var(--text-2); font-size: 11px; font-style: normal; font-weight: 400; }
.nwx-source-rail-head button {
  border: 0;
  color: var(--text-2);
  background: transparent;
  font: 500 11px/1 inherit;
  cursor: pointer;
}
.nwx-source-rail-head button:hover { color: var(--text); }
.nwx-source-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-top: 1px solid var(--line);
  border-left: 1px solid var(--line);
}
.nwx-source-grid > button {
  position: relative;
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) 7px 28px;
  align-items: center;
  gap: 8px;
  min-width: 0;
  min-height: 48px;
  padding: 6px 10px;
  border: 0;
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  color: var(--text);
  background: transparent;
  text-align: left;
  cursor: pointer;
}
.nwx-source-grid > button:hover { background: var(--hover); }
.nwx-source-grid > button.on { background: color-mix(in srgb, var(--accent) 7%, var(--panel)); }
.nwx-source-grid > button > span { display: grid; min-width: 0; }
.nwx-source-grid > button b { overflow: hidden; font-size: 11px; font-weight: 500; line-height: 15px; text-overflow: ellipsis; white-space: nowrap; }
.nwx-source-grid > button em { color: var(--text-2); font-size: 9px; font-style: normal; line-height: 12px; text-transform: capitalize; }
.nwx-source-grid > button strong { color: var(--text-2); font-size: 10px; font-weight: 500; text-align: right; }
.nwx-source-state { width: 6px; height: 6px; border-radius: 50%; background: var(--faint); }
.nwx-source-state.live { background: var(--up); }
.nwx-source-state.delayed { background: #d68122; }
.nwx-source-state.error { background: var(--down); }
.nwx-source-grid .nwx-logo { border: 0; border-radius: 6px; background: var(--tile); box-shadow: none; }

.nwx-cols,
.nwx-line { grid-template-columns: var(--intel-grid); }
.nwx-cols {
  min-height: 34px;
  padding: 0 10px;
  border-bottom: 1px solid var(--line);
  color: var(--text-2);
  background: var(--bg);
  font-size: 10px;
  font-weight: 550;
  letter-spacing: .055em;
  text-transform: uppercase;
}
.nwx-page-list { border: 0; border-radius: 0; box-shadow: none; }
.nwx-line {
  position: relative;
  min-height: 66px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--line);
  color: var(--text);
  background: var(--panel);
  transition: background-color 160ms ease, border-color 160ms ease;
}
.nwx-line:hover { background: var(--hover); transform: none; }
.nwx-line.read { opacity: .72; }
.nwx-line.unread::before { left: 0; width: 2px; border-radius: 0; background: var(--accent); }
.nwx-time { display: grid; align-content: center; gap: 1px; }
.nwx-time b { font-size: 11px; font-weight: 520; line-height: 15px; }
.nwx-time em { color: var(--text-2); font-size: 10px; font-style: normal; line-height: 13px; }
.nwx-provider { gap: 9px; }
.nwx-provider .nwx-logo { width: 26px !important; height: 26px !important; border: 0; border-radius: 7px; background: var(--tile); box-shadow: none; }
.nwx-provider span { gap: 0; min-width: 0; }
.nwx-provider b { overflow: hidden; font-size: 11px; font-weight: 540; line-height: 15px; text-overflow: ellipsis; white-space: nowrap; }
.nwx-provider em { overflow: hidden; color: var(--text-2); font-size: 9px; font-weight: 400; line-height: 13px; text-overflow: ellipsis; white-space: nowrap; }
.nwx-headline-cell { display: grid; align-content: center; gap: 4px; min-width: 0; padding-right: 14px; }
.nwx-headline-cell > b { overflow: hidden; font-size: 13px; font-weight: 450; letter-spacing: -.005em; line-height: 18px; text-overflow: ellipsis; white-space: nowrap; }
.nwx-row-meta { display: flex; align-items: center; gap: 5px; overflow: hidden; }
.nwx-row-meta em,
.nwx-row-meta i { font-size: 9px; font-style: normal; font-weight: 500; line-height: 14px; white-space: nowrap; }
.nwx-row-meta em { color: var(--text-2); text-transform: uppercase; letter-spacing: .045em; }
