/* ---- header ---- */
/* Figma-language header: quiet chrome — the page's own bg through a light
   blur, one honest hairline, zero decoration. Content carries the color. */
.hdr {
  position: relative; z-index: 50; flex: none;
  height: 52px;
  isolation: isolate;
  overflow: visible; /* let top-bar dropdowns escape */
  background: color-mix(in srgb, var(--bg) 70%, transparent);
  backdrop-filter: blur(20px) saturate(150%);
  -webkit-backdrop-filter: blur(20px) saturate(150%);
}
.hdr-in { position: relative; height: 100%; display: flex; align-items: center; gap: 10px; padding: 0 14px; }
.tb-left { display: flex; align-items: center; gap: 14px; min-width: 0; flex: 1 1 auto; }
.tb-tabs {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  min-width: 0;
}
.tb-tabs button {
  position: relative;
  height: 28px;
  padding: 0 9px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  font-weight: 640;
  transition: color .12s ease, background .12s ease;
}
.tb-tabs button:hover { color: var(--text); background: var(--hover); }
.tb-tabs button.active { color: var(--text); background: transparent; }
.tb-tabs button.active::after {
  content: "";
  position: absolute;
  left: 9px;
  right: 9px;
  bottom: -8px;
  height: 2px;
  border-radius: 2px;
  background: var(--accent);
}
.tb-divider { width: 1px; height: 20px; background: linear-gradient(180deg, transparent, var(--line-2), transparent); flex: none; }

/* header status + mode: flat text, a dot and a word — no bubbles, no borders.
   This is how Binance/Coinbase keep chrome quiet; detail lives in System Health. */
.hdr-status {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 7px;
  border: 0; border-radius: 7px; background: transparent;
  font-size: 11.5px; font-weight: 640; letter-spacing: 0; white-space: nowrap;
  transition: background .12s;
}
.hdr-status .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; flex: none; }
.hdr-status:hover { background: var(--hover); }
.hdr-status.ok { color: var(--up); }
.hdr-status.warn { color: var(--accent-ink); }
.hdr-status.bad { color: var(--down); }
[data-theme="dark"] .hdr-status.warn { color: var(--accent); }

.hdr-mode {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 7px;
  font-size: 11.5px; font-weight: 620; letter-spacing: 0; white-space: nowrap;
}
.hdr-mode .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; flex: none; }
.hdr-mode.m-halted { color: var(--down); }
.hdr-mode.m-manual { color: var(--accent-ink); }
[data-theme="dark"] .hdr-mode.m-manual { color: var(--accent); }
.hdr-mode.m-live { color: var(--up); }
.hdr-mode.m-live .dot { animation: hbPulse 2.2s ease-out infinite; }

/* the ONE header action (Binance keeps one primary button in the chrome) */
.hdr-action {
  display: inline-flex; align-items: center; gap: 5px; height: 28px; padding: 0 12px;
  border: 0; border-radius: 8px; font-size: 12px; font-weight: 620; letter-spacing: 0;
  transition: filter .12s, background .12s;
}
.hdr-action svg { width: 12px; height: 12px; }
.hdr-action.halt { background: var(--down); color: #fff; }
.hdr-action.halt:hover { filter: brightness(1.1); }
.hdr-action.resume { background: transparent; color: var(--text); border: 1px solid var(--line-strong); }
.hdr-action.resume:hover { background: var(--hover); }
.brand { display: flex; align-items: center; gap: 10px; padding-right: 4px; cursor: pointer; }
.brand-name { font-weight: 620; font-size: 15px; letter-spacing: 0; color: var(--text); white-space: nowrap; }

.nav { display: flex; align-items: center; gap: 2px; }
.nav-a {
  position: relative; display: inline-flex; align-items: center; gap: 6px;
  height: 36px; padding: 0 12px; border: 0; background: transparent; border-radius: var(--r-sm);
  font-size: 13.5px; font-weight: 600; color: var(--muted);
  transition: color .12s, background .12s;
}
.nav-a:hover { color: var(--text); background: var(--hover); }
.nav-a.active { color: var(--text); }
.nav-a::after {
  content: ""; position: absolute; left: 12px; right: 12px; bottom: -11px; height: 2.5px;
  background: var(--accent); border-radius: 2px;
  transform: scaleX(0); transition: transform .18s cubic-bezier(.3,.6,.2,1);
}
.nav-a.active::after { transform: scaleX(1); }
.nav-a:hover:not(.active)::after { transform: scaleX(.45); opacity: .5; }
.nav-badge {
  background: var(--accent); color: #0b0e11; border-radius: 999px;
  font-size: 10px; font-weight: 650; padding: 1px 6px;
}
.nav-car { font-size: 9px; opacity: .6; }

.hdr-right { margin-left: auto; display: flex; align-items: center; gap: 5px; min-width: 0; flex: 0 1 auto; }
.search-btn {
  display: inline-flex; align-items: center; gap: 9px;
  height: 36px; padding: 0 11px 0 13px; min-width: 200px;
  border: 0; border-radius: var(--r-pill);
  background: var(--tile); color: var(--muted); font-size: 13px;
  transition: background .12s;
}
.search-btn:hover { background: var(--tile-hover); }
.search-btn svg { width: 14px; height: 14px; }
.search-btn .kbd { margin-left: auto; }
.kbd {
  font-family: var(--mono); font-size: 10.5px; color: var(--muted);
  border: 1px solid var(--line-2); border-bottom-width: 2px; border-radius: 5px;
  padding: 0 5px; background: var(--bg); line-height: 1.5;
}
.icon-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 32px; height: 28px; border-radius: 9px;
  border: 1px solid transparent; background: transparent; color: var(--muted);
  transition: background .12s, color .12s, transform .12s, border-color .12s;
}
.icon-btn:hover {
  color: var(--text);
  background: color-mix(in srgb, var(--panel) 68%, transparent);
  border-color: color-mix(in srgb, var(--glass-border) 58%, transparent);
  transform: translateY(-1px);
}
.icon-btn:active { transform: translateY(0); }
.icon-btn svg { width: 17px; height: 17px; }
.hdr-clock { font-size: 10.8px; color: var(--muted); font-weight: 550; white-space: nowrap; line-height: 1; }

.mode-pill {
  display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 12px;
  border-radius: 11px; font-size: 11px; font-weight: 650; letter-spacing: 0;
  background: color-mix(in srgb, var(--panel) 72%, transparent);
  color: var(--muted);
  border: 1px solid color-mix(in srgb, var(--glass-border) 58%, transparent);
  white-space: nowrap;
  box-shadow: none;
}
.mode-pill .dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
.mode-pill.m-halted { background: var(--down-soft); color: var(--down); }
.mode-pill.m-manual { background: var(--accent-soft); color: var(--accent-ink); }
[data-theme="dark"] .mode-pill.m-manual { color: var(--accent); }
.mode-pill.m-live { background: var(--up-soft); color: var(--up); }
.mode-pill.m-live .dot { animation: hbPulse 2.2s ease-out infinite; }
.halt-btn {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 13px;
  border: 0; border-radius: var(--r-pill); background: var(--down); color: #fff;
  font-size: 11px; font-weight: 650; letter-spacing: 0;
}
.halt-btn:hover { filter: brightness(1.08); }
.halt-btn svg { width: 13px; height: 13px; }

/* dropdown menus */
.menu-wrap { position: relative; }
.menu-pop {
  position: absolute; top: calc(100% + 10px); left: 0; z-index: 80; min-width: 230px;
  background: var(--glass-strong); border: 1px solid var(--glass-border); border-radius: 16px;
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  box-shadow: var(--shadow-pop), var(--glass-highlight), 0 0 0 .5px var(--glass-edge);
  padding: 6px; animation: rise .12s ease both;
}
@keyframes rise { from { transform: translateY(-6px); opacity: 0; } to { transform: none; opacity: 1; } }
.menu-item {
  display: flex; align-items: center; gap: 10px; width: 100%; padding: 9px 11px;
  border: 0; background: none; border-radius: 10px; cursor: pointer; text-align: left;
}
.menu-item:hover { background: var(--tile); }
.menu-item .m-ic { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 8px; background: var(--tile); color: var(--text-2); flex: none; }
.menu-item:hover .m-ic { background: var(--bg); }
.menu-item .m-ic svg { width: 15px; height: 15px; }
.menu-item .m-label { font-size: 13px; font-weight: 620; color: var(--text); }
.menu-item .m-sub { font-size: 11px; color: var(--muted); margin-top: 0; line-height: 1.35; }
.menu-item .m-right { margin-left: auto; font-size: 11px; font-weight: 620; color: var(--accent-ink); }
[data-theme="dark"] .menu-item .m-right { color: var(--accent); }

/* ============ top-bar icon row: clock, status/power, theme, network ======== */
.icon-btn.on { color: var(--text); background: var(--tile); border-color: color-mix(in srgb, var(--glass-border) 58%, transparent); }

/* subtle clock — quiet by default, becomes a control on hover / when open */
.hdr-clock-btn {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 8px;
  border: 1px solid transparent; border-radius: 9px; background: transparent;
  color: var(--muted); font-size: 11.5px; font-weight: 600; white-space: nowrap; cursor: pointer;
  transition: background .12s, color .12s, border-color .12s;
}
.hdr-clock-btn svg { width: 13px; height: 13px; opacity: .82; }
.hdr-clock-btn .num { color: var(--text-2); font-weight: 640; letter-spacing: .2px; }
.hdr-clock-btn:hover, .hdr-clock-btn.on {
  color: var(--text); background: var(--tile);
  border-color: color-mix(in srgb, var(--glass-border) 58%, transparent);
}
.hdr-clock-btn .hcb-zone {
  font-size: 9.5px; font-weight: 650; letter-spacing: .4px;
  background: var(--accent-soft); color: var(--accent-ink); padding: 1px 5px; border-radius: 5px;
}
[data-theme="dark"] .hdr-clock-btn .hcb-zone { color: var(--accent); }

/* shield / power icon buttons — status dot carries the mode color */
.hdr-ic {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  width: 32px; height: 28px; border-radius: 9px; border: 1px solid transparent;
  background: transparent; color: var(--muted); cursor: pointer;
  transition: background .12s, color .12s, transform .12s, border-color .12s;
}
.hdr-ic:hover { color: var(--text); background: var(--tile); transform: translateY(-1px); }
.hdr-ic:active { transform: translateY(0); }
.hdr-ic svg { width: 16px; height: 16px; }
.hdr-ic .ic-dot {
  position: absolute; top: 4px; right: 4px; width: 7px; height: 7px; border-radius: 50%;
  border: 1.5px solid var(--panel); background: var(--muted);
}
.hdr-ic.m-halted { color: var(--down); } .hdr-ic.m-halted .ic-dot { background: var(--down); }
.hdr-ic.m-manual { color: var(--accent-ink); } .hdr-ic.m-manual .ic-dot { background: var(--accent); }
[data-theme="dark"] .hdr-ic.m-manual { color: var(--accent); }
.hdr-ic.m-live { color: var(--up); } .hdr-ic.m-live .ic-dot { background: var(--up); animation: hbPulse 2.2s ease-out infinite; }

/* network / signal button */
.net-btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  width: 32px; height: 28px; border-radius: 9px; border: 1px solid transparent;
  background: transparent; color: var(--muted); cursor: pointer;
  transition: background .12s, color .12s, transform .12s, border-color .12s;
}
.net-btn:hover, .net-btn.on { color: var(--text); background: var(--tile); transform: translateY(-1px); }
.net-btn svg { width: 16px; height: 16px; }
.net-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--muted); flex: none; }
.net-btn .net-dot { position: absolute; top: 4px; right: 4px; border: 1.5px solid var(--panel); }
.net-btn.ok { color: var(--up); } .net-btn.ok .net-dot { background: var(--up); animation: hbPulse 2.4s ease-out infinite; }
.net-btn.warn { color: var(--accent-ink); } .net-btn.warn .net-dot { background: var(--accent); }
[data-theme="dark"] .net-btn.warn { color: var(--accent); }
.net-btn.bad { color: var(--down); } .net-btn.bad .net-dot { background: var(--down); animation: hbPulse 1.1s ease-out infinite; }

/* popover placement + section heads */
.menu-pop.right { left: auto; right: 0; }
.menu-head {
  font-size: 10px; font-weight: 650; letter-spacing: .6px; text-transform: uppercase;
  color: var(--faint); padding: 8px 10px 4px;
}

/* clock zone picker */
.zone-pop { min-width: 246px; }
.menu-item.sel { background: var(--accent-soft); }
.zp-code {
  width: 34px; flex: none; font-size: 10.5px; font-weight: 650; letter-spacing: .3px;
  color: var(--muted); text-align: left;
}
.menu-item.sel .zp-code { color: var(--accent-ink); }
[data-theme="dark"] .menu-item.sel .zp-code { color: var(--accent); }
.zp-city { flex: 1; font-size: 12.5px; font-weight: 600; color: var(--text); text-align: left; }
.zp-time { font-size: 11.5px; font-weight: 640; color: var(--muted); }

/* theme + ROYGBIV accent popover */
.theme-pop { min-width: 216px; }
.theme-seg { display: flex; gap: 4px; padding: 2px 8px 8px; }
.theme-seg button {
  flex: 1; height: 30px; border: 1px solid var(--line-2); background: var(--tile);
  border-radius: 9px; font-size: 12px; font-weight: 640; color: var(--muted); cursor: pointer;
  white-space: nowrap;
  transition: background .12s, color .12s, border-color .12s;
}
.theme-seg button:hover { color: var(--text); }
.theme-seg button.on { color: var(--cta-fg); background: var(--accent); border-color: var(--accent); }
.accent-dots { display: flex; gap: 8px; padding: 4px 8px 10px; }
.accent-dot {
  width: 22px; height: 22px; border-radius: 50%; border: 0; cursor: pointer; padding: 0;
  background: var(--dot); box-shadow: inset 0 0 0 1px rgba(0,0,0,.14);
  transition: transform .12s;
}
.accent-dot:hover { transform: scale(1.12); }
.accent-dot.sel { box-shadow: 0 0 0 2px var(--panel), 0 0 0 4px var(--dot); }

/* network status popover */
.net-pop { min-width: 260px; padding: 10px 12px 12px; }
.np-head {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 2px 2px 8px; border-bottom: 1px solid var(--line); margin-bottom: 6px;
}
.np-title { display: inline-flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 620; color: var(--text); }
.np-title.ok { color: var(--up); } .np-title.warn { color: var(--accent-ink); } .np-title.bad { color: var(--down); }
[data-theme="dark"] .np-title.warn { color: var(--accent); }
.np-title .net-dot { background: currentColor; position: static; border: 0; }
.np-lat { font-size: 12px; font-weight: 620; color: var(--text-2); }
.np-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 3px 2px; font-size: 12px; }
.np-row .k { color: var(--muted); }
.np-row .v { color: var(--text); font-weight: 640; }
.np-row .v.ok { color: var(--up); } .np-row .v.warn { color: var(--accent-ink); } .np-row .v.bad { color: var(--down); }
[data-theme="dark"] .np-row .v.warn { color: var(--accent); }

/* ---- live tape ---- */
.tape {
  -webkit-mask-image: linear-gradient(90deg, transparent 0, #000 26px, #000 calc(100% - 26px), transparent 100%);
  mask-image: linear-gradient(90deg, transparent 0, #000 26px, #000 calc(100% - 26px), transparent 100%);
  border-bottom: 1px solid var(--line); overflow: clip;
  max-width: 100vw; contain: layout paint; background: var(--bg);
}
.tape-track { display: flex; width: max-content; align-items: center; animation: tapeScroll 80s linear infinite; }
.tape:hover .tape-track { animation-play-state: paused; }
@keyframes tapeScroll { to { transform: translateX(-50%); } }
.tape-item {
  display: inline-flex; align-items: center; gap: 8px; padding: 0 18px;
  height: 40px; white-space: nowrap; cursor: pointer; flex: none;
  border-right: 1px solid var(--line); background: none; border-top: 0; border-bottom: 0; border-left: 0;
  font: inherit;
}
.tape-sym { font-weight: 640; font-size: 12.5px; color: var(--text); }
.tape-item:hover .tape-sym { color: var(--accent-ink); }
[data-theme="dark"] .tape-item:hover .tape-sym { color: var(--accent); }
.tape-px { font-size: 12.5px; color: var(--text-2); }
.tape-chg { font-size: 11px; font-weight: 640; padding: 2px 8px; border-radius: 999px; }
.tape-chg.up { background: var(--up-soft); }
.tape-chg.down { background: var(--down-soft); }

/* ---- page head / sections ---- */
/* Figma-language page heroes: big tight editorial type, whitespace does the
   framing, the subtitle is a real sentence with room to breathe. */
.page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; margin: 52px 0 26px; flex-wrap: wrap; }
.page-title { font-size: 56px; font-weight: 660; letter-spacing: 0; line-height: 1.03; color: var(--text); margin: 0; }
.page-sub { color: var(--text-2); font-size: 16px; line-height: 1.55; margin-top: 10px; max-width: 720px; }
.head-actions { display: flex; align-items: center; gap: 8px; }
.sec-head { display: flex; align-items: baseline; justify-content: space-between; margin: 36px 0 14px; gap: 12px; flex-wrap: wrap; }
.sec-title { font-size: 19px; font-weight: 650; letter-spacing: 0; color: var(--text); margin: 0; }
.sec-note { color: var(--muted); font-size: 12.5px; }
.sec-link { color: var(--muted); font-size: 12.5px; font-weight: 600; border: 0; background: none; }
.sec-link:hover { color: var(--text); }

/* ---- stat tiles (Coinbase market stats) ---- */
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-top: 18px; }
.stat-tile {
  background: color-mix(in srgb, var(--tile) 78%, transparent);
  border-radius: 16px; padding: 14px 17px 11px;
  border: 1px solid color-mix(in srgb, var(--glass-border) 45%, transparent);
  box-shadow: var(--glass-highlight), 0 0 0 .5px var(--glass-edge);
  transition: background .15s, transform .12s, box-shadow .15s;
  text-align: left; font: inherit;
}
.stat-tile.clickable { cursor: pointer; }
.stat-tile:hover { background: var(--tile-hover); transform: translateY(-1px); box-shadow: var(--glass-highlight), var(--shadow-md); }
.stat-k { font-size: 10.5px; font-weight: 620; letter-spacing: 0; text-transform: uppercase; color: var(--muted); }
.stat-v { font-size: 22px; font-weight: 640; color: var(--text); letter-spacing: 0; margin-top: 3px; }
.stat-v.red { color: var(--down); } .stat-v.green { color: var(--up); } .stat-v.gold { color: var(--accent-ink); }
[data-theme="dark"] .stat-v.gold { color: var(--accent); }
.stat-d { font-size: 11.5px; font-weight: 620; margin-top: 2px; min-height: 15px; color: var(--muted); }
.stat-spark { height: 36px; margin-top: 8px; }
.stat-spark svg { width: 100%; height: 100%; display: block; }

/* ---- headline (asset/equity hero) ---- */
.headline { display: flex; align-items: baseline; gap: 14px; margin: 8px 0 18px; flex-wrap: wrap; }
.headline-val { font-size: 44px; font-weight: 530; letter-spacing: 0; color: var(--text); line-height: 1; }
.headline-unit { font-size: 13.5px; color: var(--muted); font-weight: 550; }
.hl-chip { font-size: 14.5px; font-weight: 650; }
.hl-chip.muted-chip { color: var(--muted); font-weight: 550; font-size: 13px; }

/* metric strip: responsive grid of divided cells — never orphans on wrap */
.metric-strip {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);
  margin: 4px 0 8px;
}
.metric {
  display: flex; flex-direction: column; gap: 1px; padding: 13px 20px 13px 0;
  border-right: 1px solid var(--line); min-width: 0;
}
.metric:last-child { border-right: 0; }
.metric .k { font-size: 10px; font-weight: 620; letter-spacing: 0; text-transform: uppercase; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.metric .v { font-size: 19px; font-weight: 640; color: var(--text); letter-spacing: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.metric .s { font-size: 11px; color: var(--faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* equity hero: headline + spark on the left, allocation donut on the right */
.equity-hero { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 24px; align-items: start; }
.equity-spark { height: 64px; max-width: 560px; }
.equity-spark-empty { padding: 22px 0 4px; }
.hero-donut { padding: 12px 16px; border-radius: 12px; background: color-mix(in srgb, var(--panel) 70%, transparent); border: 1px solid var(--line); min-width: 300px; }
/* metric strip that lives inside the hero card — top divider, no outer border */
.metric-strip.in-card { border-bottom: 0; border-top: 1px solid var(--line); margin: 14px -18px -4px; padding: 0 18px; }
@media (max-width: 900px) {
  .equity-hero { grid-template-columns: 1fr; }
  .equity-spark { max-width: none; }
  .hero-donut { min-width: 0; }
}

/* connect card (dashboard not-connected state) */
.connect-card { border-left: 3px solid var(--accent); }
.connect-inner { display: flex; align-items: flex-start; gap: 12px; }

/* ---- dashboard control room ---- */
.dashboard-page {
  max-width: min(1680px, 100%);
}

.dashboard-head {
  margin-top: 42px;
}

.dashboard-head .page-title {
  font-size: 50px;
  line-height: 1.02;
  font-weight: 620;
  letter-spacing: 0;
}

.page-kicker {
  color: var(--text-2);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
  margin-bottom: 10px;
}

.dashboard-head .head-actions {
  align-self: flex-start;
}

.dashboard-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(340px, 450px);
  gap: 24px;
  align-items: stretch;
  overflow: hidden;
  margin-top: 8px;
  padding: 24px 26px;
  background: color-mix(in srgb, var(--panel) 94%, transparent);
  border-color: var(--line-2);
  box-shadow: var(--glass-highlight), 0 1px 1px rgba(16,20,28,.035);
}

.dashboard-hero.mode-halted {
  border-color: color-mix(in srgb, var(--down) 11%, var(--line-2));
}

.dashboard-hero.mode-live_armed {
  border-color: color-mix(in srgb, var(--up) 14%, var(--line-2));
}

.dashboard-hero-main {
  min-width: 0;
}

.dash-eyebrow,
.dash-hero-actions,
.dash-equity-sub {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
}

.dash-eyebrow {
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
}

.dash-eyebrow > span:not(.state-pill) {
  display: inline-flex;
  align-items: center;
  min-height: auto;
  padding: 0;
  border-radius: 0;
  background: transparent;
  border: 0;
  color: var(--muted);
}

.dash-equity-label {
  margin-top: 22px;
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
}

.dash-equity {
  margin-top: 7px;
  color: var(--text);
  font-size: 50px;
  font-weight: 620;
  line-height: 1;
  letter-spacing: 0;
}

.dash-equity-empty {
  display: block;
  max-width: 700px;
  font-size: 40px;
  font-weight: 590;
  line-height: 1;
}

.dash-equity-sub {
  margin-top: 14px;
  max-width: 720px;
  color: var(--text-2);
  font-size: 15px;
  line-height: 1.6;
}

.dash-equity-sub .up,
.dash-equity-sub .down {
  font-weight: 650;
}

.dash-hero-actions {
  margin-top: 22px;
}

.dash-spark-shell {
  margin-top: 20px;
  min-height: 74px;
  padding: 14px 0 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.dash-spark-shell svg {
  width: 100%;
  height: 86px;
  display: block;
}

.dash-spark-empty {
  min-height: 52px;
  display: grid;
  align-content: center;
  gap: 6px;
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.45;
}

.dash-readiness {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-content: start;
  gap: 12px;
  padding: 4px 0 4px 20px;
  border: 0;
  border-left: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.dash-readiness-ring {
  --score: 0%;
  width: 78px;
  height: 78px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: conic-gradient(var(--accent) 0 var(--score), color-mix(in srgb, var(--line-2) 72%, transparent) var(--score) 100%);
  box-shadow: inset 0 0 0 9px color-mix(in srgb, var(--panel) 92%, transparent);
}

.dash-readiness-ring span {
  color: var(--text);
  font-size: 16px;
  font-weight: 640;
}

.dash-readiness-title {
  color: var(--text);
  font-size: 16px;
  font-weight: 600;
}

.dash-readiness-sub {
  margin-top: 5px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.dash-readiness-list {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 14px;
  margin-top: 2px;
  border-top: 1px solid var(--line);
}

.dash-readiness-item {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 9px 0;
  border-radius: 0;
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--line);
}
.dash-readiness-item:last-child { border-bottom: 0; }

.dash-readiness-item > span:first-child {
  width: 30px;
  height: 30px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  color: var(--muted);
  background: color-mix(in srgb, var(--tile) 58%, transparent);
  box-shadow: none;
}

.dash-readiness-item.ok > span:first-child { color: var(--up); background: var(--up-soft); }
.dash-readiness-item.bad > span:first-child { color: var(--down); background: var(--down-soft); }
.dash-readiness-item.warn > span:first-child { color: var(--accent); background: var(--accent-soft); }
.dash-readiness-item b {
  display: block;
  color: var(--text);
  font-size: 12px;
  font-weight: 660;
}
.dash-readiness-item em {
  display: block;
  color: var(--muted);
  font-size: 11.5px;
  font-style: normal;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-metrics {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0;
  margin-top: 22px;
  border-top: 1px solid var(--line-2);
  border-bottom: 1px solid var(--line-2);
  background: color-mix(in srgb, var(--panel) 90%, transparent);
}

.dash-metric-card {
  position: relative;
  min-width: 0;
  min-height: 132px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 18px 18px 16px;
  border-radius: 0;
  background: transparent;
  border: 0;
  border-right: 1px solid var(--line);
  box-shadow: none;
  overflow: hidden;
}
.dash-metric-card:last-child { border-right: 0; }

.dash-metric-card::after {
  display: none;
}

.dash-metric-icon {
  width: 32px;
  height: 32px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  flex: none;
  color: var(--muted);
  background: color-mix(in srgb, var(--tile) 76%, transparent);
  box-shadow: 0 0 0 1px var(--line);
}

.dash-metric-card.ok .dash-metric-icon { color: var(--up); background: var(--up-soft); }
.dash-metric-card.bad .dash-metric-icon { color: var(--down); background: var(--down-soft); }
.dash-metric-card.warn .dash-metric-icon { color: var(--accent); background: var(--accent-soft); }

.dash-metric-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.dash-metric-label {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dash-metric-value {
  margin-top: 7px;
  color: var(--text);
  font-size: 24px;
  font-weight: 680;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dash-metric-sub {
  margin-top: 7px;
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 590;
  line-height: 1.35;
}

.dash-meter {
  display: block;
  height: 5px;
  margin-top: 10px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--line-2) 64%, transparent);
  overflow: hidden;
}

.dash-meter i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--up), var(--accent));
}

.dash-decision-board {
  margin-top: 22px;
  padding: 0;
  overflow: hidden;
  background: color-mix(in srgb, var(--panel) 92%, transparent);
  border-color: var(--line-2);
}

.dash-decision-head {
  min-height: 74px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 18px 22px;
  border-bottom: 1px solid var(--line);
}

.dash-decision-head span:not(.state-pill) {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
}

.dash-decision-head h2 {
  margin: 5px 0 0;
  color: var(--text);
  font-size: 22px;
  line-height: 1.08;
  font-weight: 670;
  letter-spacing: 0;
}

.dash-decision-grid {
  display: grid;
  grid-template-columns: 1.25fr repeat(4, minmax(0, 1fr));
  min-width: 0;
}

.dash-decision-item {
  position: relative;
  min-width: 0;
  min-height: 176px;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  align-items: start;
  gap: 12px;
  padding: 20px;
  border: 0;
  border-right: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
  overflow: hidden;
}

.dash-decision-item:last-child {
  border-right: 0;
}

.dash-decision-item::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0;
  background:
    radial-gradient(circle at 16% 0%, color-mix(in srgb, currentColor 12%, transparent), transparent 36%),
    linear-gradient(180deg, rgba(255,255,255,.18), transparent 58%);
  pointer-events: none;
  transition: opacity .18s ease;
}

.dash-decision-item:hover::before {
  opacity: 1;
}

/* dark: no white sheen on hover — a quiet tile lift is enough */
[data-theme="dark"] .dash-decision-item::before {
  background: radial-gradient(circle at 16% 0%, color-mix(in srgb, currentColor 7%, transparent), transparent 36%);
}

.dash-decision-item:hover {
  background: color-mix(in srgb, var(--tile-hover) 76%, transparent);
}

.dash-decision-item.primary {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--tile) 80%, transparent), transparent 74%),
    color-mix(in srgb, var(--panel) 88%, transparent);
}

.dash-decision-icon {
  position: relative;
  z-index: 1;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  color: var(--muted);
  background: color-mix(in srgb, var(--tile) 78%, transparent);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.42), 0 0 0 1px var(--line);
}

.dash-decision-item.ok .dash-decision-icon { color: var(--up); background: var(--up-soft); }
.dash-decision-item.warn .dash-decision-icon { color: var(--accent-ink); background: var(--accent-soft); }
.dash-decision-item.bad .dash-decision-icon { color: var(--down); background: var(--down-soft); }
[data-theme="dark"] .dash-decision-item.warn .dash-decision-icon { color: var(--accent); }

.dash-decision-copy {
  position: relative;
  z-index: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.dash-decision-meta {
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 0;
  text-transform: uppercase;
}

.dash-decision-copy b {
  margin-top: 7px;
  color: var(--text);
  font-size: 16px;
  line-height: 1.16;
  font-weight: 640;
}

.dash-decision-item.primary .dash-decision-copy b {
  font-size: 19px;
}

.dash-decision-copy em {
  margin-top: 8px;
  color: var(--text-2);
  font-size: 12.5px;
  line-height: 1.45;
  font-style: normal;
}

.dash-decision-action {
  position: relative;
  z-index: 1;
  justify-self: start;
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 11px;
  border-radius: 10px;
  color: var(--text);
  background: color-mix(in srgb, var(--tile) 86%, transparent);
  box-shadow: 0 0 0 1px var(--line);
  font-size: 12px;
  font-weight: 600;
}

.dash-decision-item:hover .dash-decision-action {
  background: var(--text);
  color: var(--bg);
  box-shadow: none;
}

.dash-setup-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: flex-start;
  gap: 16px;
  margin-top: 22px;
  border-left: 0;
  border-color: color-mix(in srgb, var(--accent) 34%, var(--line-2));
}

.dash-setup-icon,
.dash-panel-icon {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  flex: none;
  color: var(--accent-ink);
  background: var(--accent-soft);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 18%, transparent);
}

[data-theme="dark"] .dash-setup-icon,
[data-theme="dark"] .dash-panel-icon {
  color: var(--accent);
}

.dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(330px, 430px);
  gap: 18px;
  margin-top: 22px;
}

.dash-main-lane,
.dash-side-lane {
  min-width: 0;
  display: grid;
  gap: 16px;
  align-content: start;
}

.dash-panel-head {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  min-width: 0;
  margin-bottom: 18px;
}

.dash-panel-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.dash-panel-title {
  color: var(--text);
  font-size: 19px;
  font-weight: 660;
}

.dash-panel-sub {
  margin-top: 4px;
  color: var(--text-2);
  font-size: 13px;
  line-height: 1.45;
}

.dash-panel-action {
  margin-left: auto;
  flex: none;
}

.dash-op-columns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.dash-op-panel {
  min-width: 0;
  min-height: 248px;
  padding: 0 2px;
  border-radius: 0;
  background: transparent;
  border: 0;
}

.dash-op-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.dash-op-head span {
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
}

.dash-op-head b {
  color: var(--muted);
  font-size: 12px;
}

.dash-compact-empty {
  min-height: 152px;
  display: grid;
  place-content: center;
  gap: 7px;
  text-align: center;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.dash-compact-empty b {
  color: var(--text);
  font-size: 13.5px;
  font-weight: 600;
}

.dash-timeline {
  display: grid;
  gap: 3px;
}

.dash-timeline-row {
  width: 100%;
  display: grid;
  grid-template-columns: 52px 10px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 36px;
  padding: 7px 9px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.dash-timeline-row:hover {
  background: var(--hover);
}

.dash-timeline-time {
  color: var(--faint);
  font-size: 11.5px;
}

.dash-timeline-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.dash-timeline-copy {
  color: var(--text);
  font-size: 13px;
  font-weight: 560;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dash-timeline-symbol {
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0;
}

.dash-symbol-field {
  display: grid;
  gap: 7px;
}

.dash-symbol-field span {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
}

.dash-symbol-field input {
  width: 100%;
  height: 46px;
  border: 1px solid color-mix(in srgb, var(--glass-border) 64%, transparent);
  border-radius: 14px;
  padding: 0 13px;
  outline: none;
  color: var(--text);
  background: color-mix(in srgb, var(--tile) 82%, transparent);
  font-size: 15px;
  font-weight: 600;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.42);
}

.dash-symbol-field input:focus {
  border-color: color-mix(in srgb, var(--accent) 56%, var(--glass-border));
  box-shadow: 0 0 0 3px var(--accent-soft), inset 0 1px 0 rgba(255,255,255,.42);
}

.dash-ticket-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
  margin-top: 12px;
}

.dash-ticket-actions .cta-pill {
  justify-content: center;
}

.dash-guard-note {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 12px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.dash-guard-note svg {
  flex: none;
  margin-top: 1px;
}

.dash-system-row,
.dash-proposal-row,
.dash-asset-row {
  width: 100%;
  display: grid;
  align-items: center;
  gap: 10px;
  min-height: 38px;
}

.dash-system-row {
  grid-template-columns: auto minmax(0, 1fr) auto;
  padding: 8px 0;
  border-top: 1px solid var(--line);
}

.dash-system-row:first-of-type {
  border-top: 0;
}

.dash-system-row span:not(.dot):not(.state-pill) {
  color: var(--text);
  font-size: 13px;
  font-weight: 620;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dash-system-row b {
  color: var(--text);
  font-size: 12px;
  font-weight: 640;
  white-space: nowrap;
}

.dash-proposal-list {
  display: grid;
  gap: 7px;
  margin-top: 12px;
}

.dash-proposal-row,
.dash-asset-row {
  grid-template-columns: auto minmax(0, 1fr) auto;
  border: 0;
  border-radius: 14px;
  padding: 9px;
  background: color-mix(in srgb, var(--tile) 70%, transparent);
  color: inherit;
  text-align: left;
  cursor: pointer;
  border: 1px solid transparent;
}

.dash-proposal-row:hover,
.dash-asset-row:hover {
  background: var(--tile-hover);
  border-color: color-mix(in srgb, var(--glass-border) 58%, transparent);
}

.dash-proposal-row span,
.dash-asset-row span {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.dash-proposal-row b,
.dash-asset-row b {
  color: var(--text);
  font-size: 13px;
  font-weight: 650;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dash-proposal-row em,
.dash-asset-row em {
  color: var(--muted);
  font-size: 11px;
  font-style: normal;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dash-proposal-row strong,
.dash-asset-row strong {
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
}

.dash-donut-line {
  display: grid;
  place-items: center;
  min-height: 126px;
  margin: -2px 0 8px;
}

@media (max-width: 1360px) {
  .dashboard-metrics {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .dash-metric-card:nth-child(3n) {
    border-right: 0;
  }
  .dash-metric-card:nth-child(n + 4) {
    border-top: 1px solid var(--line);
  }
  .dashboard-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .dash-decision-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .dash-decision-item {
    border-right: 1px solid var(--line);
    border-top: 1px solid var(--line);
  }
  .dash-decision-item:nth-child(-n + 2) {
    border-top: 0;
  }
  .dash-decision-item:nth-child(2n) {
    border-right: 0;
  }
  .dash-decision-item.primary {
    grid-column: 1 / -1;
    min-height: 150px;
  }
  .dash-side-lane {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1040px) {
  .dashboard-head .page-title {
    font-size: 50px;
  }
  .dashboard-hero {
    grid-template-columns: 1fr;
    padding: 24px;
  }
  .dash-equity,
  .dash-equity-empty {
    font-size: 42px;
  }
  .dash-readiness {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .dash-op-columns {
    grid-template-columns: 1fr;
  }
  .dash-decision-grid {
    grid-template-columns: 1fr;
  }
  .dash-decision-item,
  .dash-decision-item:nth-child(2n) {
    min-height: 0;
    grid-template-columns: 40px minmax(0, 1fr) auto;
    grid-template-rows: auto;
    align-items: center;
    border-right: 0;
    border-top: 1px solid var(--line);
  }
  .dash-decision-item:first-child {
    border-top: 0;
  }
  .dash-decision-item.primary {
    grid-column: auto;
  }
  .dash-decision-copy b,
  .dash-decision-item.primary .dash-decision-copy b {
    font-size: 15px;
  }
}

@media (max-width: 760px) {
  .dashboard-metrics,
  .dash-side-lane {
    grid-template-columns: 1fr;
  }
  .dash-metric-card,
  .dash-metric-card:nth-child(3n),
  .dash-metric-card:last-child {
    border-right: 0;
  }
  .dash-metric-card:nth-child(n + 2) {
    border-top: 1px solid var(--line);
  }
  .dashboard-head .page-title {
    font-size: 36px;
  }
  .dash-equity,
  .dash-equity-empty {
    font-size: 40px;
  }
  .dash-setup-card {
    grid-template-columns: 1fr;
  }
  .dash-decision-head {
    align-items: flex-start;
    flex-direction: column;
  }
  .dash-decision-item,
  .dash-decision-item:nth-child(2n) {
    grid-template-columns: 36px minmax(0, 1fr);
    padding: 16px;
  }
  .dash-decision-action {
    grid-column: 2;
  }
  .dash-readiness {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .dash-readiness-list {
    grid-template-columns: 1fr;
  }
  .dash-readiness-ring {
    margin: 0 auto;
  }
  .dash-timeline-row {
    grid-template-columns: 46px 8px minmax(0, 1fr);
  }
  .dash-timeline-symbol {
    display: none;
  }
}


/* ---- grouped settings list ---- */
.settings-control-surface::after,
.settings-preview-card::after,
.settings-density-card::after,
.settings-posture-strip::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px;
  background: linear-gradient(135deg, var(--rim-hi), transparent 34%, transparent 68%, var(--rim-lo));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor; mask-composite: exclude;
  pointer-events: none;
}
.settings-sec { font-size: 13px; font-weight: 600; color: var(--text); letter-spacing: 0; margin: 26px 4px 9px; }
.settings-control-surface {
  position: relative;
  padding: 16px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--panel) 78%, transparent);
  backdrop-filter: saturate(140%) blur(10px);
  -webkit-backdrop-filter: saturate(140%) blur(10px);
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-highlight), var(--depth);
  margin-bottom: 12px;
}
.settings-control-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 12px;
}
.settings-control-head > span {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
.settings-control-head b {
  color: var(--text);
  font-size: 15px;
  font-weight: 600;
}
.settings-control-head em {
  color: var(--muted);
  font-size: 11.5px;
  font-style: normal;
  line-height: 1.35;
}
.settings-current-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 74px;
  height: 30px;
  padding: 0 12px;
  border-radius: 999px;
  background: var(--tile);
  color: var(--text);
  border: 1px solid var(--line);
  font-size: 11px;
  font-weight: 600;
  text-transform: capitalize;
}
.settings-preview-grid,
.settings-density-grid {
  display: grid;
  gap: 10px;
}
.settings-preview-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.settings-density-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 10px;
}
.settings-preview-card,
.settings-density-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: color-mix(in srgb, var(--tile) 80%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--rim-hi) 45%, transparent);
  text-align: left;
  overflow: hidden;
  transition: transform .14s ease, border-color .14s ease, background .14s ease, box-shadow .14s ease;
}
.settings-preview-card { padding: 10px; gap: 10px; }
.settings-density-card {
  display: grid;
  grid-template-columns: 116px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 12px;
}
.settings-preview-card:hover,
.settings-density-card:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--text) 18%, var(--line));
  background: var(--tile-hover);
}
.settings-preview-card.active,
.settings-density-card.active {
  border-color: color-mix(in srgb, var(--accent) 70%, var(--line));
  box-shadow: var(--glass-highlight), 0 0 0 3px var(--accent-soft);
}
.settings-preview-frame {
  position: relative;
  display: grid;
  grid-template-columns: 26% 1fr;
  gap: 7px;
  min-height: 96px;
  padding: 9px;
  border-radius: 11px;
  border: 1px solid color-mix(in srgb, var(--glass-border) 70%, transparent);
  background:
    linear-gradient(135deg, rgba(255,255,255,.68), rgba(255,255,255,.25)),
    radial-gradient(circle at 90% 8%, rgba(42,125,224,.22), transparent 34%);
}
.settings-preview-card.theme-dark .settings-preview-frame {
  background:
    linear-gradient(135deg, rgba(22,25,32,.95), rgba(11,12,15,.72)),
    radial-gradient(circle at 88% 12%, rgba(247,208,70,.22), transparent 36%);
}
.settings-preview-card.theme-system .settings-preview-frame {
  background:
    linear-gradient(135deg, rgba(255,255,255,.74) 0 48%, rgba(22,25,32,.92) 50% 100%),
    radial-gradient(circle at 88% 12%, rgba(247,208,70,.2), transparent 36%);
}
.preview-sidebar,
.preview-window {
  display: block;
  border-radius: 8px;
  background: color-mix(in srgb, var(--panel) 78%, transparent);
  border: 1px solid rgba(255,255,255,.42);
}
.settings-preview-card.theme-dark .preview-sidebar,
.settings-preview-card.theme-dark .preview-window {
  background: rgba(255,255,255,.08);
  border-color: rgba(255,255,255,.12);
}
.preview-window {
  padding: 8px;
}
.preview-dot-row {
  display: flex;
  gap: 4px;
  margin-bottom: 10px;
}
.preview-dot-row i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--accent);
}
.preview-dot-row i:nth-child(2) { background: var(--up); }
.preview-dot-row i:nth-child(3) { background: var(--down); }
.preview-line,
.preview-chart {
  display: block;
  border-radius: 999px;
}
.preview-line {
  width: 54%;
  height: 7px;
  margin-bottom: 7px;
  background: color-mix(in srgb, var(--text) 18%, transparent);
}
.preview-line.wide { width: 78%; }
.preview-chart {
  height: 26px;
  background:
    linear-gradient(90deg, transparent 0 14%, color-mix(in srgb, var(--up) 45%, transparent) 14% 18%, transparent 18% 34%, color-mix(in srgb, var(--accent) 48%, transparent) 34% 38%, transparent 38% 60%, color-mix(in srgb, var(--up) 45%, transparent) 60% 65%, transparent 65%),
    linear-gradient(180deg, color-mix(in srgb, var(--up-soft) 70%, transparent), transparent);
}
.settings-preview-copy,
.settings-density-card > span:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.settings-preview-copy b,
.settings-density-card b {
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
}
.settings-preview-copy em,
.settings-density-card em {
  color: var(--muted);
  font-size: 11px;
  font-style: normal;
  font-weight: 620;
}
.density-list {
  display: grid;
  gap: 5px;
  padding: 8px;
  border-radius: 11px;
  background: color-mix(in srgb, var(--panel) 76%, transparent);
  border: 1px solid var(--line);
}
.density-list span {
  display: grid;
  grid-template-columns: 14px 1fr 28px;
  align-items: center;
  gap: 7px;
  height: 15px;
}
.settings-density-card.compact .density-list span { height: 11px; }
.density-list i,
.density-list b,
.density-list em {
  display: block;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text) 16%, transparent);
}
.density-list i {
  width: 14px;
  height: 14px;
  background: var(--accent);
}
.density-list b { height: 6px; }
.density-list em { height: 6px; opacity: .7; }
.settings-group {
  position: relative;
  background: color-mix(in srgb, var(--panel) 80%, transparent);
  backdrop-filter: saturate(140%) blur(10px);
  -webkit-backdrop-filter: saturate(140%) blur(10px);
  border: 1px solid var(--glass-border);
  border-radius: 14px;
  box-shadow: var(--glass-highlight), var(--depth), 0 0 0 .5px var(--glass-edge);
  overflow: hidden;
}
.settings-group::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px;
  background: linear-gradient(135deg, var(--rim-hi) 0%, transparent 32%, transparent 66%, var(--rim-lo) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor; mask-composite: exclude; pointer-events: none;
}
.settings-row {
  position: relative; display: flex; align-items: center; gap: 13px;
  padding: 10px 16px; min-height: 54px;
}
.settings-row.clickable { cursor: pointer; }
.settings-row.clickable:hover { background: var(--hover); }
/* inset divider between rows, starting after the icon */
.settings-row + .settings-row::before {
  content: ""; position: absolute; top: 0; left: 55px; right: 0; height: 1px; background: var(--line);
}
.sr-icon { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; color: #fff; flex: none; box-shadow: inset 0 1px 0 rgba(255,255,255,.28), 0 1px 2px rgba(0,0,0,.18); }
.sr-icon svg { width: 15px; height: 15px; }
.sr-main { display: flex; flex-direction: column; min-width: 0; }
.sr-label { font-size: 13.5px; font-weight: 600; color: var(--text); }
.sr-sub { font-size: 11.5px; color: var(--muted); margin-top: 1px; line-height: 1.4; }
.sr-ctl { margin-left: auto; display: flex; align-items: center; gap: 9px; flex: none; }
.sr-value { font-size: 13px; color: var(--muted); font-weight: 550; }
.sr-check { width: 20px; height: 20px; border-radius: 6px; display: grid; place-items: center; background: var(--up); color: #fff; flex: none; font-weight: 650; font-size: 12px; box-shadow: inset 0 1px 0 rgba(255,255,255,.3); }
/* status pill for grouped rows (Connected · Active · Off) */
.state-pill { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; color: var(--muted); }
.state-pill .state-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--line-strong); flex: none; }
.state-pill.ok { color: var(--up); } .state-pill.ok .state-dot { background: var(--up); box-shadow: 0 0 0 3px var(--up-soft); }
.state-pill.bad { color: var(--down); } .state-pill.bad .state-dot { background: var(--down); box-shadow: 0 0 0 3px var(--down-soft); }
.state-pill.warn { color: var(--accent-ink); } .state-pill.warn .state-dot { background: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
[data-theme="dark"] .state-pill.warn { color: var(--accent); }
.sr-chevron { color: var(--faint); display: inline-flex; }
.sr-chevron svg { width: 15px; height: 15px; transform: rotate(-90deg); }
.settings-posture-strip {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
  overflow: hidden;
  margin: 0 0 12px;
  border-radius: 16px;
  border: 1px solid var(--glass-border);
  background: color-mix(in srgb, var(--panel) 80%, transparent);
  box-shadow: var(--glass-highlight), var(--depth);
}
.settings-posture-strip > div {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 12px;
  align-items: center;
  min-height: 78px;
  padding: 14px 16px;
}
.settings-posture-strip > div + div {
  border-left: 1px solid var(--line);
}
.posture-medal {
  grid-row: 1 / 3;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 13px;
  color: var(--muted);
  background: var(--tile);
  font-size: 11px;
  font-weight: 680;
  font-variant-numeric: tabular-nums;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.52);
}
.posture-medal.ok { color: var(--up); background: var(--up-soft); }
.posture-medal.bad { color: var(--down); background: var(--down-soft); }
.posture-medal.idle { color: var(--muted); background: var(--tile); }
.settings-posture-strip b {
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
}
.settings-posture-strip em {
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
  font-style: normal;
  font-weight: 620;
}
@media (max-width: 900px) {
  .settings-preview-grid,
  .settings-density-grid,
  .settings-posture-strip {
    grid-template-columns: 1fr;
  }
  .settings-posture-strip > div + div {
    border-left: 0;
    border-top: 1px solid var(--line);
  }
}
@media (max-width: 620px) {
  .settings-control-surface {
    border-radius: 14px;
  }
  .settings-control-head,
  .settings-row {
    align-items: stretch;
  }
  .settings-control-head,
  .settings-row {
    flex-direction: column;
  }
  .sr-ctl {
    width: 100%;
    justify-content: flex-start;
    margin-left: 0;
    flex-wrap: wrap;
  }
  .settings-density-card {
    grid-template-columns: 1fr;
  }
}

/* Settings workbench: full-page account pane with a compact left rail. */
.settings-page {
  max-width: min(1500px, 100%);
}
.settings-shell {
  display: grid;
  grid-template-columns: 252px minmax(0, 1fr);
  gap: 24px;
  align-items: start;
  margin: 34px 0 42px;
}
.settings-left-rail {
  position: sticky;
  top: calc(var(--header-h) + 18px);
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-height: 560px;
  padding: 16px;
  border-radius: 18px;
  background: color-mix(in srgb, var(--panel) 84%, transparent);
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-highlight), var(--depth);
}
.settings-left-rail::after,
.settings-account-panel::after,
.settings-setup-card::after,
.settings-section .settings-control-surface::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px;
  background: linear-gradient(135deg, var(--rim-hi), transparent 34%, transparent 70%, var(--rim-lo));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor; mask-composite: exclude;
  pointer-events: none;
}
.settings-identity {
  display: grid;
  justify-items: center;
  gap: 4px;
  padding: 12px 10px 14px;
  border-bottom: 1px solid var(--line);
  text-align: center;
}
.settings-identity b {
  color: var(--text);
  font-size: 14px;
  font-weight: 680;
}
.settings-identity em {
  color: var(--muted);
  font-size: 11px;
  font-style: normal;
  font-weight: 560;
}
.settings-app-mark {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 13px;
  color: #f7d046;
  background: linear-gradient(145deg, #1a1d24, #05070a);
  border: 1px solid rgba(255,255,255,.14);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.16), 0 8px 20px rgba(0,0,0,.18);
  font-size: 13px;
  font-weight: 600;
}
.settings-app-mark.large {
  width: 72px;
  height: 72px;
  border-radius: 18px;
  font-size: 18px;
}
.settings-rail-list {
  display: grid;
  gap: 6px;
}
.settings-rail-item {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 42px;
  padding: 7px 9px;
  border-radius: 12px;
  color: var(--text-2);
  border: 1px solid transparent;
  font-size: 13px;
  font-weight: 620;
}
.settings-rail-item:hover {
  color: var(--text);
  background: var(--hover);
}
.settings-rail-item.active {
  color: var(--text);
  background: color-mix(in srgb, var(--accent-soft) 66%, var(--tile));
  border-color: color-mix(in srgb, var(--accent) 34%, var(--line));
}
.settings-rail-status {
  margin-top: auto;
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr);
  column-gap: 9px;
  row-gap: 2px;
  padding: 12px;
  border-radius: 14px;
  background: var(--tile);
  border: 1px solid var(--line);
}
.settings-rail-status b {
  color: var(--text);
  font-size: 12.5px;
  font-weight: 680;
}
.settings-rail-status em {
  grid-column: 2;
  color: var(--muted);
  font-size: 11px;
  font-style: normal;
  line-height: 1.35;
}
.mode-dot {
  width: 8px;
  height: 8px;
  margin-top: 5px;
  border-radius: 50%;
  background: var(--line-strong);
}
.mode-dot.ok { background: var(--up); box-shadow: 0 0 0 4px var(--up-soft); }
.mode-dot.warn { background: var(--accent); box-shadow: 0 0 0 4px var(--accent-soft); }
.mode-dot.idle { background: var(--line-strong); }
.settings-source-line {
  color: var(--faint);
  font-size: 10.5px;
  line-height: 1.45;
}
.settings-section {
  scroll-margin-top: calc(var(--header-h) + 18px);
}
.settings-section-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin: 0 0 11px;
}
.settings-section-head h2 {
  margin: 0;
  color: var(--text);
  font-size: 24px;
  line-height: 1.1;
  font-weight: 660;
}
.settings-section-head p {
  max-width: 720px;
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}
.settings-account-panel {
  position: relative;
  overflow: hidden;
  padding: 22px;
  border-radius: 18px;
  background:
    radial-gradient(circle at 12% 4%, color-mix(in srgb, var(--accent-soft) 62%, transparent), transparent 30%),
    color-mix(in srgb, var(--panel) 86%, transparent);
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-highlight), var(--depth);
}
.settings-account-hero {
  display: grid;
  grid-template-columns: 86px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
}
.settings-account-hero h1 {
  margin: 3px 0 7px;
  color: var(--text);
  font-size: 34px;
  line-height: 1.05;
  font-weight: 650;
}
.settings-account-hero p {
  max-width: 760px;
  margin: 0;
  color: var(--text-2);
  font-size: 14px;
  line-height: 1.5;
}
.settings-fact-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  margin: 18px 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: color-mix(in srgb, var(--tile) 66%, transparent);
}
.settings-fact {
  position: relative;
  min-height: 82px;
  padding: 15px 16px 14px;
}
.settings-fact + .settings-fact {
  border-left: 1px solid var(--line);
}
.settings-fact::before {
  content: "";
  display: block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  margin-bottom: 11px;
  background: var(--line-strong);
}
.settings-fact.ok::before { background: var(--up); box-shadow: 0 0 0 4px var(--up-soft); }
.settings-fact.warn::before { background: var(--accent); box-shadow: 0 0 0 4px var(--accent-soft); }
.settings-fact.bad::before { background: var(--down); box-shadow: 0 0 0 4px var(--down-soft); }
.settings-fact span {
  display: block;
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 640;
}
.settings-fact b {
  display: block;
  margin-top: 4px;
  color: var(--text);
  font-size: 13.5px;
  font-weight: 620;
}
.settings-pane-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.settings-section .settings-control-surface,
.settings-setup-card {
  position: relative;
}
.settings-section .settings-control-surface {
  margin-bottom: 12px;
}
.settings-setup-card {
  margin: 12px 0;
  padding: 18px 20px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--panel) 82%, transparent);
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-highlight), var(--depth);
}
.settings-section .settings-posture-strip {
  margin-top: 12px;
}
@media (max-width: 1100px) {
  .settings-shell {
    grid-template-columns: 1fr;
  }
  .settings-left-rail {
    position: relative;
    top: auto;
    min-height: 0;
  }
  .settings-rail-list {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .settings-rail-item {
    justify-content: center;
  }
}
@media (max-width: 760px) {
  .settings-shell {
    margin-top: 22px;
  }
  .settings-rail-list,
  .settings-fact-grid,
  .settings-preview-grid,
  .settings-density-grid {
    grid-template-columns: 1fr;
  }
  .settings-fact + .settings-fact {
    border-left: 0;
    border-top: 1px solid var(--line);
  }
  .settings-account-hero {
    grid-template-columns: 1fr;
  }
  .settings-account-hero h1 {
    font-size: 28px;
  }
  .settings-pane-actions .cta-pill,
  .settings-pane-actions .mini-btn {
    width: 100%;
    justify-content: center;
  }
}

/* allocation donut */
.donut-wrap { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.donut-legend { display: flex; flex-direction: column; gap: 3px; min-width: 180px; flex: 1; }
.donut-leg-row { display: flex; align-items: center; gap: 8px; font-size: 12.5px; padding: 2px 0; }
.donut-dot { width: 9px; height: 9px; border-radius: 3px; flex: none; }
.donut-leg-name { font-weight: 620; color: var(--text); }
.donut-leg-pct { margin-left: auto; font-weight: 650; }
.donut-leg-val { min-width: 74px; text-align: right; }

/* ---- account access cockpit ---- */
.account-page {
  max-width: min(1540px, 100%);
}

.account-panel {
  min-width: 0;
}

.account-panel-head {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
  margin-bottom: 16px;
}

.account-panel-icon {
  width: 32px;
  height: 32px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  color: #fff;
  background: color-mix(in srgb, var(--accent) 88%, #fff);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.34);
  flex: none;
}

.account-panel-head > span:nth-child(2) {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.account-panel-title {
  color: var(--text);
  font-size: 15px;
  font-weight: 680;
  letter-spacing: 0;
}

.account-panel-note {
  color: var(--text-2);
  font-size: 12px;
  line-height: 1.4;
}

.account-panel-right {
  margin-left: auto;
  flex: none;
}

.account-balances {
  margin-top: 16px;
}

.account-balance-layout {
  display: grid;
  grid-template-columns: minmax(240px, 330px) minmax(0, 1fr);
  gap: 18px;
  align-items: center;
}

.account-donut {
  display: grid;
  place-items: center;
  min-height: 210px;
  border-radius: 18px;
  background: color-mix(in srgb, var(--tile) 44%, transparent);
  border: 1px solid var(--line);
}

@media (max-width: 1180px) {
  .account-hero,
  .account-grid,
  .account-grid.setup,
  .account-balance-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 700px) {
  .account-panel-head {
    flex-wrap: wrap;
  }
  .account-panel-right {
    margin-left: 0;
    width: 100%;
  }
}

/* timeline as readable rows, not JSON dumps */
.tl-row { display: flex; align-items: baseline; gap: 10px; padding: 8px 0; border-bottom: 1px solid var(--line); }
.tl-row:last-child { border-bottom: 0; }
.tl-time { font-size: 11px; color: var(--faint); flex: none; width: 42px; }
.tl-body { min-width: 0; flex: 1; font-size: 13px; color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tl-body b { color: var(--text); font-weight: 620; }

/* ---- top movers cards ---- */
.mcards { display: grid; grid-template-columns: repeat(6, 1fr); gap: 13px; }
.mcard {
  background: color-mix(in srgb, var(--tile) 78%, transparent);
  border-radius: 16px; padding: 13px 14px 0; cursor: pointer;
  border: 1px solid color-mix(in srgb, var(--glass-border) 45%, transparent);
  box-shadow: var(--glass-highlight), 0 0 0 .5px var(--glass-edge);
  transition: background .15s, transform .12s, box-shadow .15s;
  overflow: hidden; text-align: left; font: inherit;
}
.mcard:hover { background: var(--tile-hover); transform: translateY(-2px); box-shadow: var(--glass-highlight), var(--shadow-md); }
.mcard-head { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.mcard-sym { font-weight: 640; font-size: 13.5px; color: var(--text); }
.mcard-px { font-size: 18px; font-weight: 640; color: var(--text); letter-spacing: 0; }
.mcard-chg { font-size: 11.5px; font-weight: 650; margin-top: 1px; }
.mcard-chart { height: 46px; margin: 6px -14px 0; }
.mcard-chart svg { width: 100%; height: 100%; display: block; }

/* ---- token identity ---- */
.tok { display: inline-flex; align-items: center; gap: 11px; min-width: 0; }
.tok-ico { width: 30px; height: 30px; border-radius: 50%; flex: none; display: block; overflow: hidden; }
.tok-ico.sm { width: 22px; height: 22px; }
.tok-ico.lg { width: 46px; height: 46px; }
.tok-mono { display: inline-flex; align-items: center; justify-content: center; border-radius: 50%; flex: none; }
/* uniform premium badge: consistent ring + subtle bg so any source looks the same */
.tok-badge {
  display: inline-flex; align-items: center; justify-content: center; flex: none;
  border-radius: 50%; overflow: hidden; background: var(--tile);
  box-shadow: inset 0 0 0 1px var(--glass-edge);
}
.tok-badge img { border-radius: 50%; }
.tok-meta { display: flex; flex-direction: column; min-width: 0; line-height: 1.25; }
.tok-name { font-weight: 620; font-size: 14px; color: var(--text); letter-spacing: 0; }
.tok-sub  { font-size: 11px; color: var(--muted); }

/* ---- chips / segs / buttons ---- */
.chips { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.chip {
  height: 31px; padding: 0 13px; border-radius: var(--r-pill); border: 0;
  background: var(--tile); color: var(--text-2); font-size: 12.5px; font-weight: 600;
  display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; transition: background .12s, color .12s;
}
.chip:hover { background: var(--tile-hover); color: var(--text); }
.chip.active { background: var(--cta-bg); color: var(--cta-fg); }
.chip-tag {
  display: inline-flex; align-items: center; gap: 5px; height: 21px; padding: 0 8px;
  border-radius: var(--r-pill); font-size: 10.5px; font-weight: 640;
  background: var(--tile); color: var(--muted);
}
.chip-tag.gold { background: var(--accent-soft); color: var(--accent-ink); }
[data-theme="dark"] .chip-tag.gold { color: var(--accent); }
.chip-tag.ok { background: var(--up-soft); color: var(--up); }
.chip-tag.bad { background: var(--down-soft); color: var(--down); }
.chip-tag.purple { background: rgba(141,125,255,.13); color: #6d5fd8; }
[data-theme="dark"] .chip-tag.purple { color: #a99bff; }

.seg { display: inline-flex; padding: 3px; gap: 2px; background: var(--tile); border-radius: var(--r-pill); }
.seg button {
  height: 34px; padding: 0 16px; border: 0; border-radius: 10px; background: transparent;
  color: var(--muted); font-size: 13px; font-weight: 620;
}
.seg button:hover { color: var(--text); }
.seg button.on { color: var(--text); background: var(--bg); box-shadow: none; }
.seg button.on.buy { color: var(--up); }
.seg button.on.sell { color: var(--down); }

.win { display: inline-flex; gap: 2px; }
.win button {
  height: 31px; min-width: 40px; padding: 0 10px; border: 0; background: transparent;
  color: var(--muted); font-size: 12.5px; font-weight: 650; border-radius: var(--r-pill);
}
.win button:hover { color: var(--text); background: var(--tile); }
.win button.on { color: var(--accent-ink); background: var(--accent-soft); }
[data-theme="dark"] .win button.on { color: var(--accent); }

/* Figma-language buttons: flat, crisp, rounded-rect. Primary is solid
   near-black (inverts to white in dark), secondary is a bordered white pill.
   Buy/sell keep their trading colors but go flat — color IS the signal. */
.cta-pill {
  height: 42px; padding: 0 22px; border-radius: 12px; border: 1px solid transparent;
  background: var(--cta-bg);
  color: var(--cta-fg); font-size: 14px; font-weight: 640; letter-spacing: 0;
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  transition: background .13s, color .13s, opacity .13s, transform .09s, box-shadow .13s;
}
.cta-pill:active { transform: scale(.98); }
.cta-pill:hover { background: color-mix(in srgb, var(--cta-bg) 82%, var(--bg)); }
.cta-pill:disabled { opacity: .35; cursor: default; }
.cta-pill:disabled:hover { background: var(--cta-bg); color: var(--cta-fg); }
.cta-pill.danger {
  background: var(--down);
  color: #fff;
  box-shadow: 0 8px 22px -14px var(--down);
}
.cta-pill.danger:hover { background: color-mix(in srgb, var(--down) 86%, #fff); }
.cta-pill.buy {
  background: var(--up);
  color: #fff;
  box-shadow: 0 8px 22px -14px var(--up);
}
.cta-pill.buy:hover { background: color-mix(in srgb, var(--up) 86%, #fff); }
.cta-pill.buy:active, .cta-pill.danger:active { transform: scale(.98); }
.mini-btn {
  height: 40px; padding: 0 16px; border-radius: 12px;
  border: 1px solid var(--line-2);
  background: transparent; color: var(--text); font-size: 13px; font-weight: 620;
  display: inline-flex; align-items: center; gap: 7px;
  transition: background .13s, border-color .13s, color .13s;
}
.mini-btn:hover { background: var(--hover); border-color: color-mix(in srgb, var(--text) 26%, var(--line-2)); }
.mini-btn:disabled { opacity: .4; cursor: default; }
.mini-btn:disabled:hover { background: transparent; border-color: var(--line-2); }
.mini-btn svg { width: 14px; height: 14px; }
.mini-btn.strong {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line-2));
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--text);
}

/* ---- unboxed market table ---- */
.table-tools { display: flex; align-items: center; gap: 10px; margin: 4px 0 2px; flex-wrap: wrap; }
.table-tools .spacer { flex: 1; }
.tsearch {
  display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 13px;
  border-radius: var(--r-pill); background: var(--tile); color: var(--muted);
}
.tsearch input { border: 0; background: none; outline: none; color: var(--text); font-size: 12.5px; width: 150px; }
.tsearch svg { width: 13px; height: 13px; }
.search-clear {
  width: 24px;
  height: 24px;
  display: inline-grid;
  place-items: center;
  flex: none;
  border: 0;
  border-radius: 50%;
  background: color-mix(in srgb, var(--tile-hover) 82%, transparent);
  color: var(--muted);
  font-size: 16px;
  line-height: 1;
  font-weight: 620;
}
.search-clear:hover {
  color: var(--text);
  background: var(--tile-hover);
}

.table-scroll { overflow-x: auto; }
table.mkt { width: 100%; border-collapse: collapse; }
.mkt thead th {
  font-size: 10.5px; font-weight: 620; letter-spacing: 0; text-transform: uppercase; color: var(--muted); text-align: right;
  padding: 10px 13px; white-space: nowrap; border-bottom: 1px solid var(--line);
  user-select: none;
}
.mkt thead th.l { text-align: left; }
.mkt thead th.sortable { cursor: pointer; }
.mkt thead th.sortable:hover { color: var(--text); }
.mkt thead th .sort-btn {
  margin: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  letter-spacing: 0;
  text-transform: inherit;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 5px;
  min-width: 0;
  white-space: nowrap;
}
.mkt thead th.l .sort-btn { justify-content: flex-start; }
.mkt thead th .sort-caret { opacity: .38; font-size: 10px; line-height: 1; }
.mkt thead th.sorted { color: var(--text); font-weight: 650; }
.mkt thead th.sorted .sort-caret { opacity: 1; }
.mkt tbody td {
  padding: 0 13px; height: 62px; text-align: right; white-space: nowrap;
  border-bottom: 1px solid var(--line); color: var(--text); font-size: 14px;
}
.mkt tbody td.l { text-align: left; }
.mkt tbody tr { transition: background .1s; }
.mkt tbody tr.rowlink { cursor: pointer; }
.mkt tbody tr:hover { background: var(--hover); }
.mkt td.val-strong, .mkt td .val-strong { color: var(--text); font-weight: 620; }
.mkt tbody td.up, .mkt tbody td .up { color: var(--up); }
.mkt tbody td.down, .mkt tbody td .down { color: var(--down); }
.mkt .idx { color: var(--faint); font-size: 12px; }
.mkt.dense tbody td { height: 46px; }
.w-star { width: 40px; } .w-idx { width: 30px; }

.star { color: var(--faint); width: 16px; height: 16px; display: inline-block; }
.star.on { color: var(--accent); }
.star-btn { background: none; border: 0; padding: 5px; display: inline-flex; border-radius: 50%; }
.star-btn:hover { background: var(--tile); }
.sparkbox { width: 96px; height: 30px; display: inline-block; vertical-align: middle; }

.table-foot {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 14px 2px 0; color: var(--muted); font-size: 12.5px; flex-wrap: wrap;
}
.pager { display: inline-flex; align-items: center; gap: 2px; }
.pager button {
  height: 30px; min-width: 30px; padding: 0 9px; border-radius: var(--r-sm);
  border: 0; background: transparent; color: var(--text-2); font-size: 12.5px; font-weight: 600;
}
.pager button:hover:not(:disabled):not(.current) { background: var(--tile); }
.pager button:disabled { opacity: .35; cursor: default; }
.pager button.current { background: var(--cta-bg); color: var(--cta-fg); }

/* ---- Markets: reference-inspired scan surface, still a private cockpit ---- */
.markets-page { max-width: min(1640px, 100%); }
.markets-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 520px);
  align-items: center;
  gap: 22px;
  margin: 24px 0 18px;
}
.market-hero-search {
  min-height: 50px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 20px;
  border-radius: var(--r-pill);
  color: var(--muted);
  background: color-mix(in srgb, var(--tile) 86%, transparent);
  border: 1px solid color-mix(in srgb, var(--glass-border) 44%, transparent);
  box-shadow: var(--glass-highlight), 0 0 0 .5px var(--glass-edge);
}
.market-hero-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  color: var(--text);
  font-size: 15px;
  font-weight: 560;
}
.market-hero-search input::placeholder { color: var(--muted); }
.market-live-panel {
  position: relative;
  display: grid;
  grid-template-columns: minmax(260px, 1.15fr) minmax(420px, 1.8fr);
  gap: 13px;
  align-items: stretch;
  margin: 16px 0 18px;
  padding: 13px;
  border-radius: 20px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--rim-hi) 42%, transparent), transparent 42%),
    color-mix(in srgb, var(--glass-strong) 78%, transparent);
  border: 1px solid color-mix(in srgb, var(--glass-border) 62%, transparent);
  box-shadow: var(--glass-highlight), var(--depth), 0 0 0 .5px var(--glass-edge);
  overflow: hidden;
}
.market-live-panel::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, var(--rim-hi), transparent 36%, transparent 72%, var(--rim-lo));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
.market-live-main {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
}
.market-live-main b {
  display: block;
  color: var(--text);
  font-size: 14px;
  font-weight: 600;
}
.market-live-main span:not(.state-pill) {
  display: block;
  color: var(--muted);
  font-size: 12px;
  font-weight: 590;
  margin-top: 2px;
}
.market-live-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}
.market-live-metric {
  min-width: 0;
  min-height: 58px;
  padding: 9px 10px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--glass-border) 44%, transparent);
  background: color-mix(in srgb, var(--tile) 66%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--rim-hi) 58%, transparent);
  text-align: left;
  font: inherit;
}
button.market-live-metric:hover { background: var(--tile-hover); }
.market-live-metric span {
  display: block;
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  text-transform: uppercase;
}
.market-live-metric b {
  display: block;
  color: var(--text);
  font-size: 15px;
  font-weight: 600;
  margin-top: 5px;
  overflow: hidden;
  text-overflow: ellipsis;
}
.market-feed-pills {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  border-top: 1px solid color-mix(in srgb, var(--line) 74%, transparent);
  padding: 11px 4px 0;
}
.feed-pill,
.refresh-rate {
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border-radius: var(--r-pill);
  background: color-mix(in srgb, var(--tile) 68%, transparent);
  color: var(--text-2);
  font-size: 11.5px;
  font-weight: 660;
}
.refresh-rate {
  margin-left: auto;
  padding-right: 4px;
}
.refresh-rate button {
  height: 22px;
  min-width: 30px;
  border: 0;
  border-radius: var(--r-pill);
  background: transparent;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}
.refresh-rate button:hover { background: var(--tile-hover); color: var(--text); }
.refresh-rate button.active { background: var(--cta-bg); color: var(--cta-fg); }
.markets-page .stats {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}
.market-scan-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 13px;
  margin: 18px 0 18px;
}
.market-scan-card,
.market-table-card,
.market-rail-card {
  position: relative;
  background: color-mix(in srgb, var(--panel) 82%, transparent);
  border: 1px solid color-mix(in srgb, var(--glass-border) 60%, transparent);
  box-shadow: var(--glass-highlight), var(--depth), 0 0 0 .5px var(--glass-edge);
}
.market-scan-card::after,
.market-table-card::after,
.market-rail-card::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, var(--rim-hi) 0%, transparent 34%, transparent 68%, var(--rim-lo) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
.market-scan-card {
  min-height: 170px;
  padding: 15px;
  border-radius: 18px;
}
.market-scan-head,
.market-rail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 11px;
}
.market-scan-title,
.market-rail-head h3 {
  margin: 0;
  color: var(--text);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0;
}
.market-scan-note,
.market-rail-head span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 620;
  margin-top: 2px;
}
.market-scan-list,
.funding-board,
.market-context-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.market-rail-row {
  min-width: 0;
  min-height: 38px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 5px 2px;
  border: 0;
  border-radius: 10px;
  background: none;
  font: inherit;
  text-align: left;
}
.market-rail-row:hover { background: var(--hover); }
.market-rail-metric {
  color: var(--text);
  font-weight: 640;
  font-size: 13px;
  white-space: nowrap;
}
.markets-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  gap: 18px;
  align-items: start;
  margin-top: 26px;
}
.market-table-card {
  min-width: 0;
  padding: 18px;
  border-radius: 20px;
}
.market-table-head {
  margin: 0 0 14px;
}
.market-health {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.row-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
}
.market-rail {
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: sticky;
  top: 78px;
}
.market-rail-card {
  border-radius: 18px;
  padding: 15px;
  overflow: hidden;
}
.rail-mover-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}
.rail-mover-card {
  min-height: 114px;
  padding: 12px;
  border: 0;
  border-radius: 16px;
  background: var(--tile);
  text-align: left;
  font: inherit;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 5px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.18);
}
.rail-mover-card:hover {
  background: var(--tile-hover);
  transform: translateY(-1px);
}
.rail-mover-symbol {
  color: var(--muted);
  font-size: 11px;
  font-weight: 680;
}
.rail-mover-change {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0;
}
.rail-mover-price {
  color: var(--text);
  font-size: 12px;
  font-weight: 680;
}

/* ---- dark: Binance-flat Markets — strips and columns, not tiles ----
   The KPI row becomes a divided stat strip, the live panel and scan cards
   flatten onto the page, the table sits directly on the bg like Coinbase
   Explore, and the rail hangs off one structural hairline. */
[data-theme="dark"] .markets-page .stats {
  gap: 0;
  margin-top: 26px;
  border-top: 1px solid var(--line-2);
  border-bottom: 1px solid var(--line-2);
}
[data-theme="dark"] .markets-page .stats .stat-tile {
  background: transparent;
  border-radius: 0;
  border-right: 1px solid var(--line-2);
  padding: 15px 18px 13px;
}
[data-theme="dark"] .markets-page .stats .stat-tile:last-child { border-right: 0; }
[data-theme="dark"] .markets-page .stats .stat-tile:hover { background: var(--hover); transform: none; }

[data-theme="dark"] .market-live-panel {
  background: transparent;
  border: 0;
  border-radius: 0;
  border-bottom: 1px solid var(--line-2);
  box-shadow: none;
  padding: 0 0 14px;
  margin: 20px 0 6px;
}
[data-theme="dark"] .market-live-panel::after { display: none; }
[data-theme="dark"] .market-live-main { padding: 6px 0; }
[data-theme="dark"] .market-live-metrics { gap: 0; }
[data-theme="dark"] .market-live-metric {
  background: transparent;
  border: 0;
  border-left: 1px solid var(--line-2);
  border-radius: 0;
  box-shadow: none;
  min-height: 0;
  padding: 6px 16px;
}
[data-theme="dark"] button.market-live-metric:hover { background: var(--hover); }
[data-theme="dark"] .feed-pill { background: transparent; padding: 0 8px 0 0; }
[data-theme="dark"] .refresh-rate { background: transparent; }

[data-theme="dark"] .market-scan-grid {
  gap: 0;
  margin: 0 0 8px;
  border-bottom: 1px solid var(--line-2);
}
[data-theme="dark"] .market-scan-card {
  background: transparent;
  border: 0;
  border-right: 1px solid var(--line-2);
  border-radius: 0;
  box-shadow: none;
  min-height: 0;
  padding: 16px 16px 14px;
}
[data-theme="dark"] .market-scan-grid .market-scan-card:first-child { padding-left: 2px; }
[data-theme="dark"] .market-scan-grid .market-scan-card:last-child { border-right: 0; }
[data-theme="dark"] .market-scan-card::after { display: none; }

[data-theme="dark"] .market-table-card {
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  padding: 0;
}
[data-theme="dark"] .market-table-card::after { display: none; }
[data-theme="dark"] .markets-layout { margin-top: 30px; }
[data-theme="dark"] .market-rail {
  border-left: 1px solid var(--line-2);
  padding-left: 18px;
  gap: 28px;
}
[data-theme="dark"] .market-rail-card {
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  padding: 0;
  overflow: visible;
}
[data-theme="dark"] .market-rail-card::after { display: none; }
[data-theme="dark"] .rail-mover-card { background: var(--panel); box-shadow: none; }
[data-theme="dark"] .rail-mover-card:hover { background: var(--tile); }
.funding-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 46px;
  padding: 6px 4px;
  border: 0;
  border-radius: 11px;
  background: none;
  text-align: left;
  font: inherit;
}
.funding-row:hover { background: var(--hover); }
.funding-metrics {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  font-size: 12px;
  font-weight: 640;
  white-space: nowrap;
}
.market-rail-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px solid var(--line);
  margin-top: 9px;
  padding-top: 10px;
  color: var(--muted);
  font-size: 12px;
}
.market-rail-footer b {
  color: var(--text);
  font-size: 13px;
}
.market-context-list {
  margin-bottom: 12px;
}
.market-context-list div {
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
}
.market-context-list div:last-child { border-bottom: 0; }
.market-context-list b {
  color: var(--text);
  font-size: 13px;
}
.market-rail-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 2px 0 10px;
}
.market-rail-actions .mini-btn {
  flex: 1;
  justify-content: center;
}
.rail-rate {
  width: 100%;
  justify-content: space-between;
  margin: 0 0 10px;
  padding-left: 11px;
}

/* value / cell flashes */
@keyframes cgFlashUp { 0%, 55% { color: var(--up); } 100% { color: inherit; } }
@keyframes cgFlashDown { 0%, 55% { color: var(--down); } 100% { color: inherit; } }
.flash-up { animation: cgFlashUp 1.4s ease-out; }
.flash-down { animation: cgFlashDown 1.4s ease-out; }
@keyframes cellUp   { from { background: var(--up-soft); }   to { background: transparent; } }
@keyframes cellDown { from { background: var(--down-soft); } to { background: transparent; } }
.cell-up   { animation: cellUp .8s ease-out; border-radius: 6px; }
.cell-down { animation: cellDown .8s ease-out; border-radius: 6px; }

/* status dots */
.dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; flex: none; }
.dot-live  { background: var(--up); box-shadow: 0 0 0 3px var(--up-soft); }
.dot-stale { background: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.dot-off   { background: var(--down); box-shadow: 0 0 0 3px var(--down-soft); }
.dot-none  { background: var(--line-strong); }
.status-mini { display: inline-flex; align-items: center; gap: 7px; font-size: 12px; color: var(--muted); }

/* ---- asset detail ---- */
.back-link { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 13px; font-weight: 600; margin-top: 16px; border: 0; background: none; }
.back-link:hover { color: var(--text); }
.back-link svg { width: 15px; height: 15px; }
.detail-top { display: flex; align-items: center; gap: 15px; margin: 16px 0 8px; flex-wrap: wrap; }
.detail-name { font-size: 24px; font-weight: 650; letter-spacing: 0; color: var(--text); line-height: 1.1; }
.detail-sub { color: var(--muted); font-size: 13px; margin-top: 2px; }
.detail-head-actions { margin-left: auto; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

.chart-shell { margin-top: 2px; }
.token-chart-card {
  margin-top: 14px;
  padding: 15px 18px 12px;
  overflow: hidden;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--rim-hi) 16%, transparent), transparent 42%),
    color-mix(in srgb, var(--glass-strong) 78%, var(--panel));
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
}
.token-chart-card::before {
  content: "";
  position: absolute;
  right: -120px;
  top: -100px;
  width: 360px;
  height: 240px;
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle, color-mix(in srgb, var(--accent) 14%, transparent), transparent 68%);
  opacity: .5;
}
.token-chart-card .chart-head,
.token-chart-card .chart-body,
.token-chart-card .chart-source-strip {
  position: relative;
  z-index: 2;
}
.chart-head { display: flex; align-items: center; gap: 12px; margin-bottom: 4px; flex-wrap: wrap; }
.chart-head .spacer { flex: 1; }
.chart-body { position: relative; }
.chart-svg { display: block; width: 100%; }
.chart-anim-area { animation: areaIn .8s ease-out both; }
@keyframes areaIn { from { opacity: 0; } to { opacity: 1; } }
.chart-tip {
  position: absolute; pointer-events: none; z-index: 5; padding: 7px 10px;
  background: var(--text); color: var(--bg); border-radius: 9px; font-size: 12px;
  box-shadow: var(--shadow-md); white-space: nowrap; transform: translate(-50%, -130%);
  opacity: 0; transition: opacity .08s;
}
.chart-tip .t-val { font-weight: 650; }
.chart-tip .t-time { color: color-mix(in srgb, var(--bg) 62%, transparent); font-size: 10.5px; margin-top: 1px; }
.chart-empty { display: flex; align-items: center; justify-content: center; color: var(--muted); font-size: 13px; }

/* hairline panels below chart — no boxes */
.asset-panels { display: grid; grid-template-columns: 1.05fr 1fr 1fr; border-top: 1px solid var(--line); margin-top: 22px; }
.apanel { padding: 22px 24px 10px; border-left: 1px solid var(--line); min-width: 0; }
.apanel:first-child { border-left: 0; padding-left: 2px; }
.apanel h3 { margin: 0 0 14px; font-size: 15.5px; font-weight: 640; letter-spacing: 0; color: var(--text); }

.kv-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px 18px; }
.kv .k { font-size: 10px; font-weight: 640; letter-spacing: 0; text-transform: uppercase; color: var(--muted); margin-bottom: 4px; }
.kv .v { font-size: 16px; font-weight: 640; color: var(--text); letter-spacing: 0; }
.kv .v.sm { font-size: 13px; }

.ladder-row { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; position: relative; }
.ladder-row .bar { position: absolute; top: 4px; bottom: 4px; right: 0; border-radius: 6px; z-index: 0; }
.ladder-row .bar.ask { background: var(--down-soft); }
.ladder-row .bar.bid { background: var(--up-soft); }
.ladder-row .k, .ladder-row .v { position: relative; z-index: 1; }
.ladder-row .k { font-size: 12px; color: var(--muted); }
.ladder-row .v { font-size: 13px; font-weight: 650; color: var(--text); }
.ladder-mid { text-align: center; padding: 8px; color: var(--muted); font-size: 10.5px; letter-spacing: 0; text-transform: uppercase; }

.xrow { display: flex; align-items: center; gap: 10px; padding: 10px 2px; border-bottom: 1px solid var(--line); }
.xrow:last-child { border-bottom: 0; }
.xrow .k { font-size: 13px; font-weight: 600; color: var(--text); }
.xrow .t { font-size: 11px; color: var(--muted); margin-top: 0; }
.xrow .v { margin-left: auto; font-size: 13px; font-weight: 660; text-align: right; }
.xrow .v .t { text-align: right; }

.token-detail-shell {
  max-width: 1500px;
  overflow: hidden;
}
.token-market-strip {
  margin-top: 14px;
  padding: 15px 16px;
  display: grid;
  grid-template-columns: minmax(280px, .9fr) minmax(360px, 1.15fr) auto;
  align-items: center;
  gap: 16px;
  overflow: hidden;
}
.market-strip-main,
.token-strip-id,
.strip-price,
.strip-metric,
.token-chart-title,
.micro-head,
.token-panel-head,
.token-data-row {
  min-width: 0;
}
.token-strip-id .detail-name,
.token-market-strip .headline-val {
  letter-spacing: 0;
}
.token-market-strip .headline-val {
  font-size: 46px;
  font-weight: 650;
  white-space: nowrap;
}
.strip-price {
  margin-top: 8px;
}
.strip-change {
  display: block;
  margin-top: 4px;
  font-size: 13px;
  font-weight: 640;
}
.strip-metrics {
  display: grid;
  grid-template-columns: repeat(5, minmax(88px, 1fr));
  gap: 8px;
}
.strip-metric {
  min-height: 58px;
  padding: 9px 10px;
  border-radius: 14px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--rim-hi) 20%, transparent), transparent 55%),
    color-mix(in srgb, var(--tile) 76%, transparent);
  box-shadow: inset 0 0 0 .5px color-mix(in srgb, var(--rim-hi) 30%, transparent);
}
.strip-label,
.micro-label,
.td-label {
  display: block;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
  color: var(--muted);
}
.strip-value {
  margin-top: 4px;
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.strip-sub {
  margin-top: 2px;
  font-size: 10.5px;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.token-market-strip .detail-head-actions {
  margin-left: 0;
  justify-content: flex-end;
}
.token-workspace {
  display: grid;
  grid-template-columns: minmax(230px, .72fr) minmax(0, 2.05fr) minmax(280px, .9fr);
  gap: 16px;
  align-items: start;
  margin-top: 16px;
}
.token-asset-card,
.micro-card,
.token-panel {
  padding: 16px;
  overflow: hidden;
}
.asset-identity {
  display: flex;
  align-items: center;
  gap: 12px;
}
.asset-title {
  display: block;
  font-size: 26px;
  font-weight: 600;
  color: var(--text);
  line-height: 1.05;
}
.asset-subtitle {
  display: block;
  margin-top: 3px;
  font-size: 11px;
  font-weight: 640;
  letter-spacing: 0;
  text-transform: uppercase;
  color: var(--muted);
}
.asset-copy {
  margin: 16px 0;
  color: var(--text);
  font-size: 13px;
  line-height: 1.5;
}
.asset-action-stack {
  display: grid;
  gap: 9px;
  margin-bottom: 14px;
}
.asset-status-list {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  margin: 12px 0;
}
.mini-btn.wide {
  width: 100%;
  justify-content: center;
}
.token-workspace .token-chart-card {
  margin-top: 0;
  min-height: 560px;
}
.token-chart-title {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 12px;
}
.token-chart-title h2 {
  margin: 0 0 3px;
  font-size: 22px;
  font-weight: 600;
  color: var(--text);
}
.token-chart-title span span,
.micro-head span,
.token-panel-head span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
}
.chart-latest {
  color: var(--text);
  font-size: 19px;
  font-weight: 600;
  text-align: right;
  white-space: nowrap;
}
.chart-latest small {
  display: block;
  margin-top: 2px;
  font-size: 11px;
  color: inherit;
}
.token-chart-controls {
  overflow: hidden;
}
.micro-head,
.token-panel-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 12px;
}
.micro-head h3,
.token-panel-head h3 {
  margin: 0;
  font-size: 16px;
  font-weight: 640;
  color: var(--text);
}
.token-data-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-top: 16px;
}
.token-panel {
  min-height: 210px;
}
.token-data-row {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.token-data-row:first-child {
  border-top: 0;
  padding-top: 0;
}
.td-sub {
  display: block;
  margin-top: 2px;
  font-size: 11px;
  color: var(--muted);
}
.td-value {
  color: var(--text);
  font-size: 13.5px;
  font-weight: 650;
  text-align: right;
  overflow-wrap: anywhere;
}
.td-value .mini-btn {
  margin-left: auto;
}

/* leaderboard-style rows with soft value bars */
.lb-row {
  position: relative; display: flex; align-items: center; gap: 11px; width: 100%;
  min-height: 46px; padding: 0 12px; margin: 0 -12px; border-radius: 10px; cursor: pointer;
  border: 0; background: none; text-align: left; font: inherit;
}
.lb-row:hover { background: var(--hover); }
.lb-bar { position: absolute; left: 0; top: 6px; bottom: 6px; border-radius: 8px; z-index: 0; }
.lb-bar.bid { background: var(--up-soft); }
.lb-bar.ask { background: var(--down-soft); }
.lb-row > *:not(.lb-bar) { position: relative; z-index: 1; }
.lb-name { font-weight: 650; font-size: 13.5px; color: var(--text); }
.lb-sub { font-size: 11px; color: var(--muted); }
.lb-val { margin-left: auto; font-size: 13.5px; font-weight: 680; text-align: right; }
.lb-val .lb-sub { display: block; }

/* ---- ticket / forms ---- */
.trade-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(330px, .72fr);
  gap: 22px;
  align-items: start;
  margin-top: 16px;
}
.trade-main { min-width: 0; }
.trade-rail {
  position: sticky;
  top: calc(var(--header-h) + 14px);
  min-width: 0;
}
.trade-card-head {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}
.trade-card-head.compact { align-items: center; margin-bottom: 12px; }
.trade-identity { display: flex; align-items: center; gap: 12px; min-width: 0; }
.trade-symbol { font-size: 22px; line-height: 1.05; font-weight: 600; letter-spacing: 0; color: var(--text); }
.trade-panel-title { font-size: 14.5px; font-weight: 650; letter-spacing: 0; color: var(--text); }
.trade-sub {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
  margin-top: 2px;
}
.trade-state-stack {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;
  flex: none;
}
.trade-icon {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  flex: none;
  color: var(--text-2);
  background:
    linear-gradient(180deg, rgba(255,255,255,.20), transparent),
    var(--tile);
  border-radius: 11px;
  box-shadow: inset 0 1px 0 var(--rim-hi), inset 0 0 0 1px var(--glass-edge);
}
.trade-icon.ok { color: var(--up); background: var(--up-soft); }
.trade-icon.bad { color: var(--down); background: var(--down-soft); }
.trade-preview-strip .v { font-size: 13px; }
.trade-input-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(220px, 1.1fr) minmax(160px, .75fr) minmax(180px, .8fr);
  gap: 12px;
  align-items: end;
}
.trade-symbol-field { grid-column: span 1; }
.trade-control-block {
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-width: 0;
  margin-bottom: 13px;
}
.trade-field-label {
  font-size: 10.5px;
  font-weight: 620;
  text-transform: uppercase;
  letter-spacing: 0;
  color: var(--muted);
}
.ticket-actions {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
  margin-top: 2px;
}
.trade-live-note {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}
.trade-await {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  color: var(--muted);
  background: color-mix(in srgb, var(--tile) 78%, transparent);
  border-radius: 14px;
}
.trade-await svg { color: var(--accent-ink); flex: none; margin-top: 1px; }
[data-theme="dark"] .trade-await svg { color: var(--accent); }
.trade-await b { display: block; color: var(--text); font-size: 13.5px; margin-bottom: 2px; }
.trade-await span { display: block; font-size: 12.5px; line-height: 1.5; }
.trade-gate-list {
  position: relative;
  z-index: 2;
  overflow: hidden;
  border-radius: 14px;
  background: color-mix(in srgb, var(--panel) 68%, transparent);
  border: 1px solid color-mix(in srgb, var(--glass-border) 54%, transparent);
}
.trade-gate-row {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 13px;
  border-bottom: 1px solid var(--line);
}
.trade-gate-row:last-child { border-bottom: 0; }
.trade-gate-row.pass .gate-mark {
  color: #fff;
  background: var(--up);
}
.trade-gate-row.fail .gate-mark {
  color: #fff;
  background: var(--down);
}
.gate-mark {
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 7px;
  flex: none;
  font-size: 12px;
  font-weight: 680;
}
.gate-main { display: flex; align-items: baseline; gap: 10px; min-width: 0; flex: 1; }
.gate-name { font-size: 13px; font-weight: 690; color: var(--text); flex: none; }
.gate-detail {
  color: var(--muted);
  font-size: 11.5px;
  margin-left: auto;
  text-align: right;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.trade-price-line {
  display: flex;
  align-items: center;
  gap: 11px;
  flex-wrap: wrap;
  margin: 8px 0 10px;
}
.trade-price-line .headline-val { font-size: 31px; letter-spacing: 0; }
.quote-ladder {
  position: relative;
  z-index: 2;
  margin-top: 8px;
}

.fld { display: flex; flex-direction: column; gap: 5px; margin-bottom: 13px; }
.fld > span { font-size: 10.5px; font-weight: 620; text-transform: uppercase; letter-spacing: 0; color: var(--muted); }
.fld input, .fld select {
  height: 40px; padding: 0 13px; border-radius: 10px; border: 1px solid transparent;
  background: var(--tile); outline: none; font-weight: 600; font-size: 13.5px; color: var(--text);
  font-variant-numeric: tabular-nums; transition: border-color .12s, background .12s;
}
.fld input:focus, .fld select:focus { border-color: var(--accent-line); background: var(--bg); }
.fld input::placeholder { color: var(--faint); }
.form-row { display: flex; gap: 10px; }
.form-row .fld { flex: 1; }

.result-strip { border-radius: 10px; padding: 10px 13px; font-weight: 600; font-size: 12.5px; margin-top: 12px; line-height: 1.45; }
.result-strip.ok { background: var(--up-soft); color: var(--up); }
.result-strip.bad { background: var(--down-soft); color: var(--down); }
.result-strip.warn { background: var(--accent-soft); color: var(--accent-ink); }
[data-theme="dark"] .result-strip.warn { color: var(--accent); }
.chip-tag.warn { background: var(--accent-soft); color: var(--accent-ink); }
.chip-tag.idle { background: color-mix(in srgb, var(--tile-hover) 80%, transparent); color: var(--muted); }
[data-theme="dark"] .chip-tag.warn { color: var(--accent); }

/* ---- overlays: modal / palette / sheet ---- */
.overlay {
  position: fixed; inset: 0; z-index: 100; background: rgba(10, 13, 18, .34);
  backdrop-filter: blur(2px); display: flex; align-items: flex-start; justify-content: center;
  padding-top: calc(11vh / var(--uiz, 1)); opacity: 0; animation: fade .12s forwards;
}
[data-theme="dark"] .overlay { background: rgba(0,0,0,.55); }
@keyframes fade { to { opacity: 1; } }
.dialog {
  width: min(470px, 92vw);
  background: var(--glass-strong); border: 1px solid var(--glass-border);
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  border-radius: 20px;
  box-shadow: var(--shadow-pop), var(--glass-highlight), 0 0 0 .5px var(--glass-edge);
  overflow: hidden;
  transform: translateY(-6px); animation: rise2 .14s forwards; padding: 20px 22px;
  max-height: calc(82vh / var(--uiz, 1)); overflow-y: auto;
}
@keyframes rise2 { to { transform: translateY(0); } }
.dialog-title { font-size: 16px; font-weight: 620; color: var(--text); margin: 0 0 12px; letter-spacing: 0; }
.dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 18px; }
.confirm-input { margin-top: 14px; display: flex; flex-direction: column; gap: 6px; font-size: 12.5px; }
.confirm-input input {
  height: 42px; padding: 0 13px; border-radius: 10px; border: 1.5px solid var(--line-2);
  outline: none; font-weight: 620; font-size: 14px; background: var(--bg); color: var(--text);
}
.confirm-input input:focus { border-color: var(--down); }

.cmd {
  width: min(600px, 92vw);
  background: var(--glass-strong); border: 1px solid var(--glass-border);
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  border-radius: 20px;
  box-shadow: var(--shadow-pop), var(--glass-highlight), 0 0 0 .5px var(--glass-edge);
  overflow: hidden;
  transform: translateY(-6px); animation: rise2 .14s forwards;
}
.cmd-input-wrap { display: flex; align-items: center; gap: 11px; padding: 14px 17px; border-bottom: 1px solid var(--line); }
.cmd-input-wrap svg { width: 17px; height: 17px; color: var(--muted); flex: none; }
.cmd-input { flex: 1; border: 0; background: transparent; font-size: 15.5px; color: var(--text); outline: none; }
.cmd-input::placeholder { color: var(--faint); }
.cmd-list { max-height: calc(50vh / var(--uiz, 1)); overflow-y: auto; padding: 6px; }
.cmd-group { font-size: 10.5px; font-weight: 620; letter-spacing: 0; text-transform: uppercase; color: var(--faint); padding: 10px 11px 4px; }
.cmd-item { display: flex; align-items: center; gap: 12px; width: 100%; padding: 9px 11px; border: 0; background: none; border-radius: 10px; cursor: pointer; text-align: left; }
.cmd-item.sel { background: var(--tile); }
.cmd-item .c-name { font-weight: 650; color: var(--text); font-size: 13.5px; }
.cmd-item .c-sub { color: var(--muted); font-size: 11.5px; }
.cmd-item .c-right { margin-left: auto; font-size: 12.5px; font-weight: 650; }
.cmd-empty { padding: 26px; text-align: center; color: var(--muted); font-size: 13px; }
.cmd-foot { display: flex; gap: 16px; padding: 9px 15px; border-top: 1px solid var(--line); color: var(--faint); font-size: 11px; }

/* toggle switch */
.switch { width: 42px; height: 24px; border-radius: 999px; background: var(--line-2); position: relative; transition: background .15s; flex: none; border: 0; }
.switch::after { content: ""; position: absolute; top: 2px; left: 2px; width: 20px; height: 20px; border-radius: 50%; background: #fff; box-shadow: var(--shadow-sm); transition: transform .15s; }
.switch.on { background: var(--accent); }
.switch.on::after { transform: translateX(18px); }
.switch.on.danger { background: var(--up); }

/* ---- health badge ---- */
.health-badge {
  position: fixed; right: 20px; bottom: 20px; z-index: 70;
  width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--glass-border);
  background: var(--glass-strong);
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  box-shadow: var(--shadow-md), var(--glass-highlight); color: var(--muted);
  display: flex; align-items: center; justify-content: center; cursor: pointer;
}
.health-badge svg { width: 19px; height: 19px; }
.health-badge .hb-dot { position: absolute; top: 4px; right: 4px; width: 10px; height: 10px; border-radius: 50%; border: 2px solid var(--bg); }
.health-badge.ok  { color: var(--up); }
.health-badge.ok .hb-dot { background: var(--up); animation: hbPulse 2.2s ease-out infinite; }
.health-badge.warn { color: var(--accent-ink); }
.health-badge.warn .hb-dot { background: var(--accent); }
.health-badge.bad { color: var(--down); }
.health-badge.bad .hb-dot { background: var(--down); animation: hbPulse 1.1s ease-out infinite; }
[data-theme="dark"] .health-badge.warn { color: var(--accent); }
@keyframes hbPulse { 0% { box-shadow: 0 0 0 0 var(--up-soft); } 70% { box-shadow: 0 0 0 9px transparent; } 100% { box-shadow: 0 0 0 0 transparent; } }
.hb-tip {
  position: absolute; right: 0; bottom: 54px; width: 235px; padding: 12px 14px;
  background: var(--glass-strong); border: 1px solid var(--glass-border); border-radius: 16px;
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  box-shadow: var(--shadow-pop), var(--glass-highlight);
  opacity: 0; pointer-events: none; transform: translateY(4px); transition: opacity .14s, transform .14s;
  text-align: left;
}
.health-badge:hover .hb-tip { opacity: 1; transform: none; }
.hb-row { display: flex; justify-content: space-between; gap: 12px; padding: 3px 0; font-size: 12px; }
.hb-row .k { color: var(--muted); }
.hb-row .v { color: var(--text); font-weight: 620; }

/* ---- misc rows / states ---- */
.drow { display: flex; align-items: center; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--line); }
.drow:last-child { border-bottom: 0; }
.drow .k { color: var(--muted); font-size: 12.5px; }
.drow .v { margin-left: auto; color: var(--text); font-size: 12.5px; font-weight: 650; font-variant-numeric: tabular-nums; text-align: right; }

.ghost-tile {
  display: flex; align-items: center; gap: 14px; padding: 14px 18px; margin: 14px 0;
  border: 1.5px dashed var(--line-2); border-radius: 14px; color: var(--muted);
}
.ghost-tile svg { width: 19px; height: 19px; flex: none; }
.gt-title { font-size: 13.5px; font-weight: 650; color: var(--text-2); }
.gt-sub { font-size: 12px; color: var(--muted); margin-top: 1px; line-height: 1.5; }
.gt-badge { margin-left: auto; font-size: 10.5px; font-weight: 620; letter-spacing: 0; text-transform: uppercase; color: var(--faint); border: 1px solid var(--line-2); border-radius: var(--r-pill); padding: 4px 10px; white-space: nowrap; flex: none; }

.setup-list { margin: 8px 0 4px; padding-left: 19px; line-height: 1.95; color: var(--muted); font-size: 12.5px; }
.setup-list b { color: var(--text-2); }

.warn-strip {
  display: flex; align-items: center; gap: 9px; margin: 12px 0;
  padding: 9px 14px; border-radius: 10px; background: var(--down-soft); color: var(--down);
  font-weight: 600; font-size: 12.5px;
}
.warn-strip svg { width: 15px; height: 15px; flex: none; }

.empty-state { padding: 44px 20px; text-align: center; color: var(--muted); }
.empty-state .e-title { font-weight: 650; color: var(--text-2); margin-bottom: 4px; font-size: 13.5px; }
.empty-state .e-body { font-size: 12.5px; max-width: 430px; margin: 0 auto; line-height: 1.55; }

/* ---- wallets / assets cockpit ---- */
.wallets-page {
  --wallet-gap: 18px;
  max-width: min(1540px, 100%);
}

.wallet-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.06fr) minmax(300px, 380px);
  align-items: stretch;
  gap: 34px;
  padding: 30px 34px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 96%, transparent), color-mix(in srgb, var(--panel) 88%, transparent));
  border-color: var(--line-2);
  overflow: hidden;
}

.wallet-hero-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.wallet-eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
}

.wallet-eyebrow > span:not(.state-pill) {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  border-radius: 9px;
  background: color-mix(in srgb, var(--tile) 45%, transparent);
  border: 1px solid var(--line);
  color: var(--text-2);
}

.wallet-balance {
  margin-top: 12px;
  color: var(--text);
  font-size: 34px;
  font-weight: 680;
  letter-spacing: -.02em;
  line-height: 1.05;
  font-variant-numeric: tabular-nums;
}

.wallet-balance.pending {
  max-width: 700px;
  font-size: 24px;
  line-height: 1.15;
  letter-spacing: -.018em;
}

.wallet-meta,
.wallet-hero-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.wallet-meta {
  margin-top: 14px;
  color: var(--text-2);
  font-size: 13px;
  font-weight: 560;
}

.wallet-meta span {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  min-width: 0;
}

.wallet-meta b {
  color: var(--text);
  font-weight: 640;
}

.wallet-hero-actions {
  margin-top: 24px;
}

.wallet-allocation {
  min-width: 0;
  display: grid;
  place-items: center;
  min-height: 100%;
  padding: 18px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--tile) 48%, transparent);
  border: 1px solid var(--line-2);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 44%, transparent);
}

.wallet-allocation-empty {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 18px;
  width: 100%;
}

.wallet-ring-placeholder {
  position: relative;
  width: 118px;
  height: 118px;
  border-radius: 50%;
  background:
    conic-gradient(from 230deg, color-mix(in srgb, var(--accent) 38%, transparent) 0 26%, color-mix(in srgb, var(--up) 25%, transparent) 26% 54%, color-mix(in srgb, var(--muted) 18%, transparent) 54% 100%);
  box-shadow: inset 0 0 0 14px color-mix(in srgb, var(--panel) 88%, transparent), inset 0 1px 0 rgba(255,255,255,.58);
}

.wallet-ring-placeholder::after {
  content: "";
  position: absolute;
  inset: 24px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--panel) 92%, transparent);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.55);
}

.wallet-ring-placeholder span {
  position: absolute;
  border-radius: 50%;
  background: rgba(255,255,255,.5);
  filter: blur(.2px);
}

.wallet-ring-placeholder span:nth-child(1) { width: 12px; height: 12px; left: 20px; top: 18px; }
.wallet-ring-placeholder span:nth-child(2) { width: 8px; height: 8px; right: 22px; top: 34px; }
.wallet-ring-placeholder span:nth-child(3) { width: 10px; height: 10px; right: 26px; bottom: 18px; }

.wallet-mini-title {
  color: var(--text);
  font-size: 17px;
  font-weight: 680;
  letter-spacing: 0;
}

.wallet-mini-sub {
  margin-top: 4px;
  color: var(--text-2);
  font-size: 12.5px;
  line-height: 1.48;
}

.wallet-tabs {
  margin-top: 14px;
}

.wallet-tabs .atab {
  height: 48px;
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 2px;
}

.wallet-tabs .atab small {
  color: var(--faint);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
}

.wallet-empty-grid,
.wallet-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.42fr) minmax(310px, .74fr);
  gap: var(--wallet-gap);
  align-items: start;
}

.wallet-panel-head {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
  margin-bottom: 16px;
}

.wallet-panel-icon {
  width: 32px;
  height: 32px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  color: #fff;
  background: color-mix(in srgb, var(--accent) 88%, #fff);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.34);
  flex: none;
}

.wallet-panel-head > span:nth-child(2) {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.wallet-panel-title {
  color: var(--text);
  font-size: 15px;
  font-weight: 680;
  letter-spacing: 0;
}

.wallet-panel-note {
  color: var(--text-2);
  font-size: 12px;
  line-height: 1.4;
}

.wallet-panel-right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 8px;
