}

.wallet-readiness {
  display: grid;
  gap: 0;
  border: 1px solid var(--line);
  border-radius: 15px;
  overflow: hidden;
}

.wallet-readiness.cols {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-top: 16px;
}

.wallet-ready-row {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 12px 14px;
  border-radius: 0;
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--line);
}

.wallet-ready-row:last-child { border-bottom: 0; }
