.wallet-readiness.cols .wallet-ready-row:last-child { border-right: 0; }

.wallet-ready-row span {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 620;
  letter-spacing: 0;
  text-transform: uppercase;
}

.wallet-ready-row b {
  color: var(--text);
  font-size: 13px;
  font-weight: 650;
  line-height: 1.45;
}

.wallet-safe-note {
  margin-top: 14px;
  padding: 10px 12px;
  border-radius: 13px;
  color: var(--down);
  background: var(--down-soft);
  font-size: 12px;
  font-weight: 680;
}

.wallet-primary {
  min-width: 0;
}

.wallet-table .wallet-share {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
