}

.wallet-share i {
  display: block;
  height: 4px;
  min-width: 8px;
  max-width: 84px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent), color-mix(in srgb, var(--up) 64%, var(--accent)));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 15%, transparent);
}

.wallet-row-actions {
  display: flex;
