}

.wallet-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}

.wallet-mini-metric {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding: 13px 14px;
  border-radius: 13px;
  background: color-mix(in srgb, var(--tile) 42%, transparent);
  border: 1px solid var(--line);
}

.wallet-mini-metric span {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 620;
  letter-spacing: 0;
  text-transform: uppercase;
}

.wallet-mini-metric b {
  color: var(--text);
  font-size: 18px;
  font-weight: 640;
  letter-spacing: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.wallet-mini-metric small {
  color: var(--muted);
  font-size: 11px;
}

.wallet-safe-list {
  display: grid;
  gap: 8px;
}

.wallet-state-card {
  min-height: 260px;
}

.wallet-state-copy {
  display: grid;
