  .wallet-panel-head {
    flex-wrap: wrap;
  }
  .wallet-panel-head > span:nth-child(2) {
    flex: 1 1 calc(100% - 46px);
  }
}

.two-col { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(300px, .8fr); gap: 34px; align-items: start; }
