}
.pnl-day-col.pos .pnl-day-track i { background: linear-gradient(180deg, var(--up), color-mix(in srgb, var(--up) 42%, transparent)); }
.pnl-day-col.neg .pnl-day-track i { background: linear-gradient(180deg, var(--down), color-mix(in srgb, var(--down) 42%, transparent)); }
.pnl-day-label {
  color: var(--faint);
  font-size: 10px;
  text-align: center;
}

