/* left info rail (Coinbase "About") */
.token-asset-card { display: flex; flex-direction: column; gap: 14px; }
.asset-identity { display: flex; align-items: center; gap: 12px; }
.asset-identity > span { display: flex; flex-direction: column; }
.asset-title { font-size: 19px; font-weight: 600; color: var(--text); letter-spacing: 0; }
.asset-subtitle { font-size: 11.5px; color: var(--muted); }
.asset-copy { font-size: 12.5px; color: var(--text-2); line-height: 1.55; margin: 0; }
.asset-action-stack { display: flex; flex-direction: column; gap: 8px; }
.asset-action-stack .cta-pill { justify-content: center; height: 38px; }
.asset-status-list { border-top: 1px solid var(--line); padding-top: 4px; }
.mini-btn.wide { width: 100%; justify-content: center; height: 34px; }

/* center chart card */
.token-chart-card { display: flex; flex-direction: column; gap: 10px; padding: 16px 18px 12px; }
.token-chart-title { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.token-chart-title h2 { margin: 0; font-size: 16px; font-weight: 650; color: var(--text); letter-spacing: 0; }
.token-chart-title > span:first-child { display: flex; flex-direction: column; gap: 2px; }
.token-chart-title > span:first-child > span { font-size: 11px; color: var(--muted); }
.chart-latest { display: flex; flex-direction: column; align-items: flex-end; font-size: 18px; font-weight: 650; line-height: 1.1; }
.chart-latest small { font-size: 11.5px; font-weight: 650; }
.token-chart-controls { margin-top: 2px; }

/* right micro card: order book + prints */
.micro-card { padding: 0; overflow: hidden; }
.micro-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding: 14px 16px 10px; border-bottom: 1px solid var(--line); }
.micro-head h3 { margin: 0; font-size: 14px; font-weight: 650; color: var(--text); }
.micro-head > span { font-size: 10.5px; color: var(--faint); }
.book-trades-grid { display: flex; flex-direction: column; }
.micro-section { padding: 12px 14px; }
.micro-section + .micro-section { border-top: 1px solid var(--line); }
.micro-label { font-size: 10px; font-weight: 620; letter-spacing: 0; text-transform: uppercase; color: var(--muted); margin-bottom: 7px; }

/* bottom Coinbase-style info columns */
.token-data-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 14px; }
.token-panel { padding: 15px 17px; }
.token-panel-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.token-panel-head h3 { margin: 0; font-size: 14px; font-weight: 650; color: var(--text); }
.token-panel-head span { font-size: 10.5px; font-weight: 650; color: var(--faint); text-transform: uppercase; letter-spacing: 0; }
.token-data-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 8px 0; border-bottom: 1px solid var(--line); }
.token-data-row:last-child { border-bottom: 0; }
.token-data-row > span:first-child { display: flex; flex-direction: column; min-width: 0; }
.td-label { font-size: 12.5px; color: var(--muted); font-weight: 550; }
.td-sub { font-size: 11px; color: var(--faint); margin-top: 1px; }
.td-value { font-size: 13.5px; font-weight: 620; color: var(--text); text-align: right; white-space: nowrap; }
.td-value.up { color: var(--up); } .td-value.down { color: var(--down); }

/* ---- living order book (Backpack-grade) ----------------------------------
   Fed by Binance depth20@100ms + aggTrade rebroadcast over the app WS.
   Asks stack down to the last-price row, bids continue below; cumulative
   depth bars glide with each frame, size cells flash as liquidity moves. */
.ob-card { padding: 0; display: flex; flex-direction: column; }
.ob-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 9px 12px; border-bottom: 1px solid var(--line); }
.seg.mini { padding: 2px; }
.seg.mini button { height: 24px; padding: 0 13px; font-size: 11.5px; }
.ob-live { display: inline-flex; align-items: center; gap: 5px; font-size: 9.5px; font-weight: 600; letter-spacing: 0; color: var(--faint); }
.ob-live.on { color: var(--up); }
.ob-live-dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.ob-live.on .ob-live-dot { animation: obPulse 1.8s ease-in-out infinite; }
@keyframes obPulse { 0%, 100% { opacity: 1; } 50% { opacity: .4; } }
.ob-body { padding: 6px 0 10px; }
.ob-cols {
  display: grid; grid-template-columns: 1.1fr 1fr .9fr; gap: 6px; padding: 4px 14px 6px;
  font-size: 9.5px; font-weight: 640; letter-spacing: 0; text-transform: uppercase; color: var(--faint);
}
.ob-cols span:nth-child(2), .ob-cols span:nth-child(3) { text-align: right; }
.ob-row {
  position: relative; display: grid; grid-template-columns: 1.1fr 1fr .9fr; gap: 6px;
  align-items: center; padding: 2.5px 14px; font-size: 12px; line-height: 1.4; overflow: hidden;
}
.ob-row .ob-bar { position: absolute; top: 1px; bottom: 1px; right: 0; z-index: 0; border-radius: 3px 0 0 3px; transition: width .16s linear; }
.ob-row.ask .ob-bar { background: var(--down-soft); }
.ob-row.bid .ob-bar { background: var(--up-soft); }
/* liquidity walls (cum > 70% of the deep side) read a touch stronger */
.ob-row.heavy.ask .ob-bar { background: color-mix(in srgb, var(--down) 16%, transparent); }
.ob-row.heavy.bid .ob-bar { background: color-mix(in srgb, var(--up) 16%, transparent); }
.ob-row.heavy .ob-px { font-weight: 600; }
.ob-row > span:not(.ob-bar) { position: relative; z-index: 1; }
.ob-px { font-weight: 690; }
.ob-row.ask .ob-px { color: var(--down); }
.ob-row.bid .ob-px { color: var(--up); }
.ob-size { text-align: right; color: var(--text); font-weight: 620; border-radius: 4px; }
.ob-size.fl { animation: obCell .45s ease-out; }
@keyframes obCell { 0% { background: color-mix(in srgb, var(--accent) 20%, transparent); } 100% { background: transparent; } }
.ob-total { text-align: right; color: var(--muted); }
.ob-mid {
  display: flex; align-items: baseline; gap: 7px; padding: 7px 14px; margin: 3px 0;
  border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--tile) 55%, transparent);
}
.ob-mid-label { font-size: 9.5px; font-weight: 600; letter-spacing: 0; text-transform: uppercase; color: var(--faint); }
.ob-last { font-size: 17px; font-weight: 600; letter-spacing: 0; color: var(--text); }
.ob-last.up { color: var(--up); }
.ob-last.down { color: var(--down); }
.ob-arrow { font-size: 13px; font-weight: 650; }
.ob-arrow.up { color: var(--up); }
.ob-arrow.down { color: var(--down); }
.ob-spread { margin-left: auto; font-size: 10.5px; color: var(--muted); white-space: nowrap; }
.ob-ratio { display: flex; align-items: center; gap: 9px; padding: 9px 14px 2px; }
.ob-ratio-tag { font-size: 10.5px; font-weight: 650; }
.ob-ratio-tag.up { color: var(--up); }
.ob-ratio-tag.down { color: var(--down); }
.ob-ratio-bar { flex: 1; height: 5px; border-radius: 3px; background: color-mix(in srgb, var(--down) 42%, transparent); overflow: hidden; }
.ob-ratio-fill { display: block; height: 100%; background: var(--up); border-radius: 3px 0 0 3px; transition: width .25s ease; }
.ob-trades .ob-row { grid-template-columns: 1.1fr 1fr .8fr; }
.ob-time { text-align: right; color: var(--faint); font-size: 11px; }
.ob-row.trade.in { animation: obIn .3s ease-out; }
@keyframes obIn { from { background: color-mix(in srgb, var(--accent) 10%, transparent); opacity: .35; } to { background: transparent; opacity: 1; } }
.ob-empty { padding: 14px; color: var(--muted); font-size: 12px; }

/* ---- Strategies: the basis engine as an instrument (server truth only) ---- */
.strategies-page { max-width: min(1680px, 100%); }
.strategies-page .t-right { text-align: right; justify-self: end; }

