/* ---- Opportunities radar ---- */
.opportunities-page { max-width: min(1680px, 100%); }
.opp-brief {
  display: grid;
  gap: 7px;
  margin-bottom: 13px;
}
.opp-brief span {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.38;
  font-weight: 630;
}
.opp-brief svg { flex: none; color: var(--accent); margin-top: 1px; }

