.risk-metric::after,
.risk-arm-card::after,
.risk-gate-step::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, var(--rim-hi), transparent 38%, transparent 72%, var(--rim-lo));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
.risk-gate-chain {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 9px;
}
.risk-gate-step {
  position: relative;
  min-height: 112px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 13px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--tile) 70%, transparent);
  border: 1px solid color-mix(in srgb, var(--glass-border) 42%, transparent);
}
.risk-gate-step.ok { --gate: var(--up); --gate-soft: var(--up-soft); }
.risk-gate-step.warn { --gate: var(--accent); --gate-soft: var(--accent-soft); }
.risk-gate-step.bad { --gate: var(--down); --gate-soft: var(--down-soft); }
.risk-gate-step.idle { --gate: var(--muted); --gate-soft: var(--tile); }
.risk-gate-icon {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  color: var(--gate);
  background: var(--gate-soft);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.45);
}
.risk-gate-step b {
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
}
.risk-gate-step em {
  display: block;
  margin-top: 4px;
  color: var(--muted);
  font-style: normal;
  font-size: 11.5px;
  font-weight: 640;
}

@media (max-width: 1320px) {
  .risk-gate-chain { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (max-width: 900px) {
  .risk-gate-chain,
  .risk-field-grid,
  .risk-field-grid.scanner,
  .risk-capacity-row { grid-template-columns: 1fr; }
}
@media (max-width: 560px) {
}

/* ---- Ledger / Logs audit console ---- */
.ledger-page { max-width: min(1680px, 100%); }
.ledger-hero {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 18px;
  margin: 24px 0 16px; flex-wrap: wrap;
}
.ledger-live {
  display: inline-flex; align-items: center; gap: 9px; height: 36px; padding: 0 13px;
  border-radius: var(--r-pill);
  background: color-mix(in srgb, var(--panel) 70%, transparent);
  border: 1px solid color-mix(in srgb, var(--glass-border) 62%, transparent);
  color: var(--text-2); font-size: 12.5px; font-weight: 680;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.5), 0 7px 18px rgba(15,23,42,.05);
}
.ledger-live .state-dot {
  width: 7px; height: 7px; border-radius: 50%; display: inline-block; flex: none;
  background: var(--line-strong);
}
.ledger-live .state-dot.ok { background: var(--up); box-shadow: 0 0 0 3px var(--up-soft); }
.ledger-live .state-dot.warn { background: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.ledger-live .state-dot.bad { background: var(--down); box-shadow: 0 0 0 3px var(--down-soft); }

.ledger-metrics {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 13px;
  margin: 0 0 14px;
}
.ledger-metric {
  position: relative; min-height: 96px; padding: 15px 16px;
  display: flex; align-items: flex-start; gap: 12px; overflow: hidden;
  border-radius: 18px;
  background:
    linear-gradient(135deg, rgba(255,255,255,.38), transparent 38%),
    color-mix(in srgb, var(--panel) 78%, transparent);
  border: 1px solid color-mix(in srgb, var(--glass-border) 60%, transparent);
  box-shadow: var(--glass-highlight), var(--depth), 0 0 0 .5px var(--glass-edge);
}
.ledger-metric::after {
  content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px;
  background: linear-gradient(135deg, var(--rim-hi) 0%, transparent 34%, transparent 68%, var(--rim-lo) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor; mask-composite: exclude; pointer-events: none;
}
.ledger-metric-icon {
  width: 34px; height: 34px; border-radius: 11px; display: grid; place-items: center;
  color: var(--text); background: color-mix(in srgb, var(--tile) 74%, transparent);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.42), 0 0 0 1px var(--glass-edge);
  flex: none;
}
.ledger-metric.ok .ledger-metric-icon { color: var(--up); background: var(--up-soft); }
.ledger-metric.bad .ledger-metric-icon { color: var(--down); background: var(--down-soft); }
.ledger-metric-label {
  display: block; font-size: 10.5px; font-weight: 600; letter-spacing: 0;
  text-transform: uppercase; color: var(--muted);
}
.ledger-metric-value {
  display: block; margin-top: 5px; font-size: 24px; line-height: 1; font-weight: 600;
  letter-spacing: 0; color: var(--text);
}
.ledger-metric-sub {
  display: block; margin-top: 6px; color: var(--muted); font-size: 12px; font-weight: 620;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

.ledger-filter-card {
  padding: 18px; margin-bottom: 18px; overflow: hidden;
  background:
    radial-gradient(620px 180px at 10% -40%, color-mix(in srgb, var(--accent-soft) 52%, transparent), transparent 70%),
    color-mix(in srgb, var(--panel) 84%, transparent);
}
.ledger-filter-head,
.ledger-stream-head,
.ledger-inspector-head {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 14px;
}
.ledger-filter-head h2,
.ledger-stream-head h2,
.ledger-inspector-head h2 {
  margin: 0; color: var(--text); font-size: 18px; font-weight: 600; letter-spacing: 0;
}
.ledger-filter-head span,
.ledger-stream-head span,
.ledger-inspector-head span {
  display: block; margin-top: 3px; color: var(--muted); font-size: 12px; font-weight: 620;
}
.ledger-filter-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.ledger-tools {
  display: grid; grid-template-columns: minmax(160px, 220px) minmax(240px, 1fr) auto;
  gap: 10px; margin: 16px 0 14px; align-items: center;
}
.ledger-input {
  min-height: 42px; display: flex; align-items: center; gap: 9px; padding: 0 13px;
  border-radius: var(--r-pill);
  background: color-mix(in srgb, var(--tile) 80%, transparent);
  border: 1px solid color-mix(in srgb, var(--glass-border) 48%, transparent);
  color: var(--muted);
}
.ledger-input.warn { border-color: color-mix(in srgb, var(--accent) 55%, transparent); }
.ledger-input span {
  font-size: 10px; font-weight: 600; letter-spacing: 0; text-transform: uppercase;
  color: var(--muted);
}
.ledger-input input {
  width: 100%; min-width: 0; border: 0; outline: 0; background: none;
  color: var(--text); font-size: 13px; font-weight: 650;
}
.ledger-input input::placeholder { color: var(--faint); }
.ledger-decision { justify-self: end; }

.ledger-category-summary {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1px;
  overflow: hidden; border-radius: 14px; margin: 0 0 12px;
  border: 1px solid color-mix(in srgb, var(--glass-border) 48%, transparent);
  background: color-mix(in srgb, var(--line) 68%, transparent);
}
.ledger-category-summary span {
  min-height: 58px; display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 0 14px; background: color-mix(in srgb, var(--panel) 86%, transparent);
}
.ledger-category-summary b {
  color: var(--text); font-size: 20px; line-height: 1; font-weight: 600; letter-spacing: 0;
}
.ledger-category-summary em {
  color: var(--muted); font-size: 10.5px; font-weight: 650; letter-spacing: 0;
  text-transform: uppercase; font-style: normal;
}

.ledger-kind-board {
  display: grid; grid-template-columns: minmax(150px, 190px) repeat(3, minmax(0, 1fr));
  gap: 12px; padding-top: 12px; border-top: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
}
.ledger-kind-group > span {
  display: block; margin: 0 0 8px; color: var(--muted);
  font-size: 10px; font-weight: 650; letter-spacing: 0; text-transform: uppercase;
}
.ledger-kind-group > div { display: flex; flex-wrap: wrap; gap: 6px; }
.ledger-kind-chip {
  min-height: 30px; display: inline-flex; align-items: center; gap: 7px;
  padding: 0 10px; border: 0; border-radius: var(--r-pill);
  background: color-mix(in srgb, var(--tile) 88%, transparent);
  color: var(--text-2); font-size: 11.5px; font-weight: 680;
}
.ledger-kind-chip b {
  min-width: 20px; height: 18px; display: inline-grid; place-items: center; padding: 0 5px;
  border-radius: 999px; background: var(--bg); color: var(--muted); font-size: 10.5px; font-weight: 600;
}
.ledger-kind-chip:hover { color: var(--text); background: var(--tile-hover); }
.ledger-kind-chip.active { background: var(--cta-bg); color: var(--cta-fg); }
.ledger-kind-chip.active b { background: color-mix(in srgb, var(--accent) 20%, #fff); color: #111827; }
.ledger-kind-chip.all {
  align-self: start; justify-content: space-between; min-height: 42px; width: 100%; padding: 0 13px;
  font-size: 12.5px;
}

.ledger-layout {
  display: grid; grid-template-columns: minmax(0, 1fr) 360px; gap: 18px; align-items: start;
}
.ledger-stream-card { padding: 0; min-width: 0; overflow: hidden; }
.ledger-stream-card .ledger-stream-head {
  padding: 16px 18px 14px;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
}
.ledger-timeline {
  position: relative; display: flex; flex-direction: column; gap: 0; margin: 0;
}
.ledger-day-section {
  border-bottom: 1px solid color-mix(in srgb, var(--line) 74%, transparent);
}
.ledger-day-section:last-child { border-bottom: 0; }
.ledger-day-label {
  min-height: 36px; display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 0 18px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 88%, transparent), color-mix(in srgb, var(--tile) 60%, transparent));
  border-bottom: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
}
.ledger-day-label span {
  color: var(--text); font-size: 12px; font-weight: 600; letter-spacing: 0; text-transform: uppercase;
}
.ledger-day-label b {
  color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: 0; text-transform: uppercase;
}
.ledger-event {
  --event: var(--muted);
  --event-soft: var(--tile);
  position: relative; border-radius: 0;
  background: color-mix(in srgb, var(--panel) 54%, transparent);
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 64%, transparent);
  overflow: hidden;
  transition: background .14s, border-color .14s, transform .12s;
}
.ledger-day-section .ledger-event:last-child { border-bottom: 0; }
.ledger-event.ok { --event: var(--up); --event-soft: var(--up-soft); }
.ledger-event.bad { --event: var(--down); --event-soft: var(--down-soft); }
.ledger-event.warn { --event: var(--accent); --event-soft: var(--accent-soft); }
.ledger-event.purple { --event: #8d7dff; --event-soft: rgba(141,125,255,.13); }
.ledger-event.info { --event: #3985ff; --event-soft: rgba(57,133,255,.12); }
.ledger-event::before {
  content: ""; position: absolute; inset: 0 auto 0 0; width: 3px; background: var(--event);
  opacity: .72; transform: scaleY(.56); transform-origin: center; border-radius: 0 2px 2px 0;
}
.ledger-event:hover { background: color-mix(in srgb, var(--event-soft) 28%, var(--panel)); }
.ledger-event.open { background: color-mix(in srgb, var(--event-soft) 34%, var(--panel)); }
.ledger-event-main {
  width: 100%; min-height: 74px; display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto; gap: 12px; align-items: center;
  border: 0; background: none; padding: 11px 14px 11px 18px; text-align: left; font: inherit; color: var(--text);
}
.ledger-event-icon {
  width: 32px; height: 32px; border-radius: 10px; display: grid; place-items: center; color: var(--event);
  background: var(--event-soft); box-shadow: inset 0 1px 0 rgba(255,255,255,.42), 0 0 0 1px color-mix(in srgb, var(--event) 12%, transparent);
}
.ledger-event-body { min-width: 0; display: flex; flex-direction: column; gap: 5px; }
.ledger-event-top {
  display: flex; align-items: center; gap: 8px; min-width: 0; flex-wrap: wrap;
}
.ledger-time {
  color: var(--muted); font-size: 11.5px; font-weight: 620; white-space: nowrap;
}
.ledger-event-body strong {
  color: var(--text); font-size: 14.5px; line-height: 1.35; font-weight: 640; letter-spacing: 0;
  overflow: hidden; text-overflow: ellipsis;
}
.ledger-event-meta {
  display: flex; align-items: center; gap: 10px; min-width: 0; color: var(--muted);
  font-size: 11.5px; font-weight: 640;
}
.ledger-symbol {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0; color: var(--text); font-weight: 650;
}
.ledger-symbol.system {
  color: var(--muted); background: var(--tile); height: 22px; padding: 0 8px; border-radius: var(--r-pill);
}
.ledger-open-mark {
  height: 28px; display: inline-flex; align-items: center; justify-content: center;
  padding: 0 10px; border-radius: var(--r-pill); background: transparent; color: var(--muted);
  font-size: 11.5px; font-weight: 640; white-space: nowrap;
}
.ledger-event-main:hover .ledger-open-mark { color: var(--text); background: color-mix(in srgb, var(--tile-hover) 70%, transparent); }
.ledger-event-detail {
  margin: 0 14px 14px 64px; padding: 13px;
  border-top: 1px solid color-mix(in srgb, var(--event) 20%, var(--line));
  border-radius: 14px;
  background: color-mix(in srgb, var(--panel) 56%, transparent);
}
.ledger-field-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 9px;
}
.ledger-field-grid > span,
.ledger-inspector-meta > span {
  display: flex; flex-direction: column; gap: 3px; min-width: 0;
  padding: 9px 10px; border-radius: 11px; background: var(--tile);
}
.ledger-field-grid b,
.ledger-inspector-meta b {
  color: var(--muted); font-size: 10px; font-weight: 650; letter-spacing: 0; text-transform: uppercase;
}
.ledger-field-grid em,
.ledger-inspector-meta em {
  color: var(--text); font-style: normal; font-size: 12.5px; font-weight: 620;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.ledger-json-head {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  margin: 12px 0 7px; color: var(--muted); font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0;
}
.ledger-raw {
  margin: 0; padding: 12px 13px; border-radius: 12px;
  background: color-mix(in srgb, var(--bg) 74%, var(--tile));
  border: 1px solid var(--line);
  color: var(--text-2);
  font-family: var(--mono); font-size: 11px; line-height: 1.55;
  white-space: pre-wrap; word-break: break-word; max-height: 300px; overflow: auto;
}
.ledger-side {
  display: flex; flex-direction: column; gap: 14px; position: sticky; top: calc(var(--header-h) + 16px);
}
.ledger-inspector { padding: 16px; overflow: hidden; }
.ledger-inspector-head { justify-content: flex-start; align-items: center; }
.ledger-inspector-head .ledger-event-icon { flex: none; }
.ledger-inspector p {
  margin: 14px 0; color: var(--text); font-size: 13.5px; line-height: 1.45; font-weight: 650;
}
.ledger-inspector-meta {
  display: grid; grid-template-columns: 1fr; gap: 8px; margin-bottom: 12px;
}
.ledger-side-empty { display: block; color: var(--muted); font-size: 12.5px; margin-top: 12px; }
.ledger-count-list { display: flex; flex-direction: column; gap: 4px; margin-top: 12px; }
.ledger-count-list button {
  min-height: 34px; display: flex; align-items: center; justify-content: space-between; gap: 10px;
  border: 0; border-radius: 10px; padding: 0 10px; background: none; color: var(--text-2);
  font: inherit; font-size: 12.5px; font-weight: 680; text-align: left;
}
.ledger-count-list button:hover { background: var(--hover); color: var(--text); }
.ledger-count-list button.active { background: var(--cta-bg); color: var(--cta-fg); }
.ledger-count-list b {
  min-width: 28px; text-align: right; font-size: 12px; font-weight: 650; color: inherit;
}
