/* footer */
.footer {
  flex: none;
  width: 100%;
  margin-top: auto; /* sits at the end of the scroll — visible only at the bottom, Coinbase-style */
  border-top: 1px solid var(--line-2);
  padding: 16px 28px;
  background: var(--panel);
  /* quiet by design — small gray, never ink that competes with content */
  color: var(--muted);
  font-size: 12.5px;
  font-weight: 450;
}
[data-theme="dark"] .footer { background: var(--bg); }
.ftr-line { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.ftr-left, .ftr-right { display: inline-flex; align-items: center; gap: 12px; min-width: 0; }
.ftr-brand { color: var(--muted); font-weight: 500; }
.ftr-line i { color: var(--faint); font-style: normal; font-size: 11px; }
.ftr-right { color: var(--muted); }
.ftr-right svg { color: var(--muted); }

/* atabs (underline tabs) */
.atabs { display: flex; gap: 2px; border-bottom: 1px solid var(--line); margin: 2px 0 16px; overflow-x: auto; scrollbar-width: none; }
.atab { position: relative; height: 40px; padding: 0 15px; border: 0; background: transparent; color: var(--muted); font-size: 13.5px; font-weight: 620; white-space: nowrap; }
.atab:hover { color: var(--text); }
.atab::after {
  content: ""; position: absolute; left: 11px; right: 11px; bottom: -1px; height: 2.5px;
  background: var(--accent); border-radius: 2px; transform: scaleX(0);
  transition: transform .18s cubic-bezier(.3,.6,.2,1);
}
.atab.on { color: var(--text); }
.atab.on::after { transform: scaleX(1); }

