  margin-top: 18px;
}
.token-market-strip {
  display: grid; /* the flex rule from the older strip generation must not win here */
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "main actions"
    "metrics metrics";
  align-items: start;
  gap: 22px 24px;
  padding: 24px;
  border-radius: 24px;
}
.token-market-strip .market-strip-main {
  grid-area: main;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 24px;
}
.token-strip-id {
  display: flex;
  align-items: center;
  gap: 20px;
}
.token-strip-id .tok-badge {
  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,.35),
    0 18px 40px -24px color-mix(in srgb, var(--text) 50%, transparent);
