.token-strip-id .detail-name {
  font-size: 48px;
  font-weight: 650;
  line-height: .98;
}
.token-strip-id .detail-sub {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 8px;
  font-size: 12.5px;
  font-weight: 650;
}
.token-market-strip .strip-price {
  align-self: center;
  margin: 0;
}
.token-market-strip .headline-val {
  font-size: 72px;
  font-weight: 650;
  line-height: .92;
}
.token-market-strip .strip-change {
  margin-top: 10px;
  font-size: 15px;
  font-weight: 600;
}
.token-market-strip .detail-head-actions {
  grid-area: actions;
  align-self: center;
  justify-content: flex-end;
}
