  height: 40px;
  min-width: 74px;
  justify-content: center;
}
.token-market-strip .strip-metrics {
  grid-area: metrics;
  display: grid;
  /* auto-fit: 6 tiles for perp pairs, 4 for spot-only — both fill the row */
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
