    linear-gradient(160deg, color-mix(in srgb, var(--rim-hi) 26%, transparent), transparent 48%),
    color-mix(in srgb, var(--tile) 82%, transparent);
  box-shadow: inset 0 0 0 .5px color-mix(in srgb, var(--rim-hi) 32%, transparent);
}
