  position: relative;
  width: 100%;
  min-height: 360px;
  overflow: hidden;
  border-radius: 16px;
}
.tv-widget-wrap {
  position: relative;
  width: 100%;
  min-height: 360px;
  overflow: hidden;
  border-radius: 16px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--tile) 58%, transparent), transparent),
    color-mix(in srgb, var(--panel) 88%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--rim-hi) 20%, transparent);
