.tv-widget-wrap .tradingview-widget-container {
  position: absolute;
  inset: 0;
  z-index: 1;
  height: 100%;
  width: 100%;
}
.tv-widget-wrap iframe {
  position: absolute;
  inset: 0;
  z-index: 1;
  border: 0 !important;
  width: 100% !important;
  height: 100% !important;
  display: block;
