    radial-gradient(circle at 50% 22%, color-mix(in srgb, var(--rim-hi) 20%, transparent), transparent 34%),
    linear-gradient(180deg, color-mix(in srgb, var(--tile) 44%, transparent), transparent 58%);
}
.depth-stat-strip {
  position: absolute;
  top: 12px;
  left: 14px;
  right: 14px;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  pointer-events: none;
}
.depth-stat-strip > span:not(.chart-stream-state) {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  min-height: 28px;
  padding: 5px 9px;
  border-radius: var(--r-pill);
  background: color-mix(in srgb, var(--glass-strong) 74%, transparent);
  box-shadow: inset 0 0 0 .5px color-mix(in srgb, var(--rim-hi) 28%, transparent);
}
.depth-stat-strip b {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
  color: var(--muted);
}
.depth-stat-strip em {
  font-style: normal;
  font-size: 12px;
  font-weight: 600;
  color: var(--text);
}
.depth-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.depth-grid {
  stroke: color-mix(in srgb, var(--line) 66%, transparent);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}
.depth-mid-line {
  stroke: color-mix(in srgb, var(--text) 18%, transparent);
  stroke-width: 1.1;
  stroke-dasharray: 5 6;
  vector-effect: non-scaling-stroke;
}
.depth-line {
  fill: none;
  stroke-width: 2.1;
  vector-effect: non-scaling-stroke;
  filter: drop-shadow(0 2px 5px color-mix(in srgb, currentColor 18%, transparent));
}
.depth-line.bid { stroke: var(--up); }
.depth-line.ask { stroke: var(--down); }
.depth-area {
  transition: d .16s linear;
}
.depth-x,
.depth-y {
  fill: var(--muted);
  font-size: 11px;
  font-weight: 650;
}
.depth-y {
  opacity: .82;
}
.depth-ratio {
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 12px;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 10px;
}
.depth-ratio > span:first-child,
.depth-ratio > span:last-child {
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}
.depth-ratio-track {
  flex: 1;
  height: 10px;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--down) 28%, transparent);
  box-shadow: inset 0 0 0 .5px color-mix(in srgb, var(--rim-hi) 24%, transparent);
}
.depth-ratio-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: color-mix(in srgb, var(--up) 76%, transparent);
  transition: width .22s cubic-bezier(.2,.8,.2,1);
}
.depth-empty {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: var(--muted);
  font-size: 13px;
  font-weight: 650;
}
.chart-stream-state {
  display: inline-flex;
