/* Token Detail v5: Backpack-inspired right rail, wired to guarded tickets. */
.token-rail-stack {
  grid-area: book;
  position: sticky;
  top: 78px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
}
.token-rail-stack .ob-card {
  grid-area: auto;
  position: static;
  top: auto;
  min-height: 560px;
  max-height: none;
}
.rail-ticket-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
  padding: 12px;
  overflow: hidden;
  border-radius: 22px;
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--rim-hi) 20%, transparent), transparent 46%),
    color-mix(in srgb, var(--glass-strong) 84%, var(--panel));
}
.rail-ticket-card::before {
  content: "";
  position: absolute;
  inset: -90px -70px auto auto;
  width: 190px;
  height: 160px;
  pointer-events: none;
  opacity: .72;
  filter: blur(18px);
  background: radial-gradient(circle, color-mix(in srgb, var(--up) 18%, transparent), transparent 72%);
}
.rail-ticket-card[data-side="SELL"]::before {
  background: radial-gradient(circle, color-mix(in srgb, var(--down) 18%, transparent), transparent 72%);
}
.rail-ticket-card > * {
  position: relative;
  z-index: 1;
}
.rail-ticket-side {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  padding: 3px;
  border-radius: 15px;
  background: color-mix(in srgb, var(--tile) 78%, transparent);
  box-shadow: inset 0 0 0 .5px color-mix(in srgb, var(--rim-hi) 38%, transparent);
}
.rail-ticket-side button,
.rail-ticket-modes button,
.ob-layout button,
.ob-tick button {
  border: 0;
  cursor: pointer;
  font: inherit;
}
.rail-ticket-side button {
  height: 38px;
  border-radius: 12px;
  background: transparent;
  color: var(--muted);
  font-size: 13px;
  font-weight: 650;
}
.rail-ticket-side button.buy.on {
  color: var(--up);
  background: color-mix(in srgb, var(--up) 13%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--rim-hi) 58%, transparent);
}
.rail-ticket-side button.sell.on {
  color: var(--down);
  background: color-mix(in srgb, var(--down) 13%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--rim-hi) 58%, transparent);
}
.rail-ticket-modes {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.rail-ticket-modes button {
  flex: 1 0 auto;
  height: 30px;
  padding: 0 10px;
  border-radius: 11px;
  background: transparent;
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 600;
}
.rail-ticket-modes button:hover:not(:disabled),
.rail-ticket-modes button.on {
  color: var(--text);
  background: var(--tile);
}
.rail-ticket-modes button:disabled {
  cursor: not-allowed;
  opacity: .48;
}
.rail-ticket-field {
  display: grid;
  gap: 6px;
}
.rail-ticket-field > span {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
}
.rail-ticket-field > span em {
  display: inline-flex;
  gap: 5px;
  font-style: normal;
}
.rail-ticket-field > span em button {
  height: 22px;
  padding: 0 8px;
  border: 0;
  border-radius: 8px;
  background: var(--tile);
  color: var(--accent-ink);
  font-size: 10.5px;
  font-weight: 650;
}
[data-theme="dark"] .rail-ticket-field > span em button { color: var(--accent); }
.rail-ticket-field > span em button:disabled {
  cursor: not-allowed;
  color: var(--faint);
  opacity: .52;
}
.rail-ticket-field label {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  min-height: 46px;
  padding: 0 10px 0 12px;
  border-radius: 14px;
  background: color-mix(in srgb, var(--tile) 74%, transparent);
  box-shadow:
    inset 0 0 0 .5px color-mix(in srgb, var(--rim-hi) 32%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--rim-hi) 38%, transparent);
}
.rail-ticket-field input {
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 20px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.rail-ticket-field input:disabled {
  color: var(--muted);
}
.rail-ticket-field label b {
  min-width: 36px;
  padding: 5px 7px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--rim-hi) 38%, transparent);
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
  text-align: center;
}
.rail-ticket-slider {
  display: grid;
  gap: 5px;
}
.rail-ticket-slider input {
  width: 100%;
  accent-color: var(--accent);
}
.rail-ticket-slider span {
  display: flex;
  justify-content: space-between;
  color: var(--faint);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 680;
}
.rail-ticket-slider i {
  font-style: normal;
}
.rail-ticket-summary {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.rail-ticket-summary span {
  min-width: 0;
  padding: 9px 10px;
  border-radius: 13px;
  background: color-mix(in srgb, var(--tile) 62%, transparent);
}
.rail-ticket-summary b,
.rail-ticket-summary em {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.rail-ticket-summary b {
  color: var(--text);
  font-size: 13.5px;
  font-weight: 650;
}
.rail-ticket-summary em {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 620;
  text-transform: uppercase;
}
.rail-ticket-submit {
  width: 100%;
  justify-content: center;
  min-height: 38px;
}
.rail-ticket-card p {
  margin: -2px 2px 0;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.35;
}
.ob-head {
  align-items: stretch;
  flex-direction: column;
  gap: 9px;
}
.ob-head-main,
.ob-tools {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}
.ob-tools {
  justify-content: flex-start;
}
.ob-layout,
.ob-tick {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3px;
  border-radius: 11px;
  background: color-mix(in srgb, var(--tile) 78%, transparent);
  box-shadow: inset 0 0 0 .5px color-mix(in srgb, var(--rim-hi) 30%, transparent);
}
.ob-layout button,
.ob-tick button {
  display: grid;
  place-items: center;
  min-width: 25px;
  height: 24px;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
}
.ob-layout button:hover,
.ob-layout button.on,
.ob-tick button:hover {
  color: var(--text);
  background: color-mix(in srgb, var(--rim-hi) 45%, var(--tile));
}
.ob-layout-glyph {
  display: grid;
  gap: 2px;
  width: 14px;
}
.ob-layout-glyph i {
  display: block;
  height: 2px;
  border-radius: 3px;
  background: var(--muted);
}
.ob-layout button.on .ob-layout-glyph i,
.ob-layout button:hover .ob-layout-glyph i {
  background: currentColor;
}
.ob-layout-glyph.both i:first-child,
.ob-layout-glyph.asks i {
  background: var(--down);
}
.ob-layout-glyph.both i:last-child,
.ob-layout-glyph.bids i {
  background: var(--up);
}
.ob-tick span {
  min-width: 44px;
  color: var(--text);
  font-size: 11px;
  font-weight: 650;
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.ob-row,
.ob-cols,
.ob-last,
.ob-spread,
.ob-ratio-tag {
  font-variant-numeric: tabular-nums;
}
.ob-side.single {
  min-height: 0;
}
.ob-row.trade.buy {
  background: linear-gradient(90deg, color-mix(in srgb, var(--up) 6%, transparent), transparent 42%);
}
.ob-row.trade.sell {
  background: linear-gradient(90deg, color-mix(in srgb, var(--down) 6%, transparent), transparent 42%);
}
.token-rail-stack .ob-footer-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.token-rail-stack .ob-footer-actions .mini-btn,
.token-rail-stack .ob-footer-actions .cta-pill {
  justify-content: center;
  width: 100%;
  padding-inline: 8px;
}
.token-rail-stack .ob-footer-actions .micro-ticket-btn {
  margin-left: 0;
}
@media (max-width: 1180px) {
  .token-rail-stack {
    position: static;
    top: auto;
  }
  .token-rail-stack .ob-card {
    min-height: auto;
  }
}
@media (max-width: 760px) {
  .token-rail-stack {
    gap: 10px;
  }
  .rail-ticket-card {
    padding: 11px;
    border-radius: 18px;
  }
  .rail-ticket-field input {
    font-size: 17px;
  }
  .rail-ticket-summary,
  .token-rail-stack .ob-footer-actions {
    grid-template-columns: 1fr;
  }
}
.trade-cap-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin: -5px 0 16px;
}
.trade-cap-card {
  padding: 12px;
  border-radius: 14px;
  background: color-mix(in srgb, var(--tile) 72%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--rim-hi) 58%, transparent);
}
.cap-meter-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 9px;
}
.cap-meter-head span {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
}
.cap-meter-head b {
  color: var(--text);
  font-size: 12.5px;
  font-weight: 600;
  text-align: right;
}
.cap-meter {
  display: block;
  overflow: hidden;
  height: 7px;
  border-radius: var(--r-pill);
  background: color-mix(in srgb, var(--line-2) 72%, transparent);
}
.cap-meter > span {
  display: block;
  height: 100%;
  min-width: 4px;
  border-radius: inherit;
  transition: width .18s ease;
}
.cap-meter > span.ok { background: var(--up); }
.cap-meter > span.warn { background: var(--accent); }
.cap-meter > span.bad { background: var(--down); }

.trade-price-picks {
  position: relative;
  z-index: 2;
  margin: -2px 0 14px;
}
.price-pick-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-top: 7px;
}
.price-pick {
  min-width: 0;
  height: 48px;
  padding: 7px 11px;
  border: 1px solid color-mix(in srgb, var(--glass-border) 58%, transparent);
  border-radius: 13px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--rim-hi) 18%, transparent), transparent 58%),
    color-mix(in srgb, var(--tile) 76%, transparent);
  color: var(--text);
  text-align: left;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--rim-hi) 58%, transparent);
  transition: transform .08s, border-color .12s, background .12s;
}
.price-pick:hover:not(:disabled) { border-color: var(--accent-line); background: var(--tile-hover); }
.price-pick:active:not(:disabled) { transform: scale(.985); }
.price-pick:disabled { cursor: not-allowed; opacity: .48; }
.price-pick span {
  display: block;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
}
.price-pick b {
  display: block;
  overflow: hidden;
  margin-top: 3px;
  font-size: 13.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.price-pick.up b { color: var(--up); }
.price-pick.down b { color: var(--down); }

.trade-help {
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.35;
}
.preflight-board {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 14px;
}
.preflight-row {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  min-width: 0;
  padding: 10px;
  border-radius: 13px;
  background: color-mix(in srgb, var(--tile) 72%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--rim-hi) 52%, transparent);
}
.preflight-dot {
  width: 21px;
  height: 21px;
  display: grid;
  place-items: center;
  flex: none;
  border-radius: 8px;
  color: #fff;
  font-size: 11px;
  font-weight: 680;
}
.preflight-dot svg { display: block; }
.preflight-row.pass .preflight-dot { background: var(--up); }
.preflight-row.fail .preflight-dot { background: var(--down); }
.preflight-row b {
  display: block;
  color: var(--text);
  font-size: 12.5px;
}
.preflight-row small {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.35;
}

.side-toggle {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
  margin: 2px 0 16px;
  position: relative;
  z-index: 2;
}
.side-toggle button {
  height: 44px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: color-mix(in srgb, var(--tile) 80%, transparent);
  color: var(--muted);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0;
  transition: color .14s, background .14s, border-color .14s, box-shadow .14s, transform .08s;
}
.side-toggle button:hover { color: var(--text); }
.side-toggle button:active { transform: scale(.985); }
.side-toggle button.buy.on {
  color: var(--up);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--rim-hi) 30%, transparent), transparent 55%),
    color-mix(in srgb, var(--up) 13%, transparent);
  border-color: color-mix(in srgb, var(--up) 42%, transparent);
  box-shadow: inset 0 1px 0 var(--rim-hi), 0 10px 26px -18px var(--up);
}
.side-toggle button.sell.on {
  color: var(--down);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--rim-hi) 30%, transparent), transparent 55%),
    color-mix(in srgb, var(--down) 13%, transparent);
  border-color: color-mix(in srgb, var(--down) 42%, transparent);
  box-shadow: inset 0 1px 0 var(--rim-hi), 0 10px 26px -18px var(--down);
}

/* the whole ticket glows with the chosen side */
.trade-ticket[data-side="BUY"]::before {
  background: radial-gradient(circle, color-mix(in srgb, var(--up) 17%, transparent), transparent 70%);
}
.trade-ticket[data-side="SELL"]::before {
  background: radial-gradient(circle, color-mix(in srgb, var(--down) 17%, transparent), transparent 70%);
}

/* quick notional sizing under the quantity field */
.qsize-row { display: flex; gap: 7px; margin-top: 8px; flex-wrap: wrap; }
.qsize-chip {
  height: 26px;
  padding: 0 12px;
  border: 0;
  border-radius: var(--r-pill);
  background: var(--tile);
  color: var(--text-2);
  font-size: 11.5px;
  font-weight: 640;
  transition: background .12s, color .12s, transform .08s;
}
.qsize-chip:hover { background: var(--tile-hover); color: var(--text); }
.qsize-chip:active { transform: scale(.96); }
.qsize-chip:disabled {
  cursor: not-allowed;
  opacity: .46;
  transform: none;
}
.qsize-chip.max {
  color: var(--accent-ink);
  background: color-mix(in srgb, var(--accent) 18%, transparent);
}
[data-theme="dark"] .qsize-chip.max { color: var(--accent); }
.qsize-chip.ghost { color: var(--muted); background: transparent; box-shadow: inset 0 0 0 1px var(--line); }

/* the living book, rail-sized: not sticky, compact, no token-page min-height */
.trade-rail .ob-card { position: static; min-height: 0; max-height: none; margin-top: 14px; }
.trade-rail .ob-side { min-height: 0; } /* token-page sizes 12 levels; the rail shows 7 */
.trade-rail .ob-mid { min-height: 44px; }
.trade-rail .ob-last { font-size: 20px; }
.ob-row.clickable { cursor: pointer; }
.ob-row.clickable:hover .ob-px { text-decoration: underline; text-underline-offset: 2px; }
.rail-hint {
  margin: 8px 4px 0;
  font-size: 11px;
  color: var(--faint);
  text-align: center;
}
.quote-meta-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-top: 10px;
  margin-top: 10px;
  border-top: 1px solid var(--line);
}
.quote-meta-row .k { font-size: 10.5px; font-weight: 640; letter-spacing: 0; text-transform: uppercase; color: var(--muted); }
.quote-meta-row .v { font-size: 13px; font-weight: 640; color: var(--text); }

