}
.loan-panel-right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 8px;
  flex: none;
}
.loan-state-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 16px;
}
.loan-state-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 11px 12px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--tile) 76%, transparent);
  border: 1px solid color-mix(in srgb, var(--line) 74%, transparent);
}
.loan-state-row > span:first-child {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: var(--bg);
  color: var(--muted);
}
.loan-state-row.ok > span:first-child { color: var(--up); background: var(--up-soft); }
.loan-state-row.bad > span:first-child { color: var(--down); background: var(--down-soft); }
.loan-state-row.warn > span:first-child { color: var(--accent-ink); background: var(--accent-soft); }
[data-theme="dark"] .loan-state-row.warn > span:first-child { color: var(--accent); }
.loan-action-row {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
  margin-top: 16px;
}
.loan-preview-table {
  margin-top: 15px;
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  background: color-mix(in srgb, var(--tile) 60%, transparent);
}
.loan-preview-row {
  display: grid;
  grid-template-columns: 145px minmax(0, 1fr);
  gap: 12px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--line);
}
.loan-preview-row:last-child {
  border-bottom: 0;
}
.loan-preview-row span {
  color: var(--text);
  font-size: 12.5px;
  font-weight: 600;
}
.loan-preview-row b {
  color: var(--muted);
  font-size: 12px;
  font-weight: 620;
  line-height: 1.35;
}
.loan-slot-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 11px;
  margin-top: 15px;
}
.loan-slot {
  position: relative;
  min-height: 122px;
  padding: 15px;
  border-radius: 15px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--rim-hi) 28%, transparent), transparent 64%),
    color-mix(in srgb, var(--tile) 78%, transparent);
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 var(--rim-hi);
}
.loan-slot-dot {
  display: block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--accent-soft);
  margin-bottom: 18px;
}
.loan-stat-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 16px;
}
.loan-table-card + .loan-table-card,
.loan-margin-summary + .loan-table-card {
  margin-top: 16px;
}
.active-loans {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 16px;
}
.active-loan-card,
.collateral-card {
  border-radius: 16px;
  padding: 14px;
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--rim-hi) 22%, transparent), transparent 58%),
    color-mix(in srgb, var(--tile) 72%, transparent);
  box-shadow: inset 0 1px 0 var(--rim-hi);
}
.active-loan-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.loan-card-values,
.collateral-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 14px;
}
.collateral-stats {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.loan-value {
  display: block;
  min-width: 0;
}
.loan-value b {
  display: block;
  margin-top: 4px;
  color: var(--text);
  font-size: 15px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.loan-value.bad b { color: var(--down); }
.loan-ltv {
  margin-top: 14px;
}
.loan-ltv-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}
.loan-ltv-head b {
  color: var(--text);
  font-size: 14px;
  font-weight: 600;
}
.loan-ltv.ok .loan-ltv-head b { color: var(--up); }
.loan-ltv.warn .loan-ltv-head b { color: var(--accent-ink); }
.loan-ltv.bad .loan-ltv-head b { color: var(--down); }
[data-theme="dark"] .loan-ltv.warn .loan-ltv-head b { color: var(--accent); }
.loan-ltv-bar,
.ltv-ladder {
  height: 10px;
  border-radius: var(--r-pill);
  margin-top: 8px;
  background: color-mix(in srgb, var(--line) 70%, transparent);
  overflow: hidden;
}
.loan-ltv-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--up);
}
.loan-ltv.warn .loan-ltv-bar span { background: var(--accent); }
.loan-ltv.bad .loan-ltv-bar span { background: var(--down); }
.loan-ltv-scale {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-top: 6px;
}
.loan-ltv-scale span {
  font-size: 9.5px;
  font-weight: 640;
  letter-spacing: 0;
}
.collateral-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 16px;
}
.ltv-ladder {
  display: flex;
}
.ltv-ladder span {
  display: block;
  height: 100%;
}
.ltv-ladder span:nth-child(1) { background: var(--up); }
.ltv-ladder span:nth-child(2) { background: var(--accent); }
.ltv-ladder span:nth-child(3) { background: var(--down); }
.loan-market-table .tok-name {
  font-size: 13.5px;
}

.loan-margin-summary {
  margin-bottom: 16px;
}
.loan-proposal-list {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 15px;
}
.loan-proposal-row {
  display: grid;
  grid-template-columns: auto minmax(180px, 1fr) 96px 96px minmax(140px, .7fr) auto;
  gap: 12px;
  align-items: center;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: color-mix(in srgb, var(--tile) 66%, transparent);
}
.loan-proposal-edge b {
  display: block;
  margin-top: 4px;
  color: var(--text);
  font-size: 14px;
  font-weight: 600;
}
.loan-proposal-status {
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
}
.loan-proposal-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  flex-wrap: wrap;
}
.loan-modal-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.loan-modal-note {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  margin-top: 12px;
  padding: 11px 12px;
  border-radius: 12px;
  color: var(--accent-ink);
  background: var(--accent-soft);
  font-size: 12.5px;
  font-weight: 650;
  line-height: 1.45;
}
[data-theme="dark"] .loan-modal-note {
  color: var(--accent);
}
.loan-modal-note svg {
  flex: none;
  margin-top: 1px;
}
.loan-repay-head {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border-radius: 14px;
  background: var(--tile);
}
.loan-repay-head span {
  display: block;
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 640;
}
.loan-repay-head b {
  display: block;
  margin-top: 2px;
  color: var(--text);
  font-size: 18px;
  font-weight: 600;
}

@media (max-width: 1180px) {
  .loan-proposal-row {
    grid-template-columns: auto minmax(0, 1fr) repeat(2, 92px);
  }
  .loan-proposal-status,
  .loan-proposal-actions {
    grid-column: 2 / -1;
  }
  .loan-proposal-actions {
    justify-content: flex-start;
  }
}

@media (max-width: 760px) {
  .loan-panel-head {
    flex-wrap: wrap;
  }
  .loan-panel-right {
    width: 100%;
    margin-left: 0;
    justify-content: flex-start;
  }
  .loan-preview-row {
    grid-template-columns: 1fr;
    gap: 4px;
  }
  .loan-tab {
    justify-content: center;
  }
}

@media (max-width: 520px) {
  .loan-proposal-row {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .loan-proposal-edge,
  .loan-proposal-status,
  .loan-proposal-actions {
    grid-column: 2 / -1;
  }
  .loan-state-row {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .loan-state-row em {
    grid-column: 2 / -1;
  }
}

/* System Health: trading-impact monitor for sources, account truth, risk gate,
   and ledger writes. The page grades consequences, not just component uptime. */
.system-page {
  max-width: min(1540px, 100%);
}
.sys-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(320px, .65fr);
  gap: 18px;
  align-items: stretch;
  padding: 22px;
}
.sys-hero-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
}
.sys-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  width: fit-content;
  color: var(--muted);
  font-size: 11px;
  font-weight: 640;
  letter-spacing: 0;
  text-transform: uppercase;
}
.sys-hero-copy .page-title {
  margin: 9px 0 0;
}
.sys-hero-copy p {
  max-width: 760px;
  margin: 10px 0 0;
  color: var(--text-2);
  font-size: 15.5px;
  font-weight: 430;
  line-height: 1.55;
}
.sys-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 18px;
}
.sys-hero-panel {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 208px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--panel) 88%, transparent), transparent 68%),
    color-mix(in srgb, var(--tile) 64%, transparent);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.5);
}
.sys-hero-panel > span:not(.state-pill) {
  margin-top: auto;
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 640;
  letter-spacing: 0;
  text-transform: uppercase;
}
.sys-hero-panel > b {
  display: block;
  margin-top: 5px;
  color: var(--text);
  font-size: 31px;
  font-weight: 600;
  line-height: 1;
}
.sys-hero-panel > em {
  margin-top: 7px;
  color: var(--muted);
  font-size: 12.5px;
  font-style: normal;
  font-weight: 560;
  line-height: 1.4;
}
.sys-mode-ladder {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin-top: 16px;
}
.sys-mode-ladder span {
  display: grid;
  place-items: center;
  min-height: 31px;
  border: 1px solid var(--line);
  border-radius: 10px;
  color: var(--muted);
  background: color-mix(in srgb, var(--panel) 58%, transparent);
  font-size: 11px;
  font-weight: 640;
  letter-spacing: 0;
}
.sys-mode-ladder span.on {
  color: var(--text);
  border-color: color-mix(in srgb, var(--up) 42%, var(--line));
  background: color-mix(in srgb, var(--up) 12%, var(--panel));
}
.sys-mode-ladder span.warn.on {
  border-color: color-mix(in srgb, var(--down) 36%, var(--line));
  background: color-mix(in srgb, var(--down) 10%, var(--panel));
}
.sys-alert {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--down);
  font-size: 13px;
  font-weight: 660;
}
.sys-metric-grid,
.sys-impact-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}
.sys-metric {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  min-height: 98px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: color-mix(in srgb, var(--panel) 82%, transparent);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.44);
}
.sys-metric-icon,
.sys-impact-icon,
.sys-source-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  color: var(--muted);
  background: color-mix(in srgb, var(--muted) 9%, transparent);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.42);
}
.sys-metric.ok .sys-metric-icon,
.sys-impact-card.ok .sys-impact-icon,
.sys-source-row.ok .sys-source-icon,
.sys-check-step.ok i { color: var(--up); background: color-mix(in srgb, var(--up) 12%, transparent); }
.sys-metric.warn .sys-metric-icon,
.sys-impact-card.warn .sys-impact-icon,
.sys-source-row.warn .sys-source-icon,
.sys-check-step.warn i { color: var(--accent-ink); background: color-mix(in srgb, var(--accent) 15%, transparent); }
.sys-metric.bad .sys-metric-icon,
.sys-impact-card.bad .sys-impact-icon,
.sys-source-row.bad .sys-source-icon,
.sys-check-step.bad i { color: var(--down); background: color-mix(in srgb, var(--down) 11%, transparent); }
[data-theme="dark"] .sys-metric.warn .sys-metric-icon,
[data-theme="dark"] .sys-impact-card.warn .sys-impact-icon,
[data-theme="dark"] .sys-source-row.warn .sys-source-icon,
[data-theme="dark"] .sys-check-step.warn i { color: var(--accent); }
.sys-metric em {
  display: block;
  color: var(--muted);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 640;
  letter-spacing: 0;
  text-transform: uppercase;
}
.sys-metric b {
  display: block;
  margin-top: 6px;
  color: var(--text);
  font-size: 22px;
  font-weight: 600;
  line-height: 1.05;
}
.sys-metric small {
  display: block;
  margin-top: 5px;
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 560;
  line-height: 1.35;
}
.sys-impact-card {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  min-height: 112px;
  padding: 15px;
  text-align: left;
  border: 1px solid var(--line);
  border-radius: 15px;
  color: var(--text);
  background: color-mix(in srgb, var(--panel) 78%, transparent);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.42);
  transition: transform .14s ease, border-color .14s ease, background .14s ease;
}
.sys-impact-card:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--text) 20%, var(--line));
  background: var(--hover);
}
.sys-impact-copy {
  min-width: 0;
}
.sys-impact-copy span {
  display: block;
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 640;
  letter-spacing: 0;
  text-transform: uppercase;
}
.sys-impact-copy b {
  display: block;
  margin-top: 4px;
  color: var(--text);
  font-size: 18px;
  font-weight: 640;
  line-height: 1.15;
}
.sys-impact-copy em {
  display: block;
  margin-top: 5px;
  color: var(--text-2);
  font-size: 12px;
  font-style: normal;
  font-weight: 520;
  line-height: 1.35;
}
.sys-impact-action {
  align-self: end;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0;
}
.sys-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 372px;
  gap: 16px;
  align-items: start;
}
.sys-main,
.sys-panel {
  margin-bottom: 0;
}
.sys-rail {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.sys-section-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 14px;
}
.sys-section-head.compact {
  margin-bottom: 12px;
}
.sys-section-head h2 {
  margin: 0;
  color: var(--text);
  font-size: 18px;
  font-weight: 640;
  letter-spacing: 0;
}
.sys-section-head span:not(.state-pill) {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 560;
  line-height: 1.4;
}
.sys-source-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.sys-source-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  min-height: 66px;
  padding: 11px 12px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: color-mix(in srgb, var(--tile) 62%, transparent);
}
.sys-source-copy {
  min-width: 0;
}
.sys-source-copy b {
  display: block;
  color: var(--text);
  font-size: 13.5px;
  font-weight: 690;
  line-height: 1.2;
}
.sys-source-copy em {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 520;
  line-height: 1.35;
}
.sys-check-list,
.sys-action-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.sys-check-step {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: color-mix(in srgb, var(--tile) 62%, transparent);
}
.sys-check-step i {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  border-radius: 8px;
  color: var(--muted);
  background: color-mix(in srgb, var(--muted) 10%, transparent);
  font-size: 11px;
  font-style: normal;
  font-weight: 600;
}
.sys-check-step b {
  display: block;
  color: var(--text);
  font-size: 12.5px;
  font-weight: 690;
  line-height: 1.25;
}
.sys-check-step em {
  display: block;
  margin-top: 4px;
  color: var(--muted);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 520;
  line-height: 1.35;
}
.sys-weight span {
  display: block;
  height: 10px;
  border-radius: var(--r-pill);
  overflow: hidden;
  background: color-mix(in srgb, var(--line) 78%, transparent);
}
.sys-weight i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--up);
}
.sys-weight.warn i { background: var(--accent); }
.sys-weight.bad i { background: var(--down); }
.sys-weight b {
  display: block;
  margin-top: 10px;
  color: var(--text);
  font-size: 25px;
  font-weight: 600;
  line-height: 1;
}
.sys-weight em {
  display: block;
  margin-top: 6px;
  color: var(--muted);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 520;
  line-height: 1.35;
}
.sys-action-list button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 42px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 12px;
  color: var(--text);
  background: color-mix(in srgb, var(--tile) 58%, transparent);
  transition: background .14s ease, border-color .14s ease, transform .14s ease;
}
.sys-action-list button:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--text) 18%, var(--line));
  background: var(--hover);
}
.sys-action-list span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  font-size: 12.5px;
  font-weight: 650;
}
.sys-action-list b {
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}
.sys-source-line {
  margin: 13px 4px 0;
  color: var(--faint);
  font-size: 11.5px;
  font-weight: 520;
}

@media (max-width: 1180px) {
  .sys-hero,
  .sys-layout {
    grid-template-columns: 1fr;
  }
  .sys-metric-grid,
  .sys-impact-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .sys-hero {
    padding: 18px;
  }
  .sys-metric-grid,
  .sys-impact-grid,
  .sys-mode-ladder {
    grid-template-columns: 1fr;
  }
  .sys-impact-card,
  .sys-source-row {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .sys-impact-action,
  .sys-source-row .state-pill {
    grid-column: 2 / -1;
    justify-self: start;
  }
  .sys-section-head {
    flex-direction: column;
  }
}

/* accessibility / capability fallbacks for the glass */
@media (prefers-reduced-transparency: reduce) {
  .hdr, .snav, .menu-pop, .dialog, .cmd, .health-badge, .hb-tip, .bottom-nav {
    background: var(--bg);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }
  body::before { display: none; }
}
@supports not (backdrop-filter: blur(1px)) {
  .hdr, .snav, .menu-pop, .dialog, .cmd, .health-badge, .hb-tip, .bottom-nav { background: var(--bg); }
}
[data-theme="dark"] .fills-source-strip {
  gap: 0;
  margin-bottom: 18px;
  border-top: 1px solid var(--line-2);
  border-bottom: 1px solid var(--line-2);
}

/* ===== PAGE RESCUE: dashboard ===== */
.dashboard-page {
  max-width: min(1640px, 100%);
}

.dashboard-head {
  align-items: flex-end;
  margin-top: 28px;
  margin-bottom: 14px;
}

.dashboard-head .page-title {
  margin: 4px 0 0;
  font-size: 31px;
  line-height: 1.04;
  font-weight: 520;
}

.dashboard-head .page-sub {
  margin-top: 6px;
  max-width: 680px;
  font-size: 13px;
  font-weight: 430;
  line-height: 1.4;
}

.dashboard-head .head-actions {
  gap: 8px;
}

.dash-command-center {
  padding: 0;
  overflow: hidden;
  border-radius: 14px;
  background: color-mix(in srgb, var(--panel) 96%, transparent);
}

[data-theme="dark"] .dash-command-center {
  background: var(--panel);
  border-color: transparent;
  box-shadow: none;
}

[data-theme="dark"] .dash-command-center::after,
[data-theme="dark"] .dash-decision-item::before {
  display: none;
}

.dash-command-top {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 420px;
  min-width: 0;
}

.dash-truth-panel {
  min-width: 0;
  padding: 22px 24px 20px;
  border-right: 1px solid var(--line);
}

.dash-truth-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 620;
}

.dash-truth-meta span {
  min-width: 0;
}

.dash-mode-text {
  color: var(--muted);
  font-weight: 640;
}

.dash-mode-text.ok { color: var(--up); }
.dash-mode-text.bad { color: var(--down); }
.dash-mode-text.warn { color: var(--accent-ink); }
[data-theme="dark"] .dash-mode-text.warn { color: var(--accent); }

.dash-truth-main {
  display: grid;
  gap: 5px;
  margin-top: 20px;
}

.dash-truth-main > span,
.dash-kpi-label,
.dash-posture-score > span,
.dash-decision-head span:not(.state-pill) {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 620;
  letter-spacing: 0;
  text-transform: uppercase;
}

.dash-truth-main > b {
  color: var(--text);
  font-size: 48px;
  font-weight: 560;
  line-height: 1;
  letter-spacing: 0;
}

.dash-truth-main > .dash-truth-empty {
  justify-self: start;
  margin-top: 2px;
  padding: 7px 10px;
  border-radius: 9px;
  color: var(--text);
  background: color-mix(in srgb, var(--tile) 80%, transparent);
  border: 1px solid var(--line);
  font-size: 13px;
  font-weight: 650;
  line-height: 1;
}

.dash-truth-main > em {
  max-width: 720px;
  color: var(--text-2);
  font-size: 13px;
  font-style: normal;
  font-weight: 430;
  line-height: 1.5;
}

.dash-truth-note {
  display: inline-flex;
  max-width: 720px;
  margin-top: 18px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
  font-weight: 440;
  line-height: 1.45;
}

.dash-posture-panel {
  display: grid;
  grid-template-columns: 118px minmax(0, 1fr);
  gap: 16px;
  align-content: start;
  padding: 20px 22px;
  background: color-mix(in srgb, var(--tile) 32%, transparent);
}

[data-theme="dark"] .dash-posture-panel {
  background: transparent;
}

.dash-posture-score {
  display: grid;
  align-content: start;
  gap: 5px;
  padding-right: 14px;
  border-right: 1px solid var(--line);
}

.dash-posture-score b {
  color: var(--text);
  font-size: 31px;
  font-weight: 570;
  line-height: 1;
}

.dash-posture-score em {
  color: var(--muted);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 430;
  line-height: 1.35;
}

.dash-posture-list {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 14px;
}

.dash-posture-list .dash-readiness-item {
  grid-template-columns: 24px minmax(0, 1fr);
  gap: 8px;
  min-height: 45px;
  padding: 7px 0;
  border-bottom: 1px solid var(--line);
}

.dash-posture-list .dash-readiness-item > span:first-child {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  background: transparent;
  box-shadow: none;
}

.dash-posture-list .dash-readiness-item b {
  font-size: 11.5px;
  font-weight: 620;
}

.dash-posture-list .dash-readiness-item em {
  font-size: 10.5px;
  font-weight: 430;
}

.dash-kpi-strip {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.dash-command-kpi {
  min-width: 0;
  min-height: 92px;
  padding: 14px 15px;
  border-right: 1px solid var(--line);
}

.dash-command-kpi:last-child {
  border-right: 0;
}

.dash-kpi-value {
  display: block;
  margin-top: 6px;
  color: var(--text);
  font-size: 22px;
  font-weight: 560;
  line-height: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dash-command-kpi.idle .dash-kpi-value {
  font-size: 18px;
  font-weight: 520;
}

.dash-command-kpi.ok .dash-kpi-value,
.dash-command-kpi.ok .dash-kpi-value .up { color: var(--up); }
.dash-command-kpi.bad .dash-kpi-value,
.dash-command-kpi.bad .dash-kpi-value .down { color: var(--down); }
.dash-command-kpi.warn .dash-kpi-value { color: var(--accent-ink); }
[data-theme="dark"] .dash-command-kpi.warn .dash-kpi-value { color: var(--accent); }

.dash-kpi-sub {
  display: block;
  margin-top: 6px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 430;
  line-height: 1.3;
}

.dash-command-kpi .dash-meter {
  height: 4px;
  margin-top: 9px;
}

.dash-decision-stack {
  padding: 0;
}

.dash-decision-head {
  min-height: 54px;
  padding: 13px 18px;
}

.dash-decision-head h2 {
  margin-top: 2px;
  font-size: 17px;
  font-weight: 540;
}

.dash-decision-grid {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.dash-decision-item {
  min-height: 108px;
  grid-template-columns: 26px 28px minmax(0, 1fr);
  grid-template-rows: auto auto;
  gap: 8px 10px;
  padding: 13px 15px 14px;
}

.dash-decision-rank {
  grid-row: 1 / span 2;
  color: var(--faint);
  font-size: 12px;
  font-weight: 520;
}

.dash-decision-icon {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  box-shadow: none;
}

.dash-decision-copy {
  gap: 0;
}

.dash-decision-meta {
  font-size: 9.5px;
  font-weight: 650;
}

.dash-decision-copy b,
.dash-decision-item.primary .dash-decision-copy b {
  margin-top: 3px;
  font-size: 13.5px;
  font-weight: 620;
  line-height: 1.17;
}

.dash-decision-copy em {
  display: -webkit-box;
  margin-top: 4px;
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 430;
  line-height: 1.32;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.dash-decision-action {
  grid-column: 3;
  min-height: 0;
  padding: 0;
  border-radius: 0;
  color: var(--text-2);
  background: transparent;
  box-shadow: none;
  font-size: 11px;
  font-weight: 620;
}

.dash-decision-item:hover .dash-decision-action {
  color: var(--text);
  background: transparent;
}

[data-theme="dark"] .dash-decision-item.primary {
  background: transparent;
}

.dash-compact-empty {
  min-height: 86px;
  place-content: center start;
  text-align: left;
  padding: 12px 0;
}

.dash-compact-empty b {
  font-size: 12.5px;
  font-weight: 620;
}

.dash-system-row {
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 34px;
  padding: 7px 0;
}

.dash-system-row b {
  color: var(--muted);
  font-weight: 610;
}

.dash-system-row.tone-ok b { color: var(--up); }
.dash-system-row.tone-warn b { color: var(--accent-ink); }
.dash-system-row.tone-bad b { color: var(--down); }
[data-theme="dark"] .dash-system-row.tone-warn b { color: var(--accent); }

.dash-proposal-row,
.dash-asset-row {
  min-height: 36px;
  padding: 8px;
}

@media (max-width: 1360px) {
  .dash-command-top {
    grid-template-columns: 1fr;
  }

  .dash-truth-panel {
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .dash-posture-panel {
    grid-template-columns: 118px minmax(0, 1fr);
  }

  .dash-kpi-strip,
  .dash-decision-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .dash-command-kpi:nth-child(3n),
  .dash-decision-item:nth-child(3n) {
    border-right: 0;
  }

  .dash-command-kpi:nth-child(n + 4),
  .dash-decision-item:nth-child(n + 4) {
    border-top: 1px solid var(--line);
  }
}

@media (max-width: 860px) {
  .dashboard-head {
    align-items: flex-start;
  }

  .dash-posture-panel,
  .dash-posture-list,
  .dash-kpi-strip,
  .dash-decision-grid {
    grid-template-columns: 1fr;
  }

  .dash-command-kpi,
  .dash-command-kpi:nth-child(3n),
  .dash-decision-item,
  .dash-decision-item:nth-child(3n) {
    border-right: 0;
  }

  .dash-command-kpi:nth-child(n + 2),
  .dash-decision-item:nth-child(n + 2) {
    border-top: 1px solid var(--line);
  }

  .dash-posture-score {
    padding-right: 0;
    padding-bottom: 12px;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .dash-decision-item {
    grid-template-columns: 26px 28px minmax(0, 1fr);
  }
}

@media (max-width: 620px) {
  .dashboard-head .page-title {
    font-size: 26px;
  }

  .dash-truth-panel,
  .dash-posture-panel {
    padding: 18px;
  }

  .dash-truth-main > b {
    font-size: 34px;
  }
}
.ledger-console-card {
