  cursor: help;
  opacity: 1;
  color: var(--muted);
  background: color-mix(in srgb, var(--tile) 62%, transparent);
  border-color: var(--line);
  box-shadow: none;
}

.settings-disabled-control:disabled:hover {
  transform: none;
  background: color-mix(in srgb, var(--tile) 62%, transparent);
}

.settings-posture-strip {
  border-color: var(--line);
  background: color-mix(in srgb, var(--panel) 88%, transparent);
}

.settings-posture-strip > div {
  min-height: 72px;
}

.posture-medal {
  font-weight: 600;
  box-shadow: none;
}

.settings-setup-card {
  padding: 0;
  overflow: hidden;
  border-color: var(--line);
}

.settings-setup-card .setup-list {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style-position: inside;
  counter-reset: setup;
}

.settings-setup-card .setup-list li {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr);
  gap: 10px;
  min-height: 44px;
  padding: 11px 14px;
  color: var(--text-2);
  font-size: 12px;
  font-weight: 500;
  line-height: 1.35;
}

.settings-setup-card .setup-list li + li {
  border-top: 1px solid var(--line);
}

.settings-setup-card .setup-list li::before {
  counter-increment: setup;
  content: counter(setup);
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 7px;
  color: var(--muted);
  background: var(--tile);
  font-size: 11px;
  font-weight: 620;
}

.settings-setup-card .setup-list b {
  color: var(--text);
  font-weight: 620;
}

[data-theme="dark"] .settings-left-rail,
[data-theme="dark"] .settings-account-panel,
[data-theme="dark"] .settings-control-surface,
[data-theme="dark"] .settings-group,
[data-theme="dark"] .settings-posture-strip,
[data-theme="dark"] .settings-setup-card {
  background: var(--panel);
  border-color: transparent;
  box-shadow: none;
}

[data-theme="dark"] .settings-left-rail::after,
[data-theme="dark"] .settings-account-panel::after,
[data-theme="dark"] .settings-control-surface::after,
[data-theme="dark"] .settings-group::after,
[data-theme="dark"] .settings-posture-strip::after,
[data-theme="dark"] .settings-setup-card::after,
[data-theme="dark"] .settings-preview-card::after,
[data-theme="dark"] .settings-density-card::after {
