/* ========================================================================
   Arbitrage cockpit — sidebar nav motion, brand, Binance news rail,
   notifications, and the always-visible left bar (icon rail on narrow).
   Appended last so the responsive overrides win the cascade.
   ======================================================================== */

/* nav icon motion — high-quality inline SVGs with a little life */
.snav-ic {
  flex: none; display: inline-flex; align-items: center; justify-content: center;
  width: 20px; height: 20px; color: inherit;
  transition: transform .18s cubic-bezier(.3,.7,.2,1), color .12s;
}
.snav-ic svg { width: 17px; height: 17px; }
.snav-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.snav-item:hover .snav-ic { transform: translateX(1px) scale(1.08); }
.snav-item.active .snav-ic { color: var(--accent); }
.snav-item.active .snav-ic svg { animation: navPop .34s cubic-bezier(.34,1.56,.5,1); }
@keyframes navPop { 0% { transform: scale(.78); } 60% { transform: scale(1.14); } 100% { transform: scale(1); } }
.snav-item.active::before { animation: navBar .28s ease both; }
@keyframes navBar { from { transform: scaleY(0); } to { transform: scaleY(1); } }

/* Binance news rail inside the sidebar */
.snav-news {
  margin: 4px 2px 6px; padding: 10px 8px 4px; border-top: 1px solid var(--line);
}
.snav-news-head { display: flex; align-items: center; justify-content: space-between; padding: 0 2px 6px; }
.snn-title {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 9.5px; font-weight: 650; letter-spacing: .5px; text-transform: uppercase; color: var(--faint);
}
.snn-title svg { width: 13px; height: 13px; }
.snn-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--faint); flex: none; }
.snn-dot.ok { background: var(--up); animation: hbPulse 2.6s ease-out infinite; }
.snn-dot.bad { background: var(--down); }
.snav-news-body { display: flex; flex-direction: column; gap: 2px; }
.snn-item {
  display: block; padding: 6px 6px; border-radius: 8px; text-decoration: none;
  transition: background .12s;
}
.snn-item:hover { background: var(--hover); }
.snn-item-title {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
  font-size: 11.5px; font-weight: 600; line-height: 1.32; color: var(--text-2);
}
.snn-item:hover .snn-item-title { color: var(--text); }
.snn-item-date { display: block; margin-top: 2px; font-size: 10px; color: var(--faint); }
.snn-empty { padding: 8px 6px; font-size: 11.5px; color: var(--muted); }

/* notification bell badge + popover */
.hdr-ic { position: relative; }
.ic-badge {
  position: absolute; top: 1px; right: 1px; min-width: 15px; height: 15px; padding: 0 4px;
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: 999px; background: var(--down); color: #fff;
  font-size: 9px; font-weight: 650; line-height: 1; border: 1.5px solid var(--panel);
}
.notif-pop { min-width: 300px; max-width: 340px; padding: 8px 10px 10px; }
.notif-pop .np-head { display: flex; align-items: center; justify-content: space-between; padding: 2px 2px 8px; border-bottom: 1px solid var(--line); margin-bottom: 4px; }
.notif-pop .np-title { font-size: 12.5px; font-weight: 620; color: var(--text); }
.np-link { border: 0; background: none; color: var(--accent-ink); font-size: 11.5px; font-weight: 620; cursor: pointer; padding: 0; }
[data-theme="dark"] .np-link { color: var(--accent); }
.notif-row {
  display: flex; align-items: center; gap: 9px; width: 100%; padding: 7px 6px; border: 0;
  background: none; border-radius: 9px; cursor: pointer; text-align: left;
}
.notif-row:hover { background: var(--tile); }
.notif-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--muted); flex: none; }
.notif-dot.ok { background: var(--up); } .notif-dot.warn { background: var(--accent); } .notif-dot.bad { background: var(--down); }
.notif-text { flex: 1; min-width: 0; font-size: 12px; font-weight: 560; color: var(--text-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.notif-time { font-size: 10.5px; color: var(--faint); white-space: nowrap; }

/* ---- keep the left bar visible at ALL widths (icon rail when narrow) ---- */
@media (max-width: 1180px) {
  .app-root { display: flex; }
  .app-main { width: auto; }
  .snav { display: flex; }
  .bottom-nav { display: none !important; }
}
@media (max-width: 820px) {
  .snav { width: 64px !important; padding: 12px 6px; }
  .snav-brand { justify-content: center; gap: 0; padding: 6px 0 12px; }
  .brand-lockup { display: none; }
  .snav-group-title { display: none; }
  .snav-group { margin-bottom: 4px; }
  .snav-item { justify-content: center; gap: 0; padding: 0; height: 44px; }
  .snav-label { display: none; }
  .snav-item .nav-badge { position: absolute; top: 5px; right: 9px; margin: 0; padding: 1px 4px; }
  .snav-item.active::before { left: -8px; }
  .snav-news { display: none; }
  .snav-foot { padding: 10px 0 2px; }
  .snav-foot .mode-pill { padding: 0; width: 100% !important; font-size: 0; height: 30px; }
  .snav-foot .mode-pill .dot { width: 8px; height: 8px; }
  .snav-foot .faint { display: none; }
}

/* ========================================================================
   Cockpit v2 — live dots, sidebar utils, hover→accent, currency / alerts /
   data-health / zoom controls, translucent popovers, and the news + calendar
   overlays. Appended last so these win the cascade.
   ======================================================================== */

/* live-refresh dot */
.live-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--up); position: relative; }
.live-dot.off { background: var(--muted); }
.live-dot::after {
  content: ""; position: absolute; inset: 0; border-radius: 50%; background: inherit;
  animation: livePulse 1.8s ease-out infinite;
}
.live-dot.off::after { animation: none; }
@keyframes livePulse { 0% { transform: scale(1); opacity: .55; } 70% { transform: scale(3); opacity: 0; } 100% { opacity: 0; } }

/* hover → accent (sidebar + top bar), per request */
.snav-item:hover { color: var(--accent); background: color-mix(in srgb, var(--accent-soft) 42%, transparent); }
.snav-item:hover .snav-ic { color: var(--accent); }
.icon-btn:hover, .hdr-ic:hover, .net-btn:hover, .ic-pill:hover, .hdr-clock-btn:hover, .snav-util:hover {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent-soft) 40%, transparent);
  border-color: color-mix(in srgb, var(--accent-line) 55%, transparent);
}

/* sidebar util buttons (News, Calendar) */
.snav-utils { display: flex; flex-direction: column; gap: 4px; margin-top: 8px; padding-top: 8px; }
/* News / Calendar: proper tiles with a bigger icon presence (Binance-style),
   not just small nav rows. */
.snav-util {
  position: relative; display: flex; align-items: center; gap: 10px; width: 100%;
  height: 42px; padding: 0 9px; border: 0; background: var(--tile); border-radius: 11px;
  color: var(--text-2); font-size: 13px; font-weight: 660; text-align: left; cursor: pointer;
  transition: color .12s, background .12s, transform .12s;
}
.snav-util:hover { transform: translateY(-1px); }
.snav-util.active { color: var(--accent-ink); background: color-mix(in srgb, var(--accent-soft) 55%, transparent); }
[data-theme="dark"] .snav-util.active { color: var(--accent); }
.snav-util .snav-ic {
  width: 28px; height: 28px; border-radius: 8px; display: inline-flex; align-items: center; justify-content: center;
  background: var(--panel); box-shadow: var(--shadow-sm); color: var(--accent-ink);
}
[data-theme="dark"] .snav-util .snav-ic { color: var(--accent); box-shadow: none; background: var(--tile-hover); }
.snav-util .snav-ic svg { width: 20px; height: 20px; }
.snav-util .live-dot { margin-left: auto; }

/* frosted (translucent, not see-through) popovers */
.menu-pop {
  background: color-mix(in srgb, var(--panel) 93%, transparent) !important;
  backdrop-filter: saturate(180%) blur(22px);
  -webkit-backdrop-filter: saturate(180%) blur(22px);
  border-color: var(--line-2);
}
.menu-foot { padding: 8px 10px 2px; font-size: 10.5px; color: var(--faint); line-height: 1.4; }
.np-sub { font-size: 11px; font-weight: 600; color: var(--muted); }
.np-sub-line { padding: 2px 4px 8px; font-size: 11px; color: var(--muted); line-height: 1.35; }

/* currency pill + picker */
.ic-pill {
  display: inline-flex; align-items: center; gap: 5px; height: 28px; padding: 0 9px;
  border: 1px solid transparent; border-radius: 9px; background: transparent; color: var(--muted);
  font-size: 11.5px; font-weight: 620; cursor: pointer; transition: background .12s, color .12s, border-color .12s;
}
.ic-pill svg { width: 15px; height: 15px; }
.ic-pill-txt { letter-spacing: .3px; }
.cur-pop { min-width: 236px; }
.cur-sym { width: 26px; flex: none; font-size: 14px; font-weight: 650; color: var(--text); text-align: center; }
.cur-label { flex: 1; font-size: 12.5px; font-weight: 600; color: var(--text); text-align: left; }
.cur-code { font-size: 11px; font-weight: 620; color: var(--muted); }

/* alerts */
.alert-pop { min-width: 300px; padding: 8px 10px 6px; }
.alert-row { display: flex; align-items: center; gap: 12px; padding: 8px 4px; }
.alert-meta { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.alert-label { font-size: 12.5px; font-weight: 640; color: var(--text); }
.alert-sub { font-size: 10.5px; color: var(--muted); }
.toggle {
  flex: none; width: 38px; height: 22px; border-radius: 999px; border: 0; cursor: pointer; padding: 0;
  background: var(--line-strong); position: relative; transition: background .16s;
}
.toggle.on { background: var(--accent); }
.toggle .knob {
  position: absolute; top: 2px; left: 2px; width: 18px; height: 18px; border-radius: 50%;
  background: #fff; box-shadow: 0 1px 3px rgba(0,0,0,.3); transition: transform .16s;
}
.toggle.on .knob { transform: translateX(16px); }
.ic-dot.accent { background: var(--accent) !important; }

/* data health */
.dh-pop { min-width: 288px; padding: 8px 10px 8px; }
.dh-row { display: flex; align-items: center; gap: 9px; padding: 6px 4px; font-size: 12px; }
.dh-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; background: var(--muted); }
.dh-dot.ok { background: var(--up); } .dh-dot.bad { background: var(--down); }
.dh-name { flex: 1; color: var(--text); font-weight: 600; }
.dh-detail { color: var(--text-2); font-weight: 600; font-size: 11px; }
.dh-detail.muted { color: var(--muted); font-weight: 500; }
.dh-params { margin-top: 4px; border-top: 1px solid var(--line); padding-top: 2px; }

/* zoom */
.zoom-pop { min-width: 190px; padding: 8px 10px 10px; }
.zoom-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 4px 2px 8px; }
.zoom-btn { width: 34px; height: 30px; border-radius: 9px; border: 1px solid var(--line-2); background: var(--tile); color: var(--text); font-size: 17px; font-weight: 620; cursor: pointer; }
.zoom-btn:hover { color: var(--accent); border-color: var(--accent-line); }
.zoom-val { font-size: 14px; font-weight: 650; color: var(--text); }
.zoom-reset { width: 100%; height: 30px; border-radius: 9px; border: 1px solid var(--line-2); background: none; color: var(--muted); font-size: 12px; font-weight: 640; cursor: pointer; }
.zoom-reset:hover { color: var(--accent); border-color: var(--accent-line); }

/* bigger notification popout */
.notif-pop { min-width: 340px !important; max-width: 380px; }

/* ---- on-demand overlays (news + calendar) ---- */
.ov-backdrop {
  position: fixed; inset: 0; z-index: 200; display: flex; align-items: center; justify-content: center;
  padding: 24px; background: rgba(8,11,16,.42); backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px);
  animation: ovFade .14s ease both;
}
@keyframes ovFade { from { opacity: 0; } to { opacity: 1; } }
.ov-modal {
  display: flex; flex-direction: column; width: min(760px, calc(94vw / var(--uiz, 1))); max-height: calc(82vh / var(--uiz, 1));
  background: var(--panel); border: 1px solid var(--line-2); border-radius: 18px;
  box-shadow: var(--shadow-pop); overflow: hidden; animation: ovRise .16s cubic-bezier(.3,.8,.3,1) both;
}
@keyframes ovRise { from { transform: translateY(10px) scale(.99); opacity: 0; } to { transform: none; opacity: 1; } }
.ov-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 16px; border-bottom: 1px solid var(--line); }
.ov-title { display: inline-flex; align-items: center; gap: 9px; font-size: 15px; font-weight: 650; color: var(--text); }
.ov-title svg { color: var(--accent); }
.ov-actions { display: flex; align-items: center; gap: 8px; }
.ov-btn { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px; border-radius: 9px; border: 1px solid var(--line-2); background: var(--tile); color: var(--text-2); font-size: 12px; font-weight: 640; text-decoration: none; }
.ov-btn:hover { color: var(--accent); border-color: var(--accent-line); }
.ov-close { width: 32px; height: 30px; display: grid; place-items: center; border: 0; background: none; border-radius: 9px; color: var(--muted); cursor: pointer; }
.ov-close:hover { color: var(--accent); background: var(--tile); }
.ov-empty { padding: 40px 16px; text-align: center; color: var(--muted); font-size: 13px; }

/* news modal */
.news-tabs { display: flex; flex-wrap: wrap; gap: 6px; padding: 12px 16px; border-bottom: 1px solid var(--line); }
.news-tab { height: 30px; padding: 0 12px; border-radius: 999px; border: 1px solid var(--line-2); background: var(--tile); color: var(--muted); font-size: 12px; font-weight: 640; cursor: pointer; transition: all .12s; }
.news-tab:hover { color: var(--text); }
.news-tab.on { background: var(--accent); color: var(--cta-fg); border-color: var(--accent); }
.news-list { overflow-y: auto; padding: 6px 8px 12px; }
.news-item { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 12px 12px; border-radius: 11px; text-decoration: none; transition: background .12s; }
.news-item:hover { background: var(--hover); }
.news-item-title { font-size: 13.5px; font-weight: 600; color: var(--text); line-height: 1.4; }
.news-item:hover .news-item-title { color: var(--accent); }
.news-item-meta { display: inline-flex; align-items: center; gap: 8px; flex: none; color: var(--faint); }
.news-item-date { font-size: 11.5px; color: var(--muted); white-space: nowrap; }

/* calendar modal */
.cal-cols, .cal-row { display: grid; grid-template-columns: 60px 1fr 78px 78px 78px; align-items: center; gap: 10px; }
.cal-cols { padding: 10px 18px; border-bottom: 1px solid var(--line); font-size: 10.5px; font-weight: 650; letter-spacing: .5px; text-transform: uppercase; color: var(--faint); }
.cal-cols .cc-num, .cal-row .cc-num { text-align: right; }
.cal-list { overflow-y: auto; padding: 4px 0 12px; }
.cal-day-head { position: sticky; top: 0; background: color-mix(in srgb, var(--panel) 94%, transparent); backdrop-filter: blur(6px); padding: 8px 18px; font-size: 11.5px; font-weight: 650; color: var(--text-2); z-index: 1; }
.cal-row { padding: 8px 18px; font-size: 12.5px; }
.cal-row:hover { background: var(--hover); }
.cc-time { color: var(--muted); font-size: 11.5px; }
.cc-evt { display: inline-flex; align-items: center; gap: 8px; min-width: 0; }
.cal-flag { font-size: 15px; line-height: 1; flex: none; }
.cal-imp { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--muted); }
.cal-imp.med { background: var(--accent); } .cal-imp.high { background: var(--down); }
.cal-title { color: var(--text); font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cal-period { color: var(--faint); font-weight: 500; }
.cc-num.strong { color: var(--text); font-weight: 620; }

/* rail: keep the News/Calendar utils icon-only too */
@media (max-width: 1060px) {
  .snav-utils { align-items: center; }
  .snav-util { justify-content: center; gap: 0; padding: 0; height: 42px; }
  .snav-util .snav-label, .snav-util .live-dot { display: none; }
}

/* ========================================================================
   Cockpit v3 — GC-style brand band + account card + sidebar search, tightened
   nav metrics, Rules / News / Calendar pages, cost card. Appended last.
   ======================================================================== */

/* tighter icon column: the glyph never outweighs its label */
.snav-ic { width: 20px; height: 20px; }
.snav-ic svg { width: 19px; height: 19px; }
.snav-item .snav-label { flex: 1; }
.snav-item > svg { color: var(--faint); } /* external-link hint on Cloud Shell */

/* ---- account card (Binance-style) ---- */
.acct-wrap { position: relative; flex: none; padding: 2px 0 8px; }
.acct-card {
  display: flex; align-items: center; gap: 9px; width: 100%;
  padding: 7px 8px; border: 1px solid var(--line-2); background: var(--tile);
  border-radius: 12px; cursor: pointer; text-align: left;
  transition: background .12s, border-color .12s;
}
.acct-card:hover, .acct-card.on { background: var(--tile-hover); border-color: var(--accent-line); }
.acct-avatar {
  position: relative; flex: none; width: 30px; height: 30px; border-radius: 50%;
  overflow: hidden; display: grid; place-items: center;
  background: color-mix(in srgb, var(--accent-soft) 70%, transparent); color: var(--accent-ink);
  border: 0; cursor: pointer;
}
[data-theme="dark"] .acct-avatar { color: var(--accent); }
.acct-avatar img { width: 100%; height: 100%; object-fit: cover; display: block; }
.acct-avatar.lg { width: 46px; height: 46px; overflow: visible; }
.acct-avatar.lg img { border-radius: 50%; }
.acct-cam {
  position: absolute; right: -2px; bottom: -2px; width: 18px; height: 18px; border-radius: 50%;
  display: grid; place-items: center; background: var(--accent); color: var(--cta-fg);
  border: 2px solid var(--panel);
}
.acct-meta { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.acct-name { font-size: 13px; font-weight: 650; color: var(--text); line-height: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.acct-sub { display: inline-flex; align-items: center; gap: 5px; font-size: 10.5px; font-weight: 620; color: var(--muted); white-space: nowrap; }
.acct-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--faint); flex: none; }
.acct-dot.ok { background: var(--up); } .acct-dot.bad { background: var(--down); }
.acct-pop { position: absolute; top: calc(100% + 6px); left: 0; right: -8px; z-index: 90; min-width: 0; padding: 12px 12px 8px; }
.acct-pop-head { display: flex; align-items: center; gap: 12px; padding-bottom: 10px; }
.acct-pop-id { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.acct-pop-name { border: 0; background: none; padding: 0; font-size: 15px; font-weight: 600; color: var(--text); cursor: text; text-align: left; }
.acct-pop-name:hover { color: var(--accent); }
.acct-pop-sub { font-size: 11px; color: var(--muted); }
.acct-name-form { display: flex; gap: 6px; }
.acct-name-form input {
  width: 120px; height: 28px; border-radius: 8px; border: 1px solid var(--accent-line);
  background: var(--bg); color: var(--text); font-size: 13px; padding: 0 8px; outline: none;
}
.acct-name-form button { height: 28px; padding: 0 10px; border-radius: 8px; border: 0; background: var(--accent); color: var(--cta-fg); font-size: 12px; font-weight: 620; cursor: pointer; }
.acct-ex-row { display: flex; align-items: center; justify-content: space-between; padding: 6px 2px; }
.acct-ex-name { font-size: 13px; font-weight: 620; color: var(--text); }
.acct-ex-state { font-size: 11.5px; font-weight: 640; }
.acct-ex-state.ok { color: var(--up); } .acct-ex-state.bad { color: var(--down); } .acct-ex-state.muted { color: var(--muted); }

/* ---- sidebar search ---- */
.snav-search { position: relative; flex: none; padding-bottom: 8px; }
.snav-search-box {
  display: flex; align-items: center; gap: 7px; height: 32px; padding: 0 8px;
  border-radius: 10px; border: 1px solid var(--line-2); background: var(--bg);
  color: var(--muted); transition: border-color .12s, box-shadow .12s;
}
.snav-search-box.on { border-color: var(--accent-line); box-shadow: 0 0 0 3px var(--accent-soft); }
.snav-search-box input {
  flex: 1; min-width: 0; border: 0; background: none; outline: none;
  color: var(--text); font-size: 12.5px; font-family: inherit;
}
.snav-search-box input::placeholder { color: var(--faint); }
.snav-search-k {
  flex: none; border: 1px solid var(--line-2); border-bottom-width: 2px; background: var(--tile);
  border-radius: 5px; padding: 1px 5px; font-size: 9.5px; font-weight: 620; color: var(--muted);
  font-family: var(--mono); cursor: pointer;
}
.snav-search-k:hover { color: var(--accent); border-color: var(--accent-line); }
.snav-search-pop {
  position: absolute; top: calc(100% - 2px); left: 0; right: 0; z-index: 90;
  background: color-mix(in srgb, var(--panel) 96%, transparent);
  backdrop-filter: saturate(180%) blur(22px); -webkit-backdrop-filter: saturate(180%) blur(22px);
  border: 1px solid var(--line-2); border-radius: 12px; box-shadow: var(--shadow-pop);
  padding: 4px; animation: rise .1s ease both;
}
.ssr-row {
  display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%;
  padding: 7px 9px; border: 0; background: none; border-radius: 8px; cursor: pointer; text-align: left;
}
.ssr-row.sel { background: var(--accent-soft); }
.ssr-label { font-size: 12.5px; font-weight: 680; color: var(--text); }
.ssr-row.sel .ssr-label { color: var(--accent-ink); }
[data-theme="dark"] .ssr-row.sel .ssr-label { color: var(--accent); }
.ssr-hint { font-size: 10px; color: var(--faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ssr-empty { padding: 10px; font-size: 11.5px; color: var(--muted); }

/* ---- news + calendar full pages ---- */
.news-page-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; justify-content: space-between; margin: 6px 0 2px; }
.news-page-bar .news-tabs { padding: 0; border: 0; }
.news-filter {
  display: flex; align-items: center; gap: 7px; height: 32px; padding: 0 10px; min-width: 200px;
  border-radius: 999px; border: 1px solid var(--line-2); background: var(--tile); color: var(--muted);
}
.news-filter input { flex: 1; border: 0; background: none; outline: none; color: var(--text); font-size: 12.5px; }
.news-hint { margin: 8px 2px 14px; font-size: 12px; color: var(--muted); }
.news-page-list { display: flex; flex-direction: column; gap: 2px; }
.news-item.lg { padding: 13px 12px; border-radius: 12px; }
.news-item-ic {
  flex: none; width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center;
  background: var(--accent-soft); color: var(--accent-ink); margin-right: 12px;
}
[data-theme="dark"] .news-item-ic { color: var(--accent); }
.news-item-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.news-item-sub { font-size: 11px; color: var(--muted); }
.news-source-note { margin: 18px 2px 0; font-size: 11px; color: var(--faint); line-height: 1.5; }

.cal-filters { display: flex; flex-direction: column; gap: 8px; margin: 6px 0 12px; }
.cal-filters .news-tabs { padding: 0; border: 0; }
.cal-cols.page-cols { border-top: 1px solid var(--line); }
.cal-page-list .cal-row.lg { padding: 10px 18px; font-size: 13px; }
.cal-day-head.lg { display: flex; align-items: center; justify-content: space-between; font-size: 12.5px; padding: 10px 18px 6px; }
.cal-day-count { font-size: 10.5px; font-weight: 640; color: var(--faint); }
.cal-indicator { color: var(--faint); font-weight: 500; }

/* ---- rules page ---- */
.rules-section { margin: 22px 0 6px; }
.rules-h { display: flex; align-items: center; gap: 8px; margin: 0 0 4px; font-size: 16px; font-weight: 600; color: var(--text); }
.rules-h svg { color: var(--accent); }
.rule-badge { font-size: 9.5px; font-weight: 650; letter-spacing: .4px; text-transform: uppercase; padding: 2px 8px; border-radius: 999px; }
.rule-badge.enforced { background: var(--up-soft); color: var(--up); }
.rule-badge.recorded { background: var(--accent-soft); color: var(--accent-ink); }
[data-theme="dark"] .rule-badge.recorded { color: var(--accent); }
.rules-sub { margin: 0 0 12px; font-size: 12.5px; color: var(--muted); max-width: 640px; line-height: 1.5; }
.rules-list { display: flex; flex-direction: column; }
.rule-row { display: flex; align-items: center; gap: 12px; padding: 11px 4px; border-bottom: 1px solid var(--line); }
.rule-row:last-child { border-bottom: 0; }
.rule-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.rule-name { font-size: 13.5px; font-weight: 680; color: var(--text); display: inline-flex; align-items: center; gap: 8px; }
.rule-detail { font-size: 11.5px; color: var(--muted); }
.rule-state { flex: none; font-size: 12px; font-weight: 650; color: var(--text-2); }
.rule-state.ok { color: var(--up); } .rule-state.bad { color: var(--down); } .rule-state.warn { color: var(--accent-ink); }
[data-theme="dark"] .rule-state.warn { color: var(--accent); }
.rule-effect {
  flex: none; width: 52px; text-align: center; font-size: 10px; font-weight: 650; letter-spacing: .4px;
  text-transform: uppercase; padding: 3px 0; border-radius: 7px;
}
.rule-effect.block { background: var(--down-soft); color: var(--down); }
.rule-effect.allow { background: var(--up-soft); color: var(--up); }
.rule-effect.limit { background: var(--accent-soft); color: var(--accent-ink); }
[data-theme="dark"] .rule-effect.limit { color: var(--accent); }
.rule-strict { font-size: 9px; font-weight: 650; letter-spacing: .4px; text-transform: uppercase; background: var(--tile); border: 1px solid var(--line-2); color: var(--muted); padding: 1px 6px; border-radius: 999px; }
.rule-del { flex: none; border: 0; background: none; color: var(--faint); font-size: 11.5px; font-weight: 640; cursor: pointer; }
.rule-del:hover { color: var(--down); }
.rule-form { margin: 2px 0 16px; display: flex; flex-direction: column; gap: 8px; max-width: 640px; }
.rule-form input, .rule-form select {
  height: 36px; border-radius: 10px; border: 1px solid var(--line-2); background: var(--bg);
  color: var(--text); font-size: 13px; padding: 0 11px; outline: none; font-family: inherit;
}
.rule-form input:focus, .rule-form select:focus { border-color: var(--accent-line); box-shadow: 0 0 0 3px var(--accent-soft); }
.rf-row { display: flex; align-items: center; gap: 8px; }
.rf-select { flex: 1 1 0; min-width: 0; }
.rf-select .rf-select-pill {
  width: 100%;
  height: 36px;
  justify-content: space-between;
  padding: 0 11px;
  border: 1px solid var(--line-2);
  border-radius: 10px;
  background: var(--bg);
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
}
.rf-select .mkx-menu {
  min-width: max(160px, 100%);
}
.rf-strict { display: inline-flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 640; color: var(--muted); }
.rf-add {
  height: 36px; padding: 0 16px; border-radius: 10px; border: 0; background: var(--accent);
  color: var(--cta-fg); font-size: 12.5px; font-weight: 650; cursor: pointer;
}
.rf-add:disabled { opacity: .45; cursor: default; }

/* ---- cost & usage card (System Health) ---- */
.cost-card { margin-top: 18px; padding: 18px 20px; }
.cost-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 12px; }
.cost-head h2 { margin: 0; font-size: 16px; font-weight: 600; color: var(--text); }
.cost-scope { font-size: 11px; font-weight: 640; color: var(--muted); }
.cost-body { display: flex; gap: 26px; flex-wrap: wrap; align-items: flex-start; }
.cost-stats { display: flex; gap: 26px; flex: none; }
.cost-stat { display: flex; flex-direction: column; gap: 3px; }
.cost-stat em { font-style: normal; font-size: 10px; font-weight: 650; letter-spacing: .5px; text-transform: uppercase; color: var(--faint); }
.cost-stat b { font-size: 17px; font-weight: 600; color: var(--text-2); }
.cost-stat small { font-size: 10.5px; color: var(--muted); }
.cost-setup { flex: 1; min-width: 260px; display: flex; flex-direction: column; gap: 10px; align-items: flex-start; }
.cost-setup p { margin: 0; font-size: 12px; color: var(--muted); line-height: 1.55; max-width: 520px; }

/* ---- rail (narrow) updates ---- */
@media (max-width: 1060px) {
  .acct-card { justify-content: center; padding: 6px 0; border: 0; background: none; }
  .acct-meta { display: none; }
  .acct-pop { left: 0; right: auto; width: 260px; }
  .snav-search { display: none; }
  .snav-brand { justify-content: center; padding: 0; }
}

/* ========================================================================
   Cockpit v4 — operator-grade shell and Dashboard skeleton.
   Research pass: TradingView Strategy Report, QuantConnect live algorithms,
   TT Algo Dashboard, IBKR Risk Navigator, Bloomberg PORT/Launchpad,
   OpenBB, 3Commas, Coinigy. Keep every absent engine feature honest.
   ======================================================================== */

.snav {
  width: 194px;
  padding: 0 8px 10px;
}
.snav-brand {
  height: 58px;
  gap: 9px;
  padding: 0 3px;
}
.brand-mark {
  width: 42px;
  height: 42px;
  filter: drop-shadow(0 10px 20px color-mix(in srgb, var(--accent) 28%, transparent));
}
.brand-name {
  font-size: 15.5px;
  line-height: 1.05;
  letter-spacing: 0;
}
.snav .snav-search { display: block; } /* owner wants search under the brand */
.snav-item {
  height: 29px;
  padding: 0 7px;
  gap: 7px;
  border-radius: 7px;
  font-size: 12.25px;
}
.snav-group-title {
  padding: 6px 8px 2px;
}
.snav-utils {
  gap: 5px;
  margin-top: 6px;
  padding-top: 6px;
}
.snav-util {
  width: calc(100% - 8px);
  height: 32px;
  margin: 0 auto;
  padding: 0 7px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--tile) 76%, transparent);
}
.snav-util .snav-ic {
  width: 23px;
  height: 23px;
  box-shadow: none;
}
.snav-util .snav-ic svg {
  width: 16px;
  height: 16px;
}
.topbar-search {
  width: clamp(190px, 22vw, 300px);
  padding: 0;
  margin-right: 4px;
}
.topbar-search .snav-search-box {
  height: 34px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--tile) 88%, transparent);
}
.topbar-search .snav-search-pop {
  top: calc(100% + 8px);
  left: auto;
  right: 0;
  width: min(360px, calc(100vw - 32px));
}

.acct-wrap.top {
  position: relative;
  flex: none;
  padding: 0;
}
.acct-wrap.top .acct-card {
  width: 38px;
  height: 34px;
  justify-content: center;
  padding: 0;
  border-radius: 999px;
  background: color-mix(in srgb, var(--tile) 72%, transparent);
}
.acct-wrap.top .acct-avatar {
  width: 28px;
  height: 28px;
}
.acct-wrap.top .acct-meta { display: none; }
.acct-wrap.top .acct-name {
  font-size: 12.5px;
}
.acct-wrap.top .acct-sub {
  font-size: 10px;
}
.acct-wrap.top .acct-pop {
  left: auto;
  right: 0;
  top: calc(100% + 8px);
  width: 304px;
}
.acct-session-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 8px 2px;
}
.acct-session-row svg {
  color: var(--accent);
}
.acct-session-row span {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.acct-session-row b {
  color: var(--text);
  font-size: 12.5px;
  font-weight: 620;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.acct-session-row em {
  color: var(--muted);
  font-size: 10.5px;
  font-style: normal;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.acct-session-row strong {
  color: var(--up);
  font-size: 11px;
  font-weight: 620;
  white-space: nowrap;
}

.pulse-orbit {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 20px;
  height: 20px;
}
.pulse-orbit::before {
  content: "";
  position: absolute;
  inset: 3px;
  border: 1px solid color-mix(in srgb, var(--up) 46%, transparent);
  border-left-color: transparent;
  border-radius: 50%;
  animation: orbitSpin 2.8s linear infinite;
}
.net-btn.ok svg,
.net-btn.warn svg {
  animation: signalBreath 1.7s ease-in-out infinite;
}
@keyframes orbitSpin {
  to { transform: rotate(360deg); }
}
@keyframes signalBreath {
  0%, 100% { opacity: .62; transform: translateY(0); }
  45% { opacity: 1; transform: translateY(-1px); }
}

.dashboard-page {
  max-width: min(1560px, 100%);
}
.dashboard-head .page-title {
  font-size: 30px;
}
.dashboard-head .page-sub {
  max-width: 680px;
}

.control-room-stack {
  display: grid;
  gap: 14px;
  margin: 16px 0;
}
.cr-band {
  position: relative;
  padding: 16px 18px;
  border: 1px solid var(--line-2);
  border-radius: 14px;
  background: color-mix(in srgb, var(--panel) 90%, transparent);
  overflow: hidden;
}
.cr-band::before {
  content: "";
  position: absolute;
  left: 0;
  top: 14px;
  bottom: 14px;
  width: 3px;
  border-radius: 999px;
  background: var(--accent);
  opacity: .72;
}
.cr-band-top::before { background: var(--up); }
.cr-band-brain::before { background: var(--accent); }
.cr-band-guard::before { background: var(--down); opacity: .55; }
.cr-band-head {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: start;
  margin-bottom: 13px;
}
.cr-overline {
  color: var(--faint);
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 0;
  text-transform: uppercase;
  padding-top: 3px;
}
.cr-band-head h2 {
  margin: 0;
  color: var(--text);
  font-size: 17px;
  font-weight: 600;
  line-height: 1.15;
}
.cr-band-head p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.45;
  max-width: 780px;
}
.cr-band-action {
  display: inline-flex;
  align-items: center;
  justify-self: end;
}
.cr-line-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 16px;
}
.cr-line-grid.brain,
.cr-line-grid.guard {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.cr-line {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 11px;
  align-items: center;
  min-height: 82px;
  padding: 10px 0;
  border: 0;
  border-top: 1px solid var(--line);
  background: none;
  text-align: left;
  cursor: pointer;
}
.cr-line:hover .cr-line-copy b {
  color: var(--accent);
}
.cr-line-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  color: var(--muted);
  background: var(--tile);
}
.cr-line-icon.live {
  color: var(--up);
  animation: crHeartbeat 1.9s ease-in-out infinite;
}
.cr-line.ok .cr-line-icon { color: var(--up); background: var(--up-soft); }
.cr-line.warn .cr-line-icon { color: var(--accent-ink); background: var(--accent-soft); }
.cr-line.bad .cr-line-icon { color: var(--down); background: var(--down-soft); }
[data-theme="dark"] .cr-line.warn .cr-line-icon { color: var(--accent); }
.cr-line-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.cr-line-copy span {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: uppercase;
}
.cr-line-copy b {
  color: var(--text);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cr-line-copy em {
  color: var(--muted);
  font-size: 11.5px;
  font-style: normal;
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.cr-line-state {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--faint);
}
.cr-line-state.ok { background: var(--up); box-shadow: 0 0 0 4px var(--up-soft); }
.cr-line-state.warn { background: var(--accent); box-shadow: 0 0 0 4px var(--accent-soft); }
.cr-line-state.bad { background: var(--down); box-shadow: 0 0 0 4px var(--down-soft); }
@keyframes crHeartbeat {
  0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 color-mix(in srgb, var(--up) 28%, transparent); }
  45% { transform: scale(1.04); box-shadow: 0 0 0 7px transparent; }
}
.cr-matrix-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 12px;
}
.cr-matrix-grid-top {
  grid-template-columns: minmax(0, 1fr);
}
.cr-mini-panel {
  min-width: 0;
  padding: 11px 12px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--tile) 70%, transparent);
}
.cr-mini-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 5px;
}
.cr-mini-head span {
  color: var(--text);
  font-size: 11.5px;
  font-weight: 650;
  letter-spacing: 0;
  text-transform: uppercase;
}
.cr-mini-rows {
  display: grid;
  gap: 2px;
}
.cr-mini-row {
  width: 100%;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 9px;
  align-items: center;
  min-height: 54px;
  padding: 6px 0;
  border: 0;
  background: none;
  color: inherit;
  text-align: left;
}
button.cr-mini-row {
  cursor: pointer;
}
button.cr-mini-row:hover .cr-mini-copy b {
  color: var(--accent);
}
.cr-mini-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 9px;
  color: var(--muted);
  background: color-mix(in srgb, var(--panel) 76%, transparent);
}
.cr-mini-icon.ok { color: var(--up); background: var(--up-soft); }
.cr-mini-icon.warn { color: var(--accent-ink); background: var(--accent-soft); }
.cr-mini-icon.bad { color: var(--down); background: var(--down-soft); }
[data-theme="dark"] .cr-mini-icon.warn { color: var(--accent); }
.cr-mini-icon.live {
  animation: crHeartbeat 2.1s ease-in-out infinite;
}
.cr-mini-copy {
  min-width: 0;
  display: grid;
  gap: 1px;
}
.cr-mini-copy span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
}
.cr-mini-copy b {
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
  line-height: 1.18;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cr-mini-copy em {
  color: var(--muted);
  font-size: 11px;
  font-style: normal;
  line-height: 1.32;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.runtime-console {
  margin-top: 12px;
  padding: 11px 12px 12px;
  border-radius: 13px;
  background: color-mix(in srgb, var(--tile) 72%, transparent);
}
.runtime-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}
.runtime-head span {
  color: var(--text);
  font-size: 11.5px;
  font-weight: 650;
  text-transform: uppercase;
}
.runtime-head b {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  text-transform: uppercase;
}
.runtime-lanes {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 8px;
}
.runtime-lane {
  min-width: 0;
  min-height: 58px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  padding: 8px;
  border: 0;
  border-radius: 10px;
  background: color-mix(in srgb, var(--panel) 78%, transparent);
  color: inherit;
  text-align: left;
}
button.runtime-lane {
  cursor: pointer;
}
button.runtime-lane:hover b {
  color: var(--accent);
}
.runtime-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--faint);
}
.runtime-dot.ok { background: var(--up); }
.runtime-dot.warn { background: var(--accent); }
.runtime-dot.bad { background: var(--down); }
.runtime-dot.live {
  animation: runtimeBeat 1.8s ease-in-out infinite;
}
.runtime-lane span:not(.runtime-dot) {
  min-width: 0;
  display: grid;
  gap: 1px;
}
.runtime-lane b {
  color: var(--text);
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.1;
}
.runtime-lane em {
  color: var(--muted);
  font-size: 10.5px;
  font-style: normal;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.runtime-lane strong {
  color: var(--text);
  font-size: 14px;
  font-weight: 650;
}
@keyframes runtimeBeat {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--up) 22%, transparent); opacity: .65; }
  50% { box-shadow: 0 0 0 5px transparent; opacity: 1; }
}

@media (max-width: 980px) {
  .cr-line-grid,
  .cr-line-grid.brain,
  .cr-line-grid.guard {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .cr-matrix-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .cr-matrix-grid-top {
    grid-template-columns: minmax(0, 1fr);
  }
  .runtime-lanes {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 1060px) {
  .snav {
    width: 74px;
  }
  .brand-mark {
    width: 38px;
    height: 38px;
  }
  .acct-wrap.top .acct-card {
    justify-content: center;
    padding: 0;
    border: 1px solid var(--line-2);
    background: color-mix(in srgb, var(--tile) 72%, transparent);
  }
  .acct-wrap.top .acct-meta {
    display: none;
  }
  .acct-wrap.top .acct-pop {
    left: auto;
    right: 0;
  }
}
@media (max-width: 760px) {
  .hdr-right {
    gap: 8px;
    overflow: visible;
  }
  .hdr-right > * {
    display: none !important;
  }
  .hdr-right > .smenu-bar.topbar-suite-v4 {
    display: inline-flex !important;
  }
  .hdr-right > .smenu-bar.topbar-suite-v4 > :not(button[data-topbar-key="power"]) {
    display: none !important;
  }
  .hdr-right > .smenu-bar.topbar-suite-v4 > button[data-topbar-key="power"] {
    display: inline-flex !important;
  }
  .hdr-right > .clock-menu,
  .hdr-right > .pulse-orbit,
  .hdr-right > .acct-wrap.top {
    display: inline-flex !important;
  }
  .hdr-right > .acct-wrap.top {
    display: block !important;
  }
  .dashboard-head .page-title {
    font-size: 24px;
  }
  .cr-band {
    padding: 14px;
  }
  .cr-band-head {
    grid-template-columns: 1fr;
    gap: 5px;
  }
  .cr-band-action {
    justify-self: start;
  }
  .cr-line-grid,
  .cr-line-grid.brain,
  .cr-line-grid.guard {
    grid-template-columns: 1fr;
  }
  .cr-matrix-grid,
  .cr-matrix-grid-top {
    grid-template-columns: 1fr;
  }
  .runtime-lanes {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .cr-line {
    min-height: 74px;
  }
}

/* ========================================================================
   Cockpit v4 — live motion (signal wave, radar logo, HALTED pulse), bigger
   brand, news-tile spacing fix, top-bar icon tints, compact sidebar search.
   Appended last so it wins the cascade. Global [data-motion="reduced"] * stops
   all of the animations below.
   ======================================================================== */

/* animated signal-strength bars (top-bar "is it alive") */
.net-btn.sig { color: var(--muted); }
.sig-bars { display: inline-flex; align-items: flex-end; gap: 2px; height: 15px; }
.sig-bars i {
  width: 3px; border-radius: 1.5px; background: currentColor; flex: none;
  height: calc(4px + var(--b) * 2.4px); transform-origin: bottom; opacity: .55;
}
.sig-bars.ok { color: var(--up); }
.sig-bars.warn { color: var(--accent); }
.sig-bars.bad { color: var(--down); }
.sig-bars.ok i, .sig-bars.warn i { animation: sigWave 1.6s ease-in-out infinite; animation-delay: calc(var(--b) * -0.16s); }
@keyframes sigWave { 0%, 100% { transform: scaleY(.4); opacity: .4; } 50% { transform: scaleY(1); opacity: 1; } }
.sig-bars.bad i { opacity: .35; }
.sig-bars.bad i:first-child { opacity: 1; }

/* radar logo: quietly alive — sweep rotates, blip pings */
.brand-mark { overflow: visible; }
.brand-sweep { transform-origin: 22px 22px; animation: radarSweep 4.5s linear infinite; }
@keyframes radarSweep { to { transform: rotate(360deg); } }
.brand-blip { animation: radarBlip 4.5s ease-in-out infinite; }
@keyframes radarBlip { 0%, 62% { opacity: 0; transform: scale(.6); } 70% { opacity: 1; transform: scale(1); } 100% { opacity: 0; transform: scale(1.4); } }

/* bigger, cleaner brand lockup */
.brand-name { font-size: 20px !important; font-weight: 650 !important; letter-spacing: -0.4px !important; line-height: 1 !important; color: var(--text) !important; }
.brand-sub { font-size: 10.5px; font-weight: 640; letter-spacing: .3px; color: var(--muted); margin-top: 3px; text-transform: none; }

/* HALTED pill — a slow breathing ring so the halt state isn't dead-still */
.mode-pill.m-halted .dot { animation: haltBreathe 2.4s ease-in-out infinite; }
@keyframes haltBreathe {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--down) 55%, transparent); opacity: 1; }
  50% { box-shadow: 0 0 0 5px transparent; opacity: .55; }
}

/* news / calendar tile — kill the "long bullet": dot sits by the label, not the far edge */
.snav-util .live-dot { margin-left: 6px !important; }
.snav-util .snav-label { flex: 0 1 auto; }

/* distinguish look-alike top-bar icons with a subtle resting tint */
.hdr-ic.tint-news { color: color-mix(in srgb, #f5a623 42%, var(--muted)); }
.hdr-ic.tint-cal  { color: color-mix(in srgb, #4f8cff 44%, var(--muted)); }
.hdr-ic.tint-shell{ color: color-mix(in srgb, #21c07a 44%, var(--muted)); }
.hdr-ic.tint-news:hover, .hdr-ic.tint-cal:hover, .hdr-ic.tint-shell:hover { color: var(--accent); }

/* keep the sidebar search compact (small, right under the brand) */
.snav-search { padding: 2px 0 8px; }
.snav-search-box { height: 30px; }
.snav-search-box input { font-size: 12px; }

/* ---- account: security & sessions ---- */
.sec-rows { display: flex; flex-direction: column; }
.sec-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 12px 2px; border-bottom: 1px solid var(--line); }
.sec-row:last-child { border-bottom: 0; }
.sec-meta { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.sec-meta b { font-size: 13.5px; font-weight: 680; color: var(--text); }
.sec-meta small { font-size: 11.5px; color: var(--muted); line-height: 1.45; max-width: 62ch; }
.sec-val { font-size: 13px; font-weight: 620; color: var(--text-2); white-space: nowrap; flex: none; }
.sec-toggle-row { border-bottom: 1px solid var(--line); }
.sec-session {
  display: flex; align-items: center; gap: 14px; padding: 14px 14px; margin-top: 12px;
  border: 1px solid var(--line-2); border-radius: 13px; background: var(--tile);
}
.sec-session-ic {
  flex: none; width: 42px; height: 42px; border-radius: 11px; display: grid; place-items: center;
  background: var(--panel); box-shadow: var(--shadow-sm); color: var(--accent-ink);
}
[data-theme="dark"] .sec-session-ic { color: var(--accent); background: var(--tile-hover); box-shadow: none; }
.sec-session-ic svg { width: 20px; height: 20px; }
.sec-session-meta { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.sec-session-meta b { font-size: 13.5px; font-weight: 620; color: var(--text); }
.sec-session-meta small { font-size: 11.5px; color: var(--muted); }
.sec-session-now { flex: none; display: inline-flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 620; color: var(--up); }
.sec-session-now i { width: 8px; height: 8px; border-radius: 50%; background: var(--up); animation: hbPulse 2.2s ease-out infinite; }
.sec-foot { margin-top: 12px; font-size: 11.5px; color: var(--faint); line-height: 1.5; }

/* ========================================================================
   Cockpit v5 — owner feedback: new logo, comfortable nav, global search in
   the top bar, real wifi signal, currency symbol, distinct icon colors.
   Appended last. Motion respects [data-motion="reduced"] *.
   ======================================================================== */

/* new 3-bar logo — static, sized to sit in line with the 52px brand band */
.brand-mark { width: 34px !important; height: 34px !important; filter: drop-shadow(0 4px 10px rgba(47,82,207,.26)) !important; animation: none !important; }
.snav-brand:hover .brand-mark { transform: translateY(-1px) !important; }

/* nav rows wear the Account-v3 word treatment (Earn/Spot/Cross Margin):
   550 weight, -0.006em, one ink step softer than pure text (owner calibration) */
.snav-item { height: 36px !important; padding: 0 10px !important; gap: 10px !important; font-size: 13.5px !important; font-weight: 460 !important; letter-spacing: -0.004em !important; border-radius: 9px !important; color: color-mix(in srgb, var(--text-2) 62%, var(--muted)) !important; }
.snav-item .snav-ic { width: 20px !important; height: 20px !important; }
.snav-item .snav-ic svg { width: 18px !important; height: 18px !important; }
.snav-group-title { padding: 10px 10px 3px !important; font-size: 10px !important; }
.snav-nav { padding-top: 4px; }

/* ---- global search bar in the top bar (beside the brand) ---- */
.tb-left { flex: 0 1 auto; display: flex; align-items: center; min-width: 0; padding-left: 2px; }
.topbar-search { position: relative; width: min(440px, 32vw); }
.topbar-search .snav-search-box {
  display: flex; align-items: center; gap: 9px; height: 36px; padding: 0 12px;
  border-radius: 11px; background: var(--tile); border: 1px solid var(--line-2); color: var(--muted);
  transition: border-color .12s, box-shadow .12s, background .12s;
}
.topbar-search .snav-search-box.on { border-color: var(--accent-line); box-shadow: 0 0 0 3px var(--accent-soft); background: var(--bg); }
.topbar-search .snav-search-box input { flex: 1; min-width: 0; border: 0; background: none; outline: none; color: var(--text); font-size: 13px; font-family: inherit; }
.topbar-search .snav-search-box input::placeholder { color: var(--faint); }
.topbar-search .snav-search-k { flex: none; border: 1px solid var(--line-2); border-bottom-width: 2px; background: var(--bg); border-radius: 5px; padding: 1px 6px; font-size: 10px; font-weight: 620; color: var(--muted); font-family: var(--mono); cursor: pointer; }
.topbar-search .snav-search-k:hover { color: var(--accent); border-color: var(--accent-line); }
.topbar-search .snav-search-pop { position: absolute; top: calc(100% + 7px); left: 0; right: 0; z-index: 90; background: color-mix(in srgb, var(--panel) 96%, transparent); backdrop-filter: saturate(180%) blur(22px); -webkit-backdrop-filter: saturate(180%) blur(22px); border: 1px solid var(--line-2); border-radius: 12px; box-shadow: var(--shadow-pop); padding: 5px; }

/* ---- currency: show the symbol so it's obviously a currency switch ---- */
.cur-pill { display: inline-flex; align-items: center; gap: 3px; height: 28px; padding: 0 9px; border: 1px solid transparent; border-radius: 9px; background: transparent; cursor: pointer; transition: background .12s, border-color .12s; }
.cur-pill:hover, .cur-pill.on { background: var(--tile); border-color: color-mix(in srgb, var(--glass-border) 58%, transparent); }
.cur-glyph { font-size: 15px; font-weight: 650; color: var(--text-2); line-height: 1; }
.cur-pill svg { opacity: .6; }
.cur-pill:hover .cur-glyph { color: var(--accent); }

/* ---- real wifi signal: arcs fill inner(low)→outer(top), repeating ---- */
.net-btn.wifi { color: var(--muted); }
.wifi-sig { display: inline-flex; align-items: center; justify-content: center; color: inherit; }
.net-btn.wifi.ok { color: var(--up); } .net-btn.wifi.warn { color: var(--accent); } .net-btn.wifi.bad { color: var(--down); }
.wifi-sig .wa { opacity: .32; }
.net-btn.wifi.bad .wifi-sig .wa.a1, .net-btn.wifi.bad .wifi-sig .wa.a2, .net-btn.wifi.bad .wifi-sig .wa.a3 { opacity: .18; }
.net-btn.wifi.bad .wifi-sig .wa.a0 { opacity: 1; }
.net-btn.wifi.ok .wifi-sig .wa, .net-btn.wifi.warn .wifi-sig .wa { animation: wifiWave 2.1s ease-in-out infinite; }
.wifi-sig .wa.a0 { animation-delay: 0s; } .wifi-sig .wa.a1 { animation-delay: .2s; } .wifi-sig .wa.a2 { animation-delay: .4s; } .wifi-sig .wa.a3 { animation-delay: .6s; }
@keyframes wifiWave { 0%, 68%, 100% { opacity: .28; } 22% { opacity: 1; } }

/* ---- distinct top-bar icon colors (variety, not a grey wall) ---- */
.hdr-ic.tint-news  { color: color-mix(in srgb, #f59e0b 58%, var(--muted)); }
.hdr-ic.tint-cal   { color: color-mix(in srgb, #8b5cf6 58%, var(--muted)); }
.hdr-ic.tint-shell { color: color-mix(in srgb, #10b981 60%, var(--muted)); }
.hdr-ic.tint-data  { color: color-mix(in srgb, #ef4444 50%, var(--muted)); }
.hdr-ic.tint-news:hover, .hdr-ic.tint-cal:hover, .hdr-ic.tint-shell:hover, .hdr-ic.tint-data:hover { color: var(--accent); }

/* ---- account popover: clean linked-exchanges list ---- */
.acct-pop { min-width: 268px; }
.acct-ex-list { display: flex; flex-direction: column; gap: 2px; padding: 2px 0 6px; }
.acct-ex { display: flex; align-items: center; gap: 10px; padding: 8px 8px; border-radius: 10px; }
.acct-ex:hover { background: var(--tile); }
.acct-ex.soon { opacity: .62; }
.acct-ex-badge { flex: none; width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; font-size: 13px; font-weight: 650; color: #fff; }
.acct-ex-badge.bn { background: linear-gradient(135deg,#f0b90b,#c99400); color: #1a1400; }
.acct-ex-badge.by { background: #17181c; }
.acct-ex-badge.cb { background: #1f5cff; }
.acct-ex-badge.ok { background: #0e1013; }
.acct-ex-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.acct-ex-info b { font-size: 13px; font-weight: 620; color: var(--text); }
.acct-ex-info small { font-size: 10.5px; color: var(--muted); }
.acct-ex-pill { flex: none; font-size: 10px; font-weight: 650; letter-spacing: .3px; text-transform: uppercase; padding: 3px 8px; border-radius: 999px; }
.acct-ex-pill.ok { background: var(--up-soft); color: var(--up); }
.acct-ex-pill.bad { background: var(--down-soft); color: var(--down); }
.acct-ex-pill.idle { background: var(--accent-soft); color: var(--accent-ink); }
[data-theme="dark"] .acct-ex-pill.idle { color: var(--accent); }
.acct-ex-pill.soon { background: var(--tile); color: var(--faint); }
.acct-ex-manage { width: 100%; margin-top: 4px; height: 34px; border-radius: 9px; border: 1px solid var(--line-2); background: var(--tile); color: var(--text-2); font-size: 12.5px; font-weight: 620; cursor: pointer; }
.acct-ex-manage:hover { color: var(--accent); border-color: var(--accent-line); }

/* ========================================================================
   Cockpit v6 — owner feedback: brand alignment, square nav bullets, smaller
   news/calendar, translucent (not transparent) popovers. Appended last.
   ======================================================================== */

/* brand text sits in line with the logo (was riding too high) */
.snav-brand { align-items: center !important; }
.brand-lockup { justify-content: center !important; margin-top: 1px !important; }

/* nav "bullet" = a small rounded SQUARE chip, not a stretched blob */
.snav-item .snav-ic {
  width: 25px !important; height: 25px !important; border-radius: 7px !important;
  background: var(--tile); box-shadow: var(--shadow-sm); flex: none;
}
[data-theme="dark"] .snav-item .snav-ic { background: var(--tile-hover); box-shadow: none; }
.snav-item .snav-ic svg { width: 15px !important; height: 15px !important; }
.snav-item:hover .snav-ic { color: var(--accent); }
.snav-item.active .snav-ic { background: var(--accent) !important; color: #fff !important; box-shadow: none; }
.snav-item.active .snav-ic svg { color: #fff; }
.snav-item.active { background: transparent !important; }
.snav-item.active .snav-label { color: var(--text); font-weight: 640; }

/* News / Calendar: shrink to compact rows (no big empty box stretching right) */
.snav-utils { gap: 2px !important; margin-top: 6px !important; padding-top: 6px !important; }
.snav-util {
  height: 32px !important; background: transparent !important; padding: 0 8px !important;
  font-size: 12.5px !important; font-weight: 620 !important; color: var(--muted) !important;
}
.snav-util:hover { background: var(--tile) !important; transform: none !important; }
.snav-util.active { background: color-mix(in srgb, var(--accent-soft) 55%, transparent) !important; color: var(--accent-ink) !important; }
[data-theme="dark"] .snav-util.active { color: var(--accent) !important; }
.snav-util .snav-ic {
  width: 25px !important; height: 25px !important; border-radius: 7px !important;
  background: var(--tile); box-shadow: var(--shadow-sm); color: var(--accent-ink);
}
[data-theme="dark"] .snav-util .snav-ic { background: var(--tile-hover); box-shadow: none; color: var(--accent); }
.snav-util .snav-ic svg { width: 15px !important; height: 15px !important; }
.snav-util .live-dot { margin-left: 6px !important; }

/* popovers: OPAQUE. backdrop-filter samples a misaligned region under :root
   zoom (Chrome), so page text ghosts through the panel — never frost these. */
.menu-pop, .acct-pop, .snav-search-pop, .topbar-search .snav-search-pop {
  background: var(--panel) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border-color: var(--line-2) !important;
}

/* token result badge in search */
.ssr-hint { text-transform: none; }

/* ========================================================================
   Cockpit v7 — owner feedback: clean clock (no lone UTC box), sequential wifi,
   database icon, small notif badge, nicer avatar, and nav "bullets" that hug
   their content instead of stretching to the right. Appended last.
   ======================================================================== */

/* clock: flat "09:08:37 UTC" — no separate tinted box on just the zone */
.hcb-zone { background: transparent !important; color: var(--muted) !important; padding: 0 0 0 2px !important; font-weight: 620 !important; }
.hdr-clock-btn .num { color: var(--text-2) !important; }

/* currency pill: symbol only (arrow removed in JS) */
.cur-pill .cur-glyph { font-size: 15px; }

/* Wi-Fi: each arc lights in sequence (inner→top), one at a time, others stay dim */
.net-btn.wifi.ok .wifi-sig .wa, .net-btn.wifi.warn .wifi-sig .wa { animation: wifiSeq 1.7s linear infinite !important; }
.wifi-sig .wa.a0 { animation-delay: 0s !important; }
.wifi-sig .wa.a1 { animation-delay: .42s !important; }
.wifi-sig .wa.a2 { animation-delay: .84s !important; }
.wifi-sig .wa.a3 { animation-delay: 1.26s !important; }
@keyframes wifiSeq { 0% { opacity: 1; } 20%, 100% { opacity: .26; } }

/* notification badge: small corner dot so the bell stays visible */
.ic-badge {
  min-width: 14px !important; height: 14px !important; padding: 0 2px !important;
  font-size: 8px !important; top: -3px !important; right: -3px !important;
  border-width: 1.5px !important; line-height: 1 !important;
}

/* nicer default profile avatar (accent gradient + white glyph) */
.acct-avatar { background: linear-gradient(135deg, var(--accent), var(--accent-ink)) !important; color: #fff !important; }
.acct-avatar svg { color: #fff; }
.acct-avatar.lg { background: linear-gradient(135deg, var(--accent), var(--accent-ink)) !important; }

/* nav + news/calendar "bullet": hug the content, do NOT stretch to the right */
.snav-item, .snav-util { width: fit-content !important; max-width: 100% !important; }
.snav-item .snav-label, .snav-util .snav-label { flex: 0 1 auto; }
.snav-item .nav-badge { margin-left: 8px !important; }

/* ========================================================================
   Cockpit v8 — precise owner fixes: permanent clock box, one common bullet
   size (= widest item) in a tighter bar, cumulative wifi fill (one curve at a
   time, building outward), clean bigger database icon (no dot). Appended last.
   ======================================================================== */

/* clock: keep the hover box PERMANENTLY */
.hdr-clock-btn { background: var(--tile) !important; border-color: var(--line-2) !important; }

/* data-health database: distinct blue, no status dot, a touch bigger */
.hdr-ic.tint-data { color: color-mix(in srgb, #0ea5e9 52%, var(--muted)) !important; }
.hdr-ic.tint-data:hover { color: var(--accent) !important; }

/* ALL left-bar bullets the same width (= the widest, "Cloud Shell"), in a
   tighter sidebar so there is no dead space to the right of them */
.snav { width: 176px !important; } /* fits 'Opportunities' + symmetric air (owner 2026-07-09) */
.snav-item.active { color: var(--text) !important; font-weight: 550 !important; }
.snav-group-title { margin: 18px 8px 6px !important; }
.snav-item, .snav-util { width: 100% !important; max-width: 100% !important; }
.snav-nav { padding-right: 0; }

/* Wi-Fi: cumulative FILL — dot greens first, then each curve outward, hold,
   then reset and repeat. One curve changes at a time; a clear flowing wave. */
.net-btn.wifi .wifi-sig .wa { opacity: 1 !important; color: var(--muted); }
.net-btn.wifi.ok .wifi-sig .wa.a0 { animation: wfa0 2.2s ease-in-out infinite !important; }
.net-btn.wifi.ok .wifi-sig .wa.a1 { animation: wfa1 2.2s ease-in-out infinite !important; }
.net-btn.wifi.ok .wifi-sig .wa.a2 { animation: wfa2 2.2s ease-in-out infinite !important; }
.net-btn.wifi.ok .wifi-sig .wa.a3 { animation: wfa3 2.2s ease-in-out infinite !important; }
@keyframes wfa0 { 0%, 6% { color: var(--muted); } 14%, 90% { color: #3ddc84; } 100% { color: var(--muted); } }
@keyframes wfa1 { 0%, 26% { color: var(--muted); } 34%, 90% { color: #3ddc84; } 100% { color: var(--muted); } }
@keyframes wfa2 { 0%, 46% { color: var(--muted); } 54%, 90% { color: #3ddc84; } 100% { color: var(--muted); } }
@keyframes wfa3 { 0%, 66% { color: var(--muted); } 74%, 90% { color: #3ddc84; } 100% { color: var(--muted); } }
.net-btn.wifi.warn .wifi-sig .wa { color: var(--accent) !important; }
.net-btn.wifi.bad .wifi-sig .wa { color: var(--muted) !important; opacity: .3 !important; }
.net-btn.wifi.bad .wifi-sig .wa.a0 { color: var(--down) !important; opacity: 1 !important; }

/* pin every bullet to one identical width (scrollbar was making utils 11px wider) */
.snav-item, .snav-util { width: 196px !important; max-width: 196px !important; }
.snav-nav { scrollbar-gutter: stable; }

/* Settings entry points: bottom utility stays pinned; top gear reflects the
   active Settings route even when its hover quick-settings panel is closed. */
.snav-utils { margin-top: auto !important; }
.settings-trigger.route-active {
  color: var(--accent-ink);
  background: color-mix(in srgb, var(--accent-soft) 62%, transparent);
  border-color: color-mix(in srgb, var(--accent-line) 70%, transparent);
}
[data-theme="dark"] .settings-trigger.route-active {
  color: var(--accent);
}
.exec-tabs {
