  background: transparent;
  color: var(--muted);
  font: inherit;
  font-size: 12.5px;
  font-weight: 650;
  padding: 6px 14px;
  border-radius: var(--r-pill);
  cursor: pointer;
}
.exec-tab:hover { color: var(--text); }
.exec-tab.on { color: var(--text); background: var(--bg); }

/* ===== AWS CloudShell quick-view overlay (terminal-styled launcher) ===== */
.cs-modal { width: min(840px, 94vw); }
.cs-head .cs-region {
  font: 600 11px var(--mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  color: var(--muted);
