  font-weight: 620;
  letter-spacing: 0.14em;
  color: #ff9900; /* AWS orange */
  margin-bottom: 8px;
}
.cs-line { white-space: pre-wrap; }
.cs-line.muted { color: #7d8a97; }
.cs-line b { color: #eaf1f7; font-weight: 600; }
.cs-k { color: #57b6ff; }
.cs-promptline { display: flex; align-items: center; gap: 8px; margin-top: 8px; }
.cs-prompt { color: #46d67f; white-space: nowrap; }
.cs-input {
