.acct-sess-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--line-strong); }
.acct-sess-dot.on { background: var(--up); box-shadow: 0 0 0 3px var(--up-soft); }
.acct-sess-info { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
