.acct-sess-right { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.acct-sess-time { font-size: 11px; font-weight: 620; color: var(--muted); white-space: nowrap; }
.acct-sess-time.on { color: var(--up); }
.acct-sess-you {
  font-size: 8px; font-weight: 650; letter-spacing: .4px; text-transform: uppercase; white-space: nowrap;
  color: var(--accent-ink); background: var(--accent-soft); padding: 2px 7px; border-radius: 999px;
}
[data-theme="dark"] .acct-sess-you { color: var(--accent); }
.acct-sess-empty { padding: 10px; font-size: 11.5px; color: var(--muted); }

/* ========================================================================
   Cockpit v9 — hover top-bar menus: uniform size + smooth appear so switching
   between icons reads as one box, plus the Trusted Advisor scanner popover.
   ======================================================================== */

/* uniform width + soft fade/slide-in for every top-bar hover popover */
.hdr-right .menu-pop.right {
  width: 284px !important; min-width: 0 !important; max-width: 284px !important;
  transform-origin: top right;
  animation: hoverPopIn .16s cubic-bezier(.3,.7,.2,1) both;
}
@keyframes hoverPopIn { from { opacity: 0; transform: translateY(-5px) scale(.985); } to { opacity: 1; transform: none; } }

/* Trusted Advisor */
.hdr-ic.tint-advisor { color: color-mix(in srgb, #14b8a6 55%, var(--muted)); }
.hdr-ic.tint-advisor:hover { color: var(--accent); }
.adv-pop { padding: 8px 12px 12px; }
.adv-stats { display: flex; flex-direction: column; gap: 9px; padding: 6px 2px 11px; border-bottom: 1px solid var(--line); margin-bottom: 8px; }
.adv-stat { display: grid; grid-template-columns: 22px auto 1fr; align-items: center; gap: 11px; }
.adv-stat .adv-ic { width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; font-weight: 650; color: #fff; }
.adv-stat.action .adv-ic { background: var(--down); }
.adv-stat.invest .adv-ic { background: #f59e0b; }
.adv-stat.pass .adv-ic { background: var(--up); }
.adv-stat b { font-size: 18px; font-weight: 600; color: var(--text); }
.adv-stat em { font-style: normal; font-size: 11.5px; color: var(--muted); }
.adv-list { display: flex; flex-direction: column; gap: 2px; max-height: 172px; overflow-y: auto; }
.adv-row { display: flex; align-items: flex-start; gap: 9px; width: 100%; padding: 7px 6px; border: 0; background: none; border-radius: 9px; cursor: pointer; text-align: left; }
.adv-row:hover { background: var(--tile); }
.adv-row-dot { flex: none; width: 7px; height: 7px; border-radius: 50%; margin-top: 4px; background: var(--muted); }
.adv-row.action .adv-row-dot { background: var(--down); }
.adv-row.invest .adv-row-dot { background: #f59e0b; }
.adv-row-meta { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.adv-row-meta b { font-size: 12.5px; font-weight: 680; color: var(--text); }
.adv-row-meta small { font-size: 10.5px; color: var(--muted); line-height: 1.35; }
.adv-clean { padding: 14px 6px; font-size: 12.5px; color: var(--up); font-weight: 640; }
.adv-actions { display: flex; gap: 8px; margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--line); }
.adv-scan, .adv-fix { flex: 1; height: 32px; border-radius: 9px; font-size: 12px; font-weight: 620; cursor: pointer; }
.adv-scan { border: 1px solid var(--line-2); background: var(--tile); color: var(--text-2); }
.adv-scan:hover { color: var(--accent); border-color: var(--accent-line); }
.adv-scan:disabled { opacity: .5; cursor: default; }
.adv-fix { border: 0; background: var(--accent); color: var(--cta-fg); }
.adv-fix:disabled { opacity: .45; cursor: default; }

/* ===================== Cockpit v10 — shared morphing popover ================
   One box for the whole top bar. It is CENTERED under the hovered trigger with
   a pointer aimed at it. Moving to another trigger does NOT close/reopen — the
   same element slides (left), resizes (width) and re-aims (arrow left) with a
   soft transition, while only the inner content cross-fades. Nothing pops. */
.smenu-bar { position: relative; display: flex; align-items: center; gap: 5px; }
/* tabular figures so ticking seconds keep a constant width and never nudge the
   triggers (which would restart the box's slide transition every second). */
.smenu-bar .hdr-clock-btn .num { font-variant-numeric: tabular-nums; font-feature-settings: "tnum"; }

.smenu {
  position: absolute; top: calc(100% + 11px); z-index: 90; box-sizing: border-box;
  /* OPAQUE — backdrop-filter ghosts page text under :root zoom (Chrome) */
  background: var(--panel);
  border: 1px solid var(--glass-border); border-radius: 16px;
  box-shadow: var(--shadow-pop), var(--glass-highlight), 0 0 0 .5px var(--glass-edge);
  padding: 7px; overflow: visible;
  /* left/width are tweened in JS (rAF) — CSS transitions freeze under :root zoom. */
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(-4px) scale(.992);
  transition: opacity .14s ease, transform .18s cubic-bezier(.22, 1, .36, 1), visibility 0s linear .18s;
  will-change: left, width;
}
.smenu.open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0) scale(1);
  transition: opacity .12s ease, transform .22s cubic-bezier(.22, 1, .36, 1), visibility 0s;
}
.smenu::before {
  content: "";
  position: absolute;
  left: -8px;
  right: -8px;
  top: -16px;
  height: 18px;
}
@keyframes smIn { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }

/* the pointer — a rotated square that glides along the box top edge */
.smenu-arrow {
  position: absolute; top: -6px; width: 12px; height: 12px; margin-left: -6px;
  background: var(--panel); border-left: 1px solid var(--glass-border); border-top: 1px solid var(--glass-border);
  border-top-left-radius: 3px; transform: rotate(45deg);
}

.smenu-content {
  position: relative;
  max-height: min(68vh, 500px);
  overflow-y: auto;
  overflow-x: hidden;
  animation: none;
  transform-origin: top center;
  transition: opacity .16s ease, transform .16s ease;
  will-change: opacity, transform;
}
.smenu-content.morphing {
  opacity: .985;
  transform: scale(.998);
  pointer-events: none;
}
@keyframes smFade { from { opacity: 0; transform: translateY(2px); } to { opacity: 1; transform: none; } }
.smenu-content::-webkit-scrollbar { width: 8px; }
.smenu-content::-webkit-scrollbar-thumb { background: color-mix(in srgb, var(--muted) 30%, transparent); border-radius: 8px; }

/* triggers inside the bar reuse .hdr-clock-btn / .hdr-ic / .net-btn / .ic-pill /
   .icon-btn styling already defined above; only the open state needs a nudge. */
.smenu-bar .ic-pill.on,
.smenu-bar .icon-btn.on { color: var(--text); background: var(--tile); }
.smenu-bar .hdr-ic.on { color: var(--text); background: var(--tile); }

/* small badge on advisor / notification triggers */
.smenu-bar .ic-badge {
  position: absolute; top: 2px; right: 2px; min-width: 14px; height: 14px; padding: 0 3px;
  display: grid; place-items: center; border-radius: 7px; font-size: 9px; font-weight: 650;
  background: var(--down); color: #fff; border: 1.5px solid var(--panel);
}
.smenu-bar .ic-dot.accent { position: absolute; top: 4px; right: 5px; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); border: 1.5px solid var(--panel); }

/* generic rows used by the morphing content (np / dh / alert / zoom / theme) */
.np-sub-line { font-size: 11.5px; color: var(--muted); padding: 2px 10px 8px; line-height: 1.4; }
.np-link { margin-left: auto; border: 0; background: none; color: var(--accent-ink); font-size: 11px; font-weight: 650; cursor: pointer; }
[data-theme="dark"] .np-link { color: var(--accent); }
.adv-actions { display: flex; gap: 8px; padding: 8px 4px 2px; }
.adv-actions .adv-scan, .adv-actions .adv-fix { flex: 1; padding: 8px 10px; border-radius: 9px; font-size: 12px; font-weight: 640; cursor: pointer; }

/* ===================== Cockpit v11 — API key tab ============================
   A compact top-bar "tab" that shows which Binance key is live (name, HMAC type,
   first chars only, IP restriction, and the six permissions the owner tracks).
   Hover = full detail inline; Expand = the big ApiKeyModal. Never shows the key
   or secret — only enough prefix to spot a rotation. */
/* icon-only key chips — no text on the bar; identity/permissions live in the
   hover popover. Two distinct kinds: read-only key vs the full AWS-Secrets key. */
.apikey-pill {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  width: 32px; height: 28px; border-radius: 9px; border: 1px solid transparent; background: transparent;
  color: var(--muted); cursor: pointer; transition: background .12s, color .12s, border-color .12s, transform .12s;
}
.apikey-pill svg { width: 15px; height: 15px; }
.apikey-pill:hover { transform: translateY(-1px); }
.apikey-pill.ro { color: var(--accent-ink); }
[data-theme="dark"] .apikey-pill.ro { color: var(--accent); }
.apikey-pill.full { color: #c98a12; }
[data-theme="dark"] .apikey-pill.full { color: #e5b048; }
.apikey-pill.ro:hover, .apikey-pill.ro.on { background: var(--accent-soft); border-color: color-mix(in srgb, var(--accent) 24%, transparent); }
.apikey-pill.full:hover, .apikey-pill.full.on { background: color-mix(in srgb, #e5b048 16%, transparent); border-color: color-mix(in srgb, #e5b048 34%, transparent); }
.apikey-dot { position: absolute; top: 4px; right: 4px; width: 6px; height: 6px; border-radius: 50%; background: var(--muted); border: 1.5px solid var(--panel); }
.apikey-dot.s-live { background: var(--up); animation: hbPulse 2.4s ease-out infinite; }
.apikey-dot.s-declared { background: var(--accent); }
.apikey-dot.s-planned { background: #e5b048; }

/* HMAC-style type tag (mirrors Binance's green tag) */
.ak-type {
  margin-left: auto; font-size: 9.5px; font-weight: 650; letter-spacing: .5px;
  background: color-mix(in srgb, var(--up) 16%, transparent); color: var(--up);
  padding: 2px 6px; border-radius: 5px;
}

.ak-idrow { display: flex; align-items: center; gap: 8px; padding: 8px 10px 6px; }
.ak-prefix { font-size: 13px; font-weight: 620; color: var(--text); letter-spacing: .3px; }
.ak-dots { color: var(--faint); margin-left: 2px; letter-spacing: 1px; }
.ak-live {
  margin-left: auto; font-size: 9.5px; font-weight: 650; letter-spacing: .4px; text-transform: uppercase;
  padding: 2px 7px; border-radius: 999px; background: var(--tile); color: var(--muted);
}
.ak-live.s-live { background: color-mix(in srgb, var(--up) 18%, transparent); color: var(--up); }
.ak-live.s-declared { background: var(--accent-soft); color: var(--accent-ink); }
[data-theme="dark"] .ak-live.s-declared { color: var(--accent); }
.ak-live.s-planned { background: color-mix(in srgb, #e5b048 20%, transparent); color: #b9820f; }
[data-theme="dark"] .ak-live.s-planned { color: #e5b048; }

.ak-ip { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; padding: 2px 10px 8px; font-size: 11.5px; color: var(--text-2); font-weight: 600; }
.ak-ip svg { color: var(--muted); flex: none; }
.ak-ip small { flex-basis: 100%; padding-left: 18px; color: var(--faint); font-size: 10.5px; font-weight: 500; }

.ak-perms { display: grid; grid-template-columns: 1fr; gap: 4px; padding: 2px 6px 4px; }
.ak-perm {
  display: flex; align-items: center; gap: 8px; padding: 6px 9px; border-radius: 8px;
  font-size: 11.5px; font-weight: 600; background: var(--tile); color: var(--muted);
}
.ak-perm-ic { width: 15px; height: 15px; display: grid; place-items: center; border-radius: 5px; font-size: 10px; font-weight: 680; flex: none; background: color-mix(in srgb, var(--muted) 22%, transparent); color: var(--muted); }
.ak-perm.on { color: var(--text); background: color-mix(in srgb, var(--up) 9%, var(--tile)); }
.ak-perm.on .ak-perm-ic { background: color-mix(in srgb, var(--up) 20%, transparent); color: var(--up); }
.ak-perm.off .ak-perm-ic { background: color-mix(in srgb, var(--down) 14%, transparent); color: var(--down); }

.ak-expand {
  width: 100%; margin-top: 8px; padding: 8px 10px; border-radius: 9px; cursor: pointer;
  border: 1px solid var(--line-2); background: var(--tile); color: var(--text-2); font-size: 12px; font-weight: 620;
}
.ak-expand:hover { color: var(--accent); border-color: var(--accent-line); }

/* ---- big expand modal ---- */
.ak-modal { width: min(560px, 92vw); }
.ak-modal-body { padding: 14px 16px 4px; }
.ak-modal-intro { font-size: 12px; color: var(--muted); line-height: 1.5; margin: 0 0 12px; }
.ak-empty { padding: 20px; text-align: center; color: var(--muted); }
.ak-card { border: 1px solid var(--line); border-radius: 12px; padding: 12px 13px; background: color-mix(in srgb, var(--panel) 70%, transparent); }
.ak-card + .ak-card { margin-top: 10px; }
.ak-card-head { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.ak-card-name { display: inline-flex; align-items: center; gap: 7px; font-size: 14px; font-weight: 650; color: var(--text); }
.ak-badges { margin-left: auto; display: inline-flex; align-items: center; gap: 6px; }
.ak-badges .ak-type { margin-left: 0; }
.ak-scope { font-size: 9.5px; font-weight: 650; letter-spacing: .4px; text-transform: uppercase; padding: 2px 7px; border-radius: 5px; background: var(--accent-soft); color: var(--accent-ink); }
[data-theme="dark"] .ak-scope { color: var(--accent); }
.ak-card-rows { display: flex; flex-direction: column; gap: 6px; margin-bottom: 10px; }
.ak-crow { display: flex; align-items: baseline; gap: 10px; font-size: 12px; }
.ak-crow .k { width: 74px; flex: none; color: var(--muted); font-weight: 600; }
.ak-crow .v { color: var(--text); font-weight: 640; }
.ak-crow .v em { color: var(--faint); font-style: normal; font-weight: 500; font-size: 11px; margin-left: 4px; }
.ak-card-perms { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.ak-card-note { margin-top: 10px; font-size: 11px; color: var(--faint); }

/* ===================== Cockpit v12 — top-bar refresh button =================
   Binance-style in-place refresh. Idle = quiet gray. Hover = green. Click =
   green + arrows spin one round, then morph to a green check, then settle back
   to gray. If a Binance/API connection is unhealthy it turns red (and the
   problem is surfaced in the alert feed via the server's error events). */
.refresh-btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  width: 32px; height: 28px; border-radius: 9px; border: 1px solid transparent;
  background: transparent; color: var(--muted); cursor: pointer;
  transition: background .2s ease, color .2s ease, border-color .2s ease, transform .1s ease;
}
.refresh-btn svg { width: 16px; height: 16px; }
.refresh-btn:hover { color: var(--up); background: color-mix(in srgb, var(--up) 12%, transparent); }
.refresh-btn:active { transform: scale(.92); }
.refresh-btn.spin { color: var(--up); background: color-mix(in srgb, var(--up) 12%, transparent); }
.refresh-btn.spin svg { animation: refreshSpin .72s cubic-bezier(.5,.15,.4,.9) infinite; }
@keyframes refreshSpin { to { transform: rotate(360deg); } }
.refresh-btn.ok {
  color: #fff; background: var(--up); border-color: var(--up);
  animation: refreshPop .34s cubic-bezier(.34,1.56,.55,1) both;
}
.refresh-btn.ok svg { animation: refreshCheck .32s ease both; }
@keyframes refreshPop { 0% { transform: scale(.72); } 60% { transform: scale(1.12); } 100% { transform: scale(1); } }
@keyframes refreshCheck { from { opacity: 0; stroke-dashoffset: 24; } to { opacity: 1; stroke-dashoffset: 0; } }
.refresh-btn.ok svg path { stroke-dasharray: 24; }
.refresh-btn.err {
  color: var(--down); background: color-mix(in srgb, var(--down) 15%, transparent);
  border-color: color-mix(in srgb, var(--down) 42%, transparent);
  animation: refreshShake .4s ease;
}
@keyframes refreshShake { 0%,100%{transform:translateX(0);} 20%{transform:translateX(-2px);} 60%{transform:translateX(2px);} 80%{transform:translateX(-1px);} }

/* ===================== Cockpit v13 — floating connection dock ===============
   Always-on bottom-right button. Resting colour tracks overall connection
   health (neutral → green strong, orange slow, red laggy/down). Hover = small
   latency popover. Click = a few slow smooth spins while everything re-pulls &
   reconnects, then a payment-style green tick (or red cross) that settles back
   to the health colour. */
.rdock { position: fixed; right: 22px; bottom: 22px; z-index: 140; }
@media (max-width: 640px) { .rdock { bottom: 76px; right: 16px; } }

.rdock-btn {
  position: relative; width: 46px; height: 46px; border-radius: 50%;
  display: grid; place-items: center; cursor: pointer; padding: 0;
  background: var(--panel); border: 1.5px solid var(--rd-color, var(--muted)); color: var(--rd-color, var(--muted));
  box-shadow: 0 8px 22px -8px rgba(16,20,28,.34), 0 1px 3px rgba(0,0,0,.06);
  /* Colour changes run via keyframes, not transitions: CSS transitions freeze
     under the :root zoom (a Chrome quirk), so a transitioned border/background
     never repaints. Keyframe animations DO run under zoom. */
  transition: box-shadow .2s ease, transform .16s ease;
}
.rdock-btn.t-good { --rd-color: var(--up); }
.rdock-btn.t-avg  { --rd-color: color-mix(in srgb, var(--muted) 82%, var(--text-2)); }
.rdock-btn.t-slow { --rd-color: #e2892a; }
.rdock-btn.t-bad  { --rd-color: var(--down); }
.rdock:hover .rdock-btn { transform: translateY(-2px); box-shadow: 0 12px 28px -8px rgba(16,20,28,.4), 0 2px 4px rgba(0,0,0,.08); }
.rdock-btn:active { transform: translateY(0) scale(.95); }
.rdock-ic { display: grid; place-items: center; transform-origin: 50% 50%; }
.rdock-ic svg { width: 19px; height: 19px; }

/* click → the spin is driven in JS (rAF) for a steady slow turn under :root zoom */
.rdock-btn.spin { --rd-color: var(--accent); }

/* hover latency popover — small, unobtrusive */
.rdock-pop {
  position: absolute; right: 2px; bottom: calc(100% + 12px); width: 272px;
  max-height: min(74vh, 520px); overflow-y: auto;
  background: var(--panel);
  border: 1px solid var(--line-2); border-radius: 12px; padding: 0;
  box-shadow: var(--shadow-md);
  animation: rdockPopIn .16s ease both;
}
[data-theme="dark"] .rdock-pop { box-shadow: none; }
.rdock-pop::-webkit-scrollbar { width: 7px; }
.rdock-pop::-webkit-scrollbar-thumb { background: color-mix(in srgb, var(--muted) 28%, transparent); border-radius: 7px; }
@keyframes rdockPopIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.rdock-pop-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 12px; border-bottom: 1px solid var(--line);
  color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase;
}
.rdock-pop-tag { font-size: 10px; font-weight: 620; padding: 2px 8px; border-radius: 999px; letter-spacing: .04em; }
.rdock-conn { display: flex; align-items: center; gap: 9px; height: 30px; padding: 0 12px; }
.rdock-conn + .rdock-conn { border-top: 1px solid var(--line); }
.rdock-conn-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; }
.rdock-conn-name { font-size: 12px; color: var(--text-2); font-weight: 500; white-space: nowrap; }
.rdock-conn-val { margin-left: auto; font-family: var(--mono); font-size: 11px; font-weight: 500; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rdock-conn-err { height: auto; padding-top: 6px; padding-bottom: 6px; }
.rdock-conn-err .rdock-conn-val { max-width: 140px; overflow: hidden; text-overflow: ellipsis; }
.rdock-pop-foot { padding: 8px 12px 9px; border-top: 1px solid var(--line); color: var(--faint); font-size: 11px; font-weight: 450; text-align: center; }

/* tier colours (dots / values / tag) */
.rdock-conn-dot.t-good, .rdock-pop-tag.t-good { background: var(--up); }
.rdock-conn-dot.t-avg,  .rdock-pop-tag.t-avg  { background: color-mix(in srgb, var(--muted) 82%, var(--text-2)); }
.rdock-conn-dot.t-slow, .rdock-pop-tag.t-slow { background: #e2892a; }
.rdock-conn-dot.t-bad,  .rdock-pop-tag.t-bad  { background: var(--down); }
.rdock-pop-tag { color: #fff; text-transform: uppercase; }
.rdock-conn-val.t-good { color: var(--up); }
.rdock-conn-val.t-avg  { color: var(--text-2); }
.rdock-conn-val.t-slow { color: #d67d1c; }
.rdock-conn-val.t-bad  { color: var(--down); }

/* ===== Control cleanup — Logs audit filters/details ===== */
.ledger-console-stats {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.ledger-query-row {
  grid-template-columns: minmax(120px, 160px) minmax(180px, 1fr) repeat(4, minmax(132px, 170px));
}
.ledger-query-actions .mini-btn.on {
  color: var(--text);
  background: var(--accent-soft);
  border-color: var(--accent-line);
}
.ledger-severity {
  height: 20px;
  display: inline-flex;
  align-items: center;
  padding: 0 7px;
  border-radius: var(--r-pill);
  font-size: 10px;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0;
}
.ledger-severity.critical { color: var(--down); background: var(--down-soft); }
.ledger-severity.warning { color: var(--accent-ink); background: var(--accent-soft); }
.ledger-severity.info { color: var(--accent); background: color-mix(in srgb, var(--accent-soft) 62%, transparent); }
.ledger-severity.debug { color: var(--muted); background: var(--tile); }
.ledger-raw-drawer {
  margin-top: 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--bg) 62%, var(--tile));
  overflow: hidden;
}
.ledger-raw-drawer summary {
  cursor: pointer;
  padding: 9px 12px;
  color: var(--text-2);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0;
}
.ledger-raw.compact {
  max-height: 190px;
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
