}
.ledger-inspector-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 10px;
}
.ledger-inspector-actions .mini-btn {
  flex: 1 1 112px;
}
@media (max-width: 1180px) {
  .ledger-console-body {
    grid-template-columns: 1fr;
  }
  .ledger-query-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 680px) {
  .ledger-console-stats,
  .ledger-query-row {
    grid-template-columns: 1fr;
  }
}

/* ===== Control cleanup — Settings local-only note ===== */
.settings-boundary-note {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 14px;
  padding: 11px 12px;
  border-radius: 12px;
  color: var(--text-2);
  background: var(--tile);
  font-size: 12.5px;
  font-weight: 650;
}
.settings-boundary-note svg {
  flex: none;
  color: var(--accent);
}


/* ===================== Cockpit — render error boundary ======================
   Shown instead of a blank white/black screen when a view throws. Recoverable. */
.crash-screen { display: grid; place-items: center; padding: 48px 20px; min-height: 300px; }
.crash-card {
  max-width: 460px; width: 100%; text-align: center;
  background: color-mix(in srgb, var(--panel) 96%, transparent);
  border: 1px solid var(--line); border-radius: 16px; padding: 26px 24px;
  box-shadow: var(--shadow-pop);
}
.crash-title { font-size: 16px; font-weight: 650; color: var(--text); }
.crash-sub { font-size: 12.5px; color: var(--muted); line-height: 1.55; margin: 8px 0 14px; }
.crash-msg {
  text-align: left; font-size: 11.5px; color: var(--down); background: var(--down-soft, color-mix(in srgb, var(--down) 10%, transparent));
  border: 1px solid color-mix(in srgb, var(--down) 30%, transparent); border-radius: 9px;
  padding: 9px 11px; margin: 0 0 16px; white-space: pre-wrap; word-break: break-word; max-height: 120px; overflow: auto;
}
.crash-actions { display: flex; gap: 10px; justify-content: center; }
.crash-btn { padding: 9px 16px; border-radius: 10px; font-size: 13px; font-weight: 650; cursor: pointer; border: 1px solid var(--line-2, var(--line)); background: var(--tile); color: var(--text-2); }
.crash-btn:hover { color: var(--text); }
.crash-btn.primary { border: 0; background: var(--accent); color: var(--cta-fg, #fff); }

/* ===== SETTINGS PAGE (rebuild) ===== */
.settings-page {
  max-width: min(1420px, 100%);
  padding-bottom: 72px;
}

.settings-page-head {
  width: min(1120px, calc(100% - 76px));
