  font-size: 13.5px;
  line-height: 1.45;
}

.settings-page .settings-section {
  scroll-margin-top: calc(var(--header-h) + 18px);
}

.settings-page .settings-section-head {
  margin: 0 0 12px;
}

.settings-page .settings-section-head h2 {
  margin: 0;
  color: var(--text);
  font-size: 25px;
  line-height: 1.12;
  font-weight: 640;
  letter-spacing: 0;
}

.settings-page .settings-section-head p {
  max-width: 780px;
  margin: 7px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

.settings-page .settings-control-surface,
.settings-page .settings-group {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: color-mix(in srgb, var(--panel) 88%, transparent);
  box-shadow: var(--glass-highlight), 0 12px 28px rgba(15, 23, 42, .06);
}

.settings-page .settings-control-surface {
  padding: 16px;
  margin-bottom: 14px;
}

.settings-page .settings-control-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 13px;
}

.settings-page .settings-control-head > span {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.settings-page .settings-control-head b {
  color: var(--text);
  font-size: 15px;
  line-height: 1.2;
  font-weight: 650;
}

.settings-page .settings-control-head em {
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.35;
  font-style: normal;
}

.settings-page .settings-current-pill,
.settings-static-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 74px;
  height: 34px;
  padding: 0 15px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--tile) 76%, transparent);
  color: var(--text-2);
  font-size: 12px;
  font-weight: 600;
  text-transform: capitalize;
}

.settings-static-pill {
  min-width: 84px;
  color: var(--muted);
}

.settings-page .settings-preview-grid,
.settings-page .settings-density-grid {
  display: grid;
  gap: 12px;
}

.settings-page .settings-preview-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.settings-page .settings-density-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 12px;
}

.settings-page .settings-preview-card,
.settings-page .settings-density-card {
  position: relative;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: color-mix(in srgb, var(--tile) 64%, transparent);
  color: var(--text);
  cursor: pointer;
  text-align: left;
  transition: transform .14s ease, border-color .14s ease, background .14s ease, box-shadow .14s ease;
}

.settings-page .settings-preview-card {
  padding: 10px;
}

.settings-page .settings-density-card {
  display: grid;
  grid-template-columns: 116px minmax(0, 1fr);
  align-items: center;
  padding: 12px;
}

.settings-page .settings-preview-card:hover,
.settings-page .settings-density-card:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--text) 18%, var(--line));
  background: color-mix(in srgb, var(--tile) 86%, var(--panel));
}

.settings-page .settings-preview-card.active,
.settings-page .settings-density-card.active {
  border-color: color-mix(in srgb, var(--accent) 70%, var(--line));
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.settings-page .settings-preview-frame {
  position: relative;
  width: 126px;
  min-height: 82px;
  display: grid;
  grid-template-columns: 26px 1fr;
  gap: 8px;
  padding: 10px;
  border-radius: 13px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--line) 80%, transparent);
  background:
    linear-gradient(135deg, rgba(255,255,255,.86), rgba(245,247,251,.74)),
    radial-gradient(circle at 90% 8%, rgba(42,125,224,.22), transparent 34%);
}

.settings-page .settings-preview-card.theme-dark .settings-preview-frame {
  background:
    linear-gradient(135deg, rgba(22,25,32,.95), rgba(11,12,15,.72)),
    radial-gradient(circle at 88% 12%, rgba(247,208,70,.22), transparent 36%);
}

.settings-page .settings-preview-card.theme-system .settings-preview-frame {
  background:
    linear-gradient(135deg, rgba(255,255,255,.74) 0 48%, rgba(22,25,32,.92) 50% 100%),
    radial-gradient(circle at 80% 10%, rgba(91,91,239,.22), transparent 34%);
}

.settings-page .preview-sidebar,
.settings-page .preview-window {
  border-radius: 8px;
  background: rgba(255,255,255,.58);
  border: 1px solid rgba(255,255,255,.48);
}

.settings-page .settings-preview-card.theme-dark .preview-sidebar,
.settings-page .settings-preview-card.theme-dark .preview-window {
  background: rgba(255,255,255,.08);
  border-color: rgba(255,255,255,.12);
}

.settings-page .preview-window {
  display: grid;
  gap: 7px;
  padding: 8px;
}

.settings-page .preview-dot-row {
  display: flex;
  gap: 4px;
}

.settings-page .preview-dot-row i,
.settings-page .preview-line,
.settings-page .preview-chart {
  display: block;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 72%, #fff);
}

.settings-page .preview-dot-row i {
  width: 6px;
  height: 6px;
}

.settings-page .preview-line {
  height: 7px;
  width: 54%;
  opacity: .72;
}

.settings-page .preview-line.wide {
  width: 86%;
}

.settings-page .preview-chart {
  height: 18px;
  border-radius: 6px;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--accent) 68%, #fff) 16%, transparent 16% 23%, color-mix(in srgb, var(--accent) 42%, #fff) 23% 48%, transparent 48% 56%, color-mix(in srgb, var(--up) 56%, #fff) 56% 100%),
    linear-gradient(180deg, color-mix(in srgb, var(--up-soft) 70%, transparent), transparent);
}

.settings-page .settings-preview-copy,
.settings-page .settings-density-card > span:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.settings-page .settings-preview-copy b,
.settings-page .settings-density-card b {
  color: var(--text);
  font-size: 13px;
  line-height: 1.15;
  font-weight: 600;
}

.settings-page .settings-preview-copy em,
.settings-page .settings-density-card em {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.3;
  font-style: normal;
  font-weight: 620;
}

.settings-page .density-list {
  display: grid;
  gap: 5px;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--panel) 82%, transparent);
}

.settings-page .density-list span {
  height: 15px;
  display: grid;
  grid-template-columns: 14px 1fr 28px;
  align-items: center;
  gap: 7px;
}

.settings-page .settings-density-card.compact .density-list span {
  height: 11px;
}

.settings-page .density-list i,
.settings-page .density-list b,
.settings-page .density-list em {
  display: block;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text) 16%, transparent);
}

.settings-page .density-list i {
  width: 14px;
  height: 14px;
  background: var(--accent);
}

.settings-page .density-list b,
.settings-page .density-list em {
  height: 6px;
}

.settings-page .density-list em {
  opacity: .7;
}

.settings-page .settings-row {
  position: relative;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  min-height: 72px;
  padding: 14px 18px;
}

.settings-page .settings-row + .settings-row::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  left: 72px;
  height: 1px;
  background: var(--line);
}

.settings-page .settings-row-static {
  grid-template-columns: minmax(0, 1fr);
}

.settings-page .settings-row-static + .settings-row-static::before {
  left: 18px;
}

.settings-page .sr-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  color: #fff;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.3), 0 2px 5px rgba(15, 23, 42, .18);
}

.settings-page .sr-icon svg {
  width: 16px;
  height: 16px;
}

.settings-page .sr-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.settings-page .sr-label {
  color: var(--accent-ink);
  font-size: 13.5px;
  line-height: 1.25;
  font-weight: 600;
}

[data-theme="dark"] .settings-page .sr-label {
  color: var(--accent);
}

.settings-page .sr-sub {
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.35;
  font-weight: 520;
}

.settings-page .sr-ctl {
  min-width: max-content;
  display: flex;
  align-items: center;
  justify-content: end;
}

.settings-page .settings-switch {
  width: 52px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  padding: 3px;
  border: 0;
  border-radius: 999px;
  background: color-mix(in srgb, var(--line-strong) 45%, var(--tile));
  cursor: pointer;
  transition: background .14s ease;
}

.settings-page .settings-switch span {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--panel);
  box-shadow: 0 1px 3px rgba(15, 23, 42, .16);
  transition: transform .16s ease;
}

.settings-page .settings-switch-on {
  background: var(--accent);
}

.settings-page .settings-switch-on span {
  transform: translateX(22px);
}

[data-theme="dark"] .settings-page .settings-control-surface,
[data-theme="dark"] .settings-page .settings-group,
[data-theme="dark"] .settings-page .settings-preview-card,
[data-theme="dark"] .settings-page .settings-density-card {
  background: var(--panel);
  border-color: transparent;
  box-shadow: none;
}

@media (max-width: 980px) {
  .settings-page .settings-row {
    grid-template-columns: 36px minmax(0, 1fr);
  }

  .settings-page .sr-ctl {
    grid-column: 2;
    justify-content: flex-start;
    min-width: 0;
  }
}

@media (max-width: 760px) {

  .settings-page-head h1 {
    font-size: 25px;
  }

  .settings-page .settings-preview-grid,
  .settings-page .settings-density-grid {
    grid-template-columns: 1fr;
  }

  .settings-page .settings-control-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .settings-page .settings-row {
    grid-template-columns: 34px minmax(0, 1fr);
    padding: 13px 14px;
  }

  .settings-page .settings-row + .settings-row::before {
    left: 62px;
  }
}

/* ===== TOP BAR QUICK SETTINGS MERGE ===== */
.notif-trigger.alerts-on {
  color: color-mix(in srgb, var(--accent) 72%, var(--muted));
}

.notif-pref-box {
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px solid var(--line);
}

.alert-row-compact {
  padding: 6px 4px;
}

.quick-settings {
  display: grid;
  gap: 0;
  padding: 0 3px 3px;
}

.qs-row {
  min-height: 40px;
  display: grid;
  grid-template-columns: minmax(0, 84px) minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  padding: 6px 3px;
}

.qs-row + .qs-row,
.qs-accent-row + .qs-row {
  border-top: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
}

.qs-row > span {
  min-width: 0;
  display: grid;
  gap: 1px;
}

.qs-row b {
  color: var(--text);
  font-size: 11.8px;
  line-height: 1.2;
  font-weight: 600;
}

.qs-row em {
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.2;
  font-style: normal;
  text-transform: capitalize;
}

.qs-mini {
  /* grid, not flex: equal cells sized by the WIDEST label. flex 1 1 0 inside a
     shrink-wrapped track under-sizes its intrinsic width in Chrome and letters
     paint outside the chips at fractional :root zoom (owner hit this at 120%). */
  justify-self: end;
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  align-items: center;
  gap: 2px;
  padding: 2px;
  border: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
  border-radius: 12px;
  background: color-mix(in srgb, var(--tile) 84%, var(--bg));
}

.quick-settings .theme-seg button {
  height: 28px;
  padding: 0 10px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
  box-shadow: none;
}

.quick-settings .theme-seg button:hover,
.qs-chip:hover {
  color: var(--text);
}

.quick-settings .theme-seg button.on,
.qs-chip.on {
  background: var(--panel);
  color: var(--text);
  box-shadow: 0 1px 2px rgba(15, 23, 42, .08);
}

.qs-accent-row {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  padding: 0 3px 7px 96px;
}

.qs-accent-row .accent-dot {
  width: 21px;
  height: 21px;
}

.qs-zoom {
  min-width: 0;
  justify-content: flex-end;
  gap: 5px;
  padding: 0;
  border: 0;
  background: transparent;
}

.qs-zoom .zoom-btn {
  width: 28px;
  height: 26px;
  border-radius: 7px;
}

.qs-zoom .zoom-reset {
  width: auto;
  min-width: 48px;
  height: 26px;
  padding: 0 8px;
  border-radius: 7px;
}

.qs-currency-grid {
  justify-self: end;
  width: min(100%, 214px);
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 4px;
}

.qs-chip {
  min-width: 0;
  height: 27px;
  padding: 0 6px;
  border: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
  border-radius: 9px;
  background: color-mix(in srgb, var(--tile) 84%, var(--bg));
  color: var(--muted);
  cursor: pointer;
  font-size: 10.8px;
  font-weight: 600;
  letter-spacing: 0;
  text-align: center;
}

/* ===== HEALTH PAGE (rebuild) =====================================
   Built on the house grouped-list system (.settings-sec / .settings-group /
   GRow / StatePill) so it reads like the rest of the cockpit's settings
   surfaces. Only the header, the verdict card, the source table and the
   external-link strip are bespoke; everything else reuses shared primitives.
   ================================================================= */

/* =====================================================================
   PRECISION SYSTEM (hp-) — the one visual system for every cockpit page.
   Locked rules (see components/px.tsx):
   · type: 11 / 12 / 13 / 24 / 28 px only · weights 450 / 500 / 600 / 680
   · spacing on a 4px grid · section rhythm 28px · panel radius 12
   · radii: 8 (micro) / 10 (mark) / 12 (panels) · one hairline (--line-2)
   · saturated color marks STATE ONLY (dots, pills, verdict word);
     all other ink is neutral; icons are quiet glyphs, never colored tiles
   · every value tabular + mono · numeric columns right-aligned
   · table rows fixed-height, single-line; ellipsis only on tertiary prose
   ===================================================================== */

.hp-page {
  --hp-amber: #cd8420;
  --hp-amber-ink: #96660a;
  max-width: 920px;
  padding-top: 28px;
}
.hp-page.wide { max-width: none; } /* the .container 1600 cap governs — 1240 looked lost on big monitors */
[data-theme="dark"] .hp-page {
  --hp-amber: #e0a43c;
  --hp-amber-ink: #e0a43c;
}

/* --- header ---------------------------------------------------------- */
.hp-head { display: flex; align-items: center; gap: 14px; margin: 0 0 20px; }
.hp-mark {
  width: 40px; height: 40px; flex: none;
  display: grid; place-items: center;
  border-radius: 10px;
  color: var(--muted); background: var(--tile);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 16%, transparent);
}
.hp-mark svg { width: 19px; height: 19px; }
.hp-mark.ok   { color: var(--up);           background: var(--up-soft); }
.hp-mark.warn { color: var(--hp-amber-ink); background: color-mix(in srgb, var(--hp-amber) 11%, transparent); }
.hp-mark.bad  { color: var(--down);         background: var(--down-soft); }
.hp-head-copy { flex: 1; min-width: 0; }
.hp-head-copy h1 { margin: 0; color: var(--text); font-size: 24px; font-weight: 680; line-height: 1.15; letter-spacing: -.018em; }
.hp-head-copy p { margin: 3px 0 0; color: var(--muted); font-size: 13.5px; font-weight: 470; line-height: 1.45; }
.hp-head-meta { flex: none; display: grid; gap: 3px; justify-items: end; text-align: right; }
.hp-head-meta span { color: var(--faint); font-size: 11px; font-weight: 500; font-variant-numeric: tabular-nums; }

/* --- shared panel skin ------------------------------------------------ */
.hp-verdict, .hp-group, .hp-sources {
  background: var(--panel);
  border: 1px solid var(--line-2);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
}
[data-theme="dark"] .hp-verdict,
[data-theme="dark"] .hp-group,
[data-theme="dark"] .hp-sources { box-shadow: none; }

/* --- verdict ---------------------------------------------------------- */
.hp-verdict { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0 24px; padding: 20px 20px 16px; }
.hp-eyebrow { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.hp-word { display: block; margin-top: 6px; color: var(--text); font-size: 28px; font-weight: 680; line-height: 1.05; letter-spacing: -.02em; }
.hp-verdict.ok   .hp-word { color: var(--up); }
.hp-verdict.warn .hp-word { color: var(--hp-amber-ink); }
.hp-verdict.bad  .hp-word { color: var(--down); }
.hp-verdict-main { min-width: 0; }
.hp-verdict-main p { margin: 8px 0 0; max-width: 60ch; color: var(--text-2); font-size: 13px; font-weight: 450; line-height: 1.5; }
.hp-verdict-side { display: grid; align-content: start; justify-items: end; gap: 6px; padding-top: 2px; text-align: right; }
.hp-verdict-side > span:not(.hp-pill) { color: var(--muted); font-size: 12px; font-weight: 450; }
.hp-tally { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 8px 20px; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line); }
.hp-tally > span { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 12px; font-weight: 450; font-variant-numeric: tabular-nums; }
.hp-tally b { font-weight: 600; color: var(--text-2); }

/* --- state atoms ------------------------------------------------------ */
.hp-dot { width: 7px; height: 7px; flex: none; border-radius: 50%; background: var(--line-strong); }
.hp-dot.ok   { background: var(--up); }
.hp-dot.warn { background: var(--hp-amber); }
.hp-dot.bad  { background: var(--down); }
.hp-pill { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 12px; font-weight: 600; white-space: nowrap; }
.hp-pill i { width: 7px; height: 7px; flex: none; border-radius: 50%; background: var(--line-strong); }
.hp-pill.ok   { color: var(--up); }           .hp-pill.ok i   { background: var(--up); }
.hp-pill.warn { color: var(--hp-amber-ink); } .hp-pill.warn i { background: var(--hp-amber); }
.hp-pill.bad  { color: var(--down); }         .hp-pill.bad i  { background: var(--down); }

/* --- alert strip ------------------------------------------------------ */
.hp-alert {
  display: flex; align-items: center; gap: 9px;
  margin-top: 12px; padding: 10px 14px;
  border: 1px solid color-mix(in srgb, var(--down) 26%, transparent);
  border-radius: 10px; background: var(--down-soft);
  color: var(--down); font-size: 12px; font-weight: 600;
}

/* --- section label ---------------------------------------------------- */
.hp-sec { margin: 26px 2px 8px; color: var(--text); font-size: 14px; font-weight: 650; letter-spacing: -.008em; text-transform: none; }

/* --- grouped rows ------------------------------------------------------ */
.hp-group { overflow: hidden; }
.hp-row { position: relative; display: flex; align-items: center; gap: 12px; min-height: 56px; padding: 10px 16px; }
.hp-group > * + .hp-row::before { content: ""; position: absolute; top: 0; left: 58px; right: 0; height: 1px; background: var(--line); }
.hp-ic { width: 30px; height: 30px; flex: none; display: grid; place-items: center; border-radius: 9px; background: transparent; color: var(--text); }
.hp-ic svg { width: 18px; height: 18px; }
.hp-main { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.hp-label { color: var(--text); font-size: 14px; font-weight: 620; letter-spacing: -.006em; }
.hp-sub { color: var(--muted); font-size: 12.5px; font-weight: 460; line-height: 1.45; margin-top: 2px; }
.hp-end { margin-left: auto; padding-left: 16px; flex: none; display: inline-flex; align-items: center; gap: 14px; }
.hp-val { display: inline-flex; align-items: center; gap: 8px; color: var(--text-2); font-family: var(--mono); font-size: 12px; font-weight: 500; font-variant-numeric: tabular-nums; white-space: nowrap; }

/* --- evidence matrix ---------------------------------------------------- */
.hp-sources-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 16px; border-bottom: 1px solid var(--line); }
.hp-sources-head h3 { margin: 0; color: var(--text); font-size: 13px; font-weight: 600; }
.hp-sources-head p { margin: 2px 0 0; color: var(--muted); font-size: 12px; font-weight: 450; line-height: 1.45; }
.hp-btn {
  flex: none; display: inline-flex; align-items: center; gap: 6px;
  height: 30px; padding: 0 12px;
  border: 1px solid transparent; border-radius: 8px;
  background: var(--tile); color: var(--text);
  font: inherit; font-size: 12.5px; font-weight: 590; cursor: pointer;
  transition: background .14s ease, color .14s ease;
}
.hp-btn:hover { background: var(--tile-hover); color: var(--text); }
.hp-table-wrap { overflow-x: auto; }
.hp-group .hp-table-wrap { border-top: 1px solid var(--line); }
.hp-group .hp-alert { margin: 0 16px 12px; border-radius: 8px; }
.hp-table { width: 100%; min-width: 860px; border-collapse: collapse; table-layout: fixed; }
.hp-table th {
  padding: 9px 12px; border-bottom: 1px solid var(--line-2);
  color: var(--muted); font-size: 11px; font-weight: 600;
  letter-spacing: .05em; text-transform: uppercase; text-align: left; white-space: nowrap;
}
.hp-table td {
  height: 44px; padding: 0 12px; border-bottom: 1px solid var(--line);
  color: var(--text-2); font-size: 12px; font-weight: 450;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.hp-table th:first-child, .hp-table td:first-child { padding-left: 16px; }
.hp-table th:last-child, .hp-table td:last-child { padding-right: 16px; }
.hp-table tbody tr:last-child td { border-bottom: 0; }
.hp-table tbody tr:hover td { background: var(--hover); }
.hp-state { display: inline-flex; align-items: center; gap: 8px; color: var(--text); font-size: 12.5px; font-weight: 620; }
.hp-table .t-layer { color: var(--muted); }
.hp-table .t-source { color: var(--text); font-size: 13px; font-weight: 620; }
.hp-table .t-measure { color: var(--muted); }
.hp-table .t-value { color: var(--text); font-family: var(--mono); font-weight: 500; font-variant-numeric: tabular-nums; }
.hp-table .t-detail { color: var(--muted); }

/* --- external links ----------------------------------------------------- */
.hp-links { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
.hp-links a {
  display: inline-flex; align-items: center; gap: 7px;
  height: 32px; padding: 0 12px;
  border: 0; border-radius: 8px;
  background: var(--tile); color: var(--text);
  font-size: 12.5px; font-weight: 590; text-decoration: none;
  transition: background .14s ease;
}
.hp-links a:hover { background: var(--tile-hover); }
[data-theme="dark"] .hp-links a,
[data-theme="dark"] .hp-btn { background: var(--tile); border-color: transparent; }

/* --- controls (shared) ---------------------------------------------------- */
.hp-btn.primary { border-color: transparent; background: var(--cta-bg); color: var(--cta-fg); }
.hp-btn.primary:hover { background: color-mix(in srgb, var(--cta-bg) 88%, #000); color: var(--cta-fg); border-color: transparent; }
.hp-btn.danger { color: var(--down); background: color-mix(in srgb, var(--down) 9%, transparent); }
.hp-btn.danger:hover { background: color-mix(in srgb, var(--down) 15%, transparent); color: var(--down); }
.hp-btn:disabled { opacity: .45; cursor: not-allowed; }
.hp-btn:disabled:hover { background: var(--tile); color: var(--text); }
.hp-input {
  height: 32px; padding: 0 10px;
  border: 1px solid var(--line-2); border-radius: 8px;
  background: var(--panel); color: var(--text);
  font: inherit; font-size: 13px; font-weight: 500;
  transition: border-color .14s ease, box-shadow .14s ease;
}
.hp-input.num { font-family: var(--mono); font-size: 12px; font-variant-numeric: tabular-nums; text-align: right; }
.hp-input:focus { outline: none; border-color: var(--accent-line); box-shadow: 0 0 0 3px var(--accent-soft); }
.hp-input::placeholder { color: var(--faint); }
.hp-input:disabled { opacity: .5; cursor: not-allowed; background: var(--tile); }
.hp-btn:focus-visible, .hp-seg button:focus-visible { outline: none; border-color: var(--accent-line); box-shadow: 0 0 0 3px var(--accent-soft); }
[data-theme="dark"] .hp-input { background: var(--tile); border-color: transparent; }
.hp-seg { display: inline-flex; gap: 2px; padding: 2px; border-radius: 8px; background: var(--tile); }
.hp-seg button {
  height: 26px; padding: 0 12px; border: 0; border-radius: 6px;
  background: transparent; color: var(--muted);
  font: inherit; font-size: 12px; font-weight: 600; cursor: pointer;
  transition: color .14s ease, background .14s ease;
}
.hp-seg button:hover { color: var(--text-2); }
.hp-seg button.active { background: var(--panel); color: var(--text); box-shadow: var(--shadow-sm); }
[data-theme="dark"] .hp-seg button.active { background: var(--panel); box-shadow: none; }
.hp-seg.disabled { opacity: .5; }
.hp-seg.disabled button { cursor: not-allowed; }
.hp-row.clickable { cursor: pointer; transition: background .12s ease; }
.hp-row.clickable:hover { background: var(--hover); }
.hp-table .num-r { text-align: right; }
.hp-empty {
  display: grid; gap: 3px; justify-items: start;
  padding: 14px 16px;
  border: 1px dashed var(--line-strong); border-radius: 10px;
}
.hp-empty b { color: var(--text-2); font-size: 13px; font-weight: 600; }
.hp-empty span { color: var(--muted); font-size: 12px; font-weight: 450; line-height: 1.45; }

/* --- stat strip (hero numbers row, hairline-divided — not a card farm) ---- */
.hp-stats { display: flex; flex-wrap: wrap; }
.hp-stat { display: grid; gap: 4px; align-content: start; padding: 2px 24px 2px 0; margin-right: 24px; border-right: 1px solid var(--line); }
.hp-stat:last-child { border-right: 0; margin-right: 0; padding-right: 0; }
.hp-stat .k { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.hp-stat .v { color: var(--text); font-size: 24px; font-weight: 680; letter-spacing: -.02em; line-height: 1.1; font-variant-numeric: tabular-nums; }
.hp-stat .s { color: var(--muted); font-size: 12px; font-weight: 450; font-variant-numeric: tabular-nums; }

/* --- loading + footer ----------------------------------------------------- */
.hp-loading { display: grid; gap: 8px; justify-items: start; padding: 8px 2px 40px; }
.hp-loading b { color: var(--text); font-size: 13px; font-weight: 600; }
.hp-loading span:not(.hp-pill) { color: var(--muted); font-size: 12px; font-weight: 450; }
.hp-foot { margin: 24px 2px 0; color: var(--faint); font-size: 11px; font-weight: 450; line-height: 1.5; }
.hp-foot code { color: var(--muted); font-family: var(--mono); font-size: 11px; }

/* --- responsive ----------------------------------------------------------- */
@media (max-width: 720px) {
  .hp-page { padding-top: 20px; }
  .hp-head { flex-wrap: wrap; }
  .hp-head-meta { width: 100%; justify-items: start; text-align: left; }
  .hp-verdict { grid-template-columns: 1fr; padding: 16px; }
  .hp-verdict-side { justify-items: start; text-align: left; margin-top: 10px; }
  .hp-word { font-size: 24px; }
  .hp-sources-head { flex-direction: column; align-items: stretch; }
  .hp-btn { justify-content: center; }
  .hp-row { flex-wrap: wrap; }
  .hp-end { margin-left: 38px; padding-left: 0; }
}

/* --- Responsive ----------------------------------------------------- */
@media (max-width: 1200px) {
  .logs-workbench { grid-template-columns: 220px minmax(0, 1fr); }
  .logs-inspector { grid-column: 1 / -1; }
}
@media (max-width: 860px) {
}
@media (max-width: 620px) {
}

/* --- Responsive ----------------------------------------------------- */
@media (max-width: 720px) {
  .risk-head { flex-wrap: wrap; gap: 14px; }
  .risk-head-meta { width: 100%; justify-items: start; text-align: left; }
