/* ==== RISK — page extras on the precision system ==================== */
.risk-unit { color: var(--faint); font-size: 11px; font-weight: 500; width: 32px; }
.hp-row.risk-dirty .hp-label::after { content: "•"; color: var(--accent); margin-left: 6px; }
.hp-input.bad { border-color: color-mix(in srgb, var(--down) 45%, transparent); box-shadow: 0 0 0 3px var(--down-soft); }
.hp-row .hp-input { width: 120px; }
.risk-chips { display: flex; flex-wrap: wrap; gap: 6px; padding: 0 16px 12px 58px; }
.risk-chip {
  display: inline-flex; align-items: center; gap: 6px;
  height: 26px; padding: 0 8px;
  border: 1px solid var(--line-2); border-radius: 8px;
  background: var(--panel); color: var(--text);
  font: inherit; font-family: var(--mono); font-size: 11px; font-weight: 500; cursor: pointer;
  transition: border-color .12s ease, background .12s ease;
}
.risk-chip span { color: var(--faint); font-family: var(--font); font-size: 12px; }
.risk-chip:hover { border-color: color-mix(in srgb, var(--down) 40%, transparent); background: var(--down-soft); }
.risk-chip:hover span { color: var(--down); }
.risk-chip.blocked { color: var(--muted); }
[data-theme="dark"] .risk-chip { background: var(--tile); border-color: transparent; }
.risk-probe { display: flex; flex-wrap: wrap; gap: 12px; align-items: end; padding: 12px 16px; border-top: 1px solid var(--line); }
.risk-probe label { display: grid; gap: 5px; }
.risk-probe label > span:first-child { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.risk-probe .hp-input { width: 140px; }
.risk-probe-go { margin-left: auto; align-self: end; }
.risk-quick { display: flex; gap: 6px; padding: 0 16px 12px; }
.risk-probe-result { border-top: 1px solid var(--line); }
.risk-empty-pad { padding: 12px 16px 14px; }


/* ==== LOGS — incident console on the precision system ================ */
.lg-filters { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-bottom: 16px; }
.lg-search { flex: 1 1 200px; min-width: 160px; }
.lg-symbol { width: 110px; font-family: var(--mono); font-size: 12px; }
.lg-select .mkx-pill {
  height: 32px;
  min-width: 132px;
  padding: 0 10px;
  border: 1px solid var(--line-2);
  border-radius: 8px;
  background: var(--panel);
  color: var(--text);
  font-size: 13px;
  font-weight: 500;
}
.lg-select .mkx-menu {
  min-width: max(160px, 100%);
}
.lg-filter-gap { flex: 0 0 4px; }
.lg-toggle.active { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
[data-theme="dark"] .lg-toggle.active { color: var(--accent); }

.lg-grid { display: grid; grid-template-columns: 188px minmax(0, 1fr) 300px; gap: 12px; align-items: start; }
.lg-grid.exec-grid.solo { grid-template-columns: minmax(0, 1fr); }
.lg-facets { display: grid; gap: 12px; }
.lg-facet { padding: 6px; }
.lg-facet h3 { margin: 8px 10px 6px; color: var(--muted); font-size: 14px; font-weight: 440; letter-spacing: 0; text-transform: none; }
.lg-facet button {
  display: flex; align-items: center; gap: 8px;
  width: 100%; height: 30px; padding: 0 10px;
  border: 0; border-radius: 8px; background: transparent;
  color: var(--text-2); font: inherit; font-size: 12px; font-weight: 500; cursor: pointer;
  transition: background .12s ease, color .12s ease;
}
.lg-facet button span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lg-facet button b { margin-left: auto; color: var(--muted); font-weight: 600; font-variant-numeric: tabular-nums; }
.lg-facet button:hover { background: var(--hover); color: var(--text); }
.lg-facet button.active { background: var(--accent-soft); color: var(--accent-ink); }
.lg-facet button.active b { color: var(--accent-ink); }
[data-theme="dark"] .lg-facet button.active, [data-theme="dark"] .lg-facet button.active b { color: var(--accent); }

.lg-feed { min-width: 0; }
.lg-feed-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; padding: 12px 14px; border-bottom: 1px solid var(--line); }
.lg-feed-head h3 { margin: 0; color: var(--text); font-size: 18px; font-weight: 620; letter-spacing: -0.008em; }
.lg-feed-head span { color: var(--muted); font-size: 13.5px; font-weight: 430; font-variant-numeric: lining-nums; }
.lg-list { max-height: 72vh; overflow-y: auto; }
.lg-row {
  position: relative;
  display: grid; grid-template-columns: 64px 7px minmax(0, 1fr) 104px 104px 76px;
  gap: 10px; align-items: center;
  height: 40px; padding: 0 14px;
  cursor: pointer;
  transition: background .1s ease;
}
.lg-row + .lg-row { border-top: 1px solid var(--line); }
.lg-row:hover { background: var(--hover); }
.lg-row.selected { background: var(--accent-soft); }
.lg-row.selected::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: var(--accent); }
.lg-row:focus-visible { outline: none; box-shadow: inset 0 0 0 2px var(--accent-line); }
.lg-time { color: var(--muted); font-family: var(--mono); font-size: 11px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.lg-main { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; }
.lg-main b { color: var(--text); font-weight: 600; }
.lg-main em { color: var(--muted); font-style: normal; font-weight: 450; }
.lg-sym {
  display: inline-flex; align-items: center; gap: 6px;
  height: 24px; padding: 0 6px; margin: 0 -6px;
  border: 0; border-radius: 6px; background: transparent;
  color: var(--text-2); font-family: var(--mono); font-size: 11px; font-weight: 500; cursor: pointer;
  overflow: hidden; white-space: nowrap;
}
.lg-sym:hover { background: var(--tile); color: var(--text); }
.lg-sym.system { color: var(--faint); cursor: default; font-family: var(--font); }
.lg-sym.system:hover { background: transparent; }
.lg-src { color: var(--muted); font-size: 11px; font-weight: 450; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lg-status { color: var(--text-2); font-size: 11px; font-weight: 600; text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.lg-inspect { position: sticky; top: 12px; padding-bottom: 6px; }
.lg-inspect-head { display: grid; gap: 4px; justify-items: start; padding: 14px 14px 12px; border-bottom: 1px solid var(--line); }
.lg-inspect-head h3 { margin: 2px 0 0; color: var(--text); font-size: 13px; font-weight: 600; }
.lg-inspect-head span { color: var(--muted); font-size: 11px; font-weight: 500; font-variant-numeric: tabular-nums; }
.lg-facts { display: grid; gap: 0; margin: 0; padding: 4px 0; }
.lg-facts > div { display: grid; grid-template-columns: 76px minmax(0, 1fr); gap: 10px; padding: 6px 14px; }
.lg-facts dt { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; line-height: 1.5; }
.lg-facts dd { margin: 0; color: var(--text-2); font-size: 12px; font-weight: 450; line-height: 1.5; overflow-wrap: break-word; }
.lg-related { display: grid; gap: 6px; padding: 10px 14px; border-top: 1px solid var(--line); }
.lg-related .hp-btn { justify-content: flex-start; }
.lg-raw { border-top: 1px solid var(--line); }
.lg-raw summary { padding: 10px 14px; color: var(--muted); font-size: 12px; font-weight: 600; cursor: pointer; list-style: none; }
.lg-raw summary::before { content: "▸ "; color: var(--faint); }
.lg-raw[open] summary::before { content: "▾ "; }
.lg-raw pre { margin: 0; padding: 0 14px 12px; max-height: 320px; overflow: auto; color: var(--text-2); font-family: var(--mono); font-size: 11px; line-height: 1.55; }
.lg-empty-pad { padding: 14px; }

@media (max-width: 1100px) {
  .lg-grid { grid-template-columns: minmax(0, 1fr); }
  .lg-facets { grid-template-columns: repeat(3, 1fr); display: grid; }
  .lg-inspect { position: static; }
}

/* ==== EXECUTION — shell + tab bodies on the precision system ========= */
.exec-page .hp-head-meta { align-self: center; }
.exec-stats { margin: 4px 0 20px; }
.exec-grid { grid-template-columns: minmax(0, 1fr) 300px; }
.exec-sym { display: inline-flex; align-items: center; gap: 8px; font-family: var(--mono); font-size: 12px; font-weight: 500; }
.exec-row-actions { display: inline-flex; gap: 6px; }
.hp-btn.exec-cancel { height: 24px; padding: 0 8px; font-size: 11px; }
