  .pnl-grid { grid-template-columns: 1fr; }
  .pnl-costs { grid-template-columns: 1fr; }
}

/* ==== OPPORTUNITIES — proposal queue on the precision system ========= */
.opp-main { min-width: 0; display: grid; gap: 12px; align-content: start; }
.opp-list { display: grid; gap: 12px; }
.opp-card { cursor: pointer; transition: border-color .12s ease; }
.opp-card.selected { border-color: var(--accent-line); }
.opp-card-head { display: flex; align-items: center; gap: 12px; padding: 12px 16px 8px; }
.opp-card-head .exec-sym b { color: var(--text); font-family: var(--font); font-size: 13px; font-weight: 600; }
.opp-card-head .exec-sym em { color: var(--muted); font-size: 12px; font-weight: 450; font-style: normal; }
.opp-edge { margin-left: auto; display: grid; justify-items: end; gap: 1px; }
.opp-edge > span { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.opp-edge b { font-family: var(--mono); font-size: 15px; font-weight: 600; font-variant-numeric: tabular-nums; }
.opp-card-spark { height: 36px; padding: 0 16px; opacity: .9; }
.opp-card-facts { display: flex; flex-wrap: wrap; gap: 4px 24px; margin: 8px 0 0; padding: 8px 16px; border-top: 1px solid var(--line); }
.opp-card-facts > div { display: grid; gap: 1px; }
.opp-card-facts dt { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; }
.opp-card-facts dd { margin: 0; color: var(--text); font-family: var(--mono); font-size: 12px; font-weight: 500; font-variant-numeric: tabular-nums; }
.opp-card-reason { margin: 0; padding: 8px 16px; color: var(--muted); font-size: 12px; font-weight: 450; line-height: 1.5; border-top: 1px solid var(--line); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.opp-card-actions { display: flex; gap: 6px; padding: 10px 16px 12px; border-top: 1px solid var(--line); }
.opp-brief-card { position: static; }

/* ==== DASHBOARD — command center on the precision system ============= */
.dash-stats { align-items: stretch; }
.dash-actions { display: flex; flex-direction: row; align-items: center; gap: 8px; border-right: 0; margin-left: auto; margin-right: 0; padding-right: 0; }
.dash-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 0 20px; align-items: start; }
.dash-col { min-width: 0; }
.dash-events button span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
