/* ==== PERFORMANCE CHARTS (SVG, theme-aware, zoom-safe: no animation) === */
.perf-chart { display: block; width: 100%; height: auto; }
.pc-grid { stroke: var(--line); stroke-width: 1; }
.pc-zero { stroke: var(--line-strong); stroke-width: 1; stroke-dasharray: 3 4; }
.pc-axis { fill: var(--faint); font-family: var(--mono); font-size: 10px; font-variant-numeric: tabular-nums; }
.pc-line { fill: none; stroke-width: 1.8; stroke-linejoin: round; stroke-linecap: round; }
.pc-line.pos { stroke: var(--up); }
.pc-line.neg { stroke: var(--down); }
.pc-area.pos { fill: var(--up); opacity: .08; }
.pc-area.neg { fill: var(--down); opacity: .08; }
.pc-dot.pos { fill: var(--up); }
.pc-dot.neg { fill: var(--down); }
.pc-bar.pos { fill: var(--up); opacity: .75; }
.pc-bar.neg { fill: var(--down); opacity: .75; }
.pc-key { display: inline-block; width: 14px; height: 3px; border-radius: 2px; margin: 0 4px 2px 10px; background: var(--up); }
.pc-key.bars { height: 8px; width: 8px; border-radius: 2px; opacity: .75; }

/* ==== DASHBOARD control room zones ==================================== */
.dash-perf { margin-bottom: 12px; }
.dash-perf-body { padding: 14px 16px 10px; }
.dash-analytics { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px; align-items: stretch; }
.dash-chart-pad { padding: 14px 16px 10px; }
.dash-donut { display: flex; align-items: center; gap: 16px; padding: 14px 16px; }
.dash-donut-legend { display: grid; gap: 2px; min-width: 0; flex: 1; }
.dash-donut-legend button {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  height: 26px; padding: 0 8px; margin: 0 -8px;
  border: 0; border-radius: 6px; background: transparent;
  color: var(--text-2); font: inherit; font-size: 12px; font-weight: 500; cursor: pointer;
}
.dash-donut-legend button:hover { background: var(--hover); color: var(--text); }
.dash-donut-legend b { font-family: var(--mono); font-size: 11px; font-weight: 500; font-variant-numeric: tabular-nums; }
.dash-structure { display: grid; gap: 10px; padding: 16px; }
.dash-struct-row { display: grid; grid-template-columns: 92px minmax(0, 1fr) 92px; align-items: center; gap: 12px; }
.dash-struct-label { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; }
.dash-struct-track { height: 14px; border-radius: 4px; background: var(--tile); overflow: hidden; }
.dash-struct-track i { display: block; height: 100%; border-radius: 4px; }
.dash-struct-track i.pos { background: var(--up); opacity: .8; }
.dash-struct-track i.neg { background: var(--down); opacity: .8; }
.dash-struct-track i.fee { background: var(--hp-amber); opacity: .8; }
.dash-struct-row b { text-align: right; font-family: var(--mono); font-size: 12px; font-weight: 500; font-variant-numeric: tabular-nums; }
.dash-events h3 { display: flex; align-items: center; gap: 6px; }
.dash-events a {
  display: flex; align-items: center; gap: 8px;
  width: 100%; min-height: 30px; padding: 4px 10px;
  border: 0; border-radius: 8px;
  color: var(--text-2); font-size: 12px; font-weight: 500; text-decoration: none;
  transition: background .12s ease, color .12s ease;
}
.dash-events a:hover { background: var(--hover); color: var(--text); }
.dash-events a span { overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; line-height: 1.35; }

/* ==== ACCOUNT — merged capital surface ================================ */
.acc-layout { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 0 20px; align-items: start; }
.acc-main { min-width: 0; }
.acc-rail { min-width: 0; }
.acc-rail .hp-sec:first-child { margin-top: 0; }
.acc-hero { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 20px; padding: 20px; margin-bottom: 16px; }
.acc-hero-left { min-width: 0; }
.acc-balance { margin-top: 8px; color: var(--text); font-size: 34px; font-weight: 680; letter-spacing: -.02em; line-height: 1.05; font-variant-numeric: tabular-nums; }
.acc-balance-meta { display: flex; flex-wrap: wrap; gap: 4px 18px; margin-top: 8px; color: var(--muted); font-size: 12px; font-weight: 450; }
.acc-balance-meta b { color: var(--text-2); font-weight: 600; font-variant-numeric: tabular-nums; }
.acc-hero-actions { display: flex; gap: 8px; margin-top: 14px; }
.acc-hero-right { display: flex; align-items: center; gap: 16px; }
.acc-alloc { display: grid; gap: 6px; }
.acc-alloc > div { display: flex; align-items: baseline; justify-content: space-between; gap: 14px; }
.acc-alloc span { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; }
.acc-alloc b { color: var(--text); font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; }
.acc-asset-bar { margin-bottom: 12px; }
.acc-sort { display: inline-flex; align-items: center; gap: 3px; border: 0; background: transparent; padding: 0; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; cursor: pointer; }
.acc-sort:hover { color: var(--text); }
.acc-sort i { font-style: normal; color: var(--accent); width: 8px; }
.acc-share { display: inline-grid; gap: 3px; justify-items: end; min-width: 84px; }
.acc-share i { display: block; width: 84px; height: 3px; border-radius: 2px; background: var(--tile); overflow: hidden; }
.acc-share i span { display: block; height: 100%; border-radius: 2px; background: var(--accent); opacity: .7; }
.acc-sub-note { color: var(--faint); font-family: var(--font); font-size: 11px; font-style: normal; }
@media (max-width: 1100px) {
  .acc-layout { grid-template-columns: 1fr; }
  .acc-hero { grid-template-columns: 1fr; }
}
.acc-head-tools { display: inline-flex; align-items: center; gap: 12px; }
.acc-head-tools .hp-input { width: 160px; height: 28px; }
.acc-margin { margin-top: 12px; }

/* ==== BORROW console (Binance-loans style) ============================ */
.loan-console { padding: 14px 16px; }
.loan-console-form { display: flex; flex-wrap: wrap; align-items: end; gap: 12px; }
.loan-console-form label { display: grid; gap: 5px; min-width: 0; }
.loan-console-form label > span { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.loan-console-form .hp-input { width: 150px; }
.loan-console-go { margin-left: auto; }
.loan-console-facts { display: flex; flex-wrap: wrap; gap: 8px 28px; margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--line); }
.loan-console-facts > div { display: grid; gap: 2px; }
.loan-console-facts .k { color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; }
.loan-console-facts b { color: var(--text); font-family: var(--mono); font-size: 12px; font-weight: 500; font-variant-numeric: tabular-nums; }
.loan-console-note { margin: 10px 0 0; color: var(--muted); font-size: 12px; font-weight: 450; line-height: 1.5; }
.pc-bench { fill: none; stroke: var(--hp-amber); stroke-width: 1.6; stroke-dasharray: 5 4; }
.pc-key.bench { background: var(--hp-amber); height: 3px; }
.dash-analytics2 { margin-top: 12px; grid-template-columns: 1fr 1fr; }
.dash-facts > div { grid-template-columns: 150px minmax(0, 1fr); }
.dash-facts dd { font-family: var(--mono); font-variant-numeric: tabular-nums; }
.dash-facts dd em { color: var(--faint); font-style: normal; font-size: 11px; margin-left: 6px; }
.lg-feed-head .hp-seg { margin-left: 12px; }

/* ==== SURFACE RICHNESS — cards float on a soft canvas (TV/Binance feel) == */
:root, [data-theme="light"] { --canvas: #f5f6f8; }
[data-theme="dark"] { --canvas: var(--bg); }
/* white canvas: structure comes from whitespace + hairlines, not gray boxes */
.hp-verdict, .hp-group, .hp-sources {
  border-radius: 12px;
  border-color: var(--line-2);
  box-shadow: var(--shadow-sm);
}
[data-theme="dark"] .hp-verdict, [data-theme="dark"] .hp-group, [data-theme="dark"] .hp-sources {
  box-shadow: none;
}

[data-theme="light"] .hp-input, [data-theme="light"] .hp-links a { background: #fff; }
[data-theme="light"] .hp-seg { background: color-mix(in srgb, var(--tile) 88%, #fff); }
/* money reads like money: sign colors on stat values are data, not decoration */
.hp-stat .v.up, .up { color: var(--up); }
.hp-stat .v.down, .down { color: var(--down); }
/* win / lose bar (Binance lead-trader style) */
.wl-bar { display: grid; gap: 5px; min-width: 180px; }
.wl-bar-labels { display: flex; justify-content: space-between; font-size: 12px; font-weight: 600; }
.wl-bar-labels .w { color: var(--up); }
.wl-bar-labels .l { color: var(--down); }
.wl-bar-track { display: flex; height: 6px; border-radius: 3px; overflow: hidden; background: var(--tile); }
.wl-bar-track .w { background: var(--up); }
.wl-bar-track .l { background: var(--down); }
/* last-value chip on charts (TV style) */
.pc-chip-bg.pos { fill: var(--up); }
.pc-chip-bg.neg { fill: var(--down); }
.pc-chip-text { fill: #fff; font-family: var(--mono); font-size: 10px; font-weight: 600; }
/* donut legend swatches */
.dash-donut-legend button i { width: 8px; height: 8px; border-radius: 2px; flex: none; margin-right: 8px; }
.dash-donut-legend button span { display: inline-flex; align-items: center; }
.dash-arming { margin-bottom: 12px; }
.dash-wl { padding: 12px 16px 2px; }

/* stat strips: bare, airy — whitespace does the framing */
.hp-stats.exec-stats { padding: 0; background: transparent; border: 0; box-shadow: none; }
/* key stats INSIDE the performance card: hairline below, no own card chrome */
.dash-keystats { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 16px; padding: 16px 20px 14px; border-bottom: 1px solid var(--line); margin: 0; }
.dash-keystats .hp-stat { padding: 2px 16px 2px 0; margin-right: 0; border-right: 1px solid var(--line); min-height: 0; }
.dash-keystats .hp-stat:last-child { border-right: 0; padding-right: 0; }
.dash-keystats .hp-stat .v { font-size: 21px; }
@media (max-width: 1200px) { .dash-keystats { grid-template-columns: repeat(3, minmax(0, 1fr)); } .dash-keystats .hp-stat:nth-child(3n) { border-right: 0; } }

/* zoom menu presets */
.zoom-presets { display: flex; gap: 6px; flex-wrap: wrap; }

/* ==== sticky footer: no dead void below the page on tall screens ====== */
/* CSS zoom does not rescale vh — compensate with the --z factor. */
html, body, #root { height: 100%; }
body { overflow: hidden; }

/* ==== TOPBAR MENUS — precision normalization for every popover ======== */
.smenu {
  background: var(--panel);
  border: 1px solid var(--line-2);
  border-radius: 12px;
  box-shadow: var(--shadow-pop);
  padding: 14px;
}
[data-theme="dark"] .smenu { box-shadow: 0 12px 32px -12px rgba(0, 0, 0, .5); }
.smenu .menu-head {
  margin: 10px 0 6px; padding: 0;
  color: var(--muted); font-size: 11px; font-weight: 600;
  letter-spacing: .06em; text-transform: uppercase;
}
.smenu .np-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 0 0 8px; border-bottom: 1px solid var(--line); margin-bottom: 8px; }
.smenu .np-title { display: inline-flex; align-items: center; gap: 7px; color: var(--text); font-size: 14px; font-weight: 650; }
.smenu .np-sub { color: var(--muted); font-size: 11px; font-weight: 500; }
.smenu .np-sub-line { color: var(--muted); font-size: 12px; font-weight: 450; line-height: 1.45; margin-bottom: 6px; }
.smenu .np-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 26px; }
.smenu .np-row .k { color: var(--muted); font-size: 12px; font-weight: 500; }
.smenu .np-row .v { color: var(--text); font-family: var(--mono); font-size: 12px; font-weight: 500; font-variant-numeric: tabular-nums; }
.smenu .menu-item {
  display: flex; align-items: center; gap: 10px;
  width: 100%; min-height: 32px; padding: 0 8px; margin: 0 -8px;
  border: 0; border-radius: 8px; background: transparent;
  color: var(--text); font: inherit; font-size: 13px; font-weight: 550; cursor: pointer;
}
.smenu .menu-item:hover { background: var(--hover); color: var(--text); }
.smenu .menu-item.sel { color: var(--accent-ink); background: var(--accent-soft); }
[data-theme="dark"] .smenu .menu-item.sel { color: var(--accent); }
.smenu .zp-time { margin-left: auto; font-family: var(--mono); font-variant-numeric: tabular-nums; }
.smenu .dh-row { display: flex; align-items: center; gap: 9px; min-height: 28px; }
.smenu .dh-name { color: var(--text); font-size: 12.5px; font-weight: 550; }
.smenu .dh-detail { margin-left: auto; color: var(--muted); font-family: var(--mono); font-size: 11px; font-variant-numeric: tabular-nums; }
.smenu .notif-row { border-radius: 8px; }
.smenu .notif-time { font-family: var(--mono); font-variant-numeric: tabular-nums; }
.smenu .menu-foot { margin-top: 10px; padding-top: 8px; border-top: 1px solid var(--line); color: var(--faint); font-size: 11px; font-weight: 450; line-height: 1.45; }
.smenu .qs-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 34px; }
.smenu .qs-row > span b { color: var(--text); font-size: 13px; font-weight: 620; display: block; }
.smenu .qs-row > span em { color: var(--muted); font-size: 11px; font-weight: 450; font-style: normal; }
.smenu .zoom-row { display: inline-flex; gap: 4px; }
.smenu .zoom-btn, .smenu .zoom-reset {
  height: 26px; min-width: 26px; padding: 0 8px;
  border: 1px solid var(--line-2); border-radius: 7px;
  background: transparent; color: var(--text-2);
  font: inherit; font-size: 12px; font-weight: 600; cursor: pointer;
}
.smenu .zoom-btn:hover, .smenu .zoom-reset:hover { background: var(--hover); color: var(--text); border-color: var(--line-strong); }
.smenu .qs-chip { height: 24px; padding: 0 8px; border: 1px solid var(--line-2); border-radius: 7px; background: transparent; color: var(--text-2); font: inherit; font-size: 11px; font-weight: 600; cursor: pointer; }
.smenu .qs-chip.on { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
[data-theme="dark"] .smenu .qs-chip.on { color: var(--accent); }


/* ==== icon tiles — macOS Settings language: saturated tile, white glyph.
   Colors come from ONE semantic dictionary (see px.tsx TINT):
   red=danger/kill · green=money/armed · orange=keys/degraded ·
   blue=connectivity · indigo=engine/ledger · teal=volume · slate=neutral. */
.hp-ic.tinted {
  background: var(--tint);
  color: #fff;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .26), 0 1px 2px rgba(0, 0, 0, .16);
}
.hp-ic.tinted svg { width: 16px; height: 16px; }

/* ==== ONE topbar: brand + search + icons; sidebar is nav-only ========= */
.app-root { flex-direction: column; }
.app-body { display: flex; flex: 1 1 auto; min-height: 0; }
.hdr { flex: none; width: 100%; border-bottom: 1px solid var(--line); }
.hdr-brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; margin-right: 14px; cursor: pointer; flex: none; }
.hdr-brand .brand-lockup { display: flex; flex-direction: column; line-height: 1.05; }
.hdr-brand .brand-name { color: var(--text); font-size: 15px; font-weight: 650; letter-spacing: -.01em; }
.hdr-brand .brand-sub { color: var(--muted); font-size: 10px; font-weight: 600; letter-spacing: .04em; }
.snav { padding-top: 10px; }
/* the base: always pinned to the viewport bottom, never floats up */
.footer { flex: none; border-top: 1px solid var(--line); }
.zoom-live { min-width: 44px; text-align: center; color: var(--text); font-size: 12.5px; font-weight: 620; font-variant-numeric: tabular-nums; }
/* keep footer text clear of the floating refresh dock */
.footer .ftr-line { padding-right: 72px; }


/* ==== ACCOUNT POPOVER — connection-panel typography, no thick random type == */
.menu-pop.acct-pop {
  background: var(--panel);
  border: 1px solid var(--line-2);
  border-radius: 12px;
  box-shadow: var(--shadow-pop);
  padding: 14px;
}
.acct-pop .acct-pop-name { font-size: 14px; font-weight: 650; color: var(--text); letter-spacing: -.006em; }
.acct-pop .acct-pop-sub { font-size: 12px; font-weight: 450; color: var(--muted); }
.acct-pop .menu-head {
  margin: 12px 0 4px; padding: 0;
  color: var(--muted); font-size: 11px; font-weight: 600;
  letter-spacing: .06em; text-transform: uppercase;
}
.acct-pop .acct-sess-warn { color: var(--accent-ink); font-weight: 600; text-transform: none; letter-spacing: 0; font-size: 11px; }
[data-theme="dark"] .acct-pop .acct-sess-warn { color: var(--accent); }
.acct-pop .acct-ex { display: flex; align-items: center; gap: 10px; min-height: 40px; padding: 4px 0; }
.acct-pop .acct-ex + .acct-ex { border-top: 1px solid var(--line); }
.acct-pop .acct-ex-badge { width: 26px; height: 26px; border-radius: 8px; font-size: 13px; font-weight: 620; }
.acct-pop .acct-ex-info b { font-size: 13px; font-weight: 550; color: var(--text); display: block; }
.acct-pop .acct-ex-info small { font-family: var(--mono); font-size: 10.5px; font-weight: 450; color: var(--faint); font-variant-numeric: tabular-nums; }
.acct-pop .acct-ex-pill {
  margin-left: auto; padding: 0; border: 0; background: transparent; border-radius: 0;
  font-family: var(--mono); font-size: 11px; font-weight: 500; letter-spacing: 0; text-transform: lowercase;
}
.acct-pop .acct-ex-pill.ok { color: var(--up); }
.acct-pop .acct-ex-pill.bad { color: var(--down); }
.acct-pop .acct-ex-pill.idle, .acct-pop .acct-ex-pill.soon { color: var(--faint); }
.acct-pop .acct-sess { display: flex; align-items: center; gap: 9px; min-height: 38px; padding: 3px 0; border-radius: 0; background: transparent; }
.acct-pop .acct-sess + .acct-sess { border-top: 1px solid var(--line); }
.acct-pop .acct-sess-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--line-strong); flex: none; }
.acct-pop .acct-sess-dot.on { background: var(--up); box-shadow: none; }
.acct-pop .acct-sess-name { font-size: 13px; font-weight: 550; color: var(--text); display: block; }
.acct-pop .acct-sess-place { font-family: var(--mono); font-size: 10.5px; font-weight: 450; color: var(--faint); }
.acct-pop .acct-sess-right { margin-left: auto; display: grid; justify-items: end; gap: 2px; }
.acct-pop .acct-sess-time { font-family: var(--mono); font-size: 11px; font-weight: 500; color: var(--faint); }
.acct-pop .acct-sess-time.on { color: var(--up); }
.acct-pop .acct-sess-you { padding: 0; border: 0; background: transparent; color: var(--accent-ink); font-size: 10px; font-weight: 650; letter-spacing: .05em; text-transform: uppercase; }
[data-theme="dark"] .acct-pop .acct-sess-you { color: var(--accent); }
.acct-pop .acct-ex-manage {
  width: 100%; margin-top: 12px; height: 32px;
  border: 0; border-radius: 8px;
  background: var(--tile); color: var(--text);
  font: inherit; font-size: 12.5px; font-weight: 590; cursor: pointer;
}
.acct-pop .acct-ex-manage:hover { background: var(--tile-hover); }


/* ==== GLOBAL TYPE DISCIPLINE — the connection-panel voice everywhere ====
   labels: UI face, 12-13px, 500-620 · values: mono, tabular, 11-12px, 500 ·
   section headers: 11px/600 tracked uppercase · nothing above weight 680. */
.drow { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 26px; }
.drow .k { color: var(--muted); font-size: 12px; font-weight: 500; }
.drow .v { color: var(--text); font-family: var(--mono); font-size: 12px; font-weight: 500; font-variant-numeric: tabular-nums; }
.quote-meta-row .k { color: var(--muted); font-size: 12px; font-weight: 500; }
.quote-meta-row .v { font-family: var(--mono); font-size: 12px; font-weight: 500; font-variant-numeric: tabular-nums; }
.chip-tag { font-size: 11px; font-weight: 550; letter-spacing: .02em; }
.mini-btn { font-size: 12.5px; font-weight: 590; }
.cta-pill { font-size: 12.5px; font-weight: 620; }
.safety-row b, .trade-review-panel b { font-weight: 620; }
.result-strip { font-weight: 550; }

/* :root zoom + backdrop-filter = Chrome samples a misaligned region and page
   text ghosts through. Every surface floating OVER content must be opaque. */
.cmd, .hb-tip {
  background: var(--panel) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* ==== ACCOUNT ACTIVITY (orders/positions/fills/pnl folded in) ==== */
.acc-activity { margin-top: 12px; }
.acc-activity-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 8px; }
.acc-activity-head .hp-sec { margin: 0; }

/* ==========================================================================
   SHELL SCALE 2026-07-08 — one deliberate size system for the chrome.
   8px rhythm: topbar 64 · icon boxes 38 (19px glyphs) · search pill 42 ·
   sidebar 240 (40px rows, 14px labels, 19px icons) · content max 1600 with
   32px symmetric gutters · dock 28px off the corners. No random sizes.
   ========================================================================== */

:root { --maxw: 1600px; }
:root { --sidebar-w: 176px; --page-gutter: 32px; --topbar-content-start: calc(var(--sidebar-w) + var(--page-gutter)); }
.container { padding-left: 32px; padding-right: 32px; }

/* ---- top bar ---- */
.hdr { height: 64px; }
.hdr-in { padding: 0 20px 0 16px; gap: 14px; }
.hdr-brand { gap: 11px; }
.hdr-brand .brand-mark { width: 34px; height: 34px; }
.hdr-brand .brand-name { font-size: 17px; font-weight: 620; letter-spacing: -0.014em; }
.hdr-brand .brand-sub {
  font-size: 10.5px; font-weight: 560; letter-spacing: .07em;
  text-transform: uppercase; color: var(--muted);
}
.tb-left {
  position: absolute;
  left: var(--topbar-content-start);
  top: 0;
  bottom: 0;
  width: clamp(360px, 31vw, 520px);
  padding-left: 0;
  display: flex;
  align-items: center;
  pointer-events: none;
}
.tb-left > * { pointer-events: auto; }

/* the Coinbase search pill, not a boxy input */
.topbar-search {
  flex: 1 1 auto;
  width: 100%;
  max-width: 100%;
  margin-right: auto;
  transition: max-width .28s cubic-bezier(.2,.8,.2,1), flex-basis .28s cubic-bezier(.2,.8,.2,1);
}
.topbar-search.open {
  flex-basis: auto;
  max-width: 100%;
}
.topbar-search .snav-search-box {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  height: 42px;
  border-radius: 21px;
  background: var(--tile);
  border: 1px solid transparent;
  box-shadow: none;
  padding: 0 10px 0 18px;
  gap: 10px;
  color: var(--muted);
  transition: border-color .18s ease, box-shadow .18s ease, background .18s ease, transform .18s ease;
}
.topbar-search .snav-search-box::before {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: inherit;
  background: conic-gradient(from 0deg, transparent 0 18%, rgba(47, 107, 255, .70) 26%, rgba(89, 186, 255, .42) 36%, transparent 48% 100%);
  opacity: 0;
  transform: rotate(0deg);
