.tbp-tag { font-size: 10px; font-weight: 620; padding: 2px 8px; border-radius: 999px; letter-spacing: .04em; color: #fff; }
.tbp-tag.ok { background: var(--up); }
.tbp-tag.warn { background: #e2892a; }
.tbp-tag.bad { background: var(--down); }
.tbp-tag.idle { background: var(--tile); color: var(--muted); }

.tbp-row, .tbp-item {
  display: flex; align-items: center; gap: 9px; min-height: 32px; padding: 0 4px;
  width: 100%;
}
.tbp-row + .tbp-row, .tbp-item + .tbp-item, .tbp-row + .tbp-item, .tbp-item + .tbp-row {
  border-top: 1px solid var(--line);
}
.tbp-row.tall { min-height: 36px; }
.tbp-item { border: 0; border-radius: 0; background: none; font: inherit; cursor: pointer; text-align: left; color: inherit; }
.tbp-item:hover { background: var(--hover); }
.tbp-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; }
.tbp-dot.ok { background: var(--up); }
.tbp-dot.warn { background: #e2892a; }
.tbp-dot.bad { background: var(--down); }
.tbp-dot.idle { background: var(--faint); }
.tbp-name { font-size: 12px; color: var(--text-2); font-weight: 500; white-space: nowrap; min-width: 0; flex: 0 1 auto; overflow: hidden; text-overflow: ellipsis; }
.tbp-name.strong { color: var(--text); font-weight: 550; font-size: 12.5px; }
.tbp-name.clip { max-width: 250px; }
.tbp-sub { font-size: 11px; color: var(--faint); font-weight: 450; white-space: nowrap; min-width: 0; flex: 1 1 auto; overflow: hidden; text-overflow: ellipsis; }
.tbp-sym { width: 20px; text-align: center; font-size: 13px; font-weight: 550; color: var(--text-2); flex: none; }
.tbp-val { margin-left: auto; flex: none; font-family: var(--mono); font-size: 11px; font-weight: 500; color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.tbp-val.ok { color: var(--up); }
.tbp-val.warn { color: #e2892a; }
.tbp-val.bad { color: var(--down); }
.tbp-check { color: var(--accent); flex: none; margin-left: 6px; }
.tbp-item .tbp-val { margin-left: auto; }
.tbp-foot {
  padding: 9px 4px 4px; border-top: 1px solid var(--line); margin-top: 2px;
  color: var(--faint); font-size: 11px; font-weight: 450; text-align: center;
}
.tbp-btn {
