  font-size: 11.5px;
  font-style: normal;
  font-weight: 430;
  line-height: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.modex-status {
  height: 23px;
  display: inline-grid;
  place-items: center;
  padding: 0 9px;
  border-radius: 999px;
  background: var(--tile);
  color: var(--muted);
  font-size: 10px;
  font-weight: 690;
  letter-spacing: .045em;
  text-transform: uppercase;
}
.modex-status.bad {
  color: var(--down);
  background: color-mix(in srgb, var(--down) 10%, transparent);
}
.modex-status.warn {
  color: #b76b15;
  background: rgba(217, 154, 43, .12);
}
.modex-status.ok {
  color: var(--up);
  background: var(--up-soft);
}
.modex-rows {
  display: grid;
  margin-top: 8px;
  border-top: 1px solid var(--line);
}
.modex-row {
  width: 100%;
  min-height: 58px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 48px;
  align-items: center;
  gap: 14px;
  padding: 10px 10px;
  border: 0;
  border-bottom: 1px solid var(--line);
  background: transparent;
  color: var(--text);
  text-align: left;
  cursor: pointer;
}
.modex-row span {
  display: grid;
  min-width: 0;
  gap: 3px;
}
.modex-row b {
  color: var(--text);
  font-size: 13px;
  font-weight: 560;
  line-height: 17px;
}
.modex-row em {
  overflow: hidden;
  color: var(--muted);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 430;
  line-height: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.modex-row:hover b {
  color: var(--text);
}
.modex-row.emergency b {
  color: var(--down);
}
.cb-switch {
  justify-self: end;
  position: relative;
  width: 46px;
  height: 28px;
  display: block;
  border-radius: 999px;
  background: #d4d9e3;
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, .06);
  transition: background .18s ease, box-shadow .18s ease;
}
.cb-switch span {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  display: block;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgba(15, 23, 42, .22);
  transition: transform .18s cubic-bezier(.2,.8,.2,1);
}
.modex-row.on .cb-switch {
  background: #0052ff;
  box-shadow: inset 0 0 0 1px rgba(0, 82, 255, .16);
}
.modex-row.on .cb-switch span {
  transform: translateX(18px);
}
.modex-row.emergency.on .cb-switch {
  background: var(--down);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--down) 18%, transparent);
}
.modex-row:nth-child(3).on .cb-switch,
.modex-row:nth-child(4).on .cb-switch {
  background: #0f9d6a;
}
.modex-foot {
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  align-items: center;
  gap: 8px;
  padding-top: 9px;
}
.modex-foot button {
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 0;
  border-radius: 10px;
  background: var(--tile);
  color: var(--text);
  font: inherit;
  font-size: 11.5px;
  font-weight: 560;
  cursor: pointer;
}
.modex-foot button:hover {
  background: var(--hover);
}
.modex-foot span {
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 620;
  letter-spacing: .045em;
  text-transform: uppercase;
  white-space: nowrap;
}

/* new utility trigger tints (match the icon-color dictionary) */
.hdr-ic.tint-mref { color: #0e7a4a; }
.hdr-ic.tint-cur { color: #1d4ed8; }
.hdr-ic.tint-basis { color: #7c22ce; }

/* appearance block in the account popover */
.acct-appear { display: flex; flex-direction: column; gap: 8px; padding: 2px 0 8px; }
.acct-appear .theme-seg { justify-self: stretch; }
.acct-accents { display: flex; align-items: center; gap: 8px; padding: 0 2px; }
.acct-accents .accent-dot { width: 19px; height: 19px; }

/* ==========================================================================
   ACCOUNT REBOOT (acb-) — Binance wallet anatomy, Coinbase voice.
   Numbers 16px/430 proportional lining, names 16/550 over 14/430 subs,
   72px borderless rows, text tabs with accent underline, quiet chrome.
   ========================================================================== */
.acb-page { padding-bottom: 12px; }
.acb-page .r { text-align: right; }
.acb-page .l { text-align: left; }

/* ---- hero ---- */
.acb-hero {
  display: flex;
  justify-content: space-between;
  gap: 28px;
  padding: 22px 24px 20px;
  margin-bottom: 16px;
}
.acb-hero-main { min-width: 0; }
.acb-label-row { display: flex; align-items: center; gap: 10px; }
.acb-label { font-size: 15px; font-weight: 560; color: var(--text); }
.acb-eye {
  display: inline-flex; align-items: center; justify-content: center;
  width: 26px; height: 26px; border: 0; border-radius: 7px;
  background: none; color: var(--muted); cursor: pointer;
}
.acb-eye:hover { color: var(--text); background: var(--tile); }
.acb-value {
  margin-top: 10px;
  font-size: 34px;
  font-weight: 560;
  letter-spacing: -0.016em;
  color: var(--text);
  font-variant-numeric: lining-nums;
}
.acb-value .num { font-weight: inherit; font-variant-numeric: inherit; font-feature-settings: "lnum" 1; }
.acb-approx { margin-top: 4px; font-size: 14px; font-weight: 430; color: var(--muted); }
.acb-today { margin-top: 12px; display: flex; align-items: center; gap: 10px; }
.acb-today-k {
  font-size: 13.5px; font-weight: 450; color: var(--text-2);
  border-bottom: 1px dotted var(--faint); padding-bottom: 1px;
}
.acb-today-v { font-size: 13.5px; font-weight: 500; font-variant-numeric: lining-nums; }
.acb-today-v.idle { color: var(--faint); }

.acb-hero-side { display: flex; flex-direction: column; align-items: flex-end; gap: 14px; flex: none; }
.acb-actions { display: flex; gap: 8px; }
.acb-chart { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; }
.acb-ranges { display: flex; gap: 2px; padding: 2px; border-radius: 9px; background: var(--tile); }
.acb-ranges button {
  height: 24px; padding: 0 10px; border: 0; border-radius: 7px; background: transparent;
  font: inherit; font-size: 11.5px; font-weight: 550; color: var(--muted); cursor: pointer;
}
.acb-ranges button.on { background: var(--panel); color: var(--text); box-shadow: 0 1px 2px rgba(15,23,42,.08); }
.acb-chart-span { font-size: 11px; font-weight: 450; color: var(--faint); }
.acb-spark { width: 320px; height: 76px; display: block; }
.acb-spark-empty { font-size: 12px; font-weight: 450; color: var(--faint); align-self: flex-end; padding-top: 22px; }

/* ---- my assets ---- */
.acb-assets { padding: 20px 24px 8px; }
.acb-assets-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.acb-assets-head h3 { margin: 0; font-size: 17px; font-weight: 620; letter-spacing: -0.01em; color: var(--text); }
.acb-assets-tools { display: flex; align-items: center; gap: 14px; }
.acb-search { width: 170px; height: 34px; font-size: 13px; }
.acb-dust {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 13px; font-weight: 450; color: var(--text-2);
  cursor: pointer; white-space: nowrap; user-select: none;
}
.acb-dust input { width: 15px; height: 15px; accent-color: var(--accent); cursor: pointer; }

.acb-tabs-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 14px; }
.acb-tabs { display: flex; gap: 22px; }
.acb-tabs button {
  position: relative; border: 0; background: none; padding: 0 0 10px;
  font: inherit; font-size: 14.5px; font-weight: 470; color: var(--muted); cursor: pointer;
}
.acb-tabs button:hover { color: var(--text-2); }
.acb-tabs button.on { color: var(--text); font-weight: 570; }
.acb-tabs button.on::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: 0;
  height: 2.5px; border-radius: 2px; background: var(--accent);
}
.acb-alloc { display: flex; align-items: center; gap: 12px; padding-bottom: 6px; }
.acb-alloc-legend { display: flex; flex-direction: column; gap: 2px; }
.acb-alloc-legend span { font-size: 12px; font-weight: 450; color: var(--muted); }
.acb-alloc-legend b { font-weight: 550; color: var(--text-2); font-variant-numeric: lining-nums; margin-left: 4px; }

/* ---- asset table (Coinbase voice) ---- */
.acb-table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.acb-table th {
  padding: 12px 8px;
  font-size: 14px; font-weight: 440; color: var(--muted);
  border-top: 1px solid var(--line);
  white-space: nowrap;
}
.acb-sort { border: 0; background: none; padding: 0; font: inherit; color: inherit; cursor: pointer; }
.acb-sort:hover { color: var(--text); }
.acb-sort i { font-style: normal; margin-left: 3px; color: var(--accent-ink); }
.acb-table td { height: 72px; padding: 0 8px; vertical-align: middle; white-space: nowrap; overflow: hidden; text-overflow: clip; }
.acb-table tbody tr.link { cursor: pointer; }
.acb-table tbody tr:hover td { background: var(--hover); }
.acb-table tbody tr:hover td:first-child { border-radius: 10px 0 0 10px; }
.acb-table tbody tr:hover td:last-child { border-radius: 0 10px 10px 0; }

.acb-asset { display: flex; align-items: center; gap: 13px; height: 72px; }
.acb-asset-name { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.acb-asset-name b { font-size: 16px; font-weight: 550; color: var(--text); letter-spacing: -0.006em; }
.acb-asset-name em {
  font-style: normal; font-size: 14px; font-weight: 430; color: var(--muted);
  overflow: hidden; text-overflow: ellipsis;
}
.acb-num { font-variant-numeric: lining-nums; }
.acb-cell-main { display: block; font-size: 16px; font-weight: 430; color: var(--text); }
.acb-cell-sub { display: block; margin-top: 1px; font-size: 13.5px; font-weight: 430; color: var(--muted); }
.acb-num.up .acb-cell-main { color: var(--up); }
.acb-num.down .acb-cell-main { color: var(--down); }
.acb-share { padding-right: 2px; }
.acb-bar {
  display: block; margin-top: 5px; margin-left: auto; width: 84px; height: 4px;
  border-radius: 2px; background: var(--tile); overflow: hidden;
}
.acb-bar i { display: block; height: 100%; border-radius: 2px; background: var(--accent); }
.acb-bar.wide { width: 100%; margin: 10px 0 0; }

/* ---- account view buckets ---- */
.acb-buckets { border-top: 1px solid var(--line); }
.acb-bucket {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto;
  grid-template-areas: "ic name val" "bar bar bar";
  align-items: center;
  column-gap: 13px;
  padding: 16px 8px 14px;
}
.acb-bucket + .acb-bucket { border-top: 1px solid var(--line); }
.acb-bucket-ic {
  display: inline-flex; align-items: center; justify-content: center;
  width: 38px; height: 38px; border-radius: 10px;
  background: var(--tile); color: var(--text-2);
}
.acb-bucket-name { grid-area: name; display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.acb-bucket-name b { font-size: 16px; font-weight: 550; color: var(--text); }
.acb-bucket-name em { font-style: normal; font-size: 13.5px; font-weight: 430; color: var(--muted); }
.acb-bucket-val { grid-area: val; text-align: right; font-variant-numeric: lining-nums; }
.acb-bucket .acb-bar.wide { grid-area: bar; }
.acb-bucket-note { margin: 12px 8px 10px; font-size: 12.5px; font-weight: 450; color: var(--faint); }

.acb-sec { margin: 0; font-size: 17px; font-weight: 620; letter-spacing: -0.01em; color: var(--text); }

@media (max-width: 860px) {
  .acb-hero { flex-direction: column; }
  .acb-hero-side { align-items: stretch; }
  .acb-spark { width: 100%; }
}

/* ==========================================================================
   ACCOUNT v3 — Binance wallet, exactly. One type scale top to bottom:
   names 16/550 · numbers 16/430 lining · subs 13.5/430 · headers 14/440.
   Nothing shrinks between the hero and the activity tables.
   ========================================================================== */
.acb-hero2 { display: block; padding: 22px 24px 14px; margin-bottom: 16px; }
.acb-hero2-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 24px; }
.acb-hero2-id { min-width: 0; }

/* chart: full-width, date axis, hover crosshair */
.acb-chartwrap { margin-top: 10px; }
.acb-chartplot { position: relative; height: 170px; cursor: crosshair; }
.acb-chartplot svg { width: 100%; height: 100%; display: block; }
.acb-cross {
  position: absolute; top: 0; bottom: 0; width: 1px;
  background: color-mix(in srgb, var(--text) 28%, transparent);
  pointer-events: none;
}
.acb-tip {
  position: absolute; top: 8px; transform: translateX(10px);
  display: flex; flex-direction: column; gap: 1px;
  padding: 7px 10px; border-radius: 9px;
  background: var(--panel); border: 1px solid var(--line-2);
  box-shadow: var(--shadow-pop); pointer-events: none; white-space: nowrap; z-index: 5;
}
.acb-tip.flip { transform: translateX(calc(-100% - 10px)); }
.acb-tip b { font-size: 14.5px; font-weight: 560; color: var(--text); font-variant-numeric: lining-nums; }
.acb-tip em { font-style: normal; font-size: 12px; font-weight: 450; color: var(--muted); }
.acb-axis { display: flex; justify-content: space-between; padding: 8px 2px 0; }
.acb-axis span { font-size: 12.5px; font-weight: 430; color: var(--muted); font-variant-numeric: lining-nums; }
.acb-chart-empty { padding: 40px 0 30px; text-align: center; font-size: 14px; font-weight: 430; color: var(--faint); }

/* my assets: bucket list + allocation */
.acb-assets2 { padding: 22px 24px 10px; margin-bottom: 16px; }
.acb-h3 { margin: 0; font-size: 18px; font-weight: 620; letter-spacing: -0.01em; color: var(--text); }
.acb-assets2-grid { display: grid; grid-template-columns: minmax(0, 1fr) 330px; gap: 44px; margin-top: 14px; }

.acb-bl-head, .acb-bl-row { display: grid; grid-template-columns: 40px minmax(0, 1fr) 210px 110px; align-items: center; column-gap: 14px; }
.acb-bl-head { padding: 10px 0; border-bottom: 1px solid var(--line); }
.acb-bl-head span { font-size: 14px; font-weight: 440; color: var(--muted); }
.acb-bl-head span:first-child { grid-column: 1 / span 2; }
.acb-bl-head .r { text-align: right; }
.acb-bl-row { min-height: 66px; }
.acb-bl-row + .acb-bl-row { border-top: 1px solid var(--line); }
.acb-bl-ic { display: inline-flex; align-items: center; justify-content: center; width: 24px; height: 24px; color: var(--text); }
.acb-bl-name { font-size: 16px; font-weight: 550; color: var(--text); letter-spacing: -0.006em; display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.acb-bl-name em { font-style: normal; font-size: 13px; font-weight: 450; color: var(--up); white-space: nowrap; }
.acb-bl-amt { text-align: right; font-variant-numeric: lining-nums; }
.acb-bl-amt b { display: block; font-size: 16px; font-weight: 430; color: var(--text); }
.acb-bl-amt small { display: block; margin-top: 1px; font-size: 13.5px; font-weight: 430; color: var(--muted); }
.acb-bl-amt i, .acb-bl-ratio i { font-style: normal; font-size: 15px; color: var(--faint); }
.acb-bl-ratio { text-align: right; font-size: 16px; font-weight: 430; color: var(--text); font-variant-numeric: lining-nums; }

.acb-allocwrap { border-left: 1px solid var(--line); padding-left: 40px; display: flex; flex-direction: column; gap: 14px; }
.acb-alloc-title { font-size: 14px; font-weight: 440; color: var(--muted); }
.acb-allocwrap .donut-wrap { display: flex; flex-direction: column; align-items: center; gap: 18px; }
.acb-allocwrap .donut-legend { width: 100%; display: flex; flex-direction: column; gap: 0; }
.acb-allocwrap .donut-leg-row { display: flex; align-items: center; gap: 10px; min-height: 34px; }
.acb-allocwrap .donut-leg-row + .donut-leg-row { border-top: 1px solid var(--line); }
.acb-allocwrap .donut-dot { width: 9px; height: 9px; border-radius: 50%; flex: none; }
.acb-allocwrap .donut-leg-name { font-size: 14.5px; font-weight: 520; color: var(--text); }
.acb-allocwrap .donut-leg-pct { margin-left: auto; font-size: 14.5px; font-weight: 430; color: var(--text); font-variant-numeric: lining-nums; font-family: inherit; }
.acb-allocwrap .donut-leg-val { font-size: 13.5px; font-weight: 430; color: var(--muted); font-variant-numeric: lining-nums; font-family: inherit; }

/* activity — same scale as everything above it */
.acb-activity2 { padding: 22px 24px 18px; }
.acb-act-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.acb-act-live { display: inline-flex; align-items: center; gap: 7px; font-size: 13px; font-weight: 450; color: var(--muted); }
.acb-act-live i { width: 8px; height: 8px; border-radius: 50%; background: var(--faint); }
.acb-act-live.on { color: var(--up); }
.acb-act-live.on i { background: var(--up); }
.acb-act-sub { display: block; margin: 18px 0 4px; font-size: 14px; font-weight: 440; color: var(--muted); }
.acb-act-empty {
  padding: 22px; border: 1px dashed var(--line-2); border-radius: 12px;
  font-size: 14px; font-weight: 430; color: var(--muted); text-align: center;
}
.acb-act-table th { border-top: 0 !important; }
.acb-act-table td { height: 58px !important; }
.acb-act-sym { display: inline-flex; align-items: baseline; gap: 10px; font-size: 15.5px; font-weight: 520; color: var(--text); }
.acb-act-sym b { font-size: 14px; font-weight: 560; }
.acb-act-sym b.up { color: var(--up); }
.acb-act-sym b.down { color: var(--down); }
.acb-act-sym em { font-style: normal; font-size: 13px; font-weight: 430; color: var(--muted); }
.acb-act-status { font-size: 13.5px; font-weight: 480; color: var(--text-2); text-transform: lowercase; }
.acb-act-status.warn { color: #e2892a; }

@media (max-width: 1080px) {
  .acb-assets2-grid { grid-template-columns: minmax(0, 1fr); }
  .acb-allocwrap { border-left: 0; padding-left: 0; }
}
.acb-chart-note { padding: 6px 2px 0; text-align: right; font-size: 12px; font-weight: 430; color: var(--faint); }


/* ==== TOPBAR UNIFORMITY FINAL 2026-07-08 ==================================
   One system, decided: hairline rules under EVERY section header (the "thick
   line" was a UA button-border bug — killed); values never clip; one tag,
   one check, one footer, one button across all eleven panels + profile. */
.tbp-row + .tbp-row, .tbp-item + .tbp-item, .tbp-row + .tbp-item, .tbp-item + .tbp-row {
  border-top: 1px solid var(--line);
}
.smenu .menu-head, .acct-pop .menu-head {
  display: flex; align-items: center; gap: 8px;
  margin: 10px 0 2px; padding: 0 4px 8px;
  border-bottom: 1px solid var(--line);
  color: var(--muted); font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase;
}

/* appearance panel bits */
.hdr-ic.tint-appear { color: #b45309; }
.tbp-swatches { display: flex; align-items: center; gap: 9px; padding: 12px 4px 8px; }
.tbp-swatches .accent-dot { width: 20px; height: 20px; }
.tbp-zoom { margin-left: auto; display: inline-flex; align-items: center; gap: 6px; }
.tbp-zoom button {
  width: 26px; height: 26px; border: 0; border-radius: 7px;
  background: var(--tile); color: var(--text-2);
  font: inherit; font-size: 14px; font-weight: 550; cursor: pointer; line-height: 1;
}
.tbp-zoom button:hover { color: var(--text); }
.tbp-zoom button.reset { width: auto; padding: 0 10px; font-size: 11.5px; font-weight: 550; }
.tbp-zoom b { min-width: 42px; text-align: center; font-family: var(--mono); font-size: 12px; font-weight: 500; color: var(--text); font-variant-numeric: tabular-nums; }

/* profile popover — same chips and words as every panel */
.acct-pop .acct-sess-you {
  font-size: 10px; font-weight: 620; letter-spacing: .04em; text-transform: uppercase;
  padding: 2px 8px; border-radius: 999px; background: var(--tile); color: var(--muted);
}
.acct-pop .acct-sess-warn {
  font-size: 10px; font-weight: 620; letter-spacing: .04em; text-transform: uppercase;
  padding: 2px 8px; border-radius: 999px; background: var(--accent-soft); color: var(--accent-ink);
  margin-left: auto;
}
[data-theme="dark"] .acct-pop .acct-sess-warn { color: var(--accent); }
.acct-pop .acct-ex-badge { border-radius: 8px; }
.acct-pop .acct-ex-manage {
  height: 34px; border: 0; border-radius: 9px; background: var(--tile);
  color: var(--text-2); font-size: 12.5px; font-weight: 550;
}
.acct-pop .acct-ex-manage:hover { color: var(--text); border: 0; }


/* ==== NOTIFICATIONS: icon-only trigger, compact account feed ============== */
.smenu .tbp-row .toggle { transform: scale(.78); transform-origin: right center; margin-left: auto; flex: none; }
.smenu-bar .notif-ghost,
.smenu-bar .notif-ghost:hover,
.smenu-bar .notif-ghost.on {
  width: 38px;
  min-width: 38px;
  padding: 0;
  border-color: transparent;
  background: transparent;
  color: var(--muted);
  box-shadow: none;
}
