/* ==== TOPBAR BASIS DISPLAY — compact spread unit switch =================== */
.smenu-bar .basis-ghost.basis-premium-trigger,
.smenu-bar .basis-ghost.basis-premium-trigger:hover,
.smenu-bar .basis-ghost.basis-premium-trigger.on {
  width: 38px;
  min-width: 38px;
  padding: 0;
  border-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
}
.basis-trigger-core {
  position: relative;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  color: color-mix(in srgb, #7c3aed 62%, var(--muted));
}
.basis-trigger-core.bps {
  color: color-mix(in srgb, var(--accent) 62%, var(--muted));
}
.basis-trigger-core::before {
  content: "";
  position: absolute;
  inset: 6px;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: .14;
}
.basis-trigger-core::after {
  content: "";
  position: absolute;
  left: 9px;
  right: 9px;
  bottom: 6px;
  height: 2px;
  border-radius: 999px;
  background: currentColor;
  opacity: .25;
}
.basis-trigger-core b {
  position: relative;
  z-index: 1;
  color: currentColor;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 760;
  line-height: 1;
}
.basis-trigger-core i {
  position: absolute;
  top: 7px;
  right: 6px;
  width: 6px;
  height: 6px;
  border: 2px solid var(--panel);
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 2px color-mix(in srgb, currentColor 10%, transparent);
}
.smenu-bar .basis-premium-trigger:hover .basis-trigger-core,
.smenu-bar .basis-premium-trigger.on .basis-trigger-core {
  color: color-mix(in srgb, #7c3aed 76%, var(--text));
}
.smenu-bar .basis-premium-trigger:hover .basis-trigger-core.bps,
.smenu-bar .basis-premium-trigger.on .basis-trigger-core.bps {
  color: color-mix(in srgb, var(--accent) 76%, var(--text));
}
.smenu-content:has(.basisx-pop) {
  max-height: min(72vh, 240px);
  overflow-x: visible;
  overflow-y: visible;
}
.basisx-pop {
  display: grid;
  gap: 8px;
  color: var(--text);
}
.basisx-hero {
  position: relative;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 52px;
  align-items: center;
  gap: 8px;
  min-height: 56px;
  padding: 8px;
  overflow: hidden;
  border: 1px solid var(--line-2);
  border-radius: 16px;
  background:
    radial-gradient(circle at 18% 0%, color-mix(in srgb, #7c3aed 12%, transparent), transparent 42%),
    linear-gradient(180deg, var(--panel), color-mix(in srgb, var(--tile) 92%, var(--panel)));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.56), 0 12px 26px rgba(15, 23, 42, .055);
}
.basisx-hero.bps {
  background:
    radial-gradient(circle at 18% 0%, color-mix(in srgb, var(--accent) 12%, transparent), transparent 42%),
    linear-gradient(180deg, var(--panel), color-mix(in srgb, var(--tile) 92%, var(--panel)));
}
.basisx-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 0 36%, rgba(255,255,255,.12) 50%, transparent 64% 100%);
  transform: translateX(-120%);
  animation: basisxSweep 4.2s cubic-bezier(.2,.8,.2,1) infinite;
  pointer-events: none;
}
.basisx-mark {
  position: relative;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 12px;
  background: color-mix(in srgb, #7c3aed 9%, var(--tile));
  color: #6d28d9;
  font-family: var(--mono);
  font-size: 13px;
  font-weight: 760;
  line-height: 1;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, #7c3aed 16%, transparent);
}
.basisx-hero.bps .basisx-mark {
  background: color-mix(in srgb, var(--accent) 9%, var(--tile));
  color: var(--accent-ink);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 16%, transparent);
}
[data-theme="dark"] .basisx-hero.bps .basisx-mark { color: var(--accent); }
.basisx-score {
  position: relative;
  display: grid;
  min-width: 0;
  gap: 2px;
}
.basisx-score b {
  overflow: hidden;
  color: var(--text);
  font-family: var(--mono);
  font-size: 20px;
  font-weight: 660;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.basisx-score em {
  overflow: hidden;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 690;
  letter-spacing: .06em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.basisx-bars {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: end;
  gap: 4px;
  width: 52px;
  height: 30px;
  padding: 6px 8px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: color-mix(in srgb, var(--tile) 84%, transparent);
}
.basisx-bars i {
  display: block;
  height: 8px;
  border-radius: 999px;
  background: #7c3aed;
  opacity: .86;
  animation: basisxBar 1.8s ease-in-out infinite;
}
.basisx-bars i:nth-child(2) { height: 14px; opacity: .68; animation-delay: .16s; }
.basisx-bars i:last-child { height: 20px; opacity: .52; animation-delay: .32s; }
.basisx-bars.bps i { background: var(--accent); }
.basisx-counters {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}
.basisx-counters span {
  display: grid;
  grid-template-columns: 7px minmax(0, 1fr) auto;
  align-items: center;
  gap: 6px;
  min-height: 34px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--tile);
}
.basisx-counters i {
  display: block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--faint);
}
.basisx-counters b {
  overflow: hidden;
  color: var(--text);
  font-family: var(--mono);
  font-size: 11.5px;
  font-weight: 620;
  font-variant-numeric: tabular-nums;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.basisx-counters em {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 690;
  letter-spacing: .05em;
  white-space: nowrap;
}
.basisx-counters .pct i { background: #7c3aed; box-shadow: 0 0 0 3px color-mix(in srgb, #7c3aed 10%, transparent); }
.basisx-counters .bps i { background: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 10%, transparent); }
.basisx-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}
.basisx-option {
  position: relative;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  min-height: 48px;
  padding: 7px 9px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--tile);
  color: var(--text-2);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform .16s ease, border-color .16s ease, background .16s ease, color .16s ease;
}
.basisx-option i {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 11px;
  background: color-mix(in srgb, currentColor 8%, var(--panel));
  color: currentColor;
  font-style: normal;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 760;
  line-height: 1;
}
.basisx-option span {
  display: grid;
  min-width: 0;
  gap: 2px;
}
.basisx-option b,
.basisx-option em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.basisx-option b {
  color: inherit;
  font-family: var(--mono);
  font-size: 12.5px;
  font-weight: 660;
  line-height: 1.1;
}
.basisx-option em {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  font-style: normal;
  font-weight: 560;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}
.basisx-option:hover {
  transform: translateY(-1px);
  background: var(--panel);
  color: var(--text);
}
.basisx-option.pct { color: color-mix(in srgb, #7c3aed 74%, var(--text-2)); }
.basisx-option.bps { color: color-mix(in srgb, var(--accent) 74%, var(--text-2)); }
.basisx-option.on {
  background: var(--panel);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 8%, transparent);
}
.basisx-option.pct.on { border-color: color-mix(in srgb, #7c3aed 28%, var(--line-2)); color: #6d28d9; }
.basisx-option.bps.on { border-color: color-mix(in srgb, var(--accent) 28%, var(--line-2)); color: var(--accent-ink); }
[data-theme="dark"] .basisx-option.bps.on { color: var(--accent); }
.basisx-option.on::after {
  content: "";
  position: absolute;
  right: 9px;
  top: 9px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 10%, transparent);
}
@keyframes basisxSweep {
  0%, 58% { transform: translateX(-120%); }
  100% { transform: translateX(120%); }
}
@keyframes basisxBar {
  0%, 100% { transform: scaleY(.72); }
  48% { transform: scaleY(1.08); }
}
.smenu-bar .appearance-ghost,
.smenu-bar .appearance-ghost:hover,
.smenu-bar .appearance-ghost.on {
  width: 38px;
  min-width: 38px;
  padding: 0;
  border-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
}
.appearance-trigger-core {
  position: relative;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  color: color-mix(in srgb, var(--apx-accent, var(--accent)) 58%, var(--muted));
}
.appearance-trigger-core > span {
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  background:
    conic-gradient(from 210deg, currentColor 0 34%, transparent 34% 62%, currentColor 62% 78%, transparent 78%),
    color-mix(in srgb, currentColor 8%, transparent);
  opacity: .22;
}
.appearance-trigger-core::before {
  content: "";
  position: absolute;
  inset: 7px;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: .18;
}
.appearance-trigger-core b {
  position: relative;
  z-index: 1;
  color: currentColor;
  font-family: var(--mono);
  font-size: 13px;
  font-weight: 760;
  line-height: 1;
}
.appearance-trigger-core i {
  position: absolute;
  right: 6px;
  bottom: 6px;
  width: 6px;
  height: 6px;
  border: 2px solid var(--panel);
  border-radius: 50%;
  background: var(--apx-accent, var(--accent));
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--apx-accent, var(--accent)) 10%, transparent);
}
.smenu-bar .appearance-ghost:hover,
.smenu-bar .appearance-ghost.on { filter: saturate(1.08); }
.smenu-bar .appearance-ghost:hover .appearance-trigger-core,
.smenu-bar .appearance-ghost.on .appearance-trigger-core {
  color: color-mix(in srgb, var(--apx-accent, var(--accent)) 76%, var(--text));
}
.smenu-content:has(.apx-pop) {
  max-height: min(72vh, 236px);
  overflow-x: visible;
  overflow-y: visible;
}
.apx-pop.apx-premium {
  display: grid;
  gap: 7px;
  color: var(--text);
}
.apx-stage {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 45px 34px;
  align-items: center;
  gap: 9px;
  min-height: 58px;
  padding: 8px;
  overflow: hidden;
  border: 1px solid var(--line-2);
  border-radius: 16px;
  background:
    radial-gradient(circle at 18% 0%, color-mix(in srgb, var(--apx-accent, var(--accent)) 12%, transparent), transparent 42%),
    linear-gradient(180deg, var(--panel), color-mix(in srgb, var(--tile) 92%, var(--panel)));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.56), 0 12px 26px rgba(15, 23, 42, .055);
}
.apx-stage::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 0 36%, rgba(255,255,255,.12) 50%, transparent 64% 100%);
  transform: translateX(-120%);
  animation: apxSweep 4.6s cubic-bezier(.2,.8,.2,1) infinite;
  pointer-events: none;
}
.apx-window {
  position: relative;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  grid-template-rows: 10px 1fr;
  gap: 5px;
  min-width: 0;
  height: 40px;
  padding: 7px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--panel) 82%, transparent);
}
.apx-window i {
  display: block;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text) 20%, transparent);
}
.apx-window i:first-child {
  grid-column: 1 / -1;
  background: color-mix(in srgb, var(--apx-accent, var(--accent)) 34%, transparent);
}
.apx-window i:nth-child(2) {
  background: color-mix(in srgb, var(--text) 10%, transparent);
}
.apx-window i:last-child {
  background: var(--apx-accent, var(--accent));
  opacity: .82;
}
.apx-rail {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: end;
  gap: 4px;
  height: 32px;
  padding: 6px 8px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: color-mix(in srgb, var(--tile) 84%, transparent);
}
.apx-rail i {
  display: block;
  height: 8px;
  border-radius: 999px;
  background: var(--apx-accent, var(--accent));
  opacity: .84;
  animation: apxBar 1.9s ease-in-out infinite;
}
.apx-rail i:nth-child(2) { height: 15px; opacity: .66; animation-delay: .14s; }
.apx-rail i:last-child { height: 22px; opacity: .48; animation-delay: .28s; }
.apx-orb {
  position: relative;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--apx-accent, var(--accent));
  box-shadow:
    inset 0 0 0 5px color-mix(in srgb, var(--panel) 92%, transparent),
    0 0 0 1px color-mix(in srgb, var(--apx-accent, var(--accent)) 22%, transparent),
    0 0 0 6px color-mix(in srgb, var(--apx-accent, var(--accent)) 8%, transparent);
}
.apx-stage b {
  position: absolute;
  right: 8px;
  bottom: 7px;
  color: var(--text);
  font-family: var(--mono);
  font-size: 10.5px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  letter-spacing: .02em;
  line-height: 1;
}
.apx-modes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}
.apx-mode {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 21px;
  align-items: center;
  gap: 6px;
  min-height: 42px;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--tile);
  color: var(--text-2);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform .16s ease, border-color .16s ease, background .16s ease, color .16s ease;
}
.apx-mode:hover {
  transform: translateY(-1px);
  background: var(--panel);
  color: var(--text);
}
.apx-mode.on {
  background: var(--panel);
  border-color: color-mix(in srgb, var(--apx-accent, var(--accent)) 28%, var(--line-2));
  color: var(--text);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--apx-accent, var(--accent)) 8%, transparent);
}
.apx-mode-art {
  position: relative;
  display: grid;
  grid-template-columns: 13px minmax(0, 1fr);
  grid-template-rows: 8px 13px;
  gap: 3px;
  height: 28px;
  min-width: 0;
  padding: 5px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
}
.apx-mode-art i {
  display: block;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text) 16%, transparent);
}
.apx-mode-art i:first-child {
  grid-column: 1 / -1;
  background: color-mix(in srgb, var(--apx-accent, var(--accent)) 30%, transparent);
}
.apx-mode-art.light {
  background: #fff;
  border-color: #dfe4ee;
}
.apx-mode-art.light i:nth-child(2) { background: #eef2f7; }
.apx-mode-art.light i:last-child { background: var(--apx-accent, var(--accent)); }
.apx-mode-art.dark {
  background: #101318;
  border-color: #222936;
}
.apx-mode-art.dark i:nth-child(2) { background: #273142; }
.apx-mode-art.dark i:last-child { background: color-mix(in srgb, var(--apx-accent, var(--accent)) 88%, #fff); }
.apx-mode-art.system {
  background: linear-gradient(90deg, #fff 0 49%, #101318 51% 100%);
}
.apx-mode b {
  display: grid;
  place-items: center;
  width: 21px;
  height: 21px;
  border-radius: 50%;
  color: currentColor;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 760;
  line-height: 1;
}
.apx-mode.on b {
  background: color-mix(in srgb, var(--apx-accent, var(--accent)) 10%, transparent);
  color: var(--accent-ink);
}
[data-theme="dark"] .apx-mode.on b { color: var(--accent); }
.apx-mode.on::after {
  content: "";
  position: absolute;
  right: 7px;
  top: 7px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--apx-accent, var(--accent));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--apx-accent, var(--accent)) 10%, transparent);
}
.apx-dots {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 5px;
  min-height: 31px;
  padding: 0 1px;
}
.apx-dot {
  position: relative;
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  padding: 0;
  cursor: pointer;
}
.apx-dot span {
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: var(--dot);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .10), 0 1px 3px rgba(15, 23, 42, .08);
}
.apx-dot:hover span {
  transform: scale(1.08);
}
.apx-dot.on::before {
  content: "";
  position: absolute;
  inset: 2.5px;
  border-radius: 50%;
  border: 2px solid var(--dot);
  box-shadow: 0 0 0 2px var(--panel);
}
.apx-dot i {
  content: "";
  position: absolute;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--panel);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, .08);
  opacity: 0;
}
.apx-dot.on i {
  opacity: 1;
}
.apx-scale {
  display: grid;
  grid-template-columns: 31px minmax(0, 1fr) 31px 31px;
  align-items: center;
  gap: 6px;
  min-height: 31px;
}
.apx-scale button {
  height: 31px;
  border: 0;
  border-radius: 10px;
  background: var(--tile);
  color: var(--text);
  font: inherit;
  font-size: 15px;
  font-weight: 650;
  cursor: pointer;
  transition: transform .16s ease, background .16s ease, color .16s ease;
}
.apx-scale button:hover {
  transform: translateY(-1px);
  background: var(--panel);
}
.apx-scale button.reset {
  color: var(--accent-ink);
  font-size: 14px;
  font-weight: 760;
}
[data-theme="dark"] .apx-scale button.reset { color: var(--accent); }
.apx-scale strong {
  display: grid;
  place-items: center;
  min-width: 0;
  height: 31px;
  padding: 0 8px;
  border-radius: 10px;
  background: var(--panel);
  border: 1px solid var(--line-2);
  color: var(--text);
  font-family: var(--mono);
  font-size: 11.5px;
  font-weight: 620;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
@keyframes apxSweep {
  0%, 62% { transform: translateX(-120%); }
  100% { transform: translateX(120%); }
}
@keyframes apxBar {
  0%, 100% { transform: scaleY(.72); }
  48% { transform: scaleY(1.08); }
}
.smenu-bar .refresh-ghost,
.smenu-bar .refresh-ghost:hover,
.smenu-bar .refresh-ghost.on {
  width: 38px;
  min-width: 38px;
  padding: 0;
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}
.smenu-bar .refresh-ghost.ok { color: var(--up); }
.smenu-bar .refresh-ghost.warn { color: #d99a2b; }
.smenu-bar .refresh-ghost.bad { color: var(--down); }
.smenu-bar .refresh-ghost:hover,
.smenu-bar .refresh-ghost.on { filter: saturate(1.08); }
.refresh-glyph {
  display: grid;
  place-items: center;
}
.refresh-ghost.spinning .refresh-glyph svg,
.mref-mark.spin svg,
.mref-now .spin svg {
  animation: mrefSpin .8s linear infinite;
}
