/* ==== TOPBAR MARKET REFRESH — compact cadence console ===================== */
.smenu-bar .refresh-ghost.refresh-premium-trigger,
.smenu-bar .refresh-ghost.refresh-premium-trigger:hover,
.smenu-bar .refresh-ghost.refresh-premium-trigger.on {
  width: 38px;
  min-width: 38px;
  padding: 0;
  border-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
}
.refresh-trigger-core {
  position: relative;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  color: color-mix(in srgb, var(--up) 58%, var(--muted));
}
.refresh-trigger-core::before {
  content: "";
  position: absolute;
  inset: 6px;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: .14;
}
.refresh-trigger-core::after {
  content: "";
  position: absolute;
  left: 9px;
  right: 9px;
  bottom: 6px;
  height: 2px;
  border-radius: 999px;
  background: currentColor;
  opacity: .26;
}
.refresh-trigger-core.warn { color: color-mix(in srgb, #d99a2b 64%, var(--muted)); }
.refresh-trigger-core.bad { color: color-mix(in srgb, var(--down) 62%, var(--muted)); }
.refresh-trigger-core i {
  position: absolute;
  top: 7px;
  right: 6px;
  width: 6px;
  height: 6px;
  border: 2px solid var(--panel);
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 2px color-mix(in srgb, currentColor 10%, transparent);
}
.smenu-bar .refresh-premium-trigger:hover .refresh-trigger-core,
.smenu-bar .refresh-premium-trigger.on .refresh-trigger-core {
  color: color-mix(in srgb, var(--up) 76%, var(--text));
}
.smenu-bar .refresh-premium-trigger:hover .refresh-trigger-core.warn,
.smenu-bar .refresh-premium-trigger.on .refresh-trigger-core.warn {
  color: color-mix(in srgb, #d99a2b 78%, var(--text));
}
.smenu-bar .refresh-premium-trigger:hover .refresh-trigger-core.bad,
.smenu-bar .refresh-premium-trigger.on .refresh-trigger-core.bad {
  color: color-mix(in srgb, var(--down) 76%, var(--text));
}
.refresh-ghost.spinning .refresh-trigger-core svg,
.mrefx-mark.spin svg,
.mrefx-now .spin svg {
  animation: mrefSpin .8s linear infinite;
}
