  color: var(--text-2);
  font: inherit;
  font-size: 12.5px;
  font-weight: 570;
  cursor: pointer;
}
.mrefx-targets button:hover,
.mrefx-targets button.on {
  background: #0b0e14;
  color: #fff;
}
.mrefx-cadence-presets {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 6px;
}
.mrefx-cadence-preset {
  height: 30px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--panel);
  color: var(--text-2);
  font: inherit;
  font-family: var(--mono);
  font-size: 11.5px;
  font-weight: 650;
  cursor: pointer;
}
.mrefx-cadence-preset:hover,
.mrefx-cadence-preset.on {
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line-2));
  background: var(--hover);
  color: var(--accent-ink);
}
[data-theme="dark"] .mrefx-cadence-preset.on {
  color: var(--accent);
}
.mrefx-source-list {
  overflow: hidden;
  border-top: 1px solid var(--line);
}
.mrefx-source-row {
  width: 100%;
  min-height: 42px;
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 5px 10px;
  border: 0;
  border-bottom: 1px solid var(--line);
  background: transparent;
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.mrefx-source-row:hover,
.mrefx-source-row.on {
  background: var(--hover);
}
.mrefx-source-ic {
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: var(--muted);
}
.mrefx-source-row.ok .mrefx-source-ic { color: var(--up); }
.mrefx-source-row.warn .mrefx-source-ic { color: #b76b15; }
.mrefx-source-row.bad .mrefx-source-ic { color: var(--down); }
.mrefx-source-copy {
  display: grid;
  min-width: 0;
  gap: 1px;
}
.mrefx-source-copy b {
  overflow: hidden;
  color: var(--text);
  font-size: 12.25px;
  font-weight: 560;
  line-height: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mrefx-source-copy em {
  overflow: hidden;
  color: var(--muted);
  font-size: 10.75px;
  font-style: normal;
  font-weight: 430;
  line-height: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mrefx-source-row strong {
  color: var(--text);
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.mrefx-custom-row {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 34px 76px;
  align-items: end;
  gap: 7px;
}
.mrefx-custom-row > button {
  height: 34px;
  border: 0;
  border-radius: 10px;
  background: var(--tile);
  color: var(--text);
  font: inherit;
  font-size: 13px;
  font-weight: 650;
  cursor: pointer;
}
.mrefx-custom-row > button:not(.mrefx-apply) {
  font-size: 15px;
}
.mrefx-custom-row > button:hover {
  background: var(--hover);
}
.mrefx-custom-row label {
  display: grid;
  min-width: 0;
  gap: 4px;
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 640;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.mrefx-custom-row input {
  width: 100%;
  height: 34px;
  border: 1px solid var(--line-2);
  border-radius: 10px;
  background: var(--panel);
  color: var(--text);
  font: inherit;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 650;
  text-align: center;
}
.mrefx-custom-row input:focus {
  outline: none;
  border-color: var(--accent-line);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.mrefx-apply {
  color: #fff !important;
  background: #0b0e14 !important;
}
.mrefx-apply:hover {
  background: #171d2a !important;
}

/* ==== NEWS — gold-voice rows, proper rhythm ==== */
.news-item.lg { min-height: 58px; align-items: center; gap: 13px; }
.news-item.lg .news-item-ic { width: 24px; height: 24px; background: none; border: 0; color: var(--text-2); }
.news-item.lg .news-item-title { font-size: 15px; font-weight: 520; color: var(--text); letter-spacing: -0.004em; line-height: 1.35; }
.news-item.lg .news-item-sub { font-size: 12.5px; font-weight: 440; color: var(--muted); margin-top: 2px; }
.news-item.lg .news-item-meta { display: inline-flex; align-items: center; gap: 10px; color: var(--faint); flex: none; }
.news-item-date { font-family: var(--mono); font-size: 11px; font-weight: 450; color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.news-page-list .news-item.lg + .news-item.lg { border-top: 1px solid var(--line); }
.news-source-note { font-size: 12px; font-weight: 440; color: var(--faint); text-align: center; padding: 14px 0 4px; }
.news-hint { font-size: 13px; font-weight: 440; color: var(--muted); }

/* ==== CALENDAR — same touches: no frost, ruled day heads, lining values ==== */
.cal-day-head { backdrop-filter: none !important; -webkit-backdrop-filter: none !important; background: var(--panel) !important; }
.cal-day-head.lg {
  font-size: 11px; font-weight: 620; letter-spacing: .06em; text-transform: uppercase; color: var(--muted);
  border-bottom: 1px solid var(--line);
}
.cal-day-count { font-size: 10.5px; font-weight: 550; color: var(--faint); letter-spacing: .04em; }
.cal-page-list .cal-row.lg { font-size: 13.5px; min-height: 44px; }
.cal-row .cc-num { font-variant-numeric: lining-nums; font-weight: 460; }

/* every page lands at the same 28px below the top bar — no exceptions */
.container.page.mkx { padding-top: 28px; }

/* ==========================================================================
   BORROW (bwx-) — bot-operated lending monitor. Account-v3 hero + gold rows,
   Markets screener. No manual borrow anywhere; the page only tells the truth.
   ========================================================================== */
.bwx-hero {
  display: grid;
  gap: 20px;
  padding: 24px 0 28px; /* NO horizontal padding — hero sits on the page's one left edge, like Markets */
}
.bwx-hero-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 28px;
  min-width: 0;
}
.bwx-hero-title { min-width: 0; }
.bwx-title-row {
  display: flex;
  align-items: center;
  gap: 11px;
  flex-wrap: wrap;
}
.bwx-title-row h1 {
  margin: 0;
  color: var(--text);
  font-size: 40px;
  line-height: 1.05;
  font-weight: 520;
  letter-spacing: -0.018em;
}
.bwx-hero-title p {
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.4;
  font-weight: 430;
}
.bwx-hero-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 28px;
}
.bwx-hero-metric {
  display: grid;
  gap: 3px;
  min-width: 0;
}
.bwx-hero-metric em {
  color: var(--muted);
  font-size: 14px;
  font-style: normal;
  font-weight: 440;
}
.bwx-hero-metric b {
  overflow: hidden;
  color: var(--text);
  font-size: 21px;
  line-height: 1.15;
  font-weight: 620;
  font-variant-numeric: lining-nums;
  text-overflow: ellipsis;
}
.bwx-hero-metric.debt b {
  font-size: 28px;
}
.bwx-hero-metric small {
  overflow: hidden;
  color: var(--faint);
  font-size: 13.5px;
  font-weight: 430;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bwx-card { padding: 20px 24px 14px; margin-bottom: 16px; }
.bwx-count { font-style: normal; font-size: 13px; font-weight: 440; color: var(--muted); margin-left: 8px; }

/* active loan rows — the gold recipe with a debt column and an LTV meter */
.bwx-loanlist { margin-top: 4px; }
.bwx-loan {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) 200px 220px;
  align-items: center;
  column-gap: 14px;
  min-height: 70px;
}
.bwx-loan + .bwx-loan { border-top: 1px solid var(--line); }
.bwx-loan-debt { text-align: right; font-variant-numeric: lining-nums; }
.bwx-loan-ltv { text-align: right; font-variant-numeric: lining-nums; }
.bwx-loan-ltv .acb-cell-main.down { color: var(--down); }
.bwx-loan-ltv .acb-bar { margin-top: 5px; }

/* activity feed — dock rows at page scale */
.bwx-feed { margin-top: 2px; }
.bwx-feed-row { display: flex; align-items: center; gap: 11px; min-height: 40px; }
.bwx-feed-row + .bwx-feed-row { border-top: 1px solid var(--line); }
.bwx-feed-label {
  display: grid;
  gap: 2px;
  min-width: 0;
  font-size: 14px;
  font-weight: 480;
  color: var(--text);
}
.bwx-feed-label b {
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 14px;
  font-weight: 560;
  color: var(--text);
}
.bwx-feed-label em {
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 12px;
  font-style: normal;
  font-weight: 430;
  color: var(--muted);
}
.bwx-feed-time { margin-left: auto; font-family: var(--mono); font-size: 11.5px; font-weight: 450; color: var(--muted); font-variant-numeric: tabular-nums; }

/* screener extras */
.bwx-pills {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 46px;
  margin: 20px 0 0;
  padding: 0 0 24px;
  border-bottom: 1px solid var(--line);
}
.bwx-flagnote { margin-left: auto; font-size: 12.5px; font-weight: 440; color: var(--faint); }
.bwx-table td { height: 64px; }
.bwx-avail { font-size: 14px; font-weight: 430; }
.bwx-avail.ok { color: var(--up); }
.bwx-avail.no { color: var(--down); }
.bwx-avail.dim { color: var(--faint); }

@media (max-width: 900px) {
  .bwx-hero-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 18px; }
  .bwx-loan { grid-template-columns: 40px minmax(0, 1fr) 160px; }
  .bwx-loan-ltv { display: none; }
}


/* Borrow rides the SAME container as Markets (.container 1600 cap + 32px
   gutters) — measured against the real monitor, a narrower cap reads shrunken
   beside the Markets tab. */
.bwx-table {
  table-layout: fixed;
  margin-top: 18px;
}
.bwx-table th.mkx-starcol { width: 44px; }
.bwx-table th:nth-child(2) { width: 33%; }
.bwx-table th:nth-child(3) { width: 17%; }
.bwx-table th:nth-child(4) { width: 15%; }
.bwx-table th:nth-child(5) { width: 19%; }
.bwx-table th:nth-child(6) { width: 12%; }
.bwx-table th.l,
.bwx-table td.l { text-align: left; }
.bwx-table th.r,
.bwx-table td.r { text-align: right; }
.bwx-table .acb-sort {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  max-width: 100%;
}
.bwx-table th.r .acb-sort {
  justify-content: flex-end;
  width: 100%;
}
.bwx-table th {
  height: 38px;
  padding: 0 14px 14px;
  border-top: 0;
  vertical-align: bottom;
}
.bwx-table td {
  height: 64px;
  padding-left: 14px;
  padding-right: 14px;
  text-overflow: ellipsis;
  border-top: 0; /* Coinbase law, same as Markets: rows are BORDERLESS — hover wash only */
}
/* Markets law: first column flush with the page edge, last flush right */
.bwx-table th:first-child,
.bwx-table td:first-child { padding-left: 0; }
.bwx-table th:last-child,
.bwx-table td:last-child { padding-right: 0; }
.bwx-table .acb-asset { height: 64px; }
.bwx-table .acb-cell-main { font-size: 16px; font-weight: 430; }

.bwx-na-note { margin: 4px 0 12px; font-size: 13.5px; font-weight: 440; color: var(--muted); }
.bwx-na { display: flex; flex-wrap: wrap; gap: 8px; padding-bottom: 10px; }
.bwx-na-chip {
  display: inline-flex; align-items: center; gap: 7px;
  height: 32px; padding: 0 12px 0 8px; border: 0; border-radius: 999px;
  background: var(--tile); color: var(--text-2);
  font: inherit; font-size: 12.5px; font-weight: 530; cursor: pointer;
}
.bwx-na-chip:hover { color: var(--text); }

/* ==== ACTIVE LOAN CARD v2 — Binance's ongoing-order stat grid, our voice ==== */
.bwx-loan2 { padding: 0 0 28px; }
.bwx-loan2 + .bwx-loan2 { border-top: 1px solid var(--line); padding-top: 16px; }
.bwx-loan2-head { display: flex; align-items: center; gap: 11px; padding: 0 0 16px; }
.bwx-loan2-head b { font-size: 16px; font-weight: 550; color: var(--text); letter-spacing: -0.006em; }
.bwx-loan2-head em { font-style: normal; font-size: 14px; font-weight: 430; color: var(--muted); }
.bwx-risk {
  margin-left: auto; font-size: 11px; font-weight: 600; letter-spacing: .03em;
  padding: 3px 10px; border-radius: 999px;
}
.bwx-risk.low { background: var(--up-soft, rgba(18,161,80,.12)); color: var(--up); }
.bwx-risk.call { background: rgba(226,137,42,.14); color: #b45309; }
.bwx-risk.liq { background: var(--down-soft, rgba(217,48,37,.12)); color: var(--down); }

.bwx-loan2-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px 28px;
}
.bwx-kv { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.bwx-kv em { font-style: normal; font-size: 14px; font-weight: 440; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bwx-kv b { font-size: 16px; font-weight: 430; color: var(--text); font-variant-numeric: lining-nums; }
.bwx-kv b.up { color: var(--up); }
.bwx-kv b.down { color: var(--down); }
.bwx-kv small { font-size: 13.5px; font-weight: 430; color: var(--faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* the LTV zone meter — green / amber / red with a position marker */
.bwx-meter { position: relative; display: flex; height: 6px; border-radius: 3px; overflow: visible; margin-top: 6px; max-width: 190px; }
.bwx-meter i { display: block; height: 100%; }
.bwx-meter i.z-low { background: var(--up); opacity: .55; border-radius: 3px 0 0 3px; }
.bwx-meter i.z-call { background: #e2892a; opacity: .55; }
.bwx-meter i.z-liq { background: var(--down); opacity: .55; border-radius: 0 3px 3px 0; }
.bwx-meter u {
  position: absolute; top: -3px; width: 3px; height: 12px; border-radius: 2px;
  background: var(--text); transform: translateX(-50%);
}

@media (max-width: 980px) { .bwx-loan2-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }


/* ==== BORROW rebuilt post-Codex — guard tile, console tabs, real actions ====
   One system: acb-tabs for views, bwx-loan2 stat grids for orders, hp/acb
   chrome everywhere. No gold, no parallel design system. */

/* the Borrow Guard — the owner's borrow kill-switch, quiet house tile */
.bwx-guard { display: flex; align-items: center; gap: 14px; padding: 12px 18px; border: 1px solid var(--line-2); border-radius: 12px; background: var(--panel); flex: none; }
.bwx-guard-copy { display: grid; gap: 2px; text-align: right; }
.bwx-guard-copy b { font-size: 13.5px; font-weight: 560; color: var(--text); letter-spacing: -0.004em; }
.bwx-guard-copy em { font-style: normal; font-size: 12px; font-weight: 520; }
.bwx-guard-copy em.blocked { color: var(--down); }
.bwx-guard-copy em.open { color: var(--up); }
.bwx-switch2 { position: relative; width: 42px; height: 25px; flex: none; border: 0; border-radius: 999px; background: var(--line-2); cursor: pointer; padding: 0; }
.bwx-switch2 span { position: absolute; top: 3px; left: 3px; width: 19px; height: 19px; border-radius: 50%; background: #fff; box-shadow: 0 1px 2px rgba(15, 23, 42, 0.25); }
.bwx-switch2.blocked { background: var(--down); }
.bwx-switch2.open { background: var(--up); }
.bwx-switch2.blocked span, .bwx-switch2.open span { left: 20px; }
.bwx-switch2.open span { left: 20px; }
.bwx-switch2:disabled { opacity: 0.5; cursor: default; }

/* console: view tabs + content, plain like the Account activity section */
.bwx-console { margin-top: 0; border-top: 1px solid var(--line); padding-top: 28px; }
.bwx-console .acb-tabs button b { font-weight: inherit; color: var(--muted); margin-left: 2px; }
.bwx-console-body { padding-top: 20px; }

/* risk chip lives beside the LTV value (Binance placement) */
.bwx-kv .bwx-risk { margin-left: 8px; vertical-align: 2px; }

/* asset overview — two quiet cards, Coinbase table voice */
.bwx-over { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin-top: 18px; }
.bwx-over-card { border: 1px solid var(--line-2); border-radius: 12px; padding: 18px 20px 8px; min-width: 0; }
.bwx-over-card h3 { margin: 0; font-size: 14px; font-weight: 440; color: var(--muted); }
.bwx-over-card strong { display: block; margin: 5px 0 14px; font-size: 21px; font-weight: 620; color: var(--text); font-variant-numeric: lining-nums; }
.bwx-over-head, .bwx-over-row { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr) minmax(0, 1fr); gap: 10px; align-items: center; }
.bwx-over-head span { font-size: 14px; font-weight: 440; color: var(--muted); padding-bottom: 9px; border-bottom: 1px solid var(--line); white-space: nowrap; }
.bwx-over-head span:not(:first-child), .bwx-over-row > span:not(:first-child) { text-align: right; }
.bwx-over-row { min-height: 50px; font-size: 16px; font-weight: 430; color: var(--text); font-variant-numeric: lining-nums; }
.bwx-over-asset { display: inline-flex; align-items: center; gap: 10px; min-width: 0; }
.bwx-over-asset b { font-size: 16px; font-weight: 550; color: var(--text); letter-spacing: -0.006em; }
.bwx-over-empty { padding: 16px 0; font-size: 14px; font-weight: 430; color: var(--faint); }

/* borrow market section head + controls */
/* ONE ruled divider separates the loan console from the market screener */
.bwx-market { padding: 20px 24px 16px; }
.bwx-market-head h2 { margin: 0; font-size: 28px; font-weight: 560; letter-spacing: -0.012em; color: var(--text); }
.bwx-market-head h2 em { font-style: normal; margin-left: 10px; font-size: 14px; font-weight: 440; color: var(--muted); }
.bwx-market-controls { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-top: 16px; }
.bwx-market-search { width: 220px; }


@media (max-width: 900px) {
  .bwx-over { grid-template-columns: 1fr; }
  .bwx-market-controls { flex-wrap: wrap; }
}

/* ==== RISK rebuilt (rsx-) — Markets voice, full width, side-by-side ====
   Reuses the shared page-hero recipe (bwx-hero/bwx-guard/bwx-switch2) and
   the five type values. Rows borderless; dividers only between bands. */
.rsx-band { border-top: 1px solid var(--line); padding-top: 28px; }
.rsx-band + .rsx-band { margin-top: 28px; }
.rsx-cols { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 64px; align-items: start; }
.rsx-col { min-width: 0; }
.rsx-col h3 { margin: 26px 0 6px; font-size: 18px; font-weight: 620; letter-spacing: -0.008em; color: var(--text); }
.rsx-col h3:first-child { margin-top: 0; }

.rsx-row { display: flex; align-items: center; gap: 13px; min-height: 60px; padding: 8px 0; }
.rsx-row.dirty .rsx-main b { color: var(--accent-ink, var(--accent)); }
.rsx-ico { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; flex: none; }
.rsx-main { display: grid; gap: 2px; min-width: 0; flex: 1; }
.rsx-main b { font-size: 16px; font-weight: 550; letter-spacing: -0.006em; color: var(--text); }
.rsx-main em { font-style: normal; font-size: 14px; font-weight: 430; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rsx-end { display: inline-flex; align-items: center; gap: 8px; flex: none; }
.rsx-val { font-size: 16px; font-weight: 430; color: var(--text); font-variant-numeric: lining-nums; }
.rsx-unit { font-size: 13.5px; font-weight: 430; color: var(--muted); min-width: 38px; }

.rsx-chips { display: flex; flex-wrap: wrap; gap: 8px; padding: 2px 0 10px 43px; }

.rsx-probe { display: flex; align-items: end; gap: 14px; flex-wrap: wrap; padding: 6px 0 2px; }
.rsx-probe label { display: grid; gap: 6px; }
.rsx-probe label > span { font-size: 14px; font-weight: 440; color: var(--muted); }
.rsx-probe .hp-input { width: 150px; }
.rsx-probe-go { display: flex; align-items: end; }
.rsx-quick { display: flex; gap: 8px; padding: 8px 0; }
.rsx-alert { margin: 8px 0; font-size: 14px; font-weight: 450; color: var(--down); }
.rsx-empty { padding: 18px 0; font-size: 14px; font-weight: 430; color: var(--faint); }

.rsx-table { width: 100%; border-collapse: collapse; table-layout: fixed; margin-top: 6px; }
.rsx-table th { padding: 8px 10px 10px 0; text-align: left; font-size: 14px; font-weight: 440; color: var(--muted); white-space: nowrap; }
.rsx-table td { height: 46px; padding: 0 10px 0 0; font-size: 15px; font-weight: 430; color: var(--text); font-variant-numeric: lining-nums; white-space: nowrap; overflow: hidden; text-overflow: clip; vertical-align: middle; }
.rsx-table td .txt, .rsx-table td.dim { overflow: hidden; text-overflow: ellipsis; }
.rsx-table td.strong { font-weight: 550; letter-spacing: -0.006em; }
.rsx-table td.dim { color: var(--muted); }

@media (max-width: 1100px) {
  .rsx-cols { grid-template-columns: 1fr; }
}

/* ==== HEALTH rebuilt (hlx-) — shares the rsx- control-page recipe ==== */
.hlx-page {
  --hlx-blue: #2563eb;
  font-family: var(--ref-ui-font, -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", Roboto, Helvetica, Arial, sans-serif);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}
.hlx-word.ok { color: var(--up); }
.hlx-word.warn { color: #b45309; }
.hlx-word.bad { color: var(--down); }
.hlx-console {
  display: grid;
  gap: 12px;
  margin: 4px 0 14px;
  padding: 16px;
  border: 1px solid var(--line-2);
  border-radius: 14px;
  background: var(--panel);
  box-shadow: var(--shadow-sm);
}
[data-theme="dark"] .hlx-console { box-shadow: none; }
.hlx-console-head {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  min-height: 70px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--hlx-blue) 22%, var(--line-2));
  border-radius: 13px;
  background:
    radial-gradient(circle at 15% 0%, color-mix(in srgb, var(--hlx-blue) 10%, transparent), transparent 48%),
    linear-gradient(180deg, var(--panel), color-mix(in srgb, var(--hlx-blue) 4%, var(--tile)));
}
.hlx-console-mark {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border: 1px solid color-mix(in srgb, var(--hlx-blue) 22%, var(--line-2));
  border-radius: 50%;
  background: color-mix(in srgb, var(--hlx-blue) 6%, var(--panel));
  color: var(--hlx-blue);
}
.hlx-console-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.hlx-console-copy b {
  overflow: hidden;
  color: color-mix(in srgb, var(--hlx-blue) 78%, var(--text));
  font-size: 11px;
  font-weight: 660;
  letter-spacing: .16em;
  line-height: 14px;
  text-transform: uppercase;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hlx-console-copy h1 {
  margin: 0;
  color: var(--text-2);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0;
  line-height: 17px;
}
.hlx-console-copy em {
  overflow: hidden;
  color: var(--muted);
  font-size: 12px;
  font-style: normal;
  font-weight: 430;
  line-height: 16px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hlx-console-pill,
.hlx-chip {
  display: inline-grid;
  place-items: center;
  height: 23px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 720;
  letter-spacing: .06em;
  line-height: 23px;
  text-transform: uppercase;
}
.hlx-console-pill.ok,
.hlx-chip.ok { background: color-mix(in srgb, var(--up) 12%, transparent); color: var(--up); }
.hlx-console-pill.warn,
.hlx-chip.warn { background: color-mix(in srgb, #d67d1c 12%, transparent); color: #b45309; }
.hlx-console-pill.bad,
.hlx-chip.bad { background: color-mix(in srgb, var(--down) 12%, transparent); color: var(--down); }
.hlx-console-pill.idle,
.hlx-chip.idle { background: var(--tile); color: var(--muted); }
.hlx-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  border: 1px solid var(--line-2);
  border-radius: 12px;
  background: color-mix(in srgb, var(--panel) 92%, var(--tile));
  overflow: hidden;
}
.hlx-summary > div {
  display: grid;
  gap: 3px;
  min-height: 76px;
  padding: 13px 16px;
  border-right: 1px solid var(--line);
}
.hlx-summary > div:last-child { border-right: 0; }
.hlx-summary em {
  color: var(--muted);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 650;
  letter-spacing: .08em;
  line-height: 13px;
  text-transform: uppercase;
}
.hlx-summary b {
  overflow: hidden;
  color: var(--text);
  font-size: 15px;
  font-weight: 520;
  letter-spacing: 0;
  line-height: 19px;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-variant-numeric: lining-nums;
}
.hlx-summary small {
  overflow: hidden;
  color: var(--muted);
  font-size: 12px;
  font-weight: 430;
  line-height: 16px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hlx-alert {
  margin: 0 0 12px;
  padding: 10px 13px;
  border: 1px solid color-mix(in srgb, var(--down) 22%, var(--line-2));
  border-radius: 10px;
  background: color-mix(in srgb, var(--down) 5%, var(--panel));
  color: var(--down);
  font-size: 12.5px;
  font-weight: 500;
}
.hlx-card-grid {
  display: grid;
  grid-template-columns: minmax(360px, .92fr) minmax(420px, 1.08fr);
  gap: 14px;
  align-items: start;
}
.hlx-card,
.hlx-evidence {
  border: 1px solid var(--line-2);
  border-radius: 14px;
  background: var(--panel);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}
[data-theme="dark"] .hlx-card,
[data-theme="dark"] .hlx-evidence { box-shadow: none; }
.hlx-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 45px;
  padding: 0 15px;
  border-bottom: 1px solid var(--line);
}
.hlx-card-head span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: .13em;
  line-height: 14px;
  text-transform: uppercase;
}
.hlx-status-list {
  display: grid;
  align-content: start;
}
.hlx-status-row {
  display: grid;
  grid-template-columns: 14px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  min-height: 42px;
  padding: 0 15px;
  border-bottom: 1px solid var(--line);
  background: transparent;
}
.hlx-status-row:last-child { border-bottom: 0; }
.hlx-status-row:hover { background: color-mix(in srgb, var(--hlx-blue) 3.5%, transparent); }
.hlx-status-mark {
  display: grid;
  place-items: center;
  color: var(--muted);
}
.hlx-status-mark .hp-dot {
  width: 7px;
  height: 7px;
}
.hlx-status-row.healthy .hlx-status-mark { color: var(--up); }
.hlx-status-row.degraded .hlx-status-mark { color: #d67d1c; }
.hlx-status-row.broken .hlx-status-mark { color: var(--down); }
.hlx-status-copy {
  display: grid;
  gap: 1px;
  min-width: 0;
}
.hlx-status-copy b {
  overflow: hidden;
  color: var(--text-2);
  font-size: 12.5px;
  font-weight: 510;
  letter-spacing: 0;
  line-height: 17px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hlx-status-copy em {
  overflow: hidden;
  color: var(--muted);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 430;
  letter-spacing: 0;
  line-height: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hlx-status-value {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  min-width: 70px;
  color: color-mix(in srgb, var(--up) 76%, var(--text));
  font-family: var(--ref-mono-font, "SF Mono", ui-monospace, Menlo, Consolas, monospace);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0;
  line-height: 16px;
  text-align: right;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.hlx-status-row.degraded .hlx-status-value { color: #d67d1c; }
.hlx-status-row.broken .hlx-status-value { color: var(--down); }
.hlx-status-row.not_configured .hlx-status-value { color: var(--muted); }
.hlx-status-value .hp-pill {
  height: 22px;
  font-family: var(--ref-ui-font, var(--font));
  font-size: 10px;
  font-weight: 650;
  line-height: 22px;
}
.hlx-links {
  display: flex;
  gap: 18px;
  padding: 12px 15px 14px 38px;
  border-top: 1px solid var(--line);
}
.hlx-links a { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 500; color: var(--text-2); text-decoration: none; }
.hlx-links a:hover { color: var(--text); }
.hlx-evidence {
  margin-top: 14px;
  padding: 14px 16px 12px;
}
.hlx-matrix-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding-bottom: 11px; border-bottom: 1px solid var(--line); }
.hlx-matrix-head h3 { margin: 0; font-size: 13px; font-weight: 560; letter-spacing: 0; color: var(--text); }
.hlx-matrix-head p { margin: 2px 0 0; font-size: 12px; font-weight: 430; color: var(--muted); }
.hlx-state { display: inline-flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 500; }
.hlx-table { margin-top: 0; }
.hlx-table td.dim { white-space: nowrap; }
.hlx-page .hlx-table th {
  height: 36px;
  padding: 0 10px 0 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: .08em;
  line-height: 14px;
  text-transform: uppercase;
}
.hlx-page .hlx-table td {
  height: 42px;
  padding: 0 10px 0 0;
  color: var(--text-2);
  font-size: 12.5px;
  font-weight: 430;
  line-height: 16px;
}
.hlx-page .hlx-table td.strong {
  color: var(--text);
  font-size: 12.5px;
  font-weight: 510;
}
.hlx-page .hlx-table td .hp-dot {
  width: 7px;
  height: 7px;
}

@media (max-width: 1100px) {
  .hlx-card-grid { grid-template-columns: 1fr; }
  .hlx-summary { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .hlx-summary > div:nth-child(2) { border-right: 0; }
  .hlx-summary > div:nth-child(-n + 2) { border-bottom: 1px solid var(--line); }
}

@media (max-width: 720px) {
  .hlx-console-head { grid-template-columns: 44px minmax(0, 1fr); }
  .hlx-console-pill { grid-column: 2; justify-self: start; }
  .hlx-summary { grid-template-columns: 1fr; }
  .hlx-summary > div { border-right: 0; border-bottom: 1px solid var(--line); }
  .hlx-summary > div:last-child { border-bottom: 0; }
}

/* ==== TOKEN PAGE (tdx-) — the Coinbase asset-page template, hairline grid ==== */
.tdx-head { display: flex; align-items: center; gap: 14px; padding: 20px 28px; border: 1px solid var(--line); border-bottom: 0; }
.tdx-head h1 { margin: 0; font-size: 28px; font-weight: 500; letter-spacing: -0.01em; color: var(--text); }
.tdx-head-right { margin-left: auto; }

.tdx-grid { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); border: 1px solid var(--line); }
.tdx-cell { border-left: 1px solid var(--line); border-top: 1px solid var(--line); padding: 26px 28px 28px; min-width: 0; }
.tdx-chartcell { grid-column: 1 / -1; border-left: 0; border-top: 0; }
.tdx-third { grid-column: span 2; }
.tdx-grid > section.tdx-third:nth-of-type(3n + 2) { border-left: 0; }
.tdx-cell h3 .tdx-src { font-style: normal; margin-left: 8px; font-size: 12.5px; font-weight: 440; color: var(--faint); letter-spacing: 0; }
.tdx-headlink { text-decoration: none; }
.tdx-cell h3 { margin: 0 0 16px; font-size: 17px; font-weight: 560; letter-spacing: -0.006em; color: var(--text); }

.tdx-links { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 18px; }
.tdx-links a { text-decoration: none; }
.tdx-happening { display: grid; gap: 8px; padding: 16px 18px; border-radius: 14px; background: color-mix(in srgb, var(--accent) 7%, transparent); }
.tdx-happening em { font-style: normal; font-size: 13px; font-weight: 560; color: var(--text); }
.tdx-happening em i { font-style: normal; font-weight: 430; color: var(--muted); }
.tdx-happening b { font-size: 14.5px; font-weight: 470; line-height: 1.45; color: var(--text); }
.tdx-happening b.dim { color: var(--muted); font-weight: 430; }
.tdx-seemore { justify-self: start; height: 32px; padding: 0 14px; border: 0; border-radius: 16px; background: var(--panel); color: var(--text); font: inherit; font-size: 13px; font-weight: 520; cursor: pointer; }

.tdx-price-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; flex-wrap: wrap; margin-bottom: 10px; }
.tdx-price b { display: block; font-size: 40px; font-weight: 430; letter-spacing: -0.014em; color: var(--text); font-variant-numeric: lining-nums; }
.tdx-delta { display: inline-block; margin-top: 4px; font-size: 16px; font-weight: 440; }
.tdx-chg { display: inline-flex; align-items: center; gap: 3px; font-variant-numeric: lining-nums; }
.tdx-chg.up { color: var(--up); }
.tdx-chg.down { color: var(--down); }
.tdx-chg.flat { color: var(--muted); }
.tdx-ranges { display: inline-flex; align-items: center; gap: 4px; }
.tdx-ranges button { height: 34px; min-width: 42px; padding: 0 12px; border: 0; border-radius: 17px; background: none; color: var(--text-2); font: inherit; font-size: 13.5px; font-weight: 440; cursor: pointer; }
.tdx-ranges button:hover { background: var(--tile); }
.tdx-ranges button.on { background: color-mix(in srgb, var(--up) 12%, transparent); color: var(--up); font-weight: 500; }
.tdx-ranges .tdx-tv { margin-left: 10px; padding: 0 14px; background: var(--tile); }
.tdx-ranges .tdx-tv.on { background: var(--accent); color: #fff; }
.tdx-chart { display: block; width: 100%; height: auto; }
.tdx-axis { font-size: 12.5px; font-weight: 430; fill: var(--muted); font-variant-numeric: lining-nums; }
.tdx-chart-empty { display: grid; place-items: center; height: 320px; font-size: 14px; color: var(--faint); }

.tdx-insights { display: flex; gap: 26px; align-items: flex-start; }
.tdx-donutwrap { display: grid; gap: 8px; justify-items: center; flex: none; }
.tdx-donutwrap em { font-style: normal; font-size: 13.5px; font-weight: 440; color: var(--muted); }
.tdx-donut-num { font-size: 15px; font-weight: 560; fill: var(--text); }
.tdx-inslist { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px 22px; flex: 1; min-width: 0; }
.tdx-statgrid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px 24px; }
.tdx-stat { display: grid; gap: 3px; min-width: 0; }
.tdx-stat em { font-style: normal; font-size: 13.5px; font-weight: 440; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tdx-stat b { font-size: 16px; font-weight: 440; color: var(--text); font-variant-numeric: lining-nums; }
.tdx-stat small { font-size: 12.5px; font-weight: 430; color: var(--faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tdx-dimnote { margin: 4px 0 0; font-size: 14px; font-weight: 430; color: var(--faint); }

.tdx-tags-label { display: block; margin: 18px 0 8px; font-style: normal; font-size: 13.5px; font-weight: 440; color: var(--muted); }
.tdx-tags { display: flex; flex-wrap: wrap; gap: 7px; }
.tdx-tag { padding: 5px 11px; border-radius: 999px; background: var(--tile); font-size: 12.5px; font-weight: 470; color: var(--text-2); }

.tdx-net-head, .tdx-net-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.tdx-net-head { padding-bottom: 9px; border-bottom: 1px solid var(--line); font-size: 13.5px; font-weight: 440; color: var(--muted); }
.tdx-net-row { min-height: 44px; font-size: 14.5px; font-weight: 450; color: var(--text); }
.tdx-addr { display: inline-flex; align-items: center; gap: 8px; }
.tdx-addr i { font-style: normal; font-family: var(--mono); font-size: 13px; color: var(--text-2); }
.tdx-addr button { width: 26px; height: 26px; border: 0; border-radius: 7px; background: none; color: var(--muted); font-size: 13px; cursor: pointer; }
.tdx-addr button:hover { background: var(--tile); color: var(--text); }
.tdx-seeall { margin-top: 10px; }

.tdx-hist-head, .tdx-hist-row { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 14px; align-items: center; }
.tdx-hist-head { padding-bottom: 9px; border-bottom: 1px solid var(--line); font-size: 13.5px; font-weight: 440; color: var(--muted); }
.tdx-hist-head span:not(:first-child) { text-align: right; }
.tdx-hist-row { min-height: 44px; font-size: 14.5px; font-weight: 430; color: var(--text); }
.tdx-hist-row .val { font-variant-numeric: lining-nums; }
.tdx-hist-row .chg { text-align: right; }

.tdx-ins-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.tdx-ins-head span { font-size: 13px; font-weight: 430; color: var(--muted); }
.tdx-newsrow { display: block; padding: 12px 0; text-decoration: none; border-bottom: 1px solid var(--line); }
.tdx-newsrow:last-of-type { border-bottom: 0; }
.tdx-newsrow b { display: block; font-size: 15px; font-weight: 550; letter-spacing: -0.004em; color: var(--text); line-height: 1.4; }
.tdx-newsrow em { font-style: normal; font-size: 12.5px; font-weight: 430; color: var(--muted); }
.tdx-newsrow:hover b { color: var(--accent-ink, var(--accent)); }
.tdx-trends { margin: 0; font-size: 15px; font-weight: 430; line-height: 1.6; color: var(--text-2); }
.tdx-updated { margin: 12px 0 0; font-size: 12.5px; font-weight: 430; color: var(--faint); }

@media (max-width: 1240px) {
  .tdx-grid { grid-template-columns: 1fr; }
  .tdx-chartcell, .tdx-third { grid-column: 1; grid-row: auto; }
  .tdx-cell { border-left: 0; }
}

/* tdx precision pass: controls cluster, chart-type toggle, stat chg sizing */
.tdx-controls { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; justify-content: flex-end; }
.tdx-kind { display: inline-flex; gap: 2px; padding: 3px; border-radius: 17px; background: var(--tile); }
.tdx-kind button { display: grid; place-items: center; width: 36px; height: 28px; border: 0; border-radius: 14px; background: none; color: var(--muted); cursor: pointer; }
.tdx-kind button.on { background: var(--panel); color: var(--text); box-shadow: 0 1px 2px rgba(15, 23, 42, 0.12); }
.tdx-stat b .tdx-chg { font-size: 13.5px; font-weight: 510; margin-left: 6px; vertical-align: 1px; }
.tdx-hist-row .chg .tdx-chg { font-size: 13.5px; font-weight: 510; }
.tdx-controls .mkx-pill { height: 34px; }

/* tdx search — the Markets search bar, docked in the token header */
.tdx-head-right { display: inline-flex; align-items: center; gap: 12px; margin-left: auto; }
.tdx-searchwrap { position: relative; }
.tdx-search { width: 300px; }
.tdx-search-menu { position: absolute; top: calc(100% + 8px); right: 0; z-index: 40; min-width: 340px; padding: 6px; border: 1px solid var(--line-2); border-radius: 14px; background: var(--panel); box-shadow: 0 16px 48px rgba(15, 23, 42, 0.16); }
.tdx-search-menu button { display: flex; align-items: center; gap: 11px; width: 100%; height: 44px; padding: 0 10px; border: 0; border-radius: 9px; background: none; font: inherit; cursor: pointer; text-align: left; }
.tdx-search-menu button:hover { background: var(--hover); }
.tdx-search-menu b { font-size: 14.5px; font-weight: 550; color: var(--text); }
.tdx-search-menu em { font-style: normal; font-size: 13px; font-weight: 430; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; }
.tdx-search-menu span { font-size: 14px; font-weight: 430; color: var(--text); font-variant-numeric: lining-nums; }

/* ==== ACCOUNT DETAILS — Coinbase profile skeleton + real links/devices ==== */
.acd-shell {
  display: grid;
  grid-template-columns: 390px minmax(0, 1fr);
  gap: 24px;
  align-items: stretch;
  margin-bottom: 24px;
}
.acd-profile-card,
.acd-panel {
  background: var(--panel);
  border: 1px solid var(--line-2);
  border-radius: 14px;
  box-shadow: var(--shadow-sm);
}
.acd-profile-card { overflow: hidden; }
.acd-person {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 24px 22px 22px;
  border-bottom: 1px solid var(--line);
}
.acd-avatar {
  display: inline-grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  font-size: 20px;
  font-weight: 600;
  box-shadow: inset 0 0 0 2px #fff, 0 0 0 2px var(--accent);
  overflow: hidden;
  flex: none;
}
.acd-avatar img { width: 100%; height: 100%; object-fit: cover; }
.acd-person-copy { display: grid; gap: 3px; min-width: 0; }
.acd-person-copy b { color: var(--text); font-size: 18px; line-height: 1.1; font-weight: 650; }
.acd-person-copy em {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.25;
  font-style: normal;
  font-weight: 430;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.acd-person-copy a {
  color: var(--accent-ink);
  font-size: 14px;
  font-weight: 580;
  text-decoration: none;
}
[data-theme="dark"] .acd-person-copy a { color: var(--accent); }
.acd-menu-list { display: grid; padding: 4px 0; }
.acd-menu-row {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  min-height: 74px;
  padding: 0 24px;
  border: 0;
  border-top: 1px solid var(--line);
  background: transparent;
  color: var(--text);
  font: inherit;
  text-align: left;
  text-decoration: none;
}
.acd-menu-row:first-child { border-top: 0; }
.acd-menu-row:hover:not(:disabled) { background: var(--hover); }
.acd-menu-row svg { color: var(--text); justify-self: center; }
.acd-menu-row span { display: grid; gap: 3px; min-width: 0; }
.acd-menu-row b { color: var(--text); font-size: 16px; line-height: 1.15; font-weight: 620; }
.acd-menu-row em { color: var(--muted); font-size: 12.5px; line-height: 1.25; font-style: normal; font-weight: 450; }
.acd-menu-row.danger,
.acd-menu-row.danger svg,
.acd-menu-row.danger b { color: var(--down); }
.acd-menu-row:disabled { cursor: not-allowed; opacity: .72; }
.acd-toggle-row { cursor: pointer; }
.acd-switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  width: 56px;
  height: 32px;
  padding: 3px;
  border-radius: 999px;
  background: #cfd4df;
  justify-self: end;
  transition: background .16s ease;
}
.acd-switch u {
  display: block;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--panel);
  box-shadow: 0 2px 5px rgba(15, 23, 42, .18);
  transform: translateX(0);
  transition: transform .16s ease;
}
.acd-switch.on { background: var(--accent); }
.acd-switch.on u { transform: translateX(24px); }
.acd-main { display: grid; grid-template-rows: auto 1fr; gap: 16px; min-width: 0; }
.acd-titlebar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  min-width: 0;
  padding: 6px 2px 2px;
}
.acd-titlebar span {
  display: block;
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.acd-titlebar h1 {
  margin: 6px 0 0;
  color: var(--text);
  font-size: 34px;
  line-height: 1.08;
  font-weight: 600;
  letter-spacing: 0;
}
.acd-titlebar p {
  max-width: 740px;
  margin: 10px 0 0;
  color: var(--text-2);
  font-size: 15px;
  line-height: 1.45;
  font-weight: 430;
}
.acd-posture {
  display: grid;
  grid-template-columns: auto auto;
  grid-template-areas: "dot icon" "main main" "sub sub";
  justify-items: end;
  gap: 4px 8px;
  min-width: 170px;
  color: var(--muted);
}
.acd-posture-dot {
  grid-area: dot;
  width: 8px;
  height: 8px;
  margin-top: 5px;
  border-radius: 50%;
  background: var(--faint);
}
.acd-posture-dot.ok { background: var(--up); }
.acd-posture-dot.bad { background: var(--down); }
.acd-posture-dot.idle { background: var(--faint); }
.acd-posture svg { grid-area: icon; color: var(--accent-ink); }
[data-theme="dark"] .acd-posture svg { color: var(--accent); }
.acd-posture b { grid-area: main; color: var(--text); font-size: 14px; font-weight: 620; white-space: nowrap; }
.acd-posture em { grid-area: sub; color: var(--muted); font-size: 12px; font-style: normal; font-weight: 450; white-space: nowrap; }
.acd-panels {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(360px, .82fr);
  gap: 16px;
  align-items: stretch;
}
.acd-panel { min-width: 0; padding: 18px 20px 16px; }
.acd-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}
.acd-panel-head > span:first-child {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--text);
  font-size: 17px;
  font-weight: 650;
}
.acd-panel-head svg { color: var(--accent-ink); }
[data-theme="dark"] .acd-panel-head svg { color: var(--accent); }
.acd-exchange-list,
.acd-device-list { display: grid; }
.acd-exchange-row,
.acd-device-row {
  display: grid;
  align-items: center;
  gap: 14px;
  min-height: 82px;
  padding: 14px 0;
  border-top: 1px solid var(--line);
}
.acd-exchange-row:first-child,
.acd-device-row:first-child { border-top: 0; }
.acd-exchange-row { grid-template-columns: 42px minmax(0, 1fr) minmax(230px, auto); }
.acd-ex-badge {
  display: inline-grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: var(--tile);
  color: var(--text);
  font-size: 15px;
  font-weight: 700;
}
.acd-ex-badge.live { background: var(--up-soft); color: var(--up); }
.acd-ex-badge.planned { background: var(--tile); color: var(--faint); }
.acd-ex-main,
.acd-device-main { display: grid; gap: 3px; min-width: 0; }
.acd-ex-main b,
.acd-device-main b {
  color: var(--text);
  font-size: 15px;
  line-height: 1.2;
  font-weight: 620;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.acd-ex-main em,
.acd-device-main em {
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.3;
  font-style: normal;
  font-weight: 450;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.acd-ex-main small {
  color: var(--faint);
  font-size: 12px;
  line-height: 1.35;
  font-weight: 430;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.acd-ex-perms { display: flex; justify-content: flex-end; gap: 6px; flex-wrap: wrap; }
.acd-ex-perms i {
  display: inline-flex;
  align-items: center;
  height: 24px;
  padding: 0 9px;
  border-radius: 999px;
  background: var(--tile);
  color: var(--muted);
  font-style: normal;
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
}
.acd-ex-perms i.ok { background: var(--up-soft); color: var(--up); }
.acd-ex-perms i.warn { background: color-mix(in srgb, #e2892a 14%, transparent); color: #b45309; }
.acd-ex-perms i.bad { background: var(--down-soft); color: var(--down); }
.acd-device-row { grid-template-columns: 12px minmax(0, 1fr) auto; }
.acd-device-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--faint); }
.acd-device-dot.on { background: var(--up); }
.acd-device-right { display: grid; justify-items: end; gap: 3px; min-width: 90px; }
.acd-device-right i {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 8px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent-ink);
  font-style: normal;
  font-size: 10.5px;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: .03em;
}
[data-theme="dark"] .acd-device-right i { color: var(--accent); }
.acd-device-right b { color: var(--muted); font-size: 12px; font-weight: 520; white-space: nowrap; }
.acd-device-note {
  margin: 4px 0 0;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  color: var(--faint);
  font-size: 12px;
  line-height: 1.4;
  font-weight: 430;
}
.acd-empty { padding: 28px 0; color: var(--muted); font-size: 14px; text-align: center; }

@media (max-width: 1180px) {
  .acd-shell,
  .acd-panels { grid-template-columns: 1fr; }
  .acd-titlebar { flex-direction: column; }
  .acd-posture { justify-items: start; }
}
@media (max-width: 720px) {
  .acd-person,
  .acd-menu-row { padding-left: 18px; padding-right: 18px; }
  .acd-titlebar h1 { font-size: 28px; }
  .acd-exchange-row { grid-template-columns: 42px minmax(0, 1fr); }
  .acd-ex-perms { grid-column: 1 / -1; justify-content: flex-start; }
}

/* ==== Coinbase skeleton account popover ================================== */
.acct-pop.cb-acct-pop {
  width: 416px !important;
  min-width: 416px !important;
  padding: 0 !important;
  overflow-y: auto;
  overflow-x: hidden;
  max-height: calc((100vh / var(--uiz, 1)) - 72px);
  border-radius: 14px !important;
  border: 1px solid var(--line-2) !important;
  background: var(--panel) !important;
}
.cb-acct-head {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 24px;
  border-bottom: 1px solid var(--line);
}
.cb-acct-avatar {
  position: relative;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid var(--accent);
