}
.cb-acct-avatar img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; display: block; }
.cb-acct-id { min-width: 0; display: grid; justify-items: start; gap: 3px; }
.cb-acct-name {
  border: 0;
  background: transparent;
  color: var(--text);
  padding: 0;
  font: inherit;
  font-size: 17px;
  font-weight: 650;
  line-height: 1.15;
  letter-spacing: 0;
