  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cb-acct-sub {
  color: var(--muted);
  font-size: 13.5px;
  line-height: 1.25;
  font-weight: 430;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cb-acct-manage {
