}
.cb-link-head span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--text);
  font-size: 13.5px;
  font-weight: 650;
}
.cb-link-head b {
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 620;
}
.cb-link-list { display: grid; }
.cb-exchange-row,
.cb-device-row {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 54px;
