}
.cb-exchange-main em,
.cb-device-main em {
  color: var(--muted);
  font-style: normal;
  font-size: 11.5px;
  font-weight: 430;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cb-status {
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
}
.cb-status.ok { color: var(--up); }
.cb-status.warn { color: #b45309; }
.cb-device-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--line-strong);
  justify-self: center;
}
.cb-device-dot.on { background: var(--up); }
.cb-device-right {
  min-width: 74px;
  display: grid;
  justify-items: end;
