/* tdx base cards: money flow, open interest, basis + reserved row */
.tdx-cardhead { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 8px; }
.tdx-cardhead h3 { margin: 0; cursor: help; }
.tdx-flow-donutwrap { display: grid; place-items: center; }
.tdx-flow-donut { width: 100%; max-width: 300px; height: auto; }
.tdx-flow-pct { font-size: 12.5px; font-weight: 470; fill: var(--text); font-variant-numeric: lining-nums; }
.tdx-flow-table { margin-top: 10px; }
.tdx-flow-row { display: grid; grid-template-columns: minmax(0, 0.9fr) 1fr 1fr 0.9fr; gap: 10px; align-items: center; min-height: 32px; font-size: 13.5px; font-weight: 430; color: var(--text); font-variant-numeric: lining-nums; border-radius: 7px; }
.tdx-flow-row.hot { background: var(--hover); }
.tdx-flow-row.head { font-size: 13.5px; font-weight: 440; color: var(--muted); border-bottom: 1px solid var(--line); padding-bottom: 6px; }
.tdx-flow-row span:not(:first-child) { text-align: right; display: inline-flex; align-items: center; justify-content: flex-end; gap: 7px; }
.tdx-flow-row i { display: inline-block; width: 9px; height: 9px; border-radius: 2.5px; flex: none; }
.tdx-flow-row.total { font-weight: 510; }
.tdx-datachart { display: block; width: 100%; height: auto; }
.tdx-legend { display: flex; flex-wrap: wrap; gap: 16px; justify-content: center; margin-top: 8px; font-size: 12.5px; font-weight: 440; color: var(--muted); }
.tdx-legend span { display: inline-flex; align-items: center; gap: 6px; }
.tdx-legend .sw { display: inline-block; width: 10px; height: 10px; border-radius: 2px; }
.tdx-legend .dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--panel); border: 1.5px solid var(--text); }
.tdx-chart-empty.small { height: 200px; }
.tdx-reserved { grid-column: 1 / -1; min-height: 150px; border-left: 0; }

/* tvx tool rail (TradingView mode only) + chart source seg */
.tv-chart-wrap { position: relative; }
.tvx-rail { position: absolute; top: 10px; left: 10px; z-index: 5; display: inline-flex; align-items: center; gap: 2px; padding: 3px; border-radius: 10px; background: var(--panel); border: 1px solid var(--line-2); box-shadow: 0 2px 10px rgba(15, 23, 42, 0.08); }
.tvx-rail button { min-width: 30px; height: 26px; padding: 0 8px; border: 0; border-radius: 7px; background: none; color: var(--muted); font: inherit; font-size: 12.5px; font-weight: 520; cursor: pointer; }
.tvx-rail button:hover { background: var(--tile); color: var(--text); }
.tvx-rail button.on { background: var(--tile); color: var(--accent-ink, var(--accent)); }
.tvx-sep { width: 1px; height: 16px; background: var(--line-2); margin: 0 3px; }
.tdx-srcseg button { width: auto; padding: 0 12px; font-size: 13px; font-weight: 460; }
.tdx-ranges button:disabled { opacity: 0.35; cursor: default; }


/* interactive chart hover: wrapper + Binance-style opaque tooltip */
.tdx-flow-donutwrap { position: relative; }
.tdx-chartwrap { position: relative; }
.tdx-tip { position: absolute; top: 12px; z-index: 30; display: grid; gap: 4px; padding: 10px 13px; border-radius: 10px; background: var(--panel); border: 1px solid var(--line-2); box-shadow: 0 8px 28px rgba(15, 23, 42, 0.16); pointer-events: none; white-space: nowrap; }
.tdx-tip b { font-size: 12.5px; font-weight: 560; color: var(--text); }
.tdx-tip span { display: inline-flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 440; color: var(--muted); }
.tdx-tip span em { font-style: normal; font-weight: 550; color: var(--text); font-variant-numeric: lining-nums; }
.tdx-tip span i { display: inline-block; width: 8px; height: 8px; border-radius: 2.5px; flex: none; }

/* cgx — the Coinglass panel (bottom row of the token page) */
.tdx-cgx { grid-column: 1 / -1; border-left: 0; }
.cgx-tabs { display: inline-flex; gap: 4px; }
.cgx-tabs button { height: 34px; padding: 0 16px; border: 0; border-radius: 17px; background: none; color: var(--text-2); font: inherit; font-size: 13.5px; font-weight: 460; cursor: pointer; }
.cgx-tabs button:hover { background: var(--tile); }
.cgx-tabs button.on { background: var(--accent); color: #fff; font-weight: 510; }
.cgx-title { margin: 2px 0 14px; }
.cgx-note { color: var(--faint); }
.tdx-cgx-empty {
  display: grid;
  place-items: center;
  min-height: clamp(620px, 28vw, 860px);
  border-top: 1px solid var(--line);
}
.tdx-cgx-empty .tdx-dimnote {
  max-width: 620px;
  margin: 0;
  text-align: center;
}
.tdx-cgx-empty .tdx-chart-empty.small {
  height: auto;
}

/* ==== BASIS SCANNER (bsx-) — Markets voice, blueprint columns ==== */
.bsx-hero { padding-top: 24px; }
.bsx-props-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 6px; }
.bsx-props-head h2 { margin: 0; font-size: 22px; font-weight: 560; letter-spacing: -0.01em; color: var(--text); }
.bsx-props-head h2 em { font-style: normal; margin-left: 10px; font-size: 14px; font-weight: 440; color: var(--muted); }
.bsx-props { display: grid; grid-template-columns: repeat(auto-fill, minmax(360px, 1fr)); gap: 12px; margin-top: 10px; }
.bsx-prop { display: flex; align-items: center; gap: 13px; padding: 14px 16px; border: 1px solid var(--line-2); border-radius: 12px; background: var(--panel); font: inherit; text-align: left; cursor: pointer; min-width: 0; }
.bsx-prop:hover { border-color: var(--line); box-shadow: var(--shadow-sm); }
.bsx-prop-main { display: grid; gap: 3px; min-width: 0; flex: 1; }
.bsx-prop-main b { display: inline-flex; align-items: center; gap: 8px; font-size: 16px; font-weight: 550; letter-spacing: -0.006em; color: var(--text); }
.bsx-prop-main em { font-style: normal; font-size: 13.5px; font-weight: 430; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bsx-prop-edge { display: grid; gap: 2px; text-align: right; flex: none; font-size: 17px; font-weight: 470; font-variant-numeric: lining-nums; }
.bsx-prop-edge small { font-size: 12px; font-weight: 440; color: var(--muted); }
.bsx-prop-edge.up { color: var(--up); }
.bsx-prop-edge.down { color: var(--down); }

.bsx-table { table-layout: fixed; margin-top: 14px; }
.bsx-table th:first-child { width: 19%; }
.bsx-table td { height: 66px; padding: 0 10px; border-top: 0; }
.bsx-table th:last-child, .bsx-table td:last-child { padding-right: 0; }
.bsx-table th:first-child, .bsx-table td:first-child { padding-left: 0; }
.bsx-cell-sub { display: block; font-size: 12.5px; font-weight: 430; color: var(--faint); font-variant-numeric: lining-nums; }
.bsx-table .acb-asset { height: 66px; }

.bsx-fund-cols { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }
.bsx-fund-label { display: block; font-style: normal; font-size: 14px; font-weight: 440; color: var(--muted); padding-bottom: 8px; border-bottom: 1px solid var(--line); margin-bottom: 4px; }
.bsx-fund-row { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 44px; padding: 0 2px; border: 0; background: none; font: inherit; cursor: pointer; text-align: left; border-radius: 8px; }
.bsx-fund-row:hover { background: var(--hover); }
.bsx-fund-row b { font-size: 14.5px; font-weight: 550; color: var(--text); flex: 1; }
.bsx-fund-row span { font-size: 14.5px; font-weight: 440; font-variant-numeric: lining-nums; }
.bsx-fund-row span.up { color: var(--up); }
.bsx-fund-row span.down { color: var(--down); }

/* ==== VOLUME SCANNER (vsx-) — honest spec surface ==== */
.vsx-surface { display: grid; grid-template-columns: repeat(auto-fill, minmax(330px, 1fr)); gap: 12px; margin: 14px 0 16px; }
.vsx-field { display: grid; gap: 5px; padding: 16px 18px; border: 1px solid var(--line-2); border-radius: 12px; background: var(--panel); }
.vsx-field b { font-size: 15px; font-weight: 550; letter-spacing: -0.004em; color: var(--text); }
.vsx-field em { font-style: normal; font-size: 13.5px; font-weight: 430; line-height: 1.5; color: var(--muted); }

/* Opportunities authority lives with the scanner repair blocks below so it
   wins over the global page-frame rules. */

/* ==== NEWS re-voice (nwx-) ==== */
.nwx-page .nwx-bar { margin-top: 4px; padding-top: 24px; border-top: 1px solid var(--line); }
.nwx-page .news-tab { font-size: 13.5px; font-weight: 460; }
.nwx-page .news-tab.on { font-weight: 520; }
.nwx-page .news-item-title { font-size: 15px; font-weight: 510; letter-spacing: -0.004em; }
.nwx-page .news-item-sub { font-size: 12.5px; font-weight: 430; }
.nwx-page .news-hint { font-size: 13.5px; font-weight: 430; color: var(--muted); }

/* ==== CALENDAR re-voice (clx-) ==== */
.clx-page .clx-filters { margin-top: 4px; padding-top: 24px; border-top: 1px solid var(--line); }
.clx-page .cal-cols { font-size: 13.5px; font-weight: 440; color: var(--muted); }


/* narrow-width repairs (owner 2026-07-09): labels never wrap, search never overflows */
.acb-label { white-space: nowrap; }
.acb-label-row { flex-wrap: wrap; row-gap: 6px; }
.topbar-search { flex: 0 1 min(440px, 36vw); min-width: 150px; }
.hdr-in { min-width: 0; }
.hdr-in > * { min-width: 0; }
@media (max-width: 1100px) {
  .bwx-hero-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 18px; }
}

/* narrow-window overflow repairs (measured at 900px, owner 2026-07-09):
   wide tables scroll INSIDE their container; header rows wrap. */
.tdx-head { flex-wrap: wrap; row-gap: 10px; }
.tdx-search { width: min(300px, 52vw); }
@media (max-width: 1020px) {
  .mkx table { display: block; overflow-x: auto; }
  .hlx-table { display: block; overflow-x: auto; }
  .bsx-table { display: block; overflow-x: auto; }
  .tdx-controls { justify-content: flex-start; }
  .cgx-tabs { flex-wrap: wrap; }
  .tdx-cardhead { flex-wrap: wrap; row-gap: 8px; }
}

/* ==== THE UNIVERSAL EDGE (owner 2026-07-09): every page's surfaces wear the
   same razor-thin boundary as Account/Token — one color, both themes. ==== */
.bwx-hero {
  background: var(--panel);
  border: 1px solid var(--line-2);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
  padding: 22px 24px 18px;
  margin: 4px 0 14px;
}
[data-theme="dark"] .bwx-hero { box-shadow: none; }
.rsx-band {
  background: var(--panel);
  border: 1px solid var(--line-2);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
  padding: 20px 24px;
  margin-top: 14px;
}
[data-theme="dark"] .rsx-band { box-shadow: none; }
.rsx-band + .rsx-band { margin-top: 14px; }

/* Markets: stats tiles already carded — frame the screener too */
.mkx-prices {
  background: var(--panel);
  border: 1px solid var(--line-2);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
  padding: 20px 24px 14px;
  margin-top: 14px;
}
[data-theme="dark"] .mkx-prices { box-shadow: none; }

/* News + Calendar lists get the same frame */
.news-page-list, .cal-page-list {
  background: var(--panel);
  border: 1px solid var(--line-2);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
  padding: 8px 20px;
  margin-top: 14px;
}
[data-theme="dark"] .news-page-list, [data-theme="dark"] .cal-page-list { box-shadow: none; }
.clx-page .cal-cols { padding: 0 20px; }

/* ==== TOPBAR ACCOUNT DETAILS — premium avatar control ===================== */
.acct-wrap.top {
  isolation: isolate;
}
.acct-wrap.top .acct-card.acct-pro-trigger,
.acct-wrap.top .acct-card.acct-pro-trigger:hover,
.acct-wrap.top .acct-card.acct-pro-trigger.on {
  width: 40px !important;
  height: 40px !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  overflow: visible;
}
.acct-card.acct-pro-trigger:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}
.acct-top-orb {
  position: relative;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
}
.acct-top-ring {
  position: absolute;
  inset: -2px;
  border-radius: 50%;
  background:
    conic-gradient(
      from 180deg,
      transparent 0deg,
      transparent 56deg,
      color-mix(in srgb, var(--acct-tone, var(--accent)) 56%, transparent) 128deg,
      transparent 220deg,
      transparent 360deg
    );
  opacity: .88;
  animation: acctOrbit 5.8s linear infinite;
}
.acct-top-ring::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: inherit;
  background: var(--panel);
}
.acct-top-face {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 1px solid color-mix(in srgb, var(--acct-tone, var(--accent)) 24%, var(--line-2));
  border-radius: 50%;
  background: var(--tile);
  color: var(--accent-ink);
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(15, 23, 42, .08);
}
.acct-top-face img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.acct-top-orb.profile-logo .acct-top-face {
  background: #f3f5f9;
}
.acct-top-orb.profile-logo .acct-top-face img {
  object-fit: contain;
  transform: scale(1.28);
}
.acct-top-dot {
  position: absolute;
  z-index: 2;
  right: 1px;
  bottom: 2px;
  width: 8px;
  height: 8px;
  border: 2px solid var(--panel);
  border-radius: 50%;
  background: var(--acct-tone, var(--muted));
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--acct-tone, var(--muted)) 12%, transparent);
}
.acct-top-orb.s-live { --acct-tone: var(--up); }
.acct-top-orb.s-warn { --acct-tone: #d89b24; }
.acct-top-orb.s-off { --acct-tone: var(--faint); }
.acct-wrap.top .acct-card.acct-pro-trigger:hover .acct-top-face,
.acct-wrap.top .acct-card.acct-pro-trigger.on .acct-top-face {
  border-color: color-mix(in srgb, var(--acct-tone, var(--accent)) 44%, var(--line-2));
  box-shadow: 0 5px 14px rgba(15, 23, 42, .12);
}
@keyframes acctOrbit {
  to { transform: rotate(360deg); }
}

.acct-pop.cb-acct-pop {
  width: 400px !important;
  min-width: 400px !important;
  max-height: min(76vh, 560px) !important;
  border-radius: 16px !important;
  box-shadow: 0 18px 48px rgba(15, 23, 42, .14) !important;
}
[data-theme="dark"] .acct-pop.cb-acct-pop {
  box-shadow: 0 18px 48px rgba(0, 0, 0, .34) !important;
}
.cb-acct-head.cb-acct-pro-head {
  position: relative;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 12px;
  padding: 18px 18px 15px;
  overflow: hidden;
}
.cb-acct-head.cb-acct-pro-head::before {
  content: "";
  position: absolute;
  left: 18px;
  right: 18px;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--acct-tone, var(--accent)) 52%, transparent), transparent);
}
.cb-acct-head.cb-acct-pro-head.s-live { --acct-tone: var(--up); }
.cb-acct-head.cb-acct-pro-head.s-warn { --acct-tone: #d89b24; }
.cb-acct-head.cb-acct-pro-head.s-off { --acct-tone: var(--faint); }
.cb-acct-pro-head .cb-acct-avatar {
  width: 40px;
  height: 40px;
  border: 1px solid color-mix(in srgb, var(--acct-tone, var(--accent)) 34%, var(--line-2));
  background: var(--tile);
  box-shadow: 0 3px 12px rgba(15, 23, 42, .08);
}
.cb-acct-pro-head .cb-acct-name {
  font-size: 16px;
  font-weight: 650;
  letter-spacing: 0;
}
.cb-acct-pro-head .cb-acct-sub {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 430;
}
.cb-acct-pro-head .cb-acct-manage {
  padding-top: 2px;
  font-size: 13px;
  font-weight: 650;
  color: var(--accent-ink);
}
[data-theme="dark"] .cb-acct-pro-head .cb-acct-manage {
  color: var(--accent);
}
.cb-acct-pro-head .cb-logout {
  height: 32px;
  padding: 0 10px;
  border: 1px solid color-mix(in srgb, var(--down) 18%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--down-soft) 72%, transparent);
  font-size: 12px;
  font-weight: 650;
}
.cb-acct-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
  padding: 10px 18px 12px;
  border-bottom: 1px solid var(--line);
}
.cb-acct-strip span {
  display: grid;
  gap: 3px;
  min-width: 0;
}
.cb-acct-strip span + span {
  padding-left: 12px;
  border-left: 1px solid var(--line);
}
.cb-acct-strip em {
  overflow: hidden;
  color: var(--muted);
  font-style: normal;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: .045em;
  text-transform: uppercase;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cb-acct-strip b {
  overflow: hidden;
  color: var(--text);
  font-size: 12.5px;
  font-weight: 620;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cb-acct-strip b.s-live { color: var(--up); }
.cb-acct-strip b.s-warn { color: #b7791f; }
.cb-acct-strip b.s-off { color: var(--muted); }
.acct-pop.cb-acct-pop .cb-link-block {
  padding: 13px 18px 0;
}
.acct-pop.cb-acct-pop .cb-link-block + .cb-link-block {
  padding-top: 12px;
}
.acct-pop.cb-acct-pop .cb-link-head {
  padding: 0 0 8px;
}
.acct-pop.cb-acct-pop .cb-link-head span {
  font-size: 13.5px;
  font-weight: 650;
}
.acct-pop.cb-acct-pop .cb-link-head b {
  font-size: 11.5px;
  font-weight: 650;
  color: var(--muted);
}
.acct-pop.cb-acct-pop .cb-exchange-row,
.acct-pop.cb-acct-pop .cb-device-row {
  min-height: 50px;
  grid-template-columns: 32px minmax(0, 1fr) auto;
}
.acct-pop.cb-acct-pop .cb-exchange-mark {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--tile);
}
.acct-pop.cb-acct-pop .cb-exchange-mark.on {
  background: color-mix(in srgb, #f0b90b 82%, white);
  color: #171300;
}
.acct-pop.cb-acct-pop .cb-exchange-main b,
.acct-pop.cb-acct-pop .cb-device-main b {
  font-size: 13.5px;
  font-weight: 620;
}
.acct-pop.cb-acct-pop .cb-exchange-main em,
.acct-pop.cb-acct-pop .cb-device-main em {
  font-size: 11.5px;
}
.acct-pop.cb-acct-pop .cb-device-right i {
  border-radius: 999px;
  background: var(--accent-soft);
  padding: 3px 7px;
  color: var(--accent-ink);
}
[data-theme="dark"] .acct-pop.cb-acct-pop .cb-device-right i {
  color: var(--accent);
}
.acct-pop.cb-acct-pop .cb-footer-action {
  width: calc(100% - 36px);
  height: 38px;
  margin: 14px 18px 16px;
  border-radius: 10px;
  background: var(--tile);
  font-size: 12.5px;
  font-weight: 650;
}
@media (max-width: 680px) {
  .acct-pop.cb-acct-pop {
    width: min(400px, calc(100vw - 24px)) !important;
    min-width: min(400px, calc(100vw - 24px)) !important;
  }
  .cb-acct-strip {
    grid-template-columns: 1fr;
    gap: 8px;
  }
  .cb-acct-strip span + span {
    padding-left: 0;
    border-left: 0;
  }
}

/* ==== Account Details: compact premium identity/security popover ========== */
.acct-pop.cb-acct-pop {
  width: 368px !important;
  min-width: 368px !important;
  max-height: min(74vh, 500px) !important;
  padding: 0 !important;
  overflow: hidden !important;
  border: 1px solid color-mix(in srgb, var(--line-2) 82%, transparent) !important;
  border-radius: 18px !important;
  background:
    radial-gradient(circle at 18% 0%, color-mix(in srgb, var(--acct-tone, var(--accent)) 8%, transparent), transparent 38%),
    var(--panel) !important;
  box-shadow: 0 18px 48px rgba(15, 23, 42, .13) !important;
}
