/* ==== NEWS DESK — premium announcement scanner ============================ */
.nwx-page {
  padding-top: 34px;
  padding-bottom: 34px;
}
.nwx-hero {
  padding: 4px 0 22px;
  border-bottom: 1px solid var(--line);
}
.nwx-hero-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}
.nwx-title {
  min-width: 0;
  max-width: 860px;
}
.nwx-kicker {
  display: block;
  margin-bottom: 6px;
  color: var(--faint);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 720;
  letter-spacing: .12em;
  line-height: 1;
  text-transform: uppercase;
}
.nwx-title-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.nwx-title-row h1 {
  margin: 0;
  color: var(--text);
  font-size: clamp(34px, 3.1vw, 48px);
  font-weight: 760;
  letter-spacing: -.02em;
  line-height: .98;
}
.nwx-title p {
  margin: 12px 0 0;
  max-width: 760px;
  color: var(--text-2);
  font-size: 15px;
  font-weight: 430;
  line-height: 1.55;
}
.nwx-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: none;
}
.nwx-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 34px;
  padding: 0 13px;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  background: var(--panel);
  color: var(--text);
  font-size: 13px;
  font-weight: 610;
  text-decoration: none;
  transition: background .14s ease, border-color .14s ease, color .14s ease, transform .14s ease;
}
.nwx-action:hover {
  transform: translateY(-1px);
  border-color: var(--line-strong);
  background: var(--tile);
}
.nwx-stat-strip {
  display: grid;
  grid-template-columns: 1.15fr .72fr .72fr 1fr;
  margin-top: 28px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.nwx-stat-strip span {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 16px 22px 15px;
  border-right: 1px solid var(--line);
}
.nwx-stat-strip span:first-child { padding-left: 0; }
.nwx-stat-strip span:last-child {
  border-right: 0;
  padding-right: 0;
}
.nwx-stat-strip b {
  min-width: 0;
  overflow: hidden;
  color: var(--text);
  font-size: 20px;
  font-weight: 620;
  letter-spacing: -.01em;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nwx-stat-strip em {
  min-width: 0;
  overflow: hidden;
  color: var(--muted);
  font-size: 12.5px;
  font-style: normal;
  font-weight: 430;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nwx-controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 360px);
  gap: 18px;
  align-items: start;
  padding: 22px 0 14px;
}
.nwx-tab-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  min-width: 0;
}
.nwx-tab {
  height: 34px;
  padding: 0 13px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: var(--tile);
  color: var(--text-2);
  font-size: 13px;
  font-weight: 560;
  letter-spacing: 0;
  transition: background .14s ease, color .14s ease, border-color .14s ease;
}
.nwx-tab:hover {
  color: var(--text);
  background: var(--tile-hover);
}
.nwx-tab.on {
  border-color: #05070b;
  background: #05070b;
  color: #fff;
}
[data-theme="dark"] .nwx-tab.on {
  border-color: var(--line-strong);
  background: var(--tile-hover);
}
.nwx-search {
  display: flex;
  align-items: center;
  gap: 9px;
  height: 38px;
  padding: 0 13px;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  background: var(--panel);
  color: var(--muted);
  transition: border-color .14s ease, box-shadow .14s ease;
}
.nwx-search:focus-within {
  border-color: var(--accent-line);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.nwx-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--text);
  font-size: 13.5px;
}
.nwx-search input::placeholder { color: var(--faint); }
.nwx-context {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
}
.nwx-context p {
  min-width: 0;
  flex: 1;
  margin: 0;
  color: var(--muted);
  font-size: 13.5px;
  font-weight: 430;
  line-height: 1.45;
}
.nwx-code {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  height: 24px;
  padding: 0 8px;
  border-radius: 999px;
  background: var(--tile);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 720;
  letter-spacing: .04em;
}
.nwx-code.ok { color: var(--up); }
.nwx-code.warn { color: #b7791f; }
.nwx-code.bad { color: var(--down); }
.nwx-source {
  flex: none;
  color: var(--faint);
  font-size: 12.5px;
  font-weight: 470;
  white-space: nowrap;
}
.nwx-grid {
  display: grid;
  grid-template-columns: minmax(300px, 390px) minmax(0, 1fr);
  gap: 24px;
  align-items: start;
  margin-top: 22px;
}
.nwx-lead,
.nwx-feed {
  min-width: 0;
}
.nwx-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  min-height: 28px;
  margin-bottom: 10px;
}
.nwx-section-head span {
  color: var(--text);
  font-size: 17px;
  font-weight: 680;
  letter-spacing: -.01em;
}
.nwx-section-head em {
  color: var(--muted);
  font-size: 12px;
  font-style: normal;
  font-weight: 520;
}
.nwx-lead-card,
.nwx-empty-card,
.nwx-feed-list {
  border: 1px solid var(--line-2);
  border-radius: 12px;
  background: var(--panel);
  box-shadow: var(--shadow-sm);
}
[data-theme="dark"] .nwx-lead-card,
[data-theme="dark"] .nwx-empty-card,
[data-theme="dark"] .nwx-feed-list {
  box-shadow: none;
}
.nwx-lead-card {
  position: relative;
  display: grid;
  align-content: start;
  gap: 14px;
  min-height: 236px;
  padding: 22px;
  color: inherit;
  text-decoration: none;
  overflow: hidden;
}
.nwx-lead-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--accent);
}
.nwx-lead-card.ok::before { background: var(--up); }
.nwx-lead-card.warn::before { background: #d99a2b; }
.nwx-lead-card.bad::before { background: var(--down); }
.nwx-lead-card:hover h2 {
  color: var(--accent);
}
.nwx-lead-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--tile);
  color: var(--text-2);
}
.nwx-lead-card h2 {
  margin: 28px 0 0;
  color: var(--text);
  font-size: 24px;
  font-weight: 680;
  letter-spacing: -.018em;
  line-height: 1.16;
  transition: color .14s ease;
}
.nwx-lead-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  color: var(--muted);
  font-size: 12.5px;
  font-weight: 470;
}
.nwx-lead-meta b {
  color: var(--text-2);
  font-weight: 650;
}
.nwx-lead-meta i {
  min-width: 0;
  overflow: hidden;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nwx-empty-card {
  min-height: 180px;
  display: grid;
  place-items: center;
  padding: 20px;
  color: var(--muted);
  font-size: 13px;
}
.nwx-feed-list {
  overflow: hidden;
}
.nwx-row {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) minmax(132px, auto) 26px;
  align-items: center;
  gap: 14px;
  min-height: 66px;
  padding: 11px 16px;
  border-bottom: 1px solid var(--line);
  color: inherit;
  text-decoration: none;
  transition: background .14s ease;
}
.nwx-row:last-child {
  border-bottom: 0;
}
.nwx-row:hover {
  background: var(--hover);
}
.nwx-row-index {
  color: var(--faint);
  font-size: 12px;
  font-weight: 620;
}
.nwx-row-body {
  display: grid;
  gap: 5px;
  min-width: 0;
}
.nwx-row-title {
  min-width: 0;
  overflow: hidden;
  color: var(--text);
  font-size: 15px;
  font-weight: 560;
  letter-spacing: -.006em;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nwx-row:hover .nwx-row-title {
  color: var(--accent);
}
.nwx-row-sub {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 430;
}
.nwx-row-sub b {
  color: var(--text-2);
  font-weight: 610;
}
.nwx-row-sub i {
  min-width: 0;
  overflow: hidden;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nwx-row-date {
  justify-self: end;
  color: var(--muted);
  font-size: 12.5px;
  font-weight: 460;
  white-space: nowrap;
}
.nwx-row-open {
  justify-self: end;
  color: var(--faint);
}
.nwx-row:hover .nwx-row-open {
  color: var(--accent);
}
.nwx-source-note {
  margin: 16px 0 0;
  color: var(--faint);
  font-size: 12px;
  font-weight: 430;
}
@media (max-width: 1100px) {
  .nwx-grid {
    grid-template-columns: 1fr;
  }
  .nwx-lead-card {
    min-height: 190px;
  }
}
@media (max-width: 820px) {
  .nwx-page { padding-top: 22px; }
  .nwx-hero-main,
  .nwx-context {
    align-items: flex-start;
    flex-direction: column;
  }
  .nwx-title-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }
  .nwx-actions,
  .nwx-source {
    width: 100%;
  }
  .nwx-action {
    flex: 1;
  }
  .nwx-stat-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .nwx-stat-strip span {
    border-right: 0;
    border-bottom: 1px solid var(--line);
    padding: 14px 0;
  }
  .nwx-stat-strip span:nth-last-child(-n + 2) {
    border-bottom: 0;
  }
  .nwx-controls {
    grid-template-columns: 1fr;
  }
  .nwx-row {
    grid-template-columns: 34px minmax(0, 1fr) 22px;
  }
  .nwx-row-date {
    grid-column: 2;
    justify-self: start;
  }
  .nwx-row-open {
    grid-column: 3;
    grid-row: 1 / span 2;
  }
}

