  min-height: 80px;
  align-items: center;
  gap: 18px;
}
.ux-page .ux-hero .bwx-title-row {
  display: grid;
  grid-template-columns: max-content;
  align-items: center;
  gap: 0;
  min-height: 42px;
}
.ux-page .ux-hero .bwx-title-row h1 {
  font-size: 40px;
  font-weight: 540;
  line-height: 42px;
  letter-spacing: 0;
}
.ux-page .ux-live-status {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  overflow: hidden;
  isolation: isolate;
  width: 154px;
  min-width: 154px;
  height: 40px;
  padding: 0 13px;
  border: 1px solid color-mix(in srgb, var(--up) 22%, var(--line-2));
  border-radius: 999px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 94%, var(--up)), var(--panel));
  color: color-mix(in srgb, var(--up) 72%, var(--text));
  font-size: 12px;
  font-weight: 570;
  line-height: 1;
  letter-spacing: 0;
  font-variant-numeric: tabular-nums;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .82);
}
.ux-page .ux-live-status.bad {
  border-color: color-mix(in srgb, var(--down) 24%, var(--line-2));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 94%, var(--down)), var(--panel));
  color: color-mix(in srgb, var(--down) 76%, var(--text));
}
.ux-page .ux-live-status.idle {
  border-color: var(--line-2);
  background: var(--panel);
  color: var(--muted);
}
.ux-page .ux-live-status i {
  position: relative;
  z-index: 1;
  width: 7px;
  height: 7px;
  box-shadow: 0 0 0 1px color-mix(in srgb, currentColor 12%, transparent);
}
.ux-page .ux-live-status::before {
  content: "";
  position: absolute;
  left: 13px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  opacity: .32;
  transform: scale(1);
  pointer-events: none;
}
.ux-page .ux-live-status::after {
  content: "";
  position: absolute;
  left: 18px;
  bottom: 5px;
  width: 62px;
  height: 1px;
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, currentColor 50%, transparent), transparent);
  opacity: 0;
  transform: translate3d(-80px, 0, 0);
  pointer-events: none;
}
.ux-page .ux-live-status i,
.ux-page .ux-live-status::before {
  animation: uxLiveDotPing 2.2s cubic-bezier(.22, .82, .18, 1) infinite;
}
.ux-page .ux-live-status i {
  animation-name: uxLiveDotCore;
}
.ux-page .ux-live-status.syncing::after {
  animation: uxLiveStatusSweep 2.4s cubic-bezier(.22, .82, .18, 1) infinite;
}
@keyframes uxLiveDotCore {
  0%, 100% {
    transform: scale(1);
    opacity: .82;
  }
  42% {
    transform: scale(1.16);
    opacity: 1;
  }
}
@keyframes uxLiveDotPing {
  0% {
    opacity: .34;
    transform: scale(1);
  }
  70%, 100% {
    opacity: 0;
    transform: scale(3.2);
  }
}
@keyframes uxLiveStatusSweep {
  0% {
    opacity: 0;
    transform: translate3d(-80px, 0, 0);
  }
  18% {
    opacity: .42;
  }
  58% {
    opacity: .58;
  }
  100% {
    opacity: 0;
    transform: translate3d(122px, 0, 0);
  }
}
.ux-page .ux-hero p {
  max-width: 820px;
  margin-top: 10px;
  font-size: 14.5px;
  font-weight: 430;
  line-height: 1.55;
