  height: 40px;
  padding: 0 14px;
  border: 1px solid color-mix(in srgb, var(--line-strong) 52%, var(--line-2));
  border-radius: 999px;
  background: var(--panel);
  color: color-mix(in srgb, var(--text) 86%, var(--muted));
  font-size: 13.5px;
  font-weight: 500;
  line-height: 1;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .82);
  transition:
    border-color .18s ease,
    color .18s ease,
    box-shadow .18s ease,
    background .18s ease;
}
.ux-page .ux-refresh:hover,
.ux-page .ux-refresh:focus-visible {
  border-color: color-mix(in srgb, var(--accent) 26%, var(--line-strong));
  color: var(--text);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .88),
    0 8px 20px rgba(15, 23, 42, .055);
}
.ux-page .ux-refresh > svg,
.ux-page .ux-refresh > span:not(.ux-refresh-beam) {
  position: relative;
  z-index: 1;
  flex: none;
}
.ux-page .ux-refresh-beam {
  position: absolute;
  inset: -1px;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
  z-index: 0;
}
.ux-page .ux-refresh-beam::before,
.ux-page .ux-refresh-beam::after {
  content: "";
  position: absolute;
  left: 0;
  width: 34%;
  height: 1px;
  border-radius: 999px;
  background:
    radial-gradient(circle at 88% 50%, rgba(255, 255, 255, .32) 0 1.5px, transparent 3px),
    linear-gradient(
      90deg,
      transparent 0%,
      rgba(56, 189, 248, .08) 34%,
      rgba(37, 99, 235, .22) 66%,
      rgba(255, 255, 255, .32) 86%,
      transparent 100%
    );
  box-shadow:
    0 0 7px rgba(56, 189, 248, .06),
    0 0 12px rgba(37, 99, 235, .045);
  opacity: 0;
  transform: translate3d(-135%, 0, 0);
  animation: uxRefreshBeamIdle 9s cubic-bezier(.22, .82, .18, 1) infinite;
}
.ux-page .ux-refresh-beam::before {
  top: 1px;
}
.ux-page .ux-refresh-beam::after {
  bottom: 1px;
  animation-delay: .08s;
}
.ux-page .ux-refresh.checking {
  border-color: color-mix(in srgb, var(--accent) 30%, var(--line-strong));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 96%, var(--accent-soft)), var(--panel));
  color: var(--text);
}
.ux-page .ux-refresh.checking .ux-refresh-beam::before,
.ux-page .ux-refresh.checking .ux-refresh-beam::after {
  width: 30%;
  height: 2px;
  background:
    radial-gradient(circle at 88% 50%, rgba(255, 255, 255, .78) 0 1.5px, transparent 3px),
    linear-gradient(
      90deg,
      transparent 0%,
      rgba(56, 189, 248, .22) 34%,
      rgba(37, 99, 235, .54) 66%,
      rgba(255, 255, 255, .76) 86%,
      transparent 100%
    );
  box-shadow:
    0 0 7px rgba(56, 189, 248, .18),
    0 0 12px rgba(37, 99, 235, .13);
  animation-name: uxRefreshBeamActive;
  animation-duration: 3.2s;
}
.ux-page .ux-refresh:disabled {
  cursor: default;
  opacity: 1;
}
.ux-page .ux-refresh.checking svg,
.ux-page .ux-refresh.refreshing svg {
  animation: uxRefreshSpin 1.05s linear infinite;
}
@keyframes uxRefreshSpin {
  to { transform: rotate(360deg); }
}
@keyframes uxRefreshBeamIdle {
  0%, 58%, 100% {
    opacity: 0;
    transform: translate3d(-135%, 0, 0);
  }
  64% {
    opacity: .22;
  }
  74% {
    opacity: .38;
  }
  88% {
    opacity: .22;
    transform: translate3d(335%, 0, 0);
  }
  96% {
    opacity: 0;
    transform: translate3d(335%, 0, 0);
  }
}
@keyframes uxRefreshBeamActive {
  0% {
    opacity: 0;
    transform: translate3d(-135%, 0, 0);
  }
  12% {
    opacity: .78;
  }
  38% {
    opacity: .98;
  }
  72% {
    opacity: .72;
    transform: translate3d(335%, 0, 0);
  }
  100% {
    opacity: 0;
    transform: translate3d(335%, 0, 0);
  }
}
