  --search-beam-width: 30%;
  --search-beam-size: 2px;
  --search-beam-peak: .94;
  --search-beam-shadow: .30;
}
.topbar-search .search-beam {
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  top: 0 !important;
  bottom: 0 !important;
  height: auto !important;
  z-index: 8 !important;
  display: block !important;
  overflow: hidden !important;
  border-radius: 999px !important;
  pointer-events: none !important;
}
.topbar-search .search-beam::before,
.topbar-search .search-beam::after {
  content: "" !important;
  position: absolute !important;
  left: 0 !important;
  width: var(--search-beam-width) !important;
  height: var(--search-beam-size) !important;
  padding: 0 !important;
  border-radius: 999px !important;
  opacity: 0;
  transform: translate3d(-128%, 0, 0);
  will-change: transform, opacity;
  background:
    radial-gradient(circle at 88% 50%, rgba(255, 255, 255, calc(var(--search-beam-peak) * .96)) 0 1.5px, transparent 3px),
    linear-gradient(90deg,
      transparent 0%,
      rgba(56, 189, 248, 0) 12%,
      rgba(56, 189, 248, calc(var(--search-beam-peak) * .26)) 34%,
      rgba(37, 99, 235, calc(var(--search-beam-peak) * .62)) 66%,
      rgba(255, 255, 255, calc(var(--search-beam-peak) * .90)) 86%,
      transparent 100%
    ) !important;
  box-shadow:
    0 0 7px rgba(56, 189, 248, var(--search-beam-shadow)),
    0 0 12px rgba(37, 99, 235, calc(var(--search-beam-shadow) * .72)) !important;
  filter: none !important;
  animation: searchPairedBeamIdle var(--search-beam-speed) cubic-bezier(.22, .82, .18, 1) infinite !important;
  -webkit-mask: none !important;
  mask: none !important;
}
.topbar-search .search-beam::before { top: 1px !important; }
.topbar-search .search-beam::after {
  bottom: 1px !important;
  animation-delay: .04s !important;
}
.topbar-search.open .search-beam::before,
.topbar-search.open .search-beam::after {
  animation-name: searchPairedBeamActive !important;
}
.topbar-search .search-beam > * {
