}
@keyframes searchPairedBeamIdle {
  0%, 68%, 100% { opacity: 0; transform: translate3d(-128%, 0, 0); }
  5% { opacity: calc(var(--search-beam-peak) * .54); }
  13% { opacity: var(--search-beam-peak); }
  25% { opacity: calc(var(--search-beam-peak) * .68); }
  31% { opacity: 0; transform: translate3d(334%, 0, 0); }
}
@keyframes searchPairedBeamActive {
  0%, 80%, 100% { opacity: 0; transform: translate3d(-132%, 0, 0); }
  7% { opacity: calc(var(--search-beam-peak) * .74); }
  18%, 43% { opacity: var(--search-beam-peak); }
  60% { opacity: 0; transform: translate3d(342%, 0, 0); }
}
@media (prefers-reduced-motion: reduce) {
  .smenu-bar .hdr-clock-btn.clock-pro-btn .clock-orbit::after,
