/* ==== TOPBAR TYPOGRAPHY BASELINE - match Connection Health reference ======= */
:root {
  --ref-ui-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --ref-mono-font: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  --ref-label: var(--muted);
  --ref-row: var(--text-2);
  --ref-value: var(--text-2);
}
.smenu-content:has(.clock-pop),
.smenu-content:has(.shell-premium),
.smenu-content:has(.keyx-pop),
.smenu-content:has(.datax-pop),
.smenu-content:has(.advx-pop.advisor-audit),
.smenu-content:has(.ntfx-pop),
.smenu-content:has(.modex-pop),
.smenu-content:has(.mrefx-pop),
.smenu-content:has(.curfx-pop),
.smenu-content:has(.basisx-pop),
.smenu-content:has(.apx-pop),
.acct-pop.cb-acct-pop {
  --ref-ui-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --ref-mono-font: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  --ref-label: var(--muted);
  --ref-row: var(--text-2);
  --ref-value: var(--text-2);
  font-family: var(--ref-ui-font) !important;
  -webkit-font-smoothing: antialiased !important;
  -moz-osx-font-smoothing: grayscale !important;
  text-rendering: optimizeLegibility !important;
}

.smenu-content:has(.clock-pop) :is(small, em),
.smenu-content:has(.shell-premium) :is(.shell-stage-bar b, .shell-pills em),
.smenu-content:has(.keyx-pop) :is(.keyx-enabled > em, .keyx-card-meta em),
.smenu-content:has(.datax-pop) :is(.datax-score em, .datax-counters em),
.smenu-content:has(.advx-pop.advisor-audit) :is(.advx-focus-head b),
.smenu-content:has(.modex-pop) :is(.modex-status, .modex-head-copy em),
.smenu-content:has(.mrefx-pop) :is(.mrefx-cadence-title em, .mrefx-cadence-status, .mrefx-custom-row label span),
.smenu-content:has(.curfx-pop) :is(.curfx-score em, .curfx-counters em),
.smenu-content:has(.basisx-pop) :is(.basisx-score em, .basisx-counters em),
.smenu-content:has(.apx-pop) :is(.apx-scale strong),
.acct-pop.cb-acct-pop :is(.cb-link-head > b, .cb-status, .cb-device-right i) {
  color: var(--ref-label) !important;
  font-family: var(--ref-ui-font) !important;
  font-size: 11px !important;
  font-style: normal !important;
  font-weight: 600 !important;
  letter-spacing: .06em !important;
  line-height: 14px !important;
  text-transform: uppercase !important;
