/* ==== EXECUTION CLOCK - real animated face + filled premium popover ========= */
.smenu-bar .hdr-clock-btn.clock-pro-btn,
.smenu-bar .hdr-clock-btn.clock-pro-btn:hover,
.smenu-bar .hdr-clock-btn.clock-pro-btn.active,
.smenu-bar .hdr-clock-btn.clock-pro-btn.on {
  min-width: 168px !important;
  height: 34px !important;
  gap: 8px !important;
  justify-content: flex-start !important;
  padding: 0 12px 0 9px !important;
}

.clock-face {
  --clock-face: var(--panel);
  --clock-ring: color-mix(in srgb, #2563eb 34%, var(--line-2));
  --clock-hand: color-mix(in srgb, var(--text) 84%, #2563eb);
  --clock-minute-hand: color-mix(in srgb, #2563eb 74%, var(--text));
  --clock-second-hand: #15996a;
  position: relative;
  display: inline-grid;
  place-items: center;
  flex: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 50%, var(--clock-face) 0 54%, transparent 55%),
    conic-gradient(from -90deg, color-mix(in srgb, #2563eb 46%, transparent), color-mix(in srgb, #15996a 40%, transparent), color-mix(in srgb, #2563eb 46%, transparent));
  box-shadow:
    inset 0 0 0 1px var(--clock-ring),
    inset 0 1px 0 rgba(255, 255, 255, .78),
    0 3px 9px rgba(37, 99, 235, .10);
  overflow: hidden;
}

.clock-face::before {
  content: "";
  position: absolute;
  inset: 4px;
  border-radius: inherit;
  background:
    radial-gradient(circle at 50% 0%, rgba(255, 255, 255, .78), transparent 42%),
    var(--clock-face);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--line) 72%, transparent);
}

.clock-face .tick,
.clock-face .hand,
.clock-face .pin {
  position: absolute;
  z-index: 2;
  display: block;
}

.clock-face .tick {
  border-radius: 999px;
  background: color-mix(in srgb, var(--muted) 54%, transparent);
}

.clock-face .t12,
.clock-face .t6 {
  left: 50%;
  width: 1px;
  height: 2.5px;
  transform: translateX(-50%);
}

.clock-face .t12 { top: 5.5px; }
.clock-face .t6 { bottom: 5.5px; }

.clock-face .t3,
.clock-face .t9 {
  top: 50%;
  width: 2.5px;
  height: 1px;
  transform: translateY(-50%);
}

.clock-face .t3 { right: 5.5px; }
.clock-face .t9 { left: 5.5px; }

.clock-face .hand {
  left: 50%;
  bottom: 50%;
  border-radius: 999px;
  transform-origin: 50% 100%;
}

.clock-face .hand.hour {
  width: 2px;
  height: 5.4px;
  margin-left: -1px;
  background: var(--clock-hand);
  transform: rotate(var(--clock-hour));
}

.clock-face .hand.minute {
  width: 1.6px;
  height: 7.4px;
  margin-left: -.8px;
  background: var(--clock-minute-hand);
