/* ==== CLOCK REPAIR - clean rim, visible motion, no text collision =========== */
.clock-face {
  --clock-face: var(--panel);
  --clock-ring: color-mix(in srgb, #2563eb 34%, var(--line-2));
  background: var(--clock-face) !important;
  border: 1px solid var(--clock-ring) !important;
  box-sizing: border-box !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .82),
    0 2px 8px rgba(37, 99, 235, .10) !important;
  overflow: hidden !important;
}

.clock-face::before {
  content: "" !important;
  position: absolute !important;
  inset: 4px !important;
  border: 1px solid color-mix(in srgb, var(--line) 70%, transparent) !important;
  border-radius: 50% !important;
  background:
    radial-gradient(circle at 50% 26%, rgba(255, 255, 255, .84), transparent 46%),
    color-mix(in srgb, #2563eb 3%, var(--clock-face)) !important;
  box-shadow: none !important;
}

.clock-face::after {
  content: "" !important;
  position: absolute !important;
  inset: 3px !important;
  z-index: 2 !important;
  display: block !important;
  border-radius: 50% !important;
  background:
    radial-gradient(circle at 50% 0%, #15996a 0 1.8px, rgba(21, 153, 106, .68) 1.9px 2.8px, transparent 3px) !important;
  animation: clockFaceSweep 1.55s linear infinite !important;
  pointer-events: none !important;
}

.clock-face .tick,
.clock-face .hand {
  z-index: 3 !important;
}

.clock-face .pin {
  z-index: 4 !important;
}

.clock-face .hand.second {
  height: 8px !important;
  opacity: .95 !important;
  transition: transform 210ms linear !important;
}

.clock-face.lg::after,
.clock-face.mini::after {
  inset: 4px !important;
}

.clock-face.lg::after {
  animation-duration: 1.35s !important;
}

.clock-face.mini::after {
  animation-duration: 1.45s !important;
}

@keyframes clockFaceSweep {
  to { transform: rotate(360deg); }
}

.smenu-content:has(.clock-pop) .clock-pop {
  grid-template-rows: 66px 42px 66px minmax(0, 1fr) !important;
}

.clock-market-card {
  grid-template-columns: 34px minmax(0, 1fr) !important;
  min-height: 66px !important;
  padding: 10px 12px !important;
}

.clock-market-card b {
  line-height: 16px !important;
}

.clock-market-card small {
  line-height: 14px !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .clock-face::after {
    animation: none !important;
  }

  .clock-face .hand.second {
    transition: none !important;
  }
}

