/* ==== REFRESH DOCK PREMIUM MOTION LOCK ====================================
   Bottom-right connection health is a real control, not a decorative badge:
   keep it off the corner, keep fills neutral, and let thin orbit/sweep motion
   communicate live backend refresh without competing with the data surface. */
.rdock {
  right: 40px !important;
  bottom: 40px !important;
  width: 58px !important;
  height: 58px !important;
  display: grid !important;
  place-items: center !important;
}

@media (max-width: 640px) {
  .rdock {
    right: 24px !important;
    bottom: 92px !important;
  }
}

.rdock-btn {
  width: 52px !important;
  height: 52px !important;
  overflow: visible !important;
  isolation: isolate !important;
  background: var(--panel) !important;
  border: 1px solid color-mix(in srgb, var(--rd-color, var(--muted)) 58%, var(--line-2)) !important;
  box-shadow:
    0 18px 34px -20px color-mix(in srgb, var(--rd-color, var(--text)) 34%, transparent),
    0 8px 18px -14px rgba(16, 20, 28, .38),
    inset 0 1px 0 rgba(255, 255, 255, .78) !important;
  transition: box-shadow .22s ease, border-color .22s ease, transform .14s ease !important;
}

[data-theme="dark"] .rdock-btn {
  box-shadow:
    0 16px 30px -22px color-mix(in srgb, var(--rd-color, var(--text)) 42%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, .08) !important;
}

.rdock:hover .rdock-btn {
  transform: none !important;
  box-shadow:
    0 22px 42px -22px color-mix(in srgb, var(--rd-color, var(--text)) 45%, transparent),
    0 10px 24px -16px rgba(16, 20, 28, .46),
    inset 0 1px 0 rgba(255, 255, 255, .82) !important;
}

.rdock-btn:active {
  transform: scale(.97) !important;
}

.rdock-motion {
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--rd-color, var(--muted)) 24%, transparent);
  pointer-events: none;
  animation: rdockOrbit 8.4s linear infinite;
  z-index: 0;
}

.rdock-motion::before {
  content: "";
  position: absolute;
  inset: -5px;
  border-radius: inherit;
  background:
    conic-gradient(
      from 0deg,
      transparent 0deg 204deg,
      color-mix(in srgb, var(--rd-color, var(--muted)) 0%, transparent) 224deg,
      color-mix(in srgb, var(--rd-color, var(--muted)) 52%, transparent) 274deg,
      transparent 318deg 360deg
    );
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 2px), #000 calc(100% - 1px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 2px), #000 calc(100% - 1px));
  opacity: .72;
}

.rdock-motion::after {
  content: "";
  position: absolute;
  left: 50%;
  top: -3px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--panel);
  border: 1px solid color-mix(in srgb, var(--rd-color, var(--muted)) 68%, var(--panel));
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--rd-color, var(--muted)) 10%, transparent),
    0 0 12px color-mix(in srgb, var(--rd-color, var(--muted)) 25%, transparent);
  transform: translateX(-50%);
}

.rdock-btn::before {
  content: "";
  position: absolute;
  inset: -8px;
  border-radius: inherit;
  border: 1px solid color-mix(in srgb, var(--rd-color, var(--muted)) 18%, transparent);
  opacity: .56;
  transform: scale(.86);
  animation: rdockBreath 4.8s ease-in-out infinite;
  pointer-events: none;
}

.rdock-ic {
  position: relative !important;
  z-index: 1 !important;
  color: var(--rd-color, var(--text-2));
}

.rdock-ic svg {
  width: 18px !important;
  height: 18px !important;
  stroke-width: 1.9 !important;
}

.rdock-btn.spin {
  --rd-color: color-mix(in srgb, var(--accent) 78%, var(--text-2)) !important;
  background: var(--panel) !important;
}

.rdock-btn.spin .rdock-motion {
  animation-duration: 1.7s;
}

.rdock-btn.spin .rdock-motion::before {
  opacity: .92;
}


.rdock-pop {
  right: 0 !important;
  bottom: calc(100% + 16px) !important;
  width: 292px !important;
  border-radius: 13px !important;
  box-shadow:
    0 26px 54px -32px rgba(16, 20, 28, .45),
    0 10px 22px -18px rgba(16, 20, 28, .28) !important;
}

[data-theme="dark"] .rdock-pop {
  box-shadow: none !important;
}

