/* ========================================================================== */
/* TOPBAR SUITE V3 — operator sheets, July 2026                              */
/* ========================================================================== */

.topbar-suite-v3 {
  --ops-blue: #315bea;
  --ops-green: #17875f;
  --ops-amber: #a86408;
  --ops-red: #d83a3a;
  display: flex !important;
  align-items: center !important;
  gap: 2px !important;
  min-width: 0;
}

/* CSS zoom does not participate in media queries. Size the command field from
   the effective layout width so 125% keeps the complete operator rail visible. */
.hdr-in > .tb-left {
  width: clamp(145px, calc((100vw / var(--uiz)) - 879px), 520px) !important;
}

.topbar-suite-v3 .smenu {
  height: auto !important;
  max-height: calc(100vh - 84px) !important;
  padding: 0 !important;
  border: 1px solid color-mix(in srgb, var(--text) 13%, transparent) !important;
  border-radius: 14px !important;
  background: var(--panel) !important;
  box-shadow: 0 18px 48px rgba(12, 16, 26, .16), 0 3px 10px rgba(12, 16, 26, .07) !important;
  overflow: hidden !important;
  backdrop-filter: none !important;
}

[data-theme="dark"] .topbar-suite-v3 .smenu {
  border-color: rgba(255, 255, 255, .11) !important;
  box-shadow: 0 24px 70px rgba(0, 0, 0, .48), 0 4px 14px rgba(0, 0, 0, .34) !important;
}

.topbar-suite-v3 .smenu-arrow {
  width: 10px !important;
  height: 10px !important;
  margin-left: -5px !important;
  border: 1px solid color-mix(in srgb, var(--text) 13%, transparent) !important;
  border-right: 0 !important;
  border-bottom: 0 !important;
  background: var(--panel) !important;
  box-shadow: none !important;
}

.topbar-suite-v3 .smenu-content {
  max-height: min(76vh, 640px) !important;
  padding: 0 !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--text) 16%, transparent) transparent;
}

.topbar-suite-v3 .smenu-content.morphing {
  opacity: .18 !important;
  transform: translateY(3px) !important;
}

.ops-sheet {
  --ops-accent: var(--ops-blue);
  display: block;
  width: 100%;
  color: var(--text);
  background: var(--panel);
  font-family: var(--ref-ui-font, var(--font));
}

.ops-sheet-head {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  min-height: 62px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--line);
}

.ops-sheet-icon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 9px;
  background: color-mix(in srgb, var(--ops-accent) 9%, var(--tile));
  color: color-mix(in srgb, var(--ops-accent) 78%, var(--text));
}

.ops-sheet-title {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.ops-sheet-title > b {
  overflow: hidden;
  color: var(--text);
  font-size: 14.5px;
  font-weight: 610;
  letter-spacing: -.012em;
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-sheet-title > em {
  overflow: hidden;
  color: var(--muted);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 440;
  letter-spacing: 0;
  line-height: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-sheet-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 25px;
  padding: 0 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text-2);
  background: transparent;
  font-size: 10px;
  font-style: normal;
  font-weight: 620;
  letter-spacing: .035em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
}

.ops-sheet-status > i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
}

.ops-sheet-status.ok { color: var(--ops-green); border-color: color-mix(in srgb, var(--ops-green) 25%, var(--line)); }
.ops-sheet-status.warn { color: var(--ops-amber); border-color: color-mix(in srgb, var(--ops-amber) 25%, var(--line)); }
.ops-sheet-status.bad { color: var(--ops-red); border-color: color-mix(in srgb, var(--ops-red) 25%, var(--line)); }
.ops-sheet-status.accent { color: var(--ops-accent); border-color: color-mix(in srgb, var(--ops-accent) 24%, var(--line)); }

.ops-section-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 36px;
  padding: 8px 16px 6px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 590;
  letter-spacing: .065em;
  line-height: 1;
  text-transform: uppercase;
}

.ops-section-label em {
  overflow: hidden;
  font-style: normal;
  font-weight: 480;
  letter-spacing: .02em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-list {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.ops-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  min-height: 52px;
  width: 100%;
  padding: 8px 16px;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  color: inherit;
  background: transparent;
  font: inherit;
  text-align: left;
}

.ops-row:has(.ops-row-icon) {
  grid-template-columns: 30px minmax(0, 1fr) auto;
}

.ops-row:has(.ops-row-check) {
  grid-template-columns: 30px minmax(0, 1fr) auto 18px;
}

.ops-row:last-child { border-bottom: 0; }
.ops-row.button { cursor: pointer; transition: background-color 150ms ease; }
.ops-row.button:hover:not(:disabled) { background: color-mix(in srgb, var(--text) 4%, transparent); }
.ops-row.button.selected { background: color-mix(in srgb, var(--ops-accent) 5%, transparent); }
.ops-row.button:disabled { cursor: default; opacity: .5; }

.ops-row-icon {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  color: var(--text-2);
  background: var(--tile);
}

.ops-row-icon.ok,
.ops-row-icon.good { color: var(--ops-green); background: color-mix(in srgb, var(--ops-green) 8%, var(--tile)); }
.ops-row-icon.warn { color: var(--ops-amber); background: color-mix(in srgb, var(--ops-amber) 8%, var(--tile)); }
.ops-row-icon.bad { color: var(--ops-red); background: color-mix(in srgb, var(--ops-red) 8%, var(--tile)); }
.ops-row-icon.accent { color: var(--ops-accent); background: color-mix(in srgb, var(--ops-accent) 8%, var(--tile)); }

.ops-row-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.ops-row-copy > b {
  overflow: hidden;
  color: var(--text);
  font-size: 12.5px;
  font-weight: 560;
  letter-spacing: -.005em;
  line-height: 16px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-row-copy > em {
  overflow: hidden;
  color: var(--muted);
  font-size: 10.75px;
  font-style: normal;
  font-weight: 430;
  line-height: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-row-value {
  display: inline-flex;
  align-items: baseline;
  gap: 1px;
  max-width: 122px;
  overflow: hidden;
  color: var(--text-2);
  font-family: var(--ref-mono-font, var(--mono));
  font-size: 10.5px;
  font-weight: 520;
  letter-spacing: -.015em;
  line-height: 15px;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-row-value > b { font-size: 12px; font-weight: 560; }
.ops-row-value > em { color: var(--muted); font-size: 9px; font-style: normal; }
.ops-row-value.ok,
.ops-row-value.good { color: var(--ops-green); }
.ops-row-value.warn { color: var(--ops-amber); }
.ops-row-value.bad { color: var(--ops-red); }
.ops-row-value.accent { color: var(--ops-accent); }

.ops-row-check {
  display: grid;
  place-items: center;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  color: #fff;
  background: var(--ops-accent);
}

.ops-sheet-foot {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  min-height: 55px;
  padding: 9px 12px;
  border-top: 1px solid var(--line);
  background: color-mix(in srgb, var(--text) 1.5%, var(--panel));
}

.ops-sheet-foot.split { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }

.ops-sheet-foot button,
.ops-sheet-foot a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 36px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: 9px;
  color: var(--text-2);
  background: var(--panel);
  font: inherit;
  font-size: 11.5px;
  font-weight: 570;
  text-decoration: none;
  cursor: pointer;
}

.ops-sheet-foot button:hover:not(:disabled),
.ops-sheet-foot a:hover { background: var(--hover); color: var(--text); }
.ops-sheet-foot button:disabled { cursor: default; opacity: .38; }
.ops-sheet-foot .primary { border-color: #10131a; color: #fff; background: #10131a; }
.ops-sheet-foot .primary:hover:not(:disabled) { color: #fff; background: #202532; }
[data-theme="dark"] .ops-sheet-foot .primary { border-color: #eef1f7; color: #11141b; background: #eef1f7; }
[data-theme="dark"] .ops-sheet-foot .primary:hover:not(:disabled) { color: #11141b; background: #fff; }

.ops-note-row,
.ops-policy-line {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  margin: 12px 14px;
  padding: 10px 11px;
  border-radius: 9px;
  color: var(--text-2);
  background: var(--tile);
}

.ops-note-row > svg,
.ops-policy-line > svg { color: var(--muted); }
.ops-note-row > span { display: grid; gap: 2px; }
.ops-note-row b { color: var(--text); font-size: 11.5px; font-weight: 570; line-height: 15px; }
.ops-note-row em { color: var(--muted); font-size: 10.5px; font-style: normal; font-weight: 430; line-height: 14px; }
.ops-policy-line { grid-template-columns: 18px minmax(0, 1fr); font-size: 10.75px; font-weight: 470; line-height: 15px; }
.ops-policy-line.ok > svg { color: var(--ops-green); }
.ops-policy-line.bad { color: var(--ops-red); background: color-mix(in srgb, var(--ops-red) 7%, var(--tile)); }
.ops-policy-line.bad > svg { color: var(--ops-red); }

.ops-empty-state {
  display: grid;
  place-items: center;
  gap: 5px;
  min-height: 124px;
  padding: 20px;
  color: var(--muted);
  text-align: center;
}

.ops-empty-state > svg { margin-bottom: 3px; color: var(--text-2); }
.ops-empty-state > b { color: var(--text); font-size: 13px; font-weight: 580; }
.ops-empty-state > em { font-size: 11px; font-style: normal; font-weight: 430; }

/* Clock */
.ops-clock-sheet { --ops-accent: #315bea; }

.ops-clock-stage {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 16px;
  min-height: 96px;
  margin: 12px;
  padding: 16px;
  border-radius: 11px;
  color: #fff;
  background: #11151d;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.06);
}

[data-theme="dark"] .ops-clock-stage { color: #11151d; background: #eef2fa; }

.ops-clock-time {
  display: flex;
  align-items: baseline;
  gap: 2px;
  font-family: var(--ref-mono-font, var(--mono));
  letter-spacing: -.075em;
  line-height: 1;
}

.ops-clock-time b { font-size: 38px; font-weight: 430; }
.ops-clock-time em { color: #7fa0ff; font-size: 20px; font-style: normal; font-weight: 450; letter-spacing: -.04em; }
.ops-clock-date { padding-bottom: 3px; color: rgba(255,255,255,.62); font-size: 10px; font-weight: 550; letter-spacing: .07em; text-transform: uppercase; }
[data-theme="dark"] .ops-clock-date { color: rgba(17,21,29,.56); }

.ops-clock-zones .ops-row { min-height: 45px; padding-block: 6px; }
.ops-zone-code { color: inherit; font-family: var(--ref-mono-font, var(--mono)); font-size: 9.5px; font-weight: 620; letter-spacing: .03em; }

/* AWS */
.ops-aws-sheet { --ops-accent: #ff9900; }

.ops-terminal-stage {
  display: grid;
  gap: 17px;
  width: calc(100% - 28px);
  min-height: 168px;
  margin: 14px;
  padding: 0 17px 17px;
  border: 0;
  border-radius: 11px;
  color: #e8edf6;
  background: #0b1017;
  font: inherit;
  text-align: left;
  cursor: pointer;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.07);
  transition: transform 160ms ease, box-shadow 160ms ease;
}

.ops-terminal-stage:hover { transform: translateY(-1px); box-shadow: inset 0 0 0 1px rgba(255,153,0,.28), 0 10px 22px rgba(6,10,16,.16); }

.ops-terminal-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 37px;
  margin: 0 -17px;
  padding: 0 14px;
  border-bottom: 1px solid rgba(255,255,255,.07);
}

.ops-terminal-bar > i { width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,.23); }
.ops-terminal-bar > i:first-child { background: #ff8d74; }
.ops-terminal-bar > em { margin-left: auto; color: rgba(255,255,255,.38); font-size: 8.5px; font-style: normal; font-weight: 620; letter-spacing: .09em; }
.ops-terminal-command { display: flex; gap: 9px; align-items: center; font-family: var(--ref-mono-font, var(--mono)); font-size: 12px; }
