.ops-terminal-help { max-width: 316px; color: rgba(232,237,246,.49); font-size: 10.5px; font-weight: 430; line-height: 16px; }

/* API keys */
.ops-key-sheet { --ops-accent: #f0b90b; }
.ops-key-list { border-bottom: 0; }
.ops-key-entry { border-bottom: 1px solid var(--line); }
