  gap: 7px;
  padding: 0 16px 11px 57px;
}
.ops-key-meta > span { display: grid; grid-template-columns: 72px minmax(0,1fr); gap: 10px; font-size: 10px; line-height: 14px; }
.ops-key-meta b { color: var(--muted); font-weight: 500; }
.ops-key-meta em { overflow: hidden; color: var(--text-2); font-style: normal; font-weight: 450; text-overflow: ellipsis; white-space: nowrap; }
.ops-key-entry.planned { opacity: .72; }

/* Data health */
.ops-data-sheet { --ops-accent: #1e9468; }
.ops-health-hero {
