}
.ops-health-hero > span { display: grid; gap: 2px; border-right: 1px solid var(--line); text-align: center; }
.ops-health-hero > span:nth-child(4) { border-right: 0; }
.ops-health-hero b { color: var(--text); font-family: var(--ref-mono-font, var(--mono)); font-size: 18px; font-weight: 500; letter-spacing: -.04em; }
.ops-health-hero em { color: var(--muted); font-size: 9.5px; font-style: normal; font-weight: 520; letter-spacing: .045em; text-transform: uppercase; }
.ops-health-hero > i { position: absolute; right: 16px; bottom: 7px; left: 16px; height: 2px; overflow: hidden; border-radius: 2px; background: var(--line); }
.ops-health-hero > i > span { display: block; height: 100%; border-radius: inherit; background: var(--ops-accent); }
.ops-health-list .ops-row { min-height: 47px; }
.ops-health-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--muted); }
.ops-health-dot.good { background: var(--ops-green); }
.ops-health-dot.warn { background: var(--ops-amber); }
.ops-health-dot.bad { background: var(--ops-red); }

/* Advisor */
.ops-advisor-sheet { --ops-accent: #315bea; }
.ops-advisor-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  min-height: 66px;
  border-bottom: 1px solid var(--line);
}
.ops-advisor-strip > span { display: grid; place-content: center; gap: 2px; border-right: 1px solid var(--line); text-align: center; }
.ops-advisor-strip > span:last-child { border-right: 0; }
.ops-advisor-strip b { font-family: var(--ref-mono-font, var(--mono)); font-size: 17px; font-weight: 520; letter-spacing: -.035em; }
.ops-advisor-strip em { color: var(--muted); font-size: 9px; font-style: normal; font-weight: 550; letter-spacing: .055em; text-transform: uppercase; }
.ops-advisor-strip .bad b { color: var(--ops-red); }
.ops-advisor-strip .warn b { color: var(--ops-amber); }
.ops-advisor-strip .ok b { color: var(--ops-green); }

/* Notifications */
.ops-notification-sheet { --ops-accent: #315bea; }
.ops-notification-list .ops-row { min-height: 61px; }

/* Bot controls */
.ops-bot-sheet { --ops-accent: #315bea; }
.ops-bot-sheet.bad { --ops-accent: #d83a3a; }
.ops-emergency {
  display: grid;
  grid-template-columns: 38px minmax(0,1fr) auto;
  align-items: center;
  gap: 11px;
  width: calc(100% - 28px);
  min-height: 76px;
  margin: 14px;
  padding: 11px 13px;
  border: 1px solid color-mix(in srgb, var(--ops-red) 22%, var(--line));
  border-radius: 10px;
  color: var(--text);
  background: color-mix(in srgb, var(--ops-red) 4%, var(--panel));
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease;
}
.ops-emergency:hover { border-color: color-mix(in srgb, var(--ops-red) 44%, var(--line)); background: color-mix(in srgb, var(--ops-red) 7%, var(--panel)); }
.ops-emergency.engaged { color: #fff; border-color: #c82731; background: #c82731; }
.ops-emergency-mark { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 50%; color: var(--ops-red); background: color-mix(in srgb, var(--ops-red) 9%, var(--tile)); }
.ops-emergency.engaged .ops-emergency-mark { color: #c82731; background: #fff; }
.ops-emergency > span:nth-child(2) { display: grid; gap: 3px; min-width: 0; }
.ops-emergency b { font-size: 12.5px; font-weight: 600; line-height: 16px; }
.ops-emergency em { color: var(--muted); font-size: 10.5px; font-style: normal; font-weight: 430; line-height: 14px; }
.ops-emergency.engaged em { color: rgba(255,255,255,.68); }
.ops-emergency strong { color: var(--ops-red); font-size: 9.5px; font-weight: 700; letter-spacing: .08em; }
.ops-emergency.engaged strong { color: #fff; }
.ops-control-row {
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  align-items: center;
  gap: 12px;
  min-height: 56px;
  width: 100%;
  padding: 9px 16px;
  border: 0;
  border-bottom: 1px solid var(--line);
  color: inherit;
  background: transparent;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.ops-control-row:last-child { border-bottom: 0; }
.ops-control-row:hover:not(:disabled) { background: color-mix(in srgb, var(--text) 4%, transparent); }
.ops-control-row:disabled { cursor: not-allowed; opacity: .5; }
.ops-control-row > span { display: grid; gap: 2px; }
.ops-control-row b { color: var(--text); font-size: 12.5px; font-weight: 560; line-height: 16px; }
.ops-control-row em { overflow: hidden; max-width: 316px; color: var(--muted); font-size: 10.5px; font-style: normal; font-weight: 430; line-height: 14px; text-overflow: ellipsis; white-space: nowrap; }
.ops-switch { position: relative; display: block; width: 34px; height: 20px; border-radius: 999px; background: color-mix(in srgb, var(--text) 13%, var(--tile)); transition: background-color 160ms ease; }
.ops-switch > span { position: absolute; top: 3px; left: 3px; width: 14px; height: 14px; border-radius: 50%; background: #fff; box-shadow: 0 1px 3px rgba(0,0,0,.24); transition: transform 160ms ease; }
.ops-switch.on { background: var(--ops-blue); }
.ops-switch.on > span { transform: translateX(14px); }

/* Cadence */
.ops-cadence-sheet { --ops-accent: #3d7bdf; }
.ops-cadence-row {
  display: grid;
  grid-template-columns: 30px minmax(0,1fr) 68px;
  align-items: center;
  gap: 11px;
