}
.ops-cadence-row:last-child { border-bottom: 0; }
.ops-cadence-row select {
  width: 68px;
  height: 30px;
  padding: 0 7px;
  border: 1px solid var(--line-2);
  border-radius: 8px;
  color: var(--text);
  background: var(--panel);
  font-family: var(--ref-mono-font, var(--mono));
  font-size: 10.5px;
  font-weight: 540;
  text-align: right;
  cursor: pointer;
}

/* Currency */
.ops-currency-sheet { --ops-accent: #315bea; }
.ops-currency-symbol { color: inherit; font-family: var(--ref-mono-font, var(--mono)); font-size: 12px; font-weight: 570; }

/* Basis */
.ops-basis-sheet { --ops-accent: #315bea; }
.ops-choice-stack { border-bottom: 1px solid var(--line); }
.ops-choice-stack > button {
  display: grid;
  grid-template-columns: 42px minmax(0,1fr) 20px;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 72px;
  padding: 11px 16px;
  border: 0;
  border-bottom: 1px solid var(--line);
  color: inherit;
  background: transparent;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.ops-choice-stack > button:last-child { border-bottom: 0; }
.ops-choice-stack > button:hover { background: color-mix(in srgb, var(--text) 4%, transparent); }
.ops-choice-stack > button.selected { background: color-mix(in srgb, var(--ops-accent) 5%, transparent); }
.ops-choice-mark { display: grid; place-items: center; width: 40px; height: 40px; border: 1px solid var(--line); border-radius: 10px; color: var(--text-2); font-family: var(--ref-mono-font, var(--mono)); font-size: 12px; font-weight: 600; }
.ops-choice-stack > button.selected .ops-choice-mark { color: #fff; border-color: var(--ops-accent); background: var(--ops-accent); }
.ops-choice-stack > button > span:nth-child(2) { display: grid; gap: 3px; }
.ops-choice-stack b { font-size: 13px; font-weight: 590; }
.ops-choice-stack em { color: var(--muted); font-size: 10.5px; font-style: normal; font-weight: 430; }
.ops-choice-stack > button > svg { color: var(--ops-accent); }

/* Appearance */
.ops-appearance-sheet { --ops-accent: var(--ops-accent, #315bea); }
.ops-segment {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 3px;
  margin: 0 14px 14px;
  padding: 3px;
  border-radius: 10px;
  background: var(--tile);
}
.ops-segment button {
  min-height: 34px;
  border: 0;
  border-radius: 7px;
  color: var(--muted);
  background: transparent;
  font: inherit;
  font-size: 11px;
  font-weight: 550;
  cursor: pointer;
}
.ops-segment button:hover { color: var(--text); }
.ops-segment button.selected { color: var(--text); background: var(--panel); box-shadow: 0 1px 4px rgba(8,12,20,.09); }
.ops-accent-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin: 0 14px 14px;
}
.ops-accent-row button { display: grid; place-items: center; width: 34px; height: 34px; border: 0; border-radius: 50%; background: transparent; cursor: pointer; }
.ops-accent-row button > span { width: 19px; height: 19px; border-radius: 50%; background: var(--swatch); box-shadow: inset 0 0 0 1px rgba(0,0,0,.09); }
.ops-accent-row button.selected { box-shadow: inset 0 0 0 2px var(--swatch); }
.ops-scale-row {
  display: grid;
  grid-template-columns: 36px minmax(0,1fr) 36px 92px;
  gap: 7px;
  margin: 0 14px 14px;
}
.ops-scale-row button,
.ops-scale-row strong { display: grid; place-items: center; min-height: 36px; border: 1px solid var(--line); border-radius: 9px; color: var(--text); background: var(--panel); font: inherit; font-size: 12px; font-weight: 570; }
.ops-scale-row button { cursor: pointer; }
.ops-scale-row button:hover { background: var(--hover); }
.ops-scale-row strong { font-family: var(--ref-mono-font, var(--mono)); font-size: 11px; }
.ops-scale-row .reset { color: var(--text-2); font-size: 10.5px; }

/* Compact rail: neutral by default, semantic only when it carries truth. */
.topbar-suite-divider {
