@keyframes opsPaneInForward { from { opacity: 0; transform: translateX(16px); } to { opacity: 1; transform: none; } }
@keyframes opsPaneOutForward { from { opacity: 1; transform: none; } to { opacity: 0; transform: translateX(-16px); } }
