.aws-runner-tabs > span { align-self: center; margin-left: auto; color: var(--muted); font-size: 11px; font-weight: 400; }

.aws-console-panel { display: grid; grid-template-rows: minmax(0, 1fr) 42px 50px; min-height: 0; background: #0c1119; }
.aws-console-output { min-height: 0; padding: 20px; overflow: auto; color: #dce4ef; font-family: var(--ref-mono-font, ui-monospace, monospace); }
.aws-console-empty { display: grid; place-items: center; align-content: center; gap: 6px; min-height: 100%; color: #768397; text-align: center; }
.aws-console-empty svg { margin-bottom: 5px; color: #ffad33; }
