.aws-console-entry header { display: flex; justify-content: space-between; gap: 12px; margin-bottom: 7px; }
.aws-console-entry header span { color: #ffbd5c; font-size: 12px; font-weight: 500; }
.aws-console-entry header em { color: #8290a5; font-size: 10px; font-style: normal; font-weight: 500; text-transform: uppercase; }
.aws-console-entry pre { margin: 0; color: #dce4ef; font: 400 12px/1.6 var(--ref-mono-font, ui-monospace, monospace); white-space: pre-wrap; word-break: break-word; }

.aws-command-map { display: flex; align-items: center; gap: 6px; padding: 5px 14px; border-top: 1px solid rgba(255,255,255,.07); }
.aws-command-map button { min-height: 26px; padding: 0 9px; border: 1px solid rgba(255,255,255,.1); border-radius: 6px; color: #9ba8bb; background: rgba(255,255,255,.035); font-size: 11px; font-weight: 500; cursor: pointer; }
.aws-command-map button:hover { color: #fff; border-color: rgba(255,153,0,.38); }

.aws-command-line { display: grid; grid-template-columns: auto minmax(0, 1fr) 70px; align-items: center; gap: 8px; padding: 7px 12px; border-top: 1px solid rgba(255,255,255,.08); background: #090d13; }
.aws-command-line > span { color: #ffad33; font: 500 12px var(--ref-mono-font, ui-monospace, monospace); }
.aws-command-line input { width: 100%; height: 34px; padding: 0 10px; border: 1px solid rgba(255,255,255,.12); border-radius: 7px; outline: none; color: #e6edf7; background: rgba(255,255,255,.035); font: 400 12px var(--ref-mono-font, ui-monospace, monospace); }
.aws-command-line input:focus { border-color: rgba(255,153,0,.55); box-shadow: 0 0 0 3px rgba(255,153,0,.08); }
.aws-command-line button { height: 34px; border: 1px solid #ff9900; border-radius: 7px; color: #141414; background: #ff9900; font-size: 12px; font-weight: 600; cursor: pointer; }
.aws-command-line button:disabled { cursor: default; opacity: .38; }

.aws-runner-editor { display: grid; grid-template-rows: 58px minmax(0, 1fr) 44px; min-height: 0; background: var(--panel); }
.aws-editor-toolbar { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 8px; padding: 8px 12px; border-bottom: 1px solid var(--line); }
.aws-editor-toolbar > span { display: grid; gap: 1px; min-width: 0; }
.aws-editor-toolbar > span b { overflow: hidden; color: var(--text); font-size: 13px; font-weight: 500; line-height: 18px; text-overflow: ellipsis; white-space: nowrap; }
.aws-editor-toolbar > span em { color: var(--muted); font-size: 11px; font-style: normal; font-weight: 400; line-height: 15px; }
.aws-editor-toolbar > button { display: inline-flex; align-items: center; gap: 6px; height: 34px; padding: 0 11px; border: 1px solid var(--line); border-radius: 7px; color: var(--text-2); background: var(--panel); font-size: 12px; font-weight: 500; cursor: pointer; }
.aws-editor-toolbar > button.primary { border-color: #ff9900; color: #17120a; background: #ff9900; font-weight: 600; }
.aws-editor-toolbar > button:disabled { cursor: default; opacity: .4; }
.aws-runner-editor > textarea { width: 100%; min-height: 0; padding: 18px; resize: none; border: 0; outline: none; color: #dce4ef; background: #0c1119; font: 400 12px/1.65 var(--ref-mono-font, ui-monospace, monospace); tab-size: 2; }
.aws-runner-editor > footer { display: grid; grid-template-columns: 18px minmax(0, 1fr); align-items: center; gap: 7px; padding: 7px 12px; border-top: 1px solid var(--line); color: var(--muted); font-size: 11px; font-weight: 400; line-height: 15px; }
.aws-runner-editor > footer svg { color: #159b66; }

.aws-runner-side { position: relative; display: grid; align-content: start; gap: 12px; min-height: 0; padding: 14px; overflow: auto; border-left: 1px solid var(--line); background: color-mix(in srgb, var(--text) 1.5%, var(--panel)); }
.aws-security-card,
.aws-target-card { overflow: hidden; border: 1px solid var(--line); border-radius: 10px; background: var(--panel); }
.aws-security-card > header,
.aws-target-card > header { display: flex; align-items: center; justify-content: space-between; gap: 8px; min-height: 42px; padding: 0 11px; border-bottom: 1px solid var(--line); }
.aws-security-card > header > span { display: inline-flex; align-items: center; gap: 7px; color: var(--text); font-size: 13px; font-weight: 500; }
.aws-security-card > header > span svg { color: #ff9900; }
.aws-security-card > header > em { color: var(--muted); font-size: 10px; font-style: normal; font-weight: 500; }
.aws-security-card > button { display: grid; grid-template-columns: minmax(0, 1fr) 34px; align-items: center; gap: 10px; width: 100%; min-height: 76px; padding: 10px 11px; border: 0; border-bottom: 1px solid var(--line); color: var(--text); background: transparent; font: inherit; text-align: left; cursor: pointer; }
.aws-security-card > button:last-child { border-bottom: 0; }
.aws-security-card > button:disabled { cursor: default; opacity: .44; }
.aws-security-card > button > span { display: grid; gap: 2px; }
.aws-security-card > button b { font-size: 14px; font-weight: 500; line-height: 20px; }
.aws-security-card > button em { color: var(--text-2); font-size: 12px; font-style: normal; font-weight: 400; line-height: 16px; }

.aws-target-card > header > span { color: var(--text); font-size: 13px; font-weight: 500; }
.aws-target-card > header > button { display: inline-flex; align-items: center; gap: 5px; min-height: 27px; padding: 0 7px; border: 0; border-radius: 6px; color: var(--muted); background: transparent; font-size: 11px; font-weight: 500; cursor: pointer; }
.aws-target-card > header > button:hover:not(:disabled) { color: var(--text); background: var(--hover); }
.aws-target-card > header > button:disabled { cursor: default; opacity: .4; }
.aws-target-card dl { margin: 0; padding: 6px 0; }
.aws-target-card dl > div { display: grid; grid-template-columns: 68px minmax(0, 1fr); gap: 8px; padding: 5px 11px; }
.aws-target-card dt,
.aws-target-card dd { overflow: hidden; margin: 0; font-size: 11px; line-height: 15px; text-overflow: ellipsis; white-space: nowrap; }
.aws-target-card dt { color: var(--muted); font-weight: 400; }
.aws-target-card dd { color: var(--text-2); font-weight: 500; }
.aws-config-missing { display: grid; gap: 3px; margin: 3px 8px 8px; padding: 9px; border-radius: 7px; color: #9a5d00; background: color-mix(in srgb, #ff9900 8%, var(--panel)); }
.aws-config-missing b { font-size: 11px; font-weight: 600; line-height: 15px; }
.aws-config-missing span { font-size: 10px; font-weight: 400; line-height: 14px; overflow-wrap: anywhere; }
.aws-runner-error { position: sticky; bottom: 0; padding: 9px 10px; border: 1px solid color-mix(in srgb, #cc4b4b 30%, var(--line)); border-radius: 8px; color: #b43d3d; background: color-mix(in srgb, #cc4b4b 8%, var(--panel)); font-size: 11px; font-weight: 400; line-height: 15px; }

@media (max-width: 900px) {
  .aws-runner-modal { height: min(820px, calc(94vh / var(--uiz, 1))) !important; }
  .aws-runner-head { grid-template-columns: 66px minmax(0, 1fr) 34px; gap: 10px; }
  .aws-runner-head > img { width: 64px; height: 36px; }
  .aws-runner-head > :is(.aws-runner-channel, a) { display: none; }
  .aws-runner-body { grid-template-columns: 1fr; grid-template-rows: minmax(390px, 1fr) auto; overflow: auto; }
  .aws-runner-side { grid-template-columns: repeat(2, minmax(0, 1fr)); overflow: visible; border-top: 1px solid var(--line); border-left: 0; }
}

@media (max-width: 620px) {
  .aws-runner-side { grid-template-columns: 1fr; }
  .aws-runner-tabs > span { display: none; }
  .aws-command-map { overflow-x: auto; }
}

/* ==== BINANCE API KEYS — two precise IP-bound objects ==== */
.topbar-suite-v4 > button[data-topbar-key="apikey"] { --rail-tone: #84cc00; }
.topbar-suite-v4 .smenu-pane[data-pane-key="apikey"] { --pane-tone: #84cc00; }

.smenu-bar.topbar-suite-v4 .api-key-trigger-core {
