  65%, 100% { box-shadow: 0 0 0 6px rgba(24,166,107,0); }
}

@media (prefers-reduced-motion: reduce) {
  .api-key-object-state.live > i,
  .api-key-sheet-v2 .ops-sheet-status.ok > i { animation: none !important; }
}

[data-motion="reduced"] .api-key-object-state.live > i,
[data-motion="reduced"] .api-key-sheet-v2 .ops-sheet-status.ok > i { animation: none !important; }

/* ==== TRUST ADVISOR — sourced shield and three-state symbol system ====== */
.topbar-suite-v4 > button[data-topbar-key="advisor"],
.topbar-suite-v4 .smenu-pane[data-pane-key="advisor"] {
  --rail-tone: #24c85a;
  --pane-tone: #24c85a;
}

/* The v4 rail applies `color: var(--rail-tone)` at higher specificity than
   the semantic grade rules, so the tone variable itself must carry the true
   grade: a warn/bad advisor re-tones the whole rail mechanism (icon colour,
   hover tint, underlight) instead of shouting identity green over a failing
   state. Same hue authorities as the state pip. */
.topbar-suite-v4 > button[data-topbar-key="advisor"].grade-warn { --rail-tone: var(--ops-amber); }
.topbar-suite-v4 > button[data-topbar-key="advisor"].grade-bad { --rail-tone: var(--ops-red); }

.trust-advisor-trigger-core {
  display: grid;
  place-items: center;
  overflow: visible !important;
  background: transparent !important;
}

.trust-advisor-trigger-image {
  display: block;
  width: 28px;
  height: 28px;
  object-fit: contain;
}

/* Real-state pip: the owner-supplied shield stays untouched; the advisor's
   non-ok grade is carried by this mark, visually integrated with the glyph. */
.trust-advisor-trigger-core {
  position: relative;
}
.trust-advisor-trigger-core .rail-state-pip {
  position: absolute;
  right: -1px;
  bottom: 0;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  pointer-events: none;
}
.trust-advisor-trigger-core .rail-state-pip[data-grade="bad"] { background: var(--ops-red); }
.trust-advisor-trigger-core .rail-state-pip[data-grade="warn"] { background: var(--ops-amber); }

.trust-advisor-source-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.popup-source-mark.brand:has(.trust-advisor-source-image) {
  overflow: visible;
  background: transparent;
}

.smenu-bar.topbar-suite-v4 .ops-advisor-sheet {
  --ops-accent: #24c85a;
}

.smenu-bar.topbar-suite-v4 .ops-advisor-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
  gap: 8px;
  min-height: 56px;
  margin: 6px 10px 4px;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.smenu-bar.topbar-suite-v4 .ops-advisor-strip > span {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  place-content: initial;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 7px 8px;
  border: 1px solid var(--line) !important;
  border-radius: 8px;
  background: color-mix(in srgb, var(--text) 1.5%, var(--panel));
  text-align: left;
}

.ops-advisor-state-icon {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 7px;
}

.ops-advisor-state-copy {
  display: grid;
  min-width: 0;
}

.smenu-bar.topbar-suite-v4 .ops-advisor-strip .bad .ops-advisor-state-icon {
  color: #cf8a12;
  background: color-mix(in srgb, #cf8a12 11%, var(--panel));
}

.smenu-bar.topbar-suite-v4 .ops-advisor-strip .warn .ops-advisor-state-icon {
  color: #d8aa20;
  background: color-mix(in srgb, #d8aa20 11%, var(--panel));
}

.smenu-bar.topbar-suite-v4 .ops-advisor-strip .ok .ops-advisor-state-icon {
  color: #1ea864;
  background: color-mix(in srgb, #1ea864 10%, var(--panel));
}

.smenu-bar.topbar-suite-v4 .smenu-pane .ops-advisor-strip .bad b { color: #b8790f; }
.smenu-bar.topbar-suite-v4 .smenu-pane .ops-advisor-strip .warn b { color: #b88c0d; }
.smenu-bar.topbar-suite-v4 .smenu-pane .ops-advisor-strip .ok b { color: #168f56; }

.smenu-bar.topbar-suite-v4 .ops-advisor-list .ops-row-icon.warn {
  color: #cf9718;
}

.smenu-bar.topbar-suite-v4 .ops-advisor-list .ops-row-icon.ok {
  color: #1b9d5e;
}

