.ntc-center {
  --ntc-red: #d94a51;
  --ntc-orange: #c98523;
  --ntc-green: #169765;
  --ntc-blue: #2874df;
  --ntc-bell: #e39a00;
  display: grid;
  grid-template-rows: auto auto auto minmax(260px, 1fr) auto;
  width: min(1680px, calc((100vw - 72px) / var(--uiz, 1)));
  max-width: none;
  height: min(1120px, calc((100vh - 72px) / var(--uiz, 1)));
  max-height: none;
  overflow: hidden;
  border: 1px solid var(--line-2);
  border-radius: 14px;
  background: var(--panel);
  box-shadow: 0 28px 80px rgba(10, 15, 25, .24), 0 2px 7px rgba(10, 15, 25, .08);
  color: var(--text);
}

.ntc-head {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 13px;
  min-height: 76px;
  padding: 10px 16px 10px 18px;
  border-bottom: 1px solid var(--line);
}

.ntc-title-mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
}

.ntc-title-mark img {
  display: block;
  width: 42px;
  height: 42px;
  object-fit: contain;
}

.ntc-title-copy,
.ntc-head-status span,
.ntc-rule-copy,
.ntc-row-copy,
.ntc-row-source,
.ntc-empty {
  display: grid;
  min-width: 0;
}

.ntc-title-copy {
  gap: 3px;
}

.ntc-title-copy > b {
  color: var(--text);
  font-size: 22px;
  font-weight: 590;
  letter-spacing: -.012em;
  line-height: 27px;
}

.ntc-title-copy > em {
  overflow: hidden;
  color: var(--muted);
  font-size: 13px;
  font-style: normal;
  font-weight: 420;
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ntc-head-status {
  display: grid;
  grid-template-columns: 7px auto;
  align-items: center;
  gap: 9px;
  min-width: 142px;
  padding: 0 14px;
  border-left: 1px solid var(--line);
}

.ntc-head-status > i {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--ntc-green);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--ntc-green) 10%, transparent);
}

.ntc-head-status span {
  gap: 1px;
}

.ntc-head-status b,
.ntc-head-status em {
  font-size: 11.5px;
  line-height: 15px;
  white-space: nowrap;
}

.ntc-head-status b {
  color: var(--text);
  font-weight: 590;
}

.ntc-head-status em {
  color: var(--muted);
  font-style: normal;
  font-weight: 430;
}

.ntc-head-actions,
.ntc-foot > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.ntc-head-actions button,
.ntc-foot button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 34px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--panel);
  color: var(--text-2);
  font: inherit;
  font-size: 12px;
  font-weight: 540;
  cursor: pointer;
  transition: border-color .14s ease, background-color .14s ease, color .14s ease;
}

.ntc-head-actions button:hover,
.ntc-foot button:hover:not(:disabled) {
  border-color: var(--line-2);
  background: var(--tile);
  color: var(--text);
}

.ntc-head-actions button:disabled,
.ntc-foot button:disabled {
  cursor: default;
  opacity: .42;
}

.ntc-head-actions .ntc-close {
  width: 34px;
  padding: 0;
  border-color: transparent;
}

.ntc-rules {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px 16px;
  padding: 13px 18px 14px;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--tile) 54%, var(--panel));
}

.ntc-rules-copy {
  display: flex;
  align-items: baseline;
  gap: 9px;
  min-width: 0;
}

.ntc-rules-copy b {
  color: var(--text);
  font-size: 13px;
  font-weight: 610;
  line-height: 18px;
}

.ntc-rules-copy em {
  color: var(--muted);
  font-size: 12px;
  font-style: normal;
  font-weight: 420;
  line-height: 17px;
}

.ntc-rule-grid {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 7px;
}

.ntc-rule {
  display: grid;
  grid-template-columns: 29px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 8px;
  min-width: 0;
  min-height: 58px;
  padding: 7px 9px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--panel);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color .14s ease, background-color .14s ease;
}

.ntc-rule:hover,
.ntc-rule.on {
  border-color: color-mix(in srgb, var(--ntc-bell) 28%, var(--line));
}

.ntc-rule.off {
  background: color-mix(in srgb, var(--tile) 75%, var(--panel));
}

.ntc-rule-icon,
.ntc-row-icon {
  display: grid;
  place-items: center;
  flex: none;
  border-radius: 8px;
}

.ntc-rule-icon {
  width: 28px;
  height: 28px;
  background: color-mix(in srgb, var(--text) 4%, var(--panel));
  color: var(--text-2);
}

.ntc-rule-icon.critical,
.ntc-row-icon.critical { color: var(--ntc-red); background: color-mix(in srgb, var(--ntc-red) 9%, var(--panel)); }
.ntc-rule-icon.account,
.ntc-row-icon.account { color: var(--ntc-blue); background: color-mix(in srgb, var(--ntc-blue) 9%, var(--panel)); }
.ntc-rule-icon.bot,
.ntc-row-icon.bot { color: var(--ntc-orange); background: color-mix(in srgb, var(--ntc-orange) 9%, var(--panel)); }
.ntc-rule-icon.opportunities,
.ntc-row-icon.opportunities { color: var(--ntc-green); background: color-mix(in srgb, var(--ntc-green) 9%, var(--panel)); }
.ntc-rule-icon.news,
.ntc-row-icon.news { color: #7a63c4; background: color-mix(in srgb, #7a63c4 9%, var(--panel)); }

.ntc-rule-copy {
  gap: 2px;
}

.ntc-rule-copy b,
.ntc-rule-copy em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ntc-rule-copy b {
  color: var(--text);
  font-size: 12px;
  font-weight: 570;
  line-height: 16px;
}

.ntc-rule-copy em {
  color: var(--muted);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 420;
  line-height: 14px;
}

.ntc-rule > strong {
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 520;
}

.ntc-toggle {
  position: relative;
  display: block;
  width: 29px;
  height: 17px;
  border-radius: 999px;
  background: var(--line-2);
  transition: background-color .14s ease;
}

.ntc-toggle span {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 11px;
  height: 11px;
  border-radius: 999px;
  background: var(--panel);
  box-shadow: 0 1px 2px rgba(0, 0, 0, .18);
  transition: transform .16s ease;
}

.ntc-rule.on .ntc-toggle {
  background: var(--ntc-green);
}

.ntc-rule.on .ntc-toggle span {
  transform: translateX(12px);
}

.ntc-delivery {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
}

.ntc-delivery > span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 23px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
}

.ntc-delivery > span.active {
  border-color: color-mix(in srgb, var(--ntc-green) 26%, var(--line));
  color: var(--ntc-green);
}

.ntc-delivery b,
.ntc-delivery em {
  font-size: 10.5px;
  line-height: 13px;
  white-space: nowrap;
}

.ntc-delivery b { font-weight: 570; }
.ntc-delivery em { color: inherit; font-style: normal; font-weight: 430; opacity: .78; }

.ntc-days {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 7px;
  padding: 10px 18px;
  border-bottom: 1px solid var(--line);
}

.ntc-days button {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 3px 8px;
  min-width: 0;
  min-height: 54px;
  padding: 7px 9px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--panel);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.ntc-days button:hover,
.ntc-days button.on {
  border-color: color-mix(in srgb, var(--ntc-bell) 32%, var(--line));
  background: color-mix(in srgb, var(--ntc-bell) 5%, var(--panel));
}

.ntc-days button > span {
  display: flex;
  align-items: baseline;
  gap: 5px;
  min-width: 0;
}

.ntc-days b,
.ntc-days em,
.ntc-days small,
.ntc-days strong {
  white-space: nowrap;
}

.ntc-days b { font-size: 11.5px; font-weight: 590; line-height: 15px; }
.ntc-days em { color: var(--muted); font-size: 10px; font-style: normal; font-weight: 430; line-height: 14px; }
.ntc-days strong { color: var(--text); font-family: var(--mono); font-size: 13px; font-weight: 530; line-height: 15px; }
.ntc-days small { grid-column: 1 / -1; color: var(--muted); font-size: 10px; font-weight: 450; line-height: 13px; }
.ntc-days small.hot { color: var(--ntc-red); }

.ntc-feed {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  min-height: 0;
}

.ntc-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 48px;
  padding: 7px 18px;
  border-bottom: 1px solid var(--line);
}

.ntc-filters {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}

.ntc-filters button,
.ntc-context button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
  font: inherit;
  font-size: 11.5px;
  font-weight: 520;
  cursor: pointer;
}

.ntc-filters button:hover,
.ntc-filters button.on,
.ntc-context button:hover {
  border-color: var(--line);
  background: var(--tile);
  color: var(--text);
}

.ntc-filters button span {
  min-width: 18px;
  padding: 1px 5px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text) 5%, transparent);
  color: inherit;
  font-family: var(--mono);
  font-size: 9.5px;
  font-weight: 520;
  text-align: center;
}

.ntc-context {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 450;
  white-space: nowrap;
}

.ntc-context button {
  height: 27px;
  border-color: var(--line);
}

.ntc-table-head,
.ntc-row {
  display: grid;
  grid-template-columns: 72px 34px minmax(0, 1fr) 150px 88px;
  align-items: center;
  gap: 10px;
  padding: 0 18px;
}

.ntc-table-head {
  min-height: 31px;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--tile) 62%, var(--panel));
}

.ntc-table-head span {
  color: var(--muted);
  font-size: 9.5px;
  font-weight: 620;
  letter-spacing: .07em;
  line-height: 12px;
  text-transform: uppercase;
}

.ntc-table-head span:nth-child(2) { color: transparent; }
.ntc-table-head span:last-child { text-align: right; }

.ntc-list {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.ntc-row {
  min-height: 58px;
  border-bottom: 1px solid var(--line);
  background: var(--panel);
}

.ntc-row:hover {
  background: color-mix(in srgb, var(--tile) 56%, var(--panel));
}

.ntc-row:last-child { border-bottom: 0; }

.ntc-row > time {
  display: grid;
  gap: 1px;
}

.ntc-row > time b {
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 11.5px;
  font-weight: 540;
  line-height: 15px;
}

.ntc-row > time em {
  color: var(--muted);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 440;
  line-height: 13px;
}

.ntc-row-icon {
  width: 30px;
  height: 30px;
  border: 1px solid color-mix(in srgb, currentColor 15%, var(--line));
}

.ntc-row-copy,
.ntc-row-source {
  gap: 2px;
}

.ntc-row-copy b,
.ntc-row-copy em,
.ntc-row-source b,
.ntc-row-source em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ntc-row-copy b {
  color: var(--text);
  font-size: 13px;
  font-weight: 560;
  letter-spacing: -.002em;
  line-height: 17px;
}

.ntc-row-copy em {
  color: var(--text-2);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 420;
  line-height: 15px;
}

.ntc-row-source b {
  color: var(--text-2);
  font-size: 11.5px;
  font-weight: 540;
  line-height: 15px;
}

.ntc-row-source em {
  color: var(--muted);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 440;
  line-height: 13px;
}

.ntc-row-status {
  justify-self: end;
  min-width: 67px;
  padding: 4px 7px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-size: 9.5px;
  font-weight: 610;
  line-height: 12px;
  text-align: center;
  text-transform: uppercase;
  white-space: nowrap;
}

.ntc-row-status.critical {
  border-color: color-mix(in srgb, var(--ntc-red) 24%, var(--line));
  background: color-mix(in srgb, var(--ntc-red) 7%, var(--panel));
  color: var(--ntc-red);
}

.ntc-row-status.warning {
  border-color: color-mix(in srgb, var(--ntc-orange) 24%, var(--line));
  color: var(--ntc-orange);
}

.ntc-empty {
  place-items: center;
  align-content: center;
  gap: 5px;
  min-height: 190px;
  padding: 24px;
  color: var(--muted);
  text-align: center;
}

.ntc-empty b { color: var(--text); font-size: 13px; font-weight: 580; line-height: 18px; }
.ntc-empty em { max-width: 460px; color: var(--muted); font-size: 11.5px; font-style: normal; font-weight: 420; line-height: 17px; }
.ntc-empty.error { color: var(--ntc-red); }

.ntc-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 54px;
  padding: 9px 16px 9px 18px;
  border-top: 1px solid var(--line);
  background: color-mix(in srgb, var(--tile) 58%, var(--panel));
}

.ntc-foot > span {
  overflow: hidden;
  color: var(--muted);
  font-size: 11px;
  font-weight: 430;
  line-height: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ntc-foot > span b {
  color: var(--text);
  font-family: var(--mono);
  font-weight: 560;
}

.ntc-foot button.primary {
  border-color: #11151d;
  background: #11151d;
  color: #fff;
}

[data-theme="dark"] .ntc-foot button.primary {
  border-color: #f5f7fa;
  background: #f5f7fa;
  color: #11151d;
}

@media (max-width: 1120px) {
  .ntc-center { width: calc((100vw - 32px) / var(--uiz, 1)); height: calc((100vh - 32px) / var(--uiz, 1)); }
  .ntc-head { grid-template-columns: 42px minmax(0, 1fr) auto; }
  .ntc-head-status { display: none; }
  .ntc-rule-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .ntc-rule:nth-child(n + 4) { grid-column: span 1; }
  .ntc-rules { max-height: 224px; overflow: auto; }
  .ntc-table-head,
  .ntc-row { grid-template-columns: 68px 32px minmax(0, 1fr) 112px 82px; }
}

@media (max-width: 760px) {
  .ntc-backdrop { padding: 8px !important; }
  .ntc-center { width: calc((100vw - 16px) / var(--uiz, 1)); height: calc((100vh - 16px) / var(--uiz, 1)); border-radius: 11px; }
  .ntc-head { grid-template-columns: 38px minmax(0, 1fr) auto; padding-inline: 12px; }
  .ntc-title-mark,
  .ntc-title-mark img { width: 36px; height: 36px; }
  .ntc-head-actions > button:not(.ntc-close) { display: none; }
  .ntc-rule-grid { grid-template-columns: 1fr 1fr; }
  .ntc-days { grid-template-columns: repeat(7, 118px); overflow-x: auto; }
  .ntc-toolbar { align-items: flex-start; flex-direction: column; overflow-x: auto; }
  .ntc-filters { min-width: max-content; }
  .ntc-table-head { display: none; }
  .ntc-row { grid-template-columns: 58px 30px minmax(0, 1fr); padding-inline: 12px; }
  .ntc-row-source,
  .ntc-row-status { display: none; }
}

/* ==== EXECUTION CONTROL — explicit three-state operator modes ============== */
.smenu-bar.topbar-suite-v4 .ops-bot-sheet.ok { --ops-accent: var(--ops-green); }

.smenu-bar.topbar-suite-v4 .execution-control-source-image,
.smenu-bar.topbar-suite-v4 .execution-control-trigger-image,
.smenu-bar.topbar-suite-v4 .ops-emergency-mark img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.smenu-bar.topbar-suite-v4 .execution-control-trigger-core {
  overflow: visible;
  background: transparent !important;
}

.smenu-bar.topbar-suite-v4 .execution-control-trigger-image {
  width: 24px;
  height: 24px;
}

.smenu-bar.topbar-suite-v4 button.power-premium-trigger.m-halted {
  color: var(--ops-green) !important;
}

.smenu-bar.topbar-suite-v4 .ops-emergency {
  min-height: 72px;
  border-color: #e8332c;
  color: #fff;
  background: #fb4138;
  box-shadow: 0 8px 18px rgba(190, 37, 31, .14);
}

.smenu-bar.topbar-suite-v4 .ops-emergency:hover {
  border-color: #d72b25;
  color: #fff;
  background: #ed3931;
}

.smenu-bar.topbar-suite-v4 .ops-emergency.engaged,
.smenu-bar.topbar-suite-v4 .ops-emergency.engaged:hover {
  border-color: #25c96a;
  color: #06140c;
  background: #3ddd86;
  box-shadow: 0 8px 18px rgba(30, 171, 87, .14);
}

.smenu-bar.topbar-suite-v4 .ops-emergency-mark,
.smenu-bar.topbar-suite-v4 .ops-emergency.engaged .ops-emergency-mark {
  width: 42px;
  height: 42px;
  overflow: hidden;
  border-radius: 50%;
  color: inherit;
  background: transparent;
}

.smenu-bar.topbar-suite-v4 .ops-emergency em,
.smenu-bar.topbar-suite-v4 .ops-emergency strong,
.smenu-bar.topbar-suite-v4 .ops-emergency.engaged em,
.smenu-bar.topbar-suite-v4 .ops-emergency.engaged strong {
  color: inherit;
}

.smenu-bar.topbar-suite-v4 .ops-emergency strong {
  min-width: 58px;
  text-align: right;
}

.smenu-bar.topbar-suite-v4 .ops-control-row.ops-tri-row {
  grid-template-columns: minmax(0, 1fr) 166px;
  gap: 10px;
  min-height: 61px;
  padding: 8px 12px 8px 16px;
  cursor: default;
}

.smenu-bar.topbar-suite-v4 .ops-tri-row > span:first-child {
  min-width: 0;
}

.smenu-bar.topbar-suite-v4 .ops-tri-row > span:first-child em {
  max-width: 176px;
}

.smenu-bar.topbar-suite-v4 .ops-tri-control {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2px;
  width: 166px;
  padding: 3px;
  border: 1px solid var(--line-2);
  border-radius: 9px;
  background: var(--tile);
}

.smenu-bar.topbar-suite-v4 .ops-tri-control label {
  position: relative;
  display: block;
  min-width: 0;
  cursor: pointer;
}

.smenu-bar.topbar-suite-v4 .ops-tri-control input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.smenu-bar.topbar-suite-v4 .ops-tri-control label > span {
  display: grid;
  place-items: center;
  height: 27px;
  padding: 0 4px;
  border-radius: 6px;
  color: var(--muted);
  font-size: 9.5px;
  font-weight: 560;
  line-height: 12px;
  white-space: nowrap;
  transition: color 140ms ease, background-color 140ms ease, box-shadow 140ms ease;
}

.smenu-bar.topbar-suite-v4 .ops-tri-control label:hover > span {
  color: var(--text);
  background: color-mix(in srgb, var(--text) 5%, transparent);
}

.smenu-bar.topbar-suite-v4 .ops-tri-control .blocked input:checked + span {
  color: #fff;
  background: #d83a3a;
  box-shadow: 0 1px 2px rgba(125, 20, 20, .18);
}

.smenu-bar.topbar-suite-v4 .ops-tri-control .paused input:checked + span {
