/* ==== BACKEND-AUTHORITATIVE OPTIONAL SURFACES ============================ */
.optional-surface-gate {
  position: relative;
  min-width: 0;
}
.optional-surface-gate.admitted {
  display: grid;
  gap: 10px;
}
.optional-surface-control-strip {
  position: relative;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-self: end;
  gap: 12px;
  min-height: 38px;
  max-width: min(520px, 100%);
  padding: 5px 6px 5px 12px;
  border: 1px solid color-mix(in srgb, var(--line-2) 82%, transparent);
  border-radius: 12px;
  background: color-mix(in srgb, var(--panel) 94%, transparent);
  box-shadow: 0 8px 24px color-mix(in srgb, #000 8%, transparent);
}
.optional-surface-control-strip > span {
  display: grid;
  min-width: 0;
  line-height: 1.2;
}
.optional-surface-control-strip b {
  color: var(--text);
  font-size: 11px;
  font-weight: 720;
  letter-spacing: .07em;
  text-transform: uppercase;
}
.optional-surface-control-strip small {
  overflow: hidden;
  max-width: 360px;
  color: var(--muted);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.optional-surface-switch {
  position: relative;
  display: inline-grid;
  grid-template-columns: 34px auto;
  align-items: center;
  gap: 7px;
  min-width: 76px;
  height: 30px;
  padding: 0 9px 0 5px;
  border: 1px solid color-mix(in srgb, var(--line-2) 88%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--tile) 88%, var(--panel));
  color: var(--muted);
  font-family: var(--mono);
  cursor: pointer;
  transition: border-color .16s ease, background .16s ease, color .16s ease, opacity .16s ease;
}
.optional-surface-switch > span {
  position: relative;
  width: 34px;
  height: 18px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--muted) 28%, var(--tile));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--line-2) 70%, transparent);
}
.optional-surface-switch > span::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--panel);
  box-shadow: 0 1px 4px color-mix(in srgb, #000 22%, transparent);
  transition: transform .18s ease, background .18s ease;
}
.optional-surface-switch > em {
  font-size: 9px;
  font-style: normal;
  font-weight: 760;
  letter-spacing: .08em;
}
.optional-surface-switch.on {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line));
  background: color-mix(in srgb, var(--accent-soft) 62%, var(--panel));
  color: var(--accent-ink);
}
.optional-surface-switch.on > span {
  background: var(--accent);
  box-shadow: none;
}
.optional-surface-switch.on > span::after {
  transform: translateX(16px);
  background: #fff;
}
.optional-surface-switch:disabled {
  cursor: wait;
  opacity: .5;
}
.optional-surface-switch.compact {
  display: grid;
  grid-template-columns: 28px;
  min-width: 30px;
  width: 30px;
  height: 24px;
  padding: 0;
  place-content: center;
  border-color: transparent;
  background: transparent;
}
.optional-surface-switch.compact > span {
  width: 28px;
  height: 16px;
}
.optional-surface-switch.compact > span::after {
  top: 3px;
  left: 3px;
  width: 10px;
  height: 10px;
}
.optional-surface-switch.compact.on > span::after {
  transform: translateX(12px);
}
.optional-surface-gate.closed {
  min-height: min(660px, calc(100dvh - 170px));
  padding: 12px;
}
.optional-surface-gate.closed > .optional-surface-switch {
  position: absolute;
  z-index: 2;
  top: 24px;
  right: 24px;
}
.optional-surface-inert {
  display: grid;
  align-content: center;
  min-height: inherit;
  padding: clamp(32px, 7vw, 92px);
  border: 1px solid color-mix(in srgb, var(--line) 88%, transparent);
  border-radius: 18px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--tile) 74%, var(--bg)), color-mix(in srgb, var(--panel) 70%, var(--bg)));
  color: var(--muted);
  filter: grayscale(.72);
  opacity: .82;
  pointer-events: none;
}
.optional-surface-inert h1 {
  margin: 10px 0 7px;
  color: color-mix(in srgb, var(--text) 54%, var(--muted));
  font-size: clamp(28px, 5vw, 54px);
  letter-spacing: -.04em;
}
.optional-surface-inert p {
  max-width: 620px;
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.6;
}
.optional-surface-kicker {
  color: var(--faint);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 760;
  letter-spacing: .14em;
}
.optional-surface-inert dl {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  width: min(620px, 100%);
  margin: 28px 0 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--line) 84%, transparent);
  border-radius: 12px;
  background: var(--line);
}
.optional-surface-inert dl > div {
  display: grid;
  gap: 4px;
  padding: 13px;
  background: color-mix(in srgb, var(--panel) 78%, var(--bg));
}
.optional-surface-inert dt {
  color: var(--faint);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.optional-surface-inert dd {
  margin: 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 11px;
}
.optional-surface-error {
  max-width: 620px;
  margin-top: 14px;
  color: var(--ops-red, #d43f4c);
  font-family: var(--mono);
}
.optional-page-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 220px;
  color: var(--muted);
}
.optional-page-loading > span {
  width: 16px;
  height: 16px;
  border: 2px solid color-mix(in srgb, var(--accent) 25%, var(--line));
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: optionalSurfaceSpin .75s linear infinite;
}
@keyframes optionalSurfaceSpin { to { transform: rotate(360deg); } }

.snav-optional-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 30px;
  align-items: center;
  min-width: 0;
}
.snav-optional-row > .snav-item {
  min-width: 0;
}

@media (max-width: 820px) {
  .snav-optional-row {
    display: block;
  }
  .snav-optional-row > .optional-surface-switch {
    display: none;
  }
  .optional-surface-control-strip small {
    display: none;
  }
}
@media (max-width: 560px) {
  .optional-surface-control-strip {
    max-width: 100%;
  }
  .optional-surface-gate.closed {
    min-height: calc(100dvh - 140px);
    padding: 6px;
  }
  .optional-surface-gate.closed > .optional-surface-switch {
    top: 16px;
    right: 16px;
  }
  .optional-surface-inert {
    padding: 76px 22px 32px;
  }
  .optional-surface-inert dl {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
